  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Weekly inspection and test run of G-9110', 'Mechanic', 'PM ', 'Completed', '2022-12-30', '<p><b>Description: Performed weekly inspection and test run of Gas Engine Generator G-9110</b>.</p><p><br></p><p><b><u>Working steps:</u></b></p><p>-Checked air filters condition. (both sides)</p><p>-Checked lube oil level and condition.</p><p>-Checked coolant level.</p><p>-Cleaned breather filters. (both sides)</p><p>-Checked coolant pump if any leakage.</p><p>-Checked turbocharger condtion.</p><p>-Installed the new ventilation fan motor.</p><p>-Housekeeping around the generator package.</p><p><b>-failed to start the engine by low rpm alarm. (1st attempt)</b></p><p><b>-failed to start the engine by Gas Valve fail alarm. (2nd attempt)</b></p><p><b>-Able to start the engine by 3rd attempt.</b></p><p>-Test run without load for 30 minutes.</p><p><br></p>', NULL, '2022-12-30 17:09:26', '2022-12-30 17:22:25', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
