-- Inserting report ID 9993
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot OGC AIT-84306 printing error', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2022-12-30', '<p>Troubleshoot OGC AIT-84306 "<b>Printing Error Alarm</b>" and "<b>AIT-84306 CHROM TELEM REP TOUT</b>" alarm</p><p><b>As found</b>:&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style="background-color: rgb(255, 255, 0);">On 29th Dec 2022,</span> (19:20 YGN Time) OGC AIT-84306&nbsp;<b>“PRINTING ERROR ALARM” </b>of all metering tubes except FQI-84152A and FQI-84202A appears on Metering HMI.</p><p>On Flow Computers of All Metering Tube A and B , it show alarm “<b>AIT-84306 CHROM TELEM REP TOUT</b>” as per below.</p><p>- CCR inform to check and inspect for the OGC AIT-84306 error alarm at 19:25 on OGC remote desktop computer.</p><p>- Check the alarm on display and logged into the system software</p><p>- Inform night-shift operator needs to check the Helium Cylinder Pressure</p><p>- Visual check the Helium Cylinder and isolation value leak check at OGC station (Cylinder pressure OK and no leak at local)</p><p>- Check the circuit breaker at junction box for AIT-84306 behind the OGC station ( Circuit Breaker is not tripped)</p><p>- Visual check the power at AIT-84306 Ex Proof junction box ( Power is normal and Sequence is running)</p><p>- Inform to Senior E&amp;I, visual check and inspection for AIT-84306 at local is normal (No failure or damage was found)</p><p>- Acknowledge and clear the alarm at FloBoss S600+ flow computer (Alarm is not clear and hold the alarm)</p><p>- Open the MON2000 software and check the Chromatograph of OGC-06</p><p>- Check and standby for the daily gas sales report. (OGC AIT-84307 is normal running and report is OK)</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">On 30th Dec. 2022,</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p>- E&amp;I team verified “the alarms and OGC failure to send analysis data to flow computer”.</p><p>- There was no abnormality on OGC &amp; metering system.</p><p>- Once E&amp;I team tried to export archive from GC controller, the data could not generate and controller was fail to respond. </p><p>- Vendor suspected about memory error of controller and suggested “power cycle” OGC.</p><p>- After Power cycle OGC , OGC is working normal and able to retrieve archive.</p><p>- Data lost for the period between 18:44 PM,29 Dec 22 to 13:00 PM, 30 Dec 22 .</p><p>- Run OGC to analyze the process gas and compare the analysis report with In-use OGC AIT-84307.</p><p>                  </p><p>- The BTU difference between OGCs is within acceptable range and put OGC AIT-84306 to auto sequence analysis at 13:45 PM , 30 Dec 22.</p>', NULL, '2022-12-30 18:07:13', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-AIT-84306', 'ATL-MS-AIT-84306', 'Gas chromatograph to metering.N2and CO2', NULL, NULL, 'Gas chromatograph to metering.N2and CO2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

