-- Inserting report ID 9998
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Support weekly firewater pumps test run', 'Mechanic', 'PM', 'Completed', '2023-01-01', '<p>Work Steps:</p><p>1.&nbsp;&nbsp;&nbsp;&nbsp;Checked the lube oil level and the coolant level.</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;Ensured the cooling supplying valves were opened.</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;Ensured the solenoid valve to the exchanger was opened.</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;Checked the fuel level and the Fuel leakage.</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;Checked the battery voltage on the Dial Gauge.</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;Checked the battery parameter and distilled water level.</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;Performed the visual inspection.</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;Started the engine&nbsp;automatically&nbsp;by opening the Hydrant in the process area.</p><p>9.&nbsp;&nbsp;&nbsp;&nbsp;During running, Checked the water leakage from the packing gland and any abnormal.</p><p>10.&nbsp;&nbsp;After running for 15 minutes, closed the hydrant, and stopped the engine.</p><p>11.&nbsp;&nbsp;Performed walkaround inspection.</p>', NULL, '2023-01-01 17:50:07', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-P-8855A', 'ATL-OC-P-8855A', 'ZOC Fire Water Pump A', NULL, NULL, 'ZOC Fire Water Pump A', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-P-8855B', 'ATL-OC-P-8855B', 'ZOC Fire Water Pump B Assembly', NULL, NULL, 'ZOC Fire Water Pump B Assembly', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

