-- Inserting report ID 10004
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform MPM on G-8320 at ZBV#2', 'Mechanic', 'PM', 'Completed', '2023-01-02', '<div>Working Steps</div><div><br></div><div>- Checked and cleaned the air filter and filter housing.</div><div>- Checked the air service indicator.</div><div>- Checked the coolant level and the radiator cap condition.(Top up coolant 0.1L)</div><div>- Drained lube oil and topped up lube oil PTT Dynamic+(10 Liters).</div><div>- Replace lube oil filter.</div><div>- Checked the alternator belt tension and condition.</div><div>- Checked and tightened the loosen bolts and nuts.</div><div>- Remove exhaust compartment cover and clean radiator by air blower.</div><div>-&nbsp;Replace lube oil pressure sensor.</div><div>- Housekeeping and Test run for 30 minutes.</div><div>- Test run and record the parameters.</div><div><br></div><div><br></div>', 'Found lube oil leaking from pressure sensor housing.', '2023-01-02 17:56:48', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8320-PACKAGE', 'ATL-BV2-G-8320-PACKAGE', 'Gen, ZBV2 Diesel Generator package2', NULL, NULL, 'Gen, ZBV2 Diesel Generator package2', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

