DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform MPM on G-8310 at ZBV#2', 'Mechanic', 'PM', 'Completed', '2023-01-02', '<div>Work Steps:</div><div><br></div><div>- Checked and cleaned the air filter and filter housing.</div><div>- Checked the air service indicator.</div><div>- Checked the coolant level and the radiator cap condition.</div><div>- Checked lube oil level and condition.</div><div>- Checked the alternator belt tension and condition.</div><div>- Checked and tightened the loosening bolts and nuts.</div><div>-&nbsp;Replaced fuel filter.</div><div>- Housekeeping and Test run for 30 minutes.</div><div>- Test run and record the parameters.</div>', 'Found voltage drop when fuel solenoid valve operate. Change cable connection point and pressure value is stable.', '2023-01-02 18:01:02', '2023-01-02 18:14:47', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
