-- Inserting report ID 10006
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verified low lube oil G-8320', 'Electrical & Instrument', 'CM', 'Completed', '2023-01-02', '<p><u>As Found</u></p><p>Lube oil reading around 2bar.</p><p>Found small lube oil leak at lube oil switch.</p><p><u>Verifying Steps</u></p><p>Measured resistance of lube oil switch. (85 Ohm)</p><p><span style="background-color: rgb(255, 255, 0);">Remark: </span>85 ohm is equivalent to approx; 4 bar. Lube oil switch is normal but with some lube oil leakage.</p><p>Replaced new lube oil and measured resistance. (85 Ohm)</p><p>Lube oil reading is still around 2 bar.</p><p>Added negative cable to controller power supply directly from battery negative for better grounding system.</p><p><span style="background-color: rgb(255, 255, 0);">Remark;</span> positive cable was already added to prevent voltage dropped before this problem happened.</p><p>Test run the engine and Lube oil reading is increased to 3.5 bar.</p><p>Lube oil reading is back to normal range.</p><p><br></p><p><br></p>', NULL, '2023-01-02 18:05:23', '2023-01-02 18:34:13', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8320-PACKAGE', 'ATL-BV2-G-8320-PACKAGE', 'Gen, ZBV2 Diesel Generator package2', NULL, NULL, 'Gen, ZBV2 Diesel Generator package2', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

