-- Inserting report ID 10009
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verified G-8310 low lube', 'Electrical & Instrument', 'CM', 'Completed', '2023-01-02', '<p><u>As Found</u></p><p>Controller shows lube oil pressure around 2bar when fuel solenoid energizes.</p><p>In normal running, controller shows around 3.2bar.</p><p><span style="background-color: rgb(255, 255, 0);">Remark;</span> lube oil pressure drops around 1bar when fuel solenoid activates.</p><p><br></p><p><u>Performing steps</u></p><p>Added negative cable for controller power supply directly from battery switch for better grounding system.</p><p>Test run and lube oil reading is around 3.1bar.</p><p><span style="background-color: rgb(255, 255, 0);">Remark;</span> lube oil pressure 0.6 bar dropped when fuel solenoid activates. It reads 2.5bar</p><p><span style="background-color: rgb(255, 255, 0);">Recommend;</span> Positive cable should be added to controller power supply directly from battery at M1 breaker.</p><p><u><br></u></p><p><br></p>', NULL, '2023-01-02 18:31:16', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Elec-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
