  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '3MPM CAT Backhoe Loader', 'Mechanic', 'PM', 'Completed', '2023-01-04', '<p>Work Steps:</p><p><br></p><p>1.&nbsp; &nbsp; Replace engine air cleaner assembly.</p><p>2.&nbsp; &nbsp; Replace engine lube oil and filter.</p><p>3.&nbsp; &nbsp; Replace diesel fuel/water separator filter.</p><p>4.&nbsp; &nbsp; Replace cabin air filter.</p><p>5.&nbsp; &nbsp; Check engine coolant level and top up. (0.75L)</p><p>6.&nbsp; &nbsp; Check grease condition and grease fittings.</p><p>7.&nbsp; &nbsp; Clean engine radiator by air.</p><p>8.&nbsp; &nbsp; Check battery condition by battery tester.</p><p>9.&nbsp; &nbsp; Function test.</p><p>10.&nbsp; Housekeeping.&nbsp;&nbsp;</p><p><br></p>', 'Found diesel cap is locked but is in open position. Make cap open/close procedure and inform logistics.', '2023-01-04 15:41:39', '2023-01-04 18:02:12', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
