-- Inserting report ID 10032
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot G-8310 charging voltage low', 'Mechanic', 'CM', 'Completed', '2023-01-08', '<p>Work steps:</p><p><br></p><p>1.&nbsp; &nbsp; Test run G-8310 by manual/local without load and check alternator charging voltage. ( 12.7 V)</p><p>2.&nbsp; &nbsp; Compare with G-8320 charging voltage. (13.5V)&nbsp;</p><p>3.&nbsp; &nbsp; Perform electrical isolation.</p><p>4.&nbsp; &nbsp; Remove the radiator fan guard and check the belt tension.&nbsp;</p><p>5.&nbsp; &nbsp; Found radiator fan is installed in the wrong direction.</p><p>6.&nbsp; &nbsp; Remove the radiator fan and install it back in to correct direction.</p><p>7.&nbsp; &nbsp; Remove the downgrade charger alternator.</p><p>8.&nbsp; &nbsp; Install a new charger alternator.</p><p>9.&nbsp; &nbsp; Adjust alternator belt tension.</p><p>10.&nbsp; Reinstall the radiator fan guard.</p><p>11.&nbsp; Test run and check alternator charging voltage. (14.1 V)</p><p>12.&nbsp; &nbsp;Stop and ask CCR to start and take load.</p>', NULL, '2023-01-08 13:47:07', '2023-01-09 06:37:53', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
