BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Recondition Portable Air Compressor', 'Mechanic', 'CM', 'Completed', '2023-01-13', '<p>Work Steps:</p><p><br></p><p>1.&nbsp; &nbsp; Install 3 phase socket to portable air compressor.</p><p>2.&nbsp; &nbsp; Remove and clean air filters.</p><p>3.&nbsp; &nbsp; Remove and clean crankcase breather.</p><p>4.&nbsp; &nbsp; Test run and check conditions.</p><p>5.&nbsp; &nbsp; Found motor rotation is incorrect.</p><p>6.&nbsp; &nbsp; Belts are in bad condition.</p><p>7.&nbsp; &nbsp; Replace compressor oil. (Azolla ZS 46 1.5L)</p><p>8.&nbsp; &nbsp; Replace new belts and adjust tension.</p><p>9.&nbsp; &nbsp; Correct motor rotation.&nbsp;</p><p>10.&nbsp; Test run and check cut in 0.75Mpa and cut out 1.05 Mpa.</p><p>11.&nbsp; &nbsp;Housekeeping.</p>', NULL, '2023-01-13 17:29:00', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
