  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot unable to start Kobelco MiniExcavator', 'Mechanic', 'CM', 'In Progress', '2023-01-13', '<p>&nbsp; &nbsp; &nbsp; &nbsp; Received information about loosening the crawler chain at GRS station, </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;then go and adjust tension in Kobelco (Completed)<br></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p>  <p>· Received information about being unable to start Kobelco Mini Excavator at GRS, then go and t</p><p>troubleshoot </p><p><br></p><p>-Check Battery Voltage (12.8V) , Battery CCA (645 CCA) found normal&nbsp;</p><p>-Check Fuses for each fuse connection and resistance - normal&nbsp;</p><p>-Try to start the starter and heard no sound from the motor shaft rotating&nbsp;</p><p>-Pull the ignition switch and hit the motor brush area by the mallet, found some rotating of the starter&nbsp;</p><p>-After hitting about 2 minutes, the motor starting is coming back&nbsp;</p><p>-Drive and move to ZOC workshop&nbsp;</p><p>-Remove the starter motor from the vehicle&nbsp;</p><p>-</p><p><br></p>', NULL, '2023-01-13 17:55:08', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-EXCAVATOR-01', 'ATL-OC-EXCAVATOR-01', 'Mini Excavator-KOBELCO', NULL, NULL, 'Mini Excavator-KOBELCO', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

