  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2MPM of Instrument Air compressor IA-8980A.', 'Mechanic', 'PM', 'Completed', '2023-01-16', '<p>Preformed 2MPM on Instrument Air Compressor A-8980A.</p><p>Job Steps;</p><p><br></p><p>- Performed Electrical and Process Isolation.</p><p>- Checked Belt tension and alignment. Belts were not replaced.</p><p>- Checked the air filter, removed and cleaned with compressed air.</p><p>- Checked lube oil and replaced with new lube oil; 4 Liters.</p><p>- Checked the leakage and connection hoses.</p><p>- Checked the tightening of the fasteners.</p><p>- Cleaned the air compressor unit and tidying.</p><p>- Housekeeping</p><p>-&nbsp; De-isolate ;Test ran and checked the condition.</p><p>- Found no abnormal conditions.</p><p>- Visual checked and job was finished.</p>', NULL, '2023-01-16 16:04:52', '2023-01-16 16:15:11', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
