-- Inserting report ID 10080
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TC1 Differential Gear replacement', 'Mechanic', 'CM', 'Completed', '2023-01-18', '<p>TC1 Differential Gear replacement</p><p>Job Steps;</p><p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Lift the rear chassis part by two car jacks </p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Drain the gear oil </p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove the drive shaft both side </p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Marking the joint </p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Measure and record on paper of flange </p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Detach and remove the propeller shaft </p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Lose the bolt tightening in gear box cover </p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Place the tire under gear box by pallet jack </p><p>9.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove the bolt and left 2 bolts to hold </p><p>10.&nbsp;&nbsp; Hold the gear box and drop down to the tire area </p><p>11.&nbsp;&nbsp; Cleaning the gasket area and inside of gear box </p><p>12.&nbsp;&nbsp; Cover the gear box by plastic </p><p>13.&nbsp;&nbsp; Compare new and old gear box </p><p>                          </p><p>14.&nbsp;&nbsp; Assembly back the gear back&nbsp;</p><p>15. Test drive</p>', NULL, '2023-01-18 16:09:10', '2023-01-19 17:09:34', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-TC-01', 'ATL-OC-TC-01', 'Truck Crane-01 ISUZU FTR240 / UNIC V550', NULL, NULL, 'Truck Crane-01 ISUZU FTR240 / UNIC V550', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

