  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Workshop air compressor PM', 'Mechanic', 'PM ', 'Completed', '2023-01-19', '<p>Working Orders:</p><p>-Electrical isolation.</p><p>-Checked belt tension and condtion.</p><p>-Drained water from the tank.</p><p>-Depressurized the tank.</p><p>-Checked and cleaned the air filter.</p><p>-Tightened motor and compressor mounting bolts nuts.</p><p>-Cleaned air cooled radiator by pressurized air.</p><p>-Housekeeping the compressor unit.</p><p>-Electrical deisolation and test run.</p><p>-Recorded cut in/off pressure. (85 psi and 115 psi).</p>', 'It takes 8 min 40 Sec to reach cut off pressure from 0 psi.', '2023-01-19 16:47:39', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTH', 'OTH', 'Other', NULL, NULL, 'Other', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
