-- Inserting report ID 10084
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TC-2 install differential gear box from TC-1 used ', 'Mechanic', 'CM', 'Completed', '2023-01-19', '<p>After replacing new gear box to TC-1, there is a used differential gear box to install in TC-2.&nbsp;</p><p><br></p><p>Remove both axle drive shaft&nbsp;</p><p>Cleaning inside gear box&nbsp;</p><p>cleaning propeller shaft&nbsp;</p><p>install differential gear box&nbsp;</p><p>Tight the torque with Air Gun Small torque number&nbsp; ( No-1, No-2, No-3 , and No-3 round)&nbsp;</p><p>Bolt size is M-14 x 1.5 thread. machine bolt&nbsp;</p><p>Wrench socket used long socket 22 mm.&nbsp;</p><p>Recharged battery&nbsp;</p><p>found low battery CCA both ( 256 CCA )&nbsp;</p><p>Found defective jumper cable and replace new cable&nbsp;</p><p><br></p><p>Try to test drive, found clutch couldn''t energize and found low clutch fluid (dot-3)&nbsp;</p><p>Top up clutch fluid (by Brake fluid Dot 3)&nbsp;</p><p>release air&nbsp;</p><p>Test drive&nbsp;</p><p><br></p><p>-</p>', NULL, '2023-01-19 17:09:08', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-TC-02', 'ATL-OC-TC-02', 'Truck Crane-02 ISUZU FTR240 / UNIC V550', NULL, NULL, 'Truck Crane-02 ISUZU FTR240 / UNIC V550', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

