  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 2K PM G-8930', 'Mechanic', 'PM', 'In Progress', '2023-02-02', '<p>Working steps,</p><p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Drain the coolant for raw water and jacket water tank.</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Check and clean the air filters.</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replace new breather filters from A and B banks.</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Check the alternator belt condition and tension.</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replace the new inlet fuel filter.</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Top up coolant and flush with new coolant.</p><p>            </p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Fill up coolant to raw water and jacket water tank (360 Liters)</p>', NULL, '2023-02-02 17:06:20', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
