  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace new Helium Cylinder No.4 at AIT-84307', 'Electrical & Instrument', 'CM ', 'Completed', '2023-02-03', '<p>Perform Helium cylinder replacement on AIT-84307 (No.4)</p><p>Inform MOGE Rep. person to replace Helium cylinder by email</p><p>Check the pressure of old Helium cylinder about 350 psi</p><p>Inform CCR to change the OGC from AIT-84307 in used auto mode to AIT-84306 in used manual mode</p><p>Replace the new Helium cylinder and purge the gas from vent</p><p>Set the outlet pressure about <span style="background-color: rgb(255, 255, 0);">115 psi</span> with pressure regulator at cylinder <span style="background-color: rgb(255, 255, 0);">no.4.</span></p><p>Set the outlet pressure about <span style="background-color: rgb(255, 255, 0);">200 psi</span> with pressure regulator at cylinder <span style="background-color: rgb(255, 255, 0);">no.3</span>.</p><p>Check the leak with snoop at every joint of tubing and cylinder head.</p><p>Inform CCR to change back to AIT-84307 in used auto mode.</p><p><br></p>', NULL, '2023-02-03 19:25:31', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-AIT-84307', 'ATL-MS-AIT-84307', 'Gas chromatograph to metering.N2and CO2', NULL, NULL, 'Gas chromatograph to metering.N2and CO2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

