-- Inserting report ID 10128
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S G-9120 Sd Hi eng./oil tp alarm', 'Electrical & Instrument', 'CM ', 'Completed', '2023-02-04', '<p>Troubleshoot G-9120 Sd Hi eng./ Oil tp alarm and cannot start</p><p>As found: During performing weekly test run G-9120 shows alarm Sd Hi eng./ Oil tp and tripped</p><p>Isolate the electrical power from switch gear room</p><p>Check and measure the connection of 16 and 5 of low jacket water level switch, R= 0.7 Ohms</p><p>Check the coolant water level at coolant tank</p><p>Check and measure the resistance of Lube Oil Temperature sensor R= 759 Ohms</p><p>Check and measure the resistance of Lube Oil Pressure, Eng Temp and Oil Temp sensors</p><p> (R= 130.1 Ohm for each)</p><p>Deisolate the electrical power and process gas valve isolation</p><p>Test run and record the parameters.</p><p>&nbsp;</p>', NULL, '2023-02-05 00:14:14', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9120-PACKAGE', 'ATL-MS-G-9120-PACKAGE', 'Gen, ZMS Gas Generator package3', NULL, NULL, 'Gen, ZMS Gas Generator package3', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

