-- Inserting report ID 10131
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Monthly PM Generator G-8010', 'Electrical & Instrument', 'PM', 'Completed', '2023-02-06', '<p>- Performed 1MPM on diesel generator G-8010.</p><p>- As-found</p><p>&nbsp; &nbsp; - The generator can''t crank. &gt;&gt; the control module showed alarm " SD ExbatteryFlat"</p><p>&nbsp; &nbsp; - Checked found the output sensing cable B02 loosen. &gt;&gt; already done.</p><p>&nbsp; &nbsp; - Checked the starting motor solenoid. &gt;&gt; Normal.</p><p>&nbsp; &nbsp; - Checked the "CR" relay. &gt;&gt; normal.</p><p>&nbsp; &nbsp; - Found the battery voltage drop lower than 6 Vdc. (cranking time). &gt;&gt; Control module S/D.</p><p>- Swap the starting battery with the unit G-8020. &gt;&gt; the generator unit G-8010 back to normal.</p><p>- Installed the battery for permanent.</p><p>- Performed 1M-PM as normal.</p><p>- Test run with local and remote.</p><p>- Done.</p>', NULL, '2023-02-06 16:52:02', '2023-02-09 17:05:57', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010-PACKAGE', 'ATL-BV1-G-8010-PACKAGE', 'Gen, ZBV1 Diesel Generator package1', NULL, NULL, 'Gen, ZBV1 Diesel Generator package1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8020', 'ATL-BV1-G-8020', 'Gen, ZBV1 Diesel generator No2', NULL, NULL, 'Gen, ZBV1 Diesel generator No2', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

