  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify P-8860 Jockey pump running frequently', 'Mechanic', 'CM', 'Under Monitoring', '2023-02-10', '<p>Working steps,</p><p>- Isolated the inlet valve of the jockey pump to monitor the water seeping from the upstream drain valve of the check valve. (Found leaking)</p><p>- Then isolate the outlet of the jockey pump.</p><p>- Drain the water from the line.</p><p>- Remove the check valve cover.</p><p>- Remove the hinge pin and remove the hinge.</p><p>- Remove the cotter pin and remove the nut.</p><p>- Remove the Disc and check the condition.</p><p>- Clean the disc with WD-40.</p><p>- Install the Hinge pin and hinge.</p><p>- Change the new spiral wound gasket of the check valve cover.</p><p>- Open the downstream gate valve to check the water seeping from the check valve.(Found leak rate is fewer and only droplets, 1 min around 50 droplets)</p>', NULL, '2023-02-10 17:54:28', '2023-02-10 18:16:06', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
