  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-P-8860-ASSY', 'ATL-OC-P-8860-ASSY', 'ZOC Fire Water Jockey Pump Assembly', NULL, NULL, 'ZOC Fire Water Jockey Pump Assembly', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
