-- Inserting report ID 10160
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace new flow meter at diesel offloading system', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2023-02-12', '<p>Replace the new flow meter M-90651 at diesel offloading system</p><p>Isolate the 24V DC power from ITR room</p><p>Remove the fuse PAI-84012-1 at PMC-01 from ITR room</p><p>Isolate the valve for process isolation and drain the diesel inside the container</p><p>Remove the old flow meter (defective one)</p><p>Check and measure the 24 VDC power at local terminal junction box<br></p><p>Disconnect the power cable at local terminal junction box</p><p>Disconnect the ground cable for body of flow meter</p><p>Remove the used stud and spiral wound gasket</p><p>Install the new 2" Class#150 spiral wound gasket and new stud&nbsp;</p><p>Mounted the new flow meter LWGY Trubine Flow Meter</p><p>Check and measure the diameter and stud length for dimention witn flang</p><p>De-isolation the power from ITR room and measure the voltage (23.8 VDC)</p><p>Check and measure the voltage at local flow meter connection terminal</p><p>Check the display screen and parameter of the flow meter</p><p>De-iolate the vale for process isolation for diesel transfer system</p><p><br></p>', NULL, '2023-02-12 18:40:34', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-FIT-90651', 'ATL-MS-FIT-90651', 'Flow Transmitter on M-9065', NULL, NULL, 'Flow Transmitter on M-9065', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

