  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 2K PM on G-8920', 'Mechanic', 'PM', 'In Progress', '2023-02-21', '<p>Working Steps;</p><p>- Isolations and toolbox talk</p><p>- Checked and removed rocker arm covers and cleaned.</p><p>- Performed valve clearance checking.</p><p>- Found some rocker''s arms needed to be adjusted.</p><p>- Adjusted the valve clearance to 0.4mm as per the manufactured recommendation.</p><p>- Tightened the rocker''s arms lock nuts with proper torque 50 Nm.</p><p>- Tightened the rocker box covers with torque 20 Nm.</p><p>- Changed new inlet fuel filter.</p><p>- Checked and cleaned breather filters.</p><p>- Changed alternator belt.</p><p>- Housekeeping and end of Day 1.</p>', NULL, '2023-02-21 17:29:32', '2023-02-21 17:52:07', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
