-- Inserting report ID 10197
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Weekly inspection PM and test run of G-9110', 'Mechanic', 'PM ', 'Completed', '2023-02-24', '<p><b>Description: Performed weekly inspection PM and test run of Gas Engine Generator G-9110.</b></p><p><br></p><p><b><u>Working steps:</u></b></p><p>-Checked lube oil level and coolant level.</p><p><b>-Changed breather filters (both units) and air fitlers (both units).</b></p><p>-Checked radiator caps condition.</p><p>-Vacuum cleaning around the engine generator.</p><p>-Housekeeping around the working area.</p><p><b>-Failed to start the engine with alarm (overspeed and Gas valve fail).</b></p><p>-Able to start the engine with 3rd attempt and test running with shared load for 30 minutes.</p><p><br></p>', NULL, '2023-02-24 14:51:58', '2023-02-24 16:50:16', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
