END $$;

-- Inserting report ID 10198
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace track shoes of Kobelco Mini Excavator', 'Mechanic', 'PM', 'Completed', '2023-02-24', '<p>Work Steps:</p><p><br></p><p>1.&nbsp; &nbsp; Lift the track shoe off the ground.</p><p>2.&nbsp; &nbsp; Locate track shoe master pin.</p><p>3.&nbsp; &nbsp; Place the track shoe master pin near the sprocket.</p><p>4.&nbsp; &nbsp; Take out the master pin and loosen the shoe track by release grease and adjust track adjuster.</p><p>5.&nbsp; &nbsp; Install new track shoes and adjust tension by track adjuster.</p><p>6.&nbsp; &nbsp; Test drive and housekeeping.</p><p><br></p>', 'Keep old track shoes as hot spare at down warehouse.', '2023-02-24 16:46:00', '2023-02-24 16:46:39', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-EXCAVATOR-01', 'ATL-OC-EXCAVATOR-01', 'Mini Excavator-KOBELCO', NULL, NULL, 'Mini Excavator-KOBELCO', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10199
DO $$
DECLARE
  new_report_id INTEGER;
