-- Inserting report ID 10208
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '3MPM on Forklift', 'Mechanic', 'PM', 'Completed', '2023-02-27', '<p><u>Perform 3MPM of Forklift&nbsp;</u></p><p><u>A- Engine Part&nbsp;</u></p><p>Check oil level and oil condition&nbsp;</p><p>Check oil filter and fuel filter - good condition (&nbsp;25-Aug-22 YPM)&nbsp;</p><p>Clean air filter.</p><p>No abnormal sound in starting.</p><p>Clean radiator.</p><p>Check cooler fan and belt.</p><p>Check coolant level.</p><p><br></p><p><u>B. Hydraulic System&nbsp;</u></p><p>Check hydraulic oil condition and level.&nbsp;</p><p>Check hydraulic pump and test running.&nbsp;</p><p>Check hydraulic cylinder and hose connection.</p><p><br></p><p><u>C. Lighting System&nbsp;</u></p><p>Check Front light, reverse light, turning light&nbsp;</p><p>Check horn&nbsp;</p><p>Check battery CCA and found lower than&nbsp; 50%.&nbsp;</p><p>CCA result 306. Original CCA - 750&nbsp;</p><p><br></p><p><u>D. Chassis Part&nbsp;</u></p><p>Check Torque converter oil level&nbsp;</p><p>Check wheel and tires&nbsp;</p><p>Check Brake and parking brake&nbsp;</p><p>Check brake fluid level.</p><p><br></p><p><u>E. Fork Lift part</u></p><p>Check structure and fork condition&nbsp;</p><p>Check lifting color code (orange)</p><p>Check the grease nipple and grease condition.</p><p>Check chain link and tension.</p><p><br></p><p><br></p><p><br></p><p><br></p>', '<p>Battery need to replace because CCA is lower than 50%.</p><p>Original CCA -750 , Testing CCA- 306, Battery installed date - 14-July-2020&nbsp;</p>', '2023-02-27 14:14:22', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-FORKLIFT-01', 'ATL-OC-FORKLIFT-01', 'Operation Forklift-01', NULL, NULL, 'Operation Forklift-01', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

