-- Inserting report ID 10272
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S Air Compressor Unit A and B trip after start', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2023-03-16', '<p>- T/S the Air Compressor unit A and B start run and trip by "Ub" code</p><p><span style="background-color: rgb(255, 255, 0);">- <b>Unit B&nbsp;</b></span></p><p>&nbsp; &nbsp; - Test run by Manual mode found the air comp run for a while and trip.</p><p>&nbsp; &nbsp; - The "PMEO-PR2" showed "Ub" at the display.</p><p>&nbsp; &nbsp; - Measure the output voltage to the motor found Voltage phase 1 and Phase 3 drop to 354 Vac.( normal should be AVG 400 Vac.)&nbsp;</p><p>&nbsp; &nbsp; - In case the output voltage is unbalance between Phase 1-2, 2-3 and 1-3 (Set point = 360 Vac). the&nbsp; PMEO-PR2 and Phase protection will send trip signal immediately.</p><p>&nbsp; &nbsp; <span style="background-color: rgb(231, 99, 99);">- Inspected all connection found the main power cable at the magnetic contactor(Delta contactor) phase 3 was loosen.</span></p><p>&nbsp; &nbsp; - Tighten all connection and clean the magnetic contactor and test run the Air Comp unit B back to normal.</p><p><br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">- <b>Unit A</b>&nbsp;</span></p><p>&nbsp; &nbsp; - Test run by Manual mode found the air comp run for a while and trip.</p><p>&nbsp; &nbsp; - The "PMEO-PR2" showed "Ub" at the display.</p><p>&nbsp; &nbsp; - Measure the output voltage to the motor found Voltage phase 1&nbsp; low output voltage.(lower than the normal).</p><p>&nbsp; &nbsp; - In case the output voltage is low or lost the"PMEO-PR2" detect by unbalance and send trip signal also.</p><p>&nbsp; &nbsp;<span style="background-color: rgb(231, 99, 99);"> - Inspected the magnetic contractor (Delta Contactor) found Phase 1 slot was damage and found a lot of Ants inside.</span></p><p>&nbsp; &nbsp; - Replaced the new Delta contactor and function test&nbsp; by manual and remote the system back to normal.</p><p>- Keep monitor.</p>', 'Delta contactor&nbsp; model = AF-26-30-11 (ABB)', '2023-03-16 16:44:14', '2023-03-16 16:46:23', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Inst-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-C-9300', 'ATL-OC-C-9300', 'Air Compressor', NULL, NULL, 'Air Compressor', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

