BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Support PMO/I YPM on Kobelco Day 1', 'Mechanic', 'PM', 'In Progress', '2023-03-23', '<p>Day 1 of Supporting PMO/I YPM on Kobelco.</p><p>Job Steps;&nbsp;</p><p>-Drain Hydraulic, Coolant, Lube oil, and Diesel.</p><p>-Replaced Hydraulic, Coolant, Lube oil, Diesel, and Air Filters.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;-For Air Filters, cleaned the outer and replaced the inner one with a new one.</p><p>-Top up Hydraulic 33 Liters, Lube Oil 12 Liters, and Coolant 4 Liters.</p><p>-Diesel Line water separator pipe was replaced with a new pipe.</p><p>-The alternator belt was tightened.</p><p>-Found that the fuel filling pipe was worn out and needed to be replaced. (Will order a new one)</p>', NULL, '2023-03-23 17:36:10', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-EXCAVATOR-01', 'ATL-OC-EXCAVATOR-01', 'Mini Excavator-KOBELCO', NULL, NULL, 'Mini Excavator-KOBELCO', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
