  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform monthly Metering Calibration for Tube 2', 'Electrical & Instrument', 'PM ', 'Completed', '2023-03-24', '<div>Perform monthly Metering Calibration for Tube 2.<br></div><div><p>Working steps.</p><p>-Performed Process isolation.</p><p>-Performed Metering Calibration for Tube 2 (M-8420).</p><p>-Calibrated the pressure transmitters by Hydraulic Dead Weight tester A &amp; B</p><p>-Calibrated the flow transmitters by Pneumatic Dead Weight tester A &amp; B</p><p>-Calibrated the temperature transmitters by RTD A &amp; B</p><p>- Replaced temperature transmitters RTD sensor on both unit A&amp;B.</p><p>- Inspected orifice plate by the MOGE.</p><p>-Leak test at connection point and remove the maintenance mode</p><p>-Leak test counter checked by operator (Arkar)</p></div>', NULL, '2023-03-24 16:25:10', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
