-- Inserting report ID 10320
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify & troubleshoot BA-0401', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2023-03-30', '<p>As found: BA-0401 shows <span style="background-color: rgb(255, 255, 0);">travelling status</span> at CCR.</p><p>Check and verify the signal at local condition.</p><p>The voltage signal is not enough the value. (<span style="background-color: rgb(255, 255, 0);">19.0 VDC</span>)</p><p>Check the connection terminals and tighten the screw, some connections are corrected.</p><p>Troubleshoot the valve status with CCR and local. (Open, Close &amp; Travelling position)</p><p>Measure the DC Voltage at open position, the signal shows 23.87 VDC.</p><p>Check the close signal and visual check the magnetic disc surface.</p><p>The <span style="background-color: rgb(255, 255, 0);">magnet surface is not good</span> and remove from the housing.</p><p>Clean the magnet and housing of the close signal circuit.</p><p>Apply the glue (502) between the magnet and housing.</p><p>Put the valve status in close position and confirm the close signal with CCR.</p><p>Measure the DC voltage at close position, the signal shows<span style="background-color: rgb(255, 255, 0);"> 23.30 VDC.</span></p><p>Check and tighten the connection terminals and cover the frame.&nbsp;</p>', NULL, '2023-03-30 18:51:36', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-BA-0401', 'ATL-MS-BA-0401', 'Isolation Valve 28" BA0401 for PR-8400', NULL, NULL, 'Isolation Valve 28" BA0401 for PR-8400', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

