  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '6M PM ZMS Firewater Pump Unit B', 'Mechanic', 'PM ', 'Completed', '2023-04-01', '<p><b><u>Working Steps</u></b></p><p><b><u><br></u></b></p><p>- Checked and cleaned the air filter.</p><p>- Checked and cleaned the breather filter.</p><p>- Checked the turbo charger condition.</p><p>- Checked the lube oil level and its condition.</p><p>- Checked the lube oil leakage.</p><p>- Checked the coolant level and the radiatot cap condition.</p><p>- Checked and cleaned the strainers in the raw water line.</p><p>- Checked the universal joints and greasing.</p><p>- Checked the fuel system and the fuel leakage.</p><p>- Checked the belt tension, Alignment and its tension.</p><p>- Checked and cleaned the alternator.</p><p>- Used the aluminium foil tape to insulate the exhaust.</p><p>- Checked the packing seals condition and the water flow rate for the DE and NDE side.</p><p>- Checked the battery level and CCA.<br></p><p>- Checked and tightened the mounting bolts.</p><p>- Checked and tightened the cover bolts and nuts.</p><p>- Test run and recorded the parameters.</p><p>Checked any abnormalities and housekeeping.</p>', NULL, '2023-04-03 11:25:01', '2023-04-08 20:40:23', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
