-- Inserting report ID 10345
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot industrial socket @ ACEDB-8407-13-01 ', 'Electrical & Instrument', 'CM ', 'Completed', '2023-04-03', '<p>Troubleshoot the industrial socket at ACEDB-8407-13-01 near fire water pump station</p><p><span style="background-color: rgb(255, 255, 0);">As Found</span>: the switch in the frame of industrial socket rotated and not worked proper condition</p><p>Visual check the physical condition of switch and frame of socket</p><p>Check the state of the switch On / Off condition and measure the voltage (230 V)</p><p>Isolate the power and remove the cover plate of the frame</p><p><span style="background-color: rgb(255, 255, 0);">Troubleshooting</span>: Inside the frame, the spring tension is not good and rotate the selector switch, So fixed the screw on the mounted and check the spring tension</p><p>Put back the selector switch and check the physical condition (No Damage)</p><p>Measure the output voltage (230 VAC) and check the On / Off state conditions</p><p>The industrial sockect is work properly and back to normal</p><p><br></p>', NULL, '2023-04-03 19:46:32', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTH', 'OTH', 'Other', NULL, NULL, 'Other', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

