  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-TIT-81204A', 'ATL-OC-TIT-81204A', 'TIT,16"PG-81010 downstream of PV-8120A', NULL, NULL, 'TIT,16"PG-81010 downstream of PV-8120A', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
