-- Inserting report ID 10350
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Performed YPM on G-8310', 'Mechanic', 'PM', 'Completed', '2023-04-05', '<p>Working steps,</p><p>- Start the generator for warming up.</p><p>- Drain lube oil.</p><p>- Drain coolant.</p><p>- Remove radiator cover and fan belt.</p><p>- Remove radiator and pulley.</p><p>- Remove air filter housing.</p><p>- Remove rocker arm box cover.</p><p>- Check and adjust valve clearance. (14N.m for lock nut)</p><p></p><p>- Change new lube oil filter, fuel filter and water separator.</p><p>- Top up lube oil 10 L and coolant 7L.</p><p>- Clean the radiator cover and radiator fan by water jet.</p><p>- Install rocker arm box cover. (14N.m for 14mm and 10N.m for 10mm)</p><p>- Change radiator fan belt.</p><p>- Install radiator and radiator cover.</p><p>- Test run and check abnormal noise.</p><p>- Record the generator parameter.</p>', 'Found coolant leakage from ball valve of coolant drain line. So replaced with new ball valve.', '2023-04-05 18:03:26', '2023-04-06 15:27:28', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

