  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-HOV-81011', 'ATL-OC-HOV-81011', 'HOV on 28"-PG-81042,ZTK BV#2 to PL2', NULL, NULL, 'HOV on 28"-PG-81042,ZTK BV#2 to PL2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
