  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Fix JCB steering cylinder seal damage', 'Mechanic', 'CM', 'In Progress', '2023-04-09', '<p>1. Parked at the intervention truck parking.</p><p>2. Removed cotter pin of left and right ball joint lock nut.</p><p>3. Removed ball joint lock nuts (30 mm) and take out the left and right ball joints.</p><p>4. Removed the 4 bolts(30 mm) of steering cylinder housing frame.</p><p>5. Removed two hydraulic hoses which are connected to the steering cylinder (22 mm).</p><p>6. Bring the steering cylinder to the ZOC workshop.</p>', NULL, '2023-04-09 18:00:07', '2023-04-09 18:16:07', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-JCB-01', 'ATL-OC-JCB-01', 'Backhole Loader-JCB', NULL, NULL, 'Backhole Loader-JCB', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
