-- Inserting report ID 10370
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Install new DB in the dry store container', 'Electrical & Instrument', 'CM ', 'Completed', '2023-04-09', '<p>Install new distribution box (DB) &amp; circuit breaker inside the dry store container</p><p>As Found: the old type circuit is not match and installed not proper design; </p><p>(Used 3 phase circuit breaker for single phase circuit)</p><p>Isolate the power from the source electrical panel (self isolation)</p><p>Remove the old circuit breaker 3 phase circuit breaker</p><p>Install the new distribution box (DB) inside the container</p><p>Install the new single phase circuit breaker and connect the load wire</p><p>De-isolate the power and test the circuit with new circuit breaker</p><p>&nbsp;</p>', NULL, '2023-04-09 18:09:21', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-LIGHTING', 'ATL-MS-LIGHTING', 'ZMS ZMS LIGHTING', NULL, NULL, 'ZMS ZMS LIGHTING', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10371
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify the Gen fault alarm @ GD-84007', 'Electrical & Instrument', 'CM ', 'In Progress', '2023-04-09', '<p>Verify the Gen fault alarm at GD-84007 near the gas generator area</p><p>As found: The alarm signal shows Gen fault alarm at CCR panel&nbsp;</p><p>Check the visual inspection at local and shows the yellow light</p><p>Reset the alarm by using with magnet and confirm with CCR</p><p>The alarm still shows and cannot reset the fault signal</p><p>Clean the lens inside the detector housing</p><p>Measure the DC Voltage (22.3 VDC) at local and the value is normal</p><p>Check &amp; measure the DC voltage &amp; mA valuea at ITR Cabinet (ZMS-FSC-01)</p><p>Show the DC Voltage value (23.3 VDC) but mA value is unstable (0.95 mA - 1 mA)</p><p><br></p>', 'Need to troubleshoot GD-84007 and test the magnet&nbsp;', '2023-04-09 18:21:48', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-GD-84007', 'ATL-MS-GD-84007', 'Point type GD in Gas Gen. area', NULL, NULL, 'Point type GD in Gas Gen. area', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

