-- Inserting report ID 10373
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S the diesel generator G-8310 Shutdown trip.', 'Electrical & Instrument', 'CM', 'Completed', '2023-04-10', '<p>- Verify the diesel generator G-8310 Shutdown trip.</p><p>- Found the first alarm at the local is " SD Low Oil Pressure"&nbsp;</p><p>- Test run the generator found the reading value swing 7 - 4 bar even though engine stop the oil pressure&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;reading still at 1.5 bar.</p><p>- Change the new oil pressure.</p><p>- Monitor around 2 hr. at the day time found reading around 3 bar @ coolant temp 75 C.</p><p>- Keep unit run with load.</p><p><br></p>', NULL, '2023-04-10 14:43:31', '2023-04-10 14:49:25', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Inst-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
