  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Fix CAT steering cylinder seal damage', 'Mechanic', 'CM', 'In Progress', '2023-04-11', '<p>1. Parked at the parking.</p><p>2. Removed left and right ball joint lock nut.</p><p>3. Released the six mounting bolts of the steering cylinder (30 mm).</p><p>4. Lifted up the backhoe with the loader and put the hydraulic jack under the front axle.</p><p>5. Removed the battery and taken out the lock pin of the front axle.</p><p>6. Dropped the front axle with hydraulic jack and removed the mounting bolts and the steering cylinder.</p><p>7. Insert the pipe for temporary lock pin and placed on the backhoe and wheel.</p><p><br></p>', NULL, '2023-04-11 16:41:33', '2023-04-11 18:52:57', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
