  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 6 MPM for gas generator G-9120 ', 'Electrical & Instrument', 'PM ', 'In Progress', '2023-04-11', '<p>Perform 6 MPM for gas generator G-9120</p><p><span style="background-color: rgb(255, 255, 0);">Working Steps:</span></p><p>Isolate the FM-200, battery bank, electrical power &amp; process isolation for G-9120</p><p>Check and test the battery banks for both A &amp; B&nbsp;</p><p>Fill up the battery water 10 Litters for both bank A &amp; B</p><p>Check and tighten the connection inside the control panel and Ex proof panel</p><p>Visual check and inspection for FM-200 cylinder and control panel</p><p>Apply the grease for ventilation fan motor at the grease point</p><p>Check the lube oil level and fill up lube oil about 10 Litter</p><p>Clean the dust and deaded insects inside the air ventilation flapper blades</p><p><br></p><p><br></p><p><br></p><p>&nbsp;</p>', NULL, '2023-04-11 19:37:25', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9120-PACKAGE', 'ATL-MS-G-9120-PACKAGE', 'Gen, ZMS Gas Generator package3', NULL, NULL, 'Gen, ZMS Gas Generator package3', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
