  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Assist & Witness for Systech team PSV activities', 'Electrical & Instrument', 'PM ', 'In Progress', '2023-04-12', '<p>Assist and witness for Systech team for annual PSV Campaign&nbsp;</p><p>Perform online test for PSV-90852, PSV-90856 at Diesel strainer and Diesel storage area in the utility area</p><p>Both PSV are passed as found receive pop test, but failed leak test.</p><p>Systech team removed the valves for overhaul test performance and check the results</p><p>Perform online test for PSV-92001 at instrument air receiver tank</p><p>PSV-92001 is passed as found receive pop test, but failed leak test</p><p>Systech team will remove the valve tomorrow and perform overhaul within 1 day shift due to <span style="background-color: rgb(255, 255, 0);">instrument air</span> receiver tank PSV&nbsp;</p><p><br></p><p><br></p>', NULL, '2023-04-12 19:11:49', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
