  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Test run G-9120 after 6 MPM E&I task', 'Electrical & Instrument', 'PM ', 'Completed', '2023-04-12', '<p>Test run the gas generator G-9120 after performing 6 MPM E&amp;I tasks</p><p>De-isolate the power at switch gear room and FM-200 system at local</p><p>Perform de-isolation by operator at dog house and local side</p><p>Test run the gas generator G-9120 about 30 mintues with load share</p><p>Check and inspection for parameter of generator after 6 MPM task</p><p>Record the parameter and event logs inside the job card and sign by ZMS supervisor</p><p>Scan the job card and save in the MPM job record file&nbsp;</p>', '<p>Battery bank 1 can crank but cannot start the engine low battery voltage (19.6 VDC)</p><p>(Need to charge the float charge for battery bank 1)</p><p>Change the charging selector switch to battery bank 1&nbsp;</p>', '2023-04-12 19:26:49', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9120-PACKAGE', 'ATL-MS-G-9120-PACKAGE', 'Gen, ZMS Gas Generator package3', NULL, NULL, 'Gen, ZMS Gas Generator package3', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
