-- Inserting report ID 10385
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot air condition units at canteen', 'Electrical & Instrument', 'OTH ', 'Under Monitoring', '2023-04-12', '<p>Troubleshoot air condition uints in the dinning room at ZMS canteen</p><p>As Found: The flexible drain water pipe was bitten by mouse and dropped the drained water</p><p>Check and inspect the leak point of the air-conditioner for both units in the canteen</p><p>Remove the wrapping tape and insulation pipe and check the leak point at drain</p><p>Consulted by phone with Thitsar vendor team "<span style="background-color: rgb(255, 255, 0);">how to replace the fitting flexible pipe</span>"</p><p>As per vendor recommand, remove the flexible fitting joint between the drained line and suction house</p><p>Replace with new flexible drain pipe and apply with the piping glue between the pipe and drain line</p><p>Test run the air-con and check the leak point again (No leak and drained water go outside to drain system)</p><p>Wrapped with insulation pipe and air condition piping tape after checking no leak the drained water</p><p>&nbsp;</p>', NULL, '2023-04-12 19:44:00', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-AIRCON', 'ATL-MS-AIRCON', 'ZMS AirConditioning System', NULL, NULL, 'ZMS AirConditioning System', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

