-- Inserting report ID 10391
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace the new gas detector GD-84007 ', 'Electrical & Instrument', 'CM ', 'In Progress', '2023-04-13', '<p>Replace the new gas detector GD-84007 shows Gen Fault alarm</p><p>Remove the control fuse and isolate the power from ITR room</p><p>Check and measure the voltage at the GD output ( 0 VDC)</p><p>Disconnect the connection wire at the local GD-84007 terminal</p><p>Disconnect the cable gland and remove the old connection plug</p><p>Remove the old gas detector GD-84007 and compare with new model (Like To Like)</p><p>Install the new gas detector on the frame and check the level by water spirit (Horizontal position)</p><p>Connect the cable gland and connection plug with new Gas Detector</p><p>Connect the connection wire at the terminal and tighten the screw</p><p>Use anti-seal grease on the cover plate to protect the water</p><p>De-isolate the power form the ITR cabinet and check the voltage (23.3 VDC)</p><p>Test the calibration at onside normal calibration process and zero calibration process</p><p>Normal calibration is passed, zero calibration finished, Re-calibrate normal calibration</p><p>After zero calibration test methane gas cylinder is empty</p><p>Need to perform normal calibration again and order the methane gas from ZOC workshop</p><p><br></p><p><br></p><p><br></p>', 'Request new calibration gas cylinder (Methane) from ZOC workshop', '2023-04-13 19:37:04', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-GD-84007', 'ATL-MS-GD-84007', 'Point type GD in Gas Gen. area', NULL, NULL, 'Point type GD in Gas Gen. area', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

