  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Assist & Witness for Systech team PSV activities', 'Electrical & Instrument', 'PM ', 'Completed', '2023-04-16', '<p>Assist and witness for Systech team recertification PSV annual campaign</p><p>Isolate the fire water pump A/B for removing PCV-0446 and PCV-0450 inspection</p><p>Check and measure the as found pop test and leak test</p><p>Record the pressure for pop test and leak test at the PSV</p><p>Perform overhaul inspection activities for the PSV valve body</p><p>After the overhaul, Systech team tests the valve the as left condition (Pass)</p><p>De-isolate the fire water pump A/B and test run for weekly inspection</p>', NULL, '2023-04-16 18:30:15', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
