  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot GD-84007 for Gen Fault alarm', 'Electrical & Instrument', 'CM ', 'Completed', '2023-04-16', '<p>Troubleshoot GD-84007 for Gen fault alarm at CCR monitor</p><p>Replace with new gas detector at (14.04.2023)</p><p>Check and measure the voltage (22.3VDC) at local</p><p>Test with magnet at magnetic testing point of the gas detector</p><p>Calibrate the gas detector with 50%LFL and air gas mixture cylinder</p><p>Show the LED signal flashing RED and off during the gas calibration</p><p>After off the signal, LED light green back and GD-84007 back to normal at CCR</p><p>CCR monitor signal value is (0.06) and nearly the same with other gas detectors</p><p><br></p><p><br></p>', NULL, '2023-04-16 18:38:37', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-GD-84007', 'ATL-MS-GD-84007', 'Point type GD in Gas Gen. area', NULL, NULL, 'Point type GD in Gas Gen. area', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10406
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot inlet ESDV-84000 shows travelling', 'Electrical & Instrument', 'CM ', 'In Progress', '2023-04-16', '<p>Troubleshoot inlet ESDV-84000 shown travelling signal at CCR</p><p>Inform CCR to confirm the valve status of ESDV-84000 (travelling)</p><p>Open the cover of valve positioner status frame</p><p>Check the as found condition and visual inspection</p><p>As Found: one of the <span style="background-color: rgb(255, 255, 0);">magnet is removed</span> and contact with another magnet ( <span style="background-color: rgb(255, 255, 0);">Magnetic error</span>) and magntic point slightly <span style="background-color: rgb(255, 255, 0);">mis-alignment</span> with magnet</p><p>Remove the linking magnet and put back the normal housing</p><p>Exercise the magnet positioner and check the valve status (travelling)</p><p>Measure the output voltage at the positioner terminal (<span style="background-color: rgb(255, 255, 0);">0.0 VDC</span>)</p><p>Put back to the normalize condition and confirm the status with CCR (travelling)</p><p>Continutes troubleshoot the other required conditions for the next day</p><p><br></p>', '<p>Need to check the mis-alignment magnet</p><p>Check the condition of voltage and fuse at ITR cabinet</p>', '2023-04-16 18:54:31', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-ESDV-84000', 'ATL-MS-ESDV-84000', 'ESDV on 28"-PG-83004, ZBV2 to PL2', NULL, NULL, 'ESDV on 28"-PG-83004, ZBV2 to PL2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

