-- Inserting report ID 10408
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'weekly inspection PM and test run of EDG-9120.', 'Mechanic', 'PM ', 'Completed', '2023-04-17', '<p><b>Description: Performed weekly inspection PM and running test on Emergency Diesel Generator EDG-9125.</b></p><p><i><u><br></u></i></p><p><i><u><b>Working Steps</b></u></i></p><p><br></p><p>- Checked and the air filters.</p><p>- Checked the coolant level and radiator cap condition.</p><p>- Checked the lube oil level.</p><p>- Checked the fuel level.</p><p>- Cleaned the diesel engine package.</p><p>- Test run with load for 30 minutes.</p>', NULL, '2023-04-17 17:18:48', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9125-PACKAGE', 'ATL-MS-G-9125-PACKAGE', 'Gen, ZMS Diesel Generator Package', NULL, NULL, 'Gen, ZMS Diesel Generator Package', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10409
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot inlet ESDV-84000 signal error', 'Electrical & Instrument', 'CM ', 'Completed', '2023-04-17', '<p>Troubleshoot inlet ESDV-84000 shows travelling error signal</p><p>As Found: ESDV-84000 shows travelling signal at CCR monitor</p><p>Check the visual inspection for valve positioner status at local (Open Status)</p><p>Open the valve positioner cover plate and check the internal condition</p><p>There is no any other physical damage on the valve stem at local&nbsp;</p><p>Check and inspection for the magnetic proximity switch at local&nbsp;</p><p>Confirm with CCR for the valve status signal as found condition (Travelling)</p><p>Exercise the magnet pointer on the stem for open and close position at proximity switch</p><p>Comfirm with CCR for the valve status signal open position (ZSO-84000) Normally Open signal</p><p>Confirm with CCR for the valve status signal close position (ZSC-84000) Normally Close signal</p><p>The other proximity switch contact with magnet, which is show travelling signal at CCR</p><p>Result: Locate the magnet at open status position (N/O) and confirm with CCR back to normal open signal</p><p>(ESDV-8400 open position)</p><p>Check and measure the voltage signal at ZSO-84000 and ZSC-84000 during testing with magnet</p><p>Clean the terminal plate with contact cleaner and tighten the screw at connection point</p><p>Close the cover plate and check the valve positioner in open status position&nbsp;&nbsp;</p><p><br></p><p><br></p><p>&nbsp;</p>', NULL, '2023-04-17 17:48:54', '2023-04-17 17:54:05', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-ESDV-84000', 'ATL-MS-ESDV-84000', 'ESDV on 28"-PG-83004, ZBV2 to PL2', NULL, NULL, 'ESDV on 28"-PG-83004, ZBV2 to PL2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10410
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Performed 6MPM of Firewater jockey pump P-9055', 'Mechanic', 'PM ', 'Completed', '2023-04-18', '<p><b>Description: Performed 6MPM of firewater pump jockey pump P-9055.</b></p><p><br></p><p><b>Working steps:</b></p><p>-Performed process and electrical isolation.</p><p>-Cleaned and inspected the suction strainer.</p><p>-Checked and inspected the coupling.</p><p>-Checked and inspected the pump and motor mounting bolts.</p><p>-Opened the junction terminal box and checked wiring terminal if it has any looseness.</p><p>-Performed process and electrical de-isolation.</p><p>-Auto test run by pressure switch activated.</p><p>-Put the unit in Auto mode.</p>', NULL, '2023-04-18 14:02:19', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-P-9055', 'ATL-MS-P-9055', 'ZMS Fire Jockey Pump', NULL, NULL, 'ZMS Fire Jockey Pump', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

