-- Inserting report ID 10412
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TC 2 Fixed hydraulic seeping from tank drain plug', 'Mechanic', 'CM', 'Under Monitoring', '2023-04-18', '<p>Work steps:</p><p><br></p><p>1.&nbsp; &nbsp; Suck out the hydraulic oil from the tank and keep it in containers to reuse.</p><p>2.&nbsp; &nbsp; Remove the drain plug.</p><p>3.&nbsp; &nbsp; Found the drain plug copper washer is damaged.</p><p>4.&nbsp; &nbsp; Replace the copper washer.</p><p>5.&nbsp; &nbsp; Reinstall the drain plug.</p><p>6.&nbsp; &nbsp; Refill the hydraulic oil.</p><p>7.&nbsp; &nbsp; Function test.</p><p>8.&nbsp; &nbsp; Found no seeping.</p>', NULL, '2023-04-18 17:37:10', '2023-04-19 17:38:37', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-TC-02', 'ATL-OC-TC-02', 'Truck Crane-02 ISUZU FTR240 / UNIC V550', NULL, NULL, 'Truck Crane-02 ISUZU FTR240 / UNIC V550', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10413
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace with new pressure gauge PG-84005 A ', 'Electrical & Instrument', 'CM ', 'Completed', '2023-04-18', '<p>Replace with new pressure gauge PG-84005 A at Pig Receiver area</p><p>As Found: The pressure gauge, PG-84005 A was <span style="background-color: rgb(255, 255, 0);">damaged the mirror</span> glasses at pig receiver area&nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">Working steps:</span></p><p>Isolate the inlet line pressure at PG-84005 A&nbsp; and vent the process gas inside the tubing</p><p>Remove the old pressure gauge with hand tools&nbsp;</p><p>Check and clean the tapping point and internal thread</p><p>Replace with new pressure gauge PG-84005 A</p><p>Close the vent and de-isolate the isolation valve for line up&nbsp;</p><p>Check the leak test with snoop at connection point</p><p>As Left: Replace with <span style="background-color: rgb(255, 255, 0);">new pressure gauge</span> and i<span style="background-color: rgb(255, 255, 0);">solate the valve</span> again because of using in Pig receiving period</p><p>&nbsp;</p>', NULL, '2023-04-18 18:14:09', '2023-04-18 18:16:10', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTH', 'OTH', 'Other', NULL, NULL, 'Other', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

