  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'PM and test run DG-02 and DG-03', 'Mechanic', 'PM', 'Completed', '2023-04-19', '<p>Work Steps:</p><p><br></p><p>1.&nbsp; &nbsp;Check lube oil and coolant level.</p><p>2.&nbsp; &nbsp;Check the diesel fuel level.</p><p>3.&nbsp; &nbsp;Check overall condition.</p><p>4.&nbsp; &nbsp;Check belt condition and tension.</p><p>5.&nbsp; &nbsp;Clean the engine with air.</p><p>6.&nbsp; &nbsp;Prime fuel.</p><p>7.&nbsp; &nbsp;Install the battery.</p><p>8.&nbsp; &nbsp;Start and test run and record parameters</p>', NULL, '2023-04-19 15:15:08', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTH', 'OTH', 'Other', NULL, NULL, 'Other', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

