  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'PM on air compressor at workshop', 'Mechanic', 'PM', 'Completed', '2023-04-20', '<p>Work Steps:</p><p><br></p><p>- &nbsp;&nbsp;&nbsp;&nbsp;Perform self-electrical isolation and tag.<br></p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Checked and cleaned the air filter.</p><p>- &nbsp;&nbsp;&nbsp;&nbsp;Checked the compressor oil level and condition.</p><p>-&nbsp; &nbsp; &nbsp;Replace compressor oil.</p><p>- &nbsp;&nbsp;&nbsp;&nbsp;Checked the belt condition and tension.</p><p>- &nbsp;&nbsp;&nbsp;&nbsp;Checked the pulley alignment.</p><p>- &nbsp;&nbsp;&nbsp;&nbsp;Checked the mounting bolt''s tension.</p><p>- &nbsp;&nbsp;&nbsp;&nbsp;Checked the hose connection.</p><p>- &nbsp;&nbsp;&nbsp;&nbsp;Checked any loosening bolts and nuts.</p><p>- &nbsp;&nbsp;&nbsp;&nbsp;Test Run and check leak by snoop. (Cut In 80 Psi, Cut out 120 Psi)</p><p>-&nbsp;&nbsp;&nbsp;&nbsp; Housekeeping.</p>', NULL, '2023-04-20 14:34:03', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
