BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Fix air seeping from accumulator of TC-1', 'Mechanic', 'CM', 'Under Monitoring', '2023-04-20', '<p>Work Steps:</p><p><br></p><p>1.&nbsp; &nbsp; Fully drain air from the tank.</p><p>2.&nbsp; &nbsp; Mark and remove the accumulator housing.</p><p>3.&nbsp; &nbsp; Remove seals and clean the housing.</p><p>4.&nbsp; &nbsp; Apply dow coning grease to seals.</p><p>5.&nbsp; &nbsp; Reinstall the housing.</p><p>6.&nbsp; &nbsp; Test run and check air leak by snoop.</p><p>7.&nbsp; &nbsp; Found no leak.</p>', '<p>-Replace both horns and reposition to prevent from mud.</p><p>-Replace defective blind spot mirror.</p>', '2023-04-20 14:41:24', '2023-04-20 14:52:33', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
