BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform calibration & orifice inspection @ Tube-3', 'Electrical & Instrument', 'PM ', 'Completed', '2023-04-20', '<p>Perform monthly Metering Calibration and Orifice plate inspection for Tube 3&nbsp;</p><p>Working steps.</p><p>-Performed Process isolation.</p><p>-Performed Metering Calibration for Tube 3 (M-8425).</p><p>-Calibrated the pressure transmitters by Hydraulic Dead Weight tester A &amp; B</p><p>-Calibrated the flow transmitters by Pneumatic Dead Weight tester A &amp; B</p><p>-Calibrated the temperature transmitters by RTD A &amp; B</p><p>-Performed Orifice plate inspection with MOGE Rep., ZMS Maintenance Technician (E&amp;I)</p><p>-Leak test at connection point and remove the maintenance mode</p><p>-Leak test counter checked by operator (Rain)</p>', 'Check the orifice plate surface and signed by MOGE Rep., E&amp;I Tech', '2023-04-20 20:35:39', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
