-- Inserting report ID 10420
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '6MPM on Two Post Car Lift', 'Mechanic', 'PM', 'Completed', '2023-04-21', '<div>Work Steps:</div><div><br></div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Test the EMG button and power off the breaker.<br></div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Checked the bolts at the base of the 2 posts and check with the torque&nbsp;100NM. ( Size 30)</div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Checked the mechanical lock, primary lock, and secondary lock and test those locks.</div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Checked the hydraulic hose connection and condition.</div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Checked the mechanical jaw''s condition.</div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Checked the car holder''s leg condition.</div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Tested without load.</div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Checked the leakage of the hydraulic system, and the condition of the lifting jaws and wire rope.</div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Checked the safety locks; working properly or defects and spring condition.</div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Checked the shaft, leakage, and steel wire rope condition.</div><div>-&nbsp;&nbsp;&nbsp;&nbsp;Performed exercising the lifting jaws, and performed final visual check around the equipment.</div><div>-&nbsp; &nbsp; Function test limit switch.</div>', 'Found some oil on the base of the post(Pump side) clean it and keep monitoring the oil level.', '2023-04-21 14:51:40', '2023-04-21 14:52:03', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-CARLIFT', 'ATL-OC-CARLIFT', 'ZOC Carlift', NULL, NULL, 'ZOC Carlift', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

