  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Measure internal resistance of battery @ G-9120', 'Electrical & Instrument', 'CM ', 'Completed', '2023-04-25', '<p>Measure the internal resistance of the gas generator battery @ G-9120</p><p>Isolate the power from the switchgear room</p><p>Isolate the battery banks for each side of the unit A/B</p><p>Check the battery water level and saturation with hydrometer</p><p>Measure the CCA of the each battery bank A/B</p><p>Measure the battery internal resistance values for each battery</p><p>Check &amp; tighten the wire at battery terminal plates</p><p>Deisolate the power and test run the generator about 30 mintues</p><p><br></p><p><br></p>', '<p>As found: The two terminal wire nuts are over tighten and damaged</p><p>Remove the old nuts and replace with new nuts.</p>', '2023-04-25 18:49:32', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9120-PACKAGE', 'ATL-MS-G-9120-PACKAGE', 'Gen, ZMS Gas Generator package3', NULL, NULL, 'Gen, ZMS Gas Generator package3', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
