  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 1MPM of G-8010 ', 'Mechanic', 'PM', 'Completed', '2023-05-05', '<p style="text-align: left;"><span style="background-color: rgb(255, 255, 0);">Remark : found coolant seeping under heater and around water pump&nbsp;</span></p><p><br></p><p>Perform Monthly PM of the generator,&nbsp;</p><p><br></p><p>-Check the fuel line&nbsp;</p><p>-Check coolant and found losing, top up about 0.7 Liter</p><p>-Check the air filter and found dirty, replace new air filter&nbsp;</p><p>-Check lube oil and found drop, top up about 0.5 liter&nbsp;</p><p>-Check belt and found losing, perform belt tension tighten&nbsp;</p><p>-Check bolts&nbsp;</p><p>-Check host and fitting, found coolant seeping around the water pump&nbsp;</p><p>-Check host and fitting found coolant seeping under heater ( jubilee clamp loosen)&nbsp;</p><p><br></p>', '<p>Low lube oil pressure and high coolant temp alarm appear&nbsp;</p><p>Check host and fitting, found coolant seeping around the water pump&nbsp;</p><p>-Check host and fitting found coolant seeping under heater ( jubilee clamp loosen)&nbsp;</p><p>-High exhaust temp compare with other generators</p><p><br></p>', '2023-05-05 18:04:35', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010-PACKAGE', 'ATL-BV1-G-8010-PACKAGE', 'Gen, ZBV1 Diesel Generator package1', NULL, NULL, 'Gen, ZBV1 Diesel Generator package1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
