-- Inserting report ID 10477
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'CM Fix diesel seeping of ZMS diesel dispenser ', 'Mechanic', 'CM', 'Under Monitoring', '2023-05-06', '<p>Operator notify by SAP about diesel seeping from the diesel dispenser.&nbsp;</p><p><br></p><p>Perform electrical and process isolation.&nbsp;</p><p>-Remove cover both side (found cover lock was damage)&nbsp;</p><p>-verify seeping point, found two point: before and after of diesel filter gasket&nbsp;</p><p>- remove filter joint line&nbsp;</p><p>-cleaning the thread and surface&nbsp;</p><p>- make new gasket by Non cuff paper Klinger 4300 gasket&nbsp;</p><p>-Install new gasket and perform bolt tightening uniformly&nbsp;</p><p>-deisolate diesel line and found diesel seeping from the installed gasket&nbsp;</p><p>-remove the line and make the new gasket again&nbsp;</p><p>- (new gasket material - rust rubber gasket)&nbsp;</p><p>-applied rtv black on the surface&nbsp;</p><p>-install back the line&nbsp;</p><p>-deisolate diesel line and check leakage, no leakage found&nbsp;</p><p>-test run diesel dispenser by diesel filling to P-2 car</p><p>-check leakage, and found no leakage on the line</p><p>-Line up the system and monitoring condition.&nbsp;</p><p><br></p><p><br></p><p><br></p>', NULL, '2023-05-06 18:51:26', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-A-9095', 'ATL-MS-A-9095', 'Diesel Dispenser unit', NULL, NULL, 'Diesel Dispenser unit', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

