-- Inserting report ID 10479
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S  malfunction of auto drain valve IA-9200A', 'Mechanic', 'PM ', 'Waiting for Material', '2023-05-07', '<p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Troubleshoot malfunction of auto drain valve of instrument air compressor unit IA-9200A at ZMS, found 2 root cause</p><p>-Check out let line&nbsp;</p><p>-Check unloader valve&nbsp;</p><p>-Check exhaust line&nbsp;</p><p>-Chekc the piston plunger&nbsp;</p><p><br></p><p> </p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (1) auto drain suction line blockage</p><p>-the rubber suction line was blockage by dry muddy&nbsp;</p><p>-swap from workshop compressor&nbsp;</p><p>-Cleaning the line and test the air flow&nbsp;</p>  <p>·&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (2) air leakage from the auto drain valve, temporary fix by swap from workshop compressor (in process)</p><p> </p>  <p>-Adjust the timer screw to reduce draining duration</p><p>-Still draining duration from (8.5 bar to 7.5 bar), not satistifed&nbsp;</p><p>-plan to recondition inside plunger of auto drain valve&nbsp;</p>', NULL, '2023-05-07 20:09:54', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-A-9200A', 'ATL-MS-A-9200A', 'ZMS IA Compressor A', NULL, NULL, 'ZMS IA Compressor A', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10480
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Reconditioned Auto Drain of IA-9200A.', 'Mechanic', 'OTH', 'Completed', '2023-05-08', '<p><b><u>Description:&nbsp;</u></b></p><p>found auto drain valve of Instrument air compressor was not working properly.</p><p>Removed it and swapped the assembly with the one of workshop air compressor.&nbsp;</p><p><br></p><p><b><u>Working steps</u></b></p><p>-Removed it from the unit and reconditioned at the workshop.</p><p>-Dismantle the auto drain valve assembly.</p><p>-Checked the diaphragm rubber condition, directional spool valve condition and its seals,</p><p><b>-Found much spots at the surface of the valve seated seal.</b></p><p>-Cleaned the spool valve and reassembled the valve.</p><p>-kept it as a hot spare.</p><p><br></p>', NULL, '2023-05-08 17:25:04', '2023-05-08 17:45:46', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-A-9200A', 'ATL-MS-A-9200A', 'ZMS IA Compressor A', NULL, NULL, 'ZMS IA Compressor A', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

