  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TADANO crane malfunction', 'Mechanic', 'CM', 'In Progress', '2023-05-15', '<p>1. Checked the PTO solenoid.</p><p> </p>  <p>2.&nbsp; Found there is no energized coil on solenoid.</p><p></p>  <p>3. Removed the solenoid and check the supply voltage.<br></p>  <p>4.&nbsp;Found one terminal is 24V and another has no voltage.</p><p> 5. Tested with DC external voltage supply to solenoid coil.&nbsp;</p><p>6.&nbsp;Found one coil is energized and the other is not energized.</p>', NULL, '2023-05-16 07:23:43', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-CRANE-01', 'ATL-OC-CRANE-01', 'Operation Crane-01 TADANO-30T-GR3000EX', NULL, NULL, 'Operation Crane-01 TADANO-30T-GR3000EX', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
