  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Performed YPM on G-8320', 'Mechanic', 'PM', 'In Progress', '2023-05-16', '<p>Working steps,</p><p>- Start the generator for warming up.</p><p>- Drain lube oil.</p><p>- Drain coolant.</p><p>- Remove radiator cover and fan belt.</p><p>- Remove radiator and pulley.</p><p>- Remove air filter housing.</p><p>- Remove rocker arm box cover.</p><p>- Check and adjust valve clearance. (14N.m for lock nut)</p><p><br></p><p>- Change new lube oil filter, fuel filter and water separator.</p><p>- Top up lube oil 10 L.</p><p>- Clean the radiator cover and radiator fan by water jet.</p><p>- Install rocker arm box cover. (14N.m for 14mm and 10N.m for 10mm)</p>', NULL, '2023-05-16 16:38:20', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8320-PACKAGE', 'ATL-BV2-G-8320-PACKAGE', 'Gen, ZBV2 Diesel Generator package2', NULL, NULL, 'Gen, ZBV2 Diesel Generator package2', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

