  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot G-9110 unable to start', 'Electrical & Instrument', 'CM ', 'In Progress', '2023-05-18', '<p>- Troubleshoot G-9110 unable to start.</p><p><br></p><p>- Found the timing sensor of the G-9110 was scratch. ( Removed and clean the surface with the sandpaper).</p><p>- Verify the G-9110 ignition timing sensor by removing the sensor and installed at the G-9120 and test run.</p><p>- G-9120 was running normal. ( The sensor of G-9110 was still good.)</p><p>- Checked the Gas pressure at the dog house. (as found 6 kpa)</p><p>- Checked the filter of the dog house gas filter. (as found very dirty - replaced with the new one).<br>- Removed the battery bank no.2 and charging at the workshop.</p>', NULL, '2023-05-18 16:10:46', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
