BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S AIT-84306 value freeze. ', 'Electrical & Instrument', 'CM ', 'Completed', '2023-05-19', '<p>- Troubleshoot AIT-84306 no of analysis lost and gas composition values freeze.</p><p><u>Work steps.</u></p><ol type="1"><li>Power off the AIT-84306 controller.</li><li>Checked the alarm and acknowledged the alarm with MOON2000 after power-off. (All alarms cleared on both Flow computer and HMI)</li><li>Retrieved archived data for stream 1 &amp; stream 2. (Normal)</li><li>Found the AIT-84306 GC time and GC analysis cycle was different with AIT-84307.</li><li>Halt the AIT-84306 and adjusted the GC time and GC analysis cycle to same with AIT-84307.</li><li>Put AIT-84306 auto sequence and Compare BTU value after adjusted time and analysis cycle.</li></ol><p><br></p>', NULL, '2023-05-19 17:24:22', '2023-05-19 17:25:11', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-AIT-84306', 'ATL-MS-AIT-84306', 'Gas chromatograph to metering.N2and CO2', NULL, NULL, 'Gas chromatograph to metering.N2and CO2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

