  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S the FAP-81101system show loop device fault.', 'Electrical & Instrument', 'CM', 'Completed', '2023-05-20', '<p>- Verify the FAP-81101 show loop device fault.</p><p>- The EQP panel showed the Catering, Senior Accom. and Guardhouse all device fault.</p><p>- Clean the smoke detector for Senior Accom. room No.3 that showed fault.</p><p>- Re-set the power for EQP controller, the Senior Accom zone. and Guardhouse zone back to normal.</p><p>&nbsp;- Found the SD-81182 at the Catering zone showed fault activated,.</p><p>- Verify the SD-81182 found water ingress the smoke detector module and also the wiring cable was damage.</p><p>- Repair the celling and signal wiring cable and replaced the new smoke detector.</p><p>- The FAP-81101 back to normal.</p>', NULL, '2023-05-20 14:00:40', '2023-05-20 14:05:06', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
