  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S G-9110 unable to start', 'Electrical & Instrument', 'CM ', 'Completed', '2023-05-20', '<p>- T/S G-9110 unable to start.</p><p>- Installed the pressure gauge at the down stream of the GVPS valve.</p><p>- Opened the GVPS valve by manually pressing the relay and observed the down steam pressure. (5Kpa)</p><p>- Cleaning the relay contact with contact cleaner.</p><p>- Exercise the GVPS open and close for 3 times.</p><p>- Test run the Generator and observed the relay sequence. (Normal), The GVPS also open and pressure was 5kpa.</p><p>- Test run the generator with share load for 2 hr and&nbsp; run with full load until next bi-weekly gas generator change over..&nbsp;</p>', NULL, '2023-05-20 16:53:58', '2023-05-20 19:39:50', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9110-PACKAGE', 'ATL-MS-G-9110-PACKAGE', 'Gen, ZMS Gas Generator package1', NULL, NULL, 'Gen, ZMS Gas Generator package1', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
