  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '6M PM Emergency Diesel Generator', 'Mechanic', 'PM ', 'In Progress', '2023-05-21', '<p><b><i><u>Working Steps</u></i></b></p><p><br></p><p>Checked and cleaned the air filters conditon.</p><p>Checked the air service indicator condition.<br>Checked the exhaust condition.<br>Checked the turbo charger and its blades condition.</p><p>Checked and cleaned the breather filter.</p><p>Checked the coolant level and the leakage.</p><p>Checked the radiator cap condition.</p><p>Checked and cleaned the radiator fins.</p><p>Checked the radiator fan blades condition.</p><p>Checked the radiator fan bolts. (75 Nm)</p><p>Checked the radiator fan belt tension.</p><p>Checked and tightened the radiator fan cover bolts. (25 Nm)</p><p>Checked and tightened the radiator mounting bolts. (300 Nm)</p><p>Checked and tightened the engine mounting bolts. (400 Nm)<br></p><p><br></p>', NULL, '2023-05-22 17:49:39', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9125-PACKAGE', 'ATL-MS-G-9125-PACKAGE', 'Gen, ZMS Diesel Generator Package', NULL, NULL, 'Gen, ZMS Diesel Generator Package', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
