-- Inserting report ID 10567
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace the new carbon brush @ G-9110', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2023-05-30', '<p>Replace the new carbon brush of the alternator charger at G-9110</p><p>As found: D+ voltage shows low about 11.9 VDC and stop the generator by operator</p><p>Isolate the FM-200 cylinders and battery banks at local panel</p><p>Isolate the breakers for GCP &amp; LCP from switch gear room (self-isolation)</p><p>Remove the old carbon brush at alternator charger @ G-9110</p><p>Check the physical condition of the carbon brushes (Carbon brush terminal was only the small layer)</p><p>Replace with the new carbon brush at alternator @ G-9110</p><p>Check and tighten the belt tension of the alternator charger&nbsp;</p><p>De-isolate the power, FM-200 and battery bank for test run</p><p>Test run the gas generator G-9110 and monitor the D+ voltage</p><p>D+ voltage shows 26.8 V DC and record the parameter</p><p>&nbsp;</p>', 'Senior E&amp;I remarks D+ voltage will increase slightly after running and weekly change over', '2023-06-02 17:33:00', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9110-PACKAGE', 'ATL-MS-G-9110-PACKAGE', 'Gen, ZMS Gas Generator package1', NULL, NULL, 'Gen, ZMS Gas Generator package1', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
