  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S assist and support for vendor FQIC-84352A/B ', 'Electrical & Instrument', 'CM ', 'In Progress', '2023-06-07', '<p>Troubleshoot FQIC-84352 A/B abnormal alarm by PMO/I and Vendor</p><p>Print out the data before setting the maintenance mode</p><p>Remove the New Hart Board from FQIC-84352 B&nbsp;</p><p>Insert the Old Hart Board (Exiting) to FQIC-84352 B</p><p>Remove the Old Hart Board (Exiting) from FQIC-84352 A</p><p>Insert the New Hart Board to FQIC-84352A</p><p>Keep monitoring the alarm signal from FQIC-84352 A</p><p>There is no alarm comes from the FQIC-84352A about 4 Hours</p><p>Check &amp; measure the ground resistance between equipment and earth bar (1.1 Ohm)</p><p>Check &amp; measure the ground resistance between Dim ray and instrument earth (IE) (0.8 Ohm)</p><p>Check &amp; measure the resistance between and instrument earth (IE) and protective earth (PE) (1.1 Ohm)</p><p>&nbsp;As Found: Some ground wires (Fan) are disconnected and roll inside the cable tray and</p><p>1IE-16/TB230-21 was disconnected from another ground bus</p><p>Connect the ground wire 1IE-16/TB230-21 at instrument earth (IE) bus</p><p>Swap the Old Hart Board with New Hart Board at FQIC-84352A</p><p>Remove the maintenance mode and print out the data after changing maintenance mode</p><p>Keep monitoring the alarm signals with Exiting Hart Board for FQIC-84352 A/B&nbsp;</p>', '<p>FQIC-84202 A shows signal flow transmitter high alarm and transient spide the signal on 06/06/2023 around (18:00)</p><p><br></p>', '2023-06-07 18:53:33', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-M-8435-ASSY', 'ATL-MS-M-8435-ASSY', 'Export Gas Metering Run-E', NULL, NULL, 'Export Gas Metering Run-E', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

