  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S assist & support PMO/I Vendor FQIC-84352 A/B', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2023-06-08', '<p>Troubleshooting assist &amp; witness for PMO/I and Vendor FQIC-84352 A/B</p><p>Print out the data before setting maintenance mode at FQIC-84352 A/B</p><p>Remove the ground wire between Instrument Earth (IE) bus and DC 0V supply with Dim way connector</p><p>Check and testing the alarms with the transient spide at FQIC-84352 A by disconnecting the control fuse&nbsp;</p><p>Measure the electrical wire in the ground with metal detector by ROW technician</p><p>Detect the underground electrical cable at the digging point with metal detector</p><p>Monitor the alarm after removing ground wire connection by Vendor</p><p>There is no alarm coming untill about 17:30 and keep monitoring by night shift</p><p>Set clear the maintenance mode and print out the data after troubleshooting&nbsp;&nbsp;</p>', NULL, '2023-06-08 18:22:10', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
