-- Inserting report ID 10596
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Weekly inspection PM and test run of G-9110.', 'Mechanic', 'PM ', 'Completed', '2023-06-09', '<p><b><u>Description: </u></b>Performed weekly inspection PM and test run of Gas Engine Generator G-9110 and troubleshoot the unit unable to start.</p><p><br></p><p><b>Working steps:</b></p><p>-Performed process and electrical isolation.</p><p><b>-Removed the DC alternator assembly and replaced with the new one.</b></p><p><b>-Replaced the battery banks with the new one. (panel side).</b></p><p><b>-Changed the alternator timing belt.&nbsp;</b></p><p>-Checked the engine oil level and condtion.</p><p>-Checked the radiator coolant level and condtion. <b>Topped up coolant 0.5 Liters.</b></p><p>-Housekeeping around the working area.</p><p>-Performed the process and electrical deisolation.</p><p>-Test run with shared load for 30 minutes and monitored the unit parameters.</p><p>-<b>Found the installed DC alterantor output voltage is 25 voltage.</b></p>', '<p>-Found oil greasy seeping at the flanged join of the Bank B side turbo-charger to cooling charger.</p><p>-Found coolant seeping from the ball valve of the water heater inlet line.&nbsp;</p>', '2023-06-09 17:32:07', '2023-06-09 17:38:55', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9110-PACKAGE', 'ATL-MS-G-9110-PACKAGE', 'Gen, ZMS Gas Generator package1', NULL, NULL, 'Gen, ZMS Gas Generator package1', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
