  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace new batteries and alternator charger', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2023-06-09', '<p>Perform replace new batteries and alternator charger at G-9110</p><p>Perform electrical isolation, remove the battery switch and inhabit FM-200 system&nbsp;&nbsp;</p><p>Replace new batteries at battery bank 1 (total 4 batteries)</p><p>Replace new alternator charger and carbon brushes</p><p>De-isolate the power and running test about 30 minutes&nbsp;</p><p>Check and measure the DC voltage after changing alternator&nbsp;</p><p>Monitor the D+ voltage and battery voltage at switch gear room</p><p>D+ voltage = 23.5 V DC and U Bat voltage= 22.1 V DC</p><p>&nbsp;&nbsp;</p>', 'Need to perform continues troubleshooting&nbsp;', '2023-06-09 19:19:41', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
