-- Inserting report ID 10601
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'weekly inspection PM and test run of G-9120.', 'Mechanic', 'PM ', 'Completed', '2023-06-10', '<p><b><u>Description:</u> performed weekly inspection PM and test run of Gas engine generator G-9120.</b></p><p><br></p><p><b><u>Working steps:</u></b></p><p>-Checked air filters(both banks) condition.</p><p>-Visually checked turbo chargers condition. (both banks).</p><p>-Checked lube oil level and condition.</p><p>-Checked radiator cap and coolant level condition.</p><p>-Checked DC alternator timing belt condition. (plan to replace it before changeover).</p><p>-Checked and cleaned breather condition. (found oily slug inside of the breather houseings as usual).</p><p>-Vacuum cleaning and housekeeping around the engine generator package.</p><p>-Test run with shared load for 30 minutes.</p><p>-Checked any abnormal sign around the unit.</p><p><br></p><p><br></p>', '-Found suspected cooling seeping areas at the radiator racks. (need to verify the seeping points areas).', '2023-06-10 15:20:09', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9120-PACKAGE', 'ATL-MS-G-9120-PACKAGE', 'Gen, ZMS Gas Generator package3', NULL, NULL, 'Gen, ZMS Gas Generator package3', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
