  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubeshoot G-9110 D+ voltage low', 'Electrical & Instrument', 'CM ', 'In Progress', '2023-06-10', '<p>Troubleshoot gas generator G-9110 D+ voltage low problem</p><p>Check and verify the manual and electrical &amp; control drawings</p><p>Check the circuit breaker and control wire termination</p><p>Check &amp; measure the D+ output voltage in GCP panel at switch gear room</p><p>D+ voltage = 23.5 V ( Lower than normal voltage)&nbsp;</p><p>Compare with other generator G-9115 &amp; G-9120&nbsp; D+ voltages&nbsp;</p><p>(G-9115= 27.8 V DC and G-9120= 27.3 V DC) (Normal)</p>', NULL, '2023-06-10 19:19:04', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9110-PACKAGE', 'ATL-MS-G-9110-PACKAGE', 'Gen, ZMS Gas Generator package1', NULL, NULL, 'Gen, ZMS Gas Generator package1', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

