  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-FIRE INTERVENTION TRUCK', 'ATL-MS-FIRE INTERVENTION TRUCK', 'Fire Intervention Truck', NULL, NULL, 'Fire Intervention Truck', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
