  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-M-8435-ASSY', 'ATL-MS-M-8435-ASSY', 'Export Gas Metering Run-E', NULL, NULL, 'Export Gas Metering Run-E', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
