  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform MPM ZOC Two Post Car Lift', 'Mechanic', 'PM', 'Completed', '2023-06-14', '<p>Working Steps.</p><p>1. Checked and&nbsp;re-torqued mounting bolts of two posts. (Torque=100 Nm) (30mm)</p><p>2. Checked the condition and level of hydraulics.</p><p>3. Checked the hydraulic hose and fitting condition.</p><p>4. Functional checked emergency button.</p><p>5. Checked lifting arm pinion gear condition.</p><p>6. Checked the rope condition.</p><p>7. Checked the limit switch&nbsp;</p><p>8. Housekeeping.</p><p>Remark :&nbsp; Hydraulic oil leak from on both side and need to repair&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Request service order by Mechanic Team&nbsp;</p>', NULL, '2023-06-14 15:57:28', '2023-06-15 14:06:10', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
