  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot G-9110 D+ voltage low', 'Electrical & Instrument', 'CM ', 'In Progress', '2023-06-13', '<p>Troubleshoot G-9110 D+ voltage low error</p><p>Working steps-</p><p>Isolate the power G-9110 from the switch gear room</p><p>Remove the alternator charger from the gas generator G-9110</p><p>Isolate the power G-9120 form the switch gear room</p><p>Remove the alternator charger from the gas generator G-9120</p><p>Swap the alternator charger from G-9110 to G-9120</p><p>De-isolate the power G-9120 and test run</p><p>D+ voltage is still low and show 23.5 V and cannot charge the battery</p>', '<p>Isolate the power G-9110 from switch gear room at over night</p><p>Inform night shift CCR operator and ZMS supevisor</p><p>Visual check by PMO/I Engineer (Ko Ka Ka)</p>', '2023-06-14 20:58:19', '2023-06-14 20:59:07', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
