  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Fix air leak of intercooler tube in A-8980A', 'Mechanic', 'CM', 'Completed', '2023-06-17', '<p><br></p><p>Operator informed the abnormal air leak sound form the unit A.</p><p>Verify by snoop and found air leak of intercooler tube&nbsp;</p><p><br></p><p>isolate electrical and process line&nbsp;</p><p>depressurize the air tank&nbsp;</p><p>remove the cover guard&nbsp;</p><p>cleaning the leak point by sand paper and wire brush and WD40</p><p>applied mixing benzona and wait for dry time about 6 hours&nbsp;</p><p>test run&nbsp;</p><p>found no leak on intercooler point</p><p>but, found another leak again at the cooler hose fitting&nbsp;</p><p><br></p>', NULL, '2023-06-17 17:05:00', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-A-8980A', 'ATL-OC-A-8980A', 'ZOC IA Compressor A', NULL, NULL, 'ZOC IA Compressor A', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

