-- Inserting report ID 10641
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Visual check and inspection for G-9110', 'Electrical & Instrument', 'CM ', 'Completed', '2023-06-19', '<p>As found: G-9110 was tripped by <span style="background-color: rgb(255, 255, 0);">low RPM</span> at (22:45) 18.06.2023 and cannot start again</p><p>Working Steps:</p><p>- Visual check &amp; inspection on-site of the gas generator G-9110</p><p>- Check the circuit breaker was tripped or not ( <span style="background-color: rgb(255, 255, 0);">Not found circuit breaker tripped</span> at GCP, LCP, Ex proof panel)</p><p>- Check the coolant &amp; lube oil level and also leak or seeping point at radiator and engine site</p><p>- Trace back the alarm history and circuit diagram at the ECS work station monitor</p><p>- Consult &amp; disscusion with ZMS Supervisor, Senior E&amp;I and Senior Mech inspection for the generator&nbsp;</p><p>- Visual check and inspection for the air filter and fuel gas pressure at dog house (<span style="background-color: rgb(255, 255, 0);">No abnormality</span> found)</p><p><br></p><p>Result:</p><p>-Ruuning test the generator after visual check and inspection</p><p>-Start the gas generator G-9110 with battery bank 2</p><p>-Show the GVPS fail alarm signal at switch gear room</p><p>-Vent and reduce the fuel gas pressure at inlet valve of gas generator</p><p>-Start again the generator and cannot crank the engine ( 150 RPM and <span style="background-color: rgb(255, 255, 0);">sd engine</span> at GCP G-9110)</p><p>-Change the other battery bank (no.1) and start again the generator</p><p>-Generator can crank and running the generator with normal RPM</p><p>-Test run about 30 minutes and record the parameter (D+ voltage, RPM, Lube oil pressure, Lube oil Temp, Coolant Temp, Fuel Gas pressure)&nbsp;&nbsp;</p><p>- All parameters are normal and stop the generator after test run</p>', '<p>Need to check and inspection magnetic sensor due to (RPM) low</p><p>Check the fuel gas pressure regulator at dog house</p><p>Check the spark plugs and ignitation timmer</p>', '2023-06-19 22:13:00', '2023-06-19 22:18:26', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9110-PACKAGE', 'ATL-MS-G-9110-PACKAGE', 'Gen, ZMS Gas Generator package1', NULL, NULL, 'Gen, ZMS Gas Generator package1', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

