  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Weekly inspection PM and test run of G-9115.', 'Mechanic', 'PM ', 'Completed', '2023-06-24', '<p>Description: weekly inspection PM and test run of G-9115.</p><p><br></p><p>Working steps:</p><p>-Checked and cleaned air filters, breather filters.</p><p>-Checked lube oil level and condtion.&nbsp;</p><p>-<b>Topped up lube oil 43 Liters.</b></p><p>-Checked radiator caps condtion and coolant level.</p><p><b>-Checked alternator charger belt tension and condtion.</b></p><p>-Housekeeping around the working area.</p><p>-Test run with shared load for 30 minutes and monitor the parameters.</p><p>-The parameters are normal and the unit is in service and standby.</p>', '<p>-Found alternator charger belt was being half-slip off the alterantor pulley as the pulley does not have the belt slip control guard as the other units. The pulley is not as the same as the other units.</p><p><br></p><p>-need to replace as being running with the half-slip belt happens the belt life short.</p>', '2023-06-24 15:27:22', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
