  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '6MPM on Sewage Blower B-8910 A', 'Mechanic', 'PM', 'Completed', '2023-06-24', '<p>Job Description: 6MPM on Sewage Blower B-8910 A.</p><p><br></p><p>Job Steps :</p><p>1. Isolation.</p><p>2. Visual Check and leakage check</p><p>3. Check, replaced and readjust the belt alignment and tension.</p><p>4. Drain the lube oil and filled up with new one (1.2 Liter of GL-5)</p><p>5. Clean the air filter.</p><p>6. Check and tighten the bolts and nuts of motor and pump.</p><p>7. Clean the area with oiler 1 and water.</p><p>8. Housekeeping and test run.</p><p><br></p>', 'Found Drain plug is worn out. Need to order a new one and replace.', '2023-06-24 15:55:36', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
