  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot G-9110 low rpm shutdown', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2023-06-24', '<p>- Troubleshooted Gas Generator G-9110 low rpm shutdown.</p><p>- As found the down stream pressure of the GVPS was 4.23Kpa. <span style="background-color: rgb(255, 255, 0);">(must be 5Kpa)</span></p><p>- As found the doghouse gas pressure was 6kpa.</p><p>- Increased the dog house gas pressure form <span style="background-color: rgb(255, 255, 0);">6kpa to 9.5kpa</span>.</p><p>- After increased doghouse gas pressure, the down stream pressure of the GVPS was 4.98.</p><p>- Test run with share load for 2hr and take full load.</p>', NULL, '2023-06-24 20:12:01', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9110-PACKAGE', 'ATL-MS-G-9110-PACKAGE', 'Gen, ZMS Gas Generator package1', NULL, NULL, 'Gen, ZMS Gas Generator package1', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
