-- Inserting report ID 10668
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Engine oil and filters replacement of G-9115', 'Mechanic', 'PM ', 'Completed', '2023-06-27', '<p><b>Description: Performed Engine oil and filters (6EA) replacement as per lube oil analysis result report.</b></p><p><br></p><p><b>Working orders:</b></p><p><br></p><p><u>Lubrication system.</u></p><p>-Performed process and electrical isolation.</p><p>-Drained lube oil and <b>replaced the oil filters (6EA).</b></p><p>-Removed drain valves assembly as found seeping at the joint fitting.</p><p>-Cleaned and reconditioned the drain valve assembly</p><p>-Installed back the drain valve assembly.</p><p>-Filled up the <b>METHANA lube oil (180 Liters).</b></p><p><br></p><p><u>Cooling system.</u></p><p>-Drained the coolant.</p><p>-Found the water heater inlet ball valve line seeping: replaced<b> the ball valve (3/4")</b> with the new one.</p><p>-<b>Replaced the rubber hose sleeve</b> of auxiliary water pump inlet line as found deformed.</p><p>-Topped up the coolant.</p><p><br></p><p>-Performed process and electrical deisolation.</p><p>-Test run with no load&nbsp;</p><p>-stop the engine and topped up the engine oil.</p><p>-Test run with shared load for 30 minutes.</p><p><b>-the unit is serviceable.</b></p><p><br></p><p><br></p>', '-need to clean the radiator.', '2023-06-28 07:07:10', '2023-06-28 07:43:32', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

