-- Inserting report ID 10670
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'G-9115 replace lube oil and oil filters ', 'Mechanic', 'CM', 'Completed', '2023-06-27', '<p>Prepare required equipment&nbsp;</p><p>-Drain motor pump, 3/4" hose, 3/4 jubilee clamp,&nbsp;</p><p>-Drain lube oil drum&nbsp;</p><p>-New lube oil drum Methana 200L drum&nbsp;</p><p>-top up oil pump&nbsp;</p><p>-Oil filters 6 EA&nbsp;</p><p>-</p><p>Perform electrical and process isolation.&nbsp;<br></p><p><br></p><p>-Drain lube oil&nbsp;</p><p>-found seeping lube oil from the drain valve&nbsp;</p><p>-remove the drain valve line&nbsp;</p><p>-recondition new teflon sealant tape and Loctitie 567- applied&nbsp;</p><p>-Installed the line&nbsp;</p><p>-replace new lube oil filter&nbsp;</p><p>-top up lube oil with new pump&nbsp;</p><p>-Test run without load about 5 minutes&nbsp;</p><p>-top up lube oil up to 100% full load (about 30 liters)</p><p>-Test run with share load and running in normal parameters</p>', 'Fix oil seeping from the lube oil drain valves lines&nbsp;', '2023-06-28 14:16:42', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10671
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'G-9115, fix defective coolant hose in oil cooler ', 'Mechanic', 'CM', 'Completed', '2023-06-27', '<p>-found coolant seeping from the heater line valve During lube oil replacement activity, found defective coolant rubber hose. It can be burst in any time.&nbsp;</p><p><br></p><p>Prepare spare part and Tools&nbsp;</p><p>- 422/5 Rubber hose - 1EA&nbsp; (18.71.8.743.3)&nbsp;</p><p>-282/295 Gasket (oil cooler inlet gasket) -1 EA&nbsp;</p><p>-Red RTV gasket maker&nbsp;</p><p>-17mm Spanner, 10mm ratchet socket&nbsp;</p><p>-Clean blue drum to drain - 3 Drum&nbsp;</p><p>-hose 3/4 and 1/2 out let fitting&nbsp;</p><p>-New top up Wilden chemical pump&nbsp;</p><p>-New Coolant drum Premix&nbsp;</p><p>-Sand paper, scraper, and hack saw blade&nbsp;</p><p>-vacuum cleaner&nbsp;</p><p><br></p><p>Steps</p><p>-Drain coolant until stopping coolant from the oil cooler line&nbsp;</p><p>-remove defectives hose and pipe of oil cooler&nbsp;<br></p><p>-clean the remaining gasket parts&nbsp;</p><p>-locate the hose in proper position</p><p>-Place new gasket with red RTV&nbsp;</p><p>-Install the line and hose with 4 jubilee clamps&nbsp;</p><p><br></p><p>-found coolant seeping from the heater line valve&nbsp;<br></p><p>-Remove the line and replace new ball valve (3/4")&nbsp;</p><p>-</p><p>-Top up coolant by Wilden by slowly to prevent air pocket&nbsp;</p><p>-Check the coolant seeping point&nbsp;</p><p>-Test run without load about 5 min&nbsp;</p><p>-Stop the engine and check the coolant level again&nbsp;</p><p>-Test run with share load about 1 hour&nbsp;</p><p>-all parameters are in normal&nbsp;</p>', '<br>', '2023-06-28 14:33:59', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

