  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '1M PM at G-8010 and G-8020', 'Electrical & Instrument', 'PM', 'Completed', '2023-07-06', '<p>- Performed the 1MPM on Diesel generator G-8010 and G-8020.</p><p>G-8010</p><p>- Inspected the battery water level.&gt;&gt; normal</p><p>- Inspected the control box and tighten the terminal.</p><p>- Clean the internal package and alternator.</p><p>- tighten the lube oil sensor cable.</p><p>- test run with local and put to remote start. &gt;&gt; normal</p><p>- run with load (duty)</p><p>G-8020</p><p>- Inspected the battery water level.&gt;&gt; refill 200 CC.</p><p>- Inspected the control box and tighten the terminal.</p><p>- Clean the internal package and alternator.</p><p>- tighten the lube oil sensor cable.&gt;&gt; found cable loosen</p><p>- test run with local and put to remote start. &gt;&gt; normal</p><p>- keep unit standby&nbsp;</p>', NULL, '2023-07-06 12:17:22', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Inst-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010', 'ATL-BV1-G-8010', 'Gen, Diesel Engine generator No1', NULL, NULL, 'Gen, Diesel Engine generator No1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
