  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2K PM Gas Generator G-9115', 'Mechanic', 'PM ', 'Completed', '2023-07-10', '<p><b><i>Air Intake System</i></b></p><p>- Checked the air service indicator condition.</p><p>- Checked and cleaned the air filter with compressed air.</p><p>- Checked the condition of the turbo charger.</p><p><b><i>Lube Oil System</i></b></p><p>- Replaced oil filter and changed the lube oil on 27-June, 2023.</p><p>- Checked and cleaned the breather filters.</p><p>- Checked the lube oil level.</p><p><i><b>Cooling System</b></i></p><p>- Checked the coolant level.</p><p>- Checked the radiator cap condition.</p><p>- Checked the radiator fan condition.</p><p>- Cleaned the radiator with the water jet.</p><p>- Checked the radiator fan hub nut tension. (75 Nm)</p><p>- Checked the radiator cover nuts tension. (75 Nm)</p><p><b><i>Fuel Gas System</i></b></p><p>- Replaced the dog house gas filter.</p><p>- Checked the fuel gas parameters and its gauge.</p><p><b><i>Electrical System&nbsp;</i></b></p><p>- Performed 3Y Battery Replacement. ( Replaced the batteries Bank at Engine Side. )</p><p>- Checked and cleaned the alternator.</p><p>- Checked the alternator belt tension.</p><p><b><i>Overall Package</i></b><br></p><p>- Checked any oil leakage.</p><p>- Checked any&nbsp; coolant leakage.</p><p>- Tightened the loosening bolts and nuts.</p><p>- Housekeeping.</p><p>- Test run and record the parameters.</p><p><br></p><p><br></p><p><br></p>', NULL, '2023-07-10 14:29:33', '2023-07-12 14:36:58', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
