  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify radiator fan bearing housing rotary seal', 'Mechanic', 'CM', 'Under Monitoring', '2023-07-10', '<p>Working steps,</p><p>- Removed fuel cooler.</p><p>- Removed radiator fan guard.</p><p>- Checked the rotary seal for any abnormal. (No abnormal)</p><p>- Removed the cover plate of bearing housing and inspected inside bearing housing. (No metal scrap and wear)</p><p>- Installed back the cover plate and rotary seal.</p><p>- Measured the distance between rotary seal and fan hub at 3,6,9,12 position. (36 mm)</p><p>- Installed the radiator fan guard.</p><p>- Applied the torque for M-8. (30 Nm)</p><p>- Installed fuel cooler.</p>', NULL, '2023-07-10 17:56:03', '2023-07-16 18:22:41', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
