-- Inserting report ID 10753
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify TC-2 Brake Piston stucking', 'Mechanic', 'CM', 'In Progress', '2023-07-19', '<p>1. Removed front brake drum cover and found brake piston jammed and stuck with brake shoe and overheating.</p><p>2. Released brake fluid and brake pad was still not moving.</p><p>3. Removed brake pipe and loosen the piston mounting nut.</p><p>4. Removed front axle hub cap.</p><p>5. Take out the gasket, washer, bearing nut and bearing from the hub.</p><p>6. Removed the wheel by using forklift.</p><p>7. Removed the brake piston and brake shoes.</p><p>8. Ordered spare parts to Desire Auto Shop.</p>', NULL, '2023-07-19 17:03:21', '2023-07-20 07:20:01', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-TC-02', 'ATL-OC-TC-02', 'Truck Crane-02 ISUZU FTR240 / UNIC V550', NULL, NULL, 'Truck Crane-02 ISUZU FTR240 / UNIC V550', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10754
DO $$
