  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot Smoke Detector Fault Alarm', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2023-07-20', '<p>Troubleshoot smoke detector SD-81050 fault alarm</p><p>&nbsp; &nbsp;Check the detector location and inhibit the detector.</p><p>&nbsp; &nbsp;Remove smoke detector. Clean around the area and remove spider web.</p><p>&nbsp; &nbsp;Clean the detector and reinstall, alarm is clear but detector light is still on.</p><p>&nbsp; &nbsp;Replace with new detector, alarm is clear, check the status with CCR and unit is back to normal.</p>', NULL, '2023-07-20 15:21:38', '2023-07-20 16:04:30', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-SD-81050', 'ATL-OC-SD-81050', 'Smoke detector in Work shop', NULL, NULL, 'Smoke detector in Work shop', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10755
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Bi-Monthly PM Instrumen Air-Comp Unit A', 'Mechanic', 'PM ', 'Completed', '2023-07-19', '<div><br></div><div><p>Working steps:</p><p><br></p><p>- Checked and cleaned the air filter.</p><p>- Drained and topped up lube oil (Total Azolla ZS-46) 4 Liters.</p><p>- Checked the belt tension and pulley alignment.</p><p>- Checked the belt condition.</p><p>- Checked and tightened the motor mounting bolts.</p><p>- Checked fan guard bolts/nuts tension.</p><p>- Visually check the dryer.</p><p>- Housekeeping the compressor assembly.</p><p>- Performed electrical and process de-isolation.</p><p>- Test run and checked any abnormality.</p></div>', NULL, '2023-07-20 16:33:23', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-A-9200A', 'ATL-MS-A-9200A', 'ZMS IA Compressor A', NULL, NULL, 'ZMS IA Compressor A', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10756
DO $$
