  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform Metering & Calibration Tube-1', 'Electrical & Instrument', 'PM ', 'Completed', '2023-07-20', '<p>Perform monthly Metering &amp; Calibration for Tube 1 and Orifice Plate Inspection</p><p>Working steps.</p><p>-Performed Process isolation.</p><p>-Performed Metering Calibration for Tube 1 (M-8415).</p><p>-Calibrated the pressure transmitters by Hydraulic Dead Weight tester A &amp; B</p><p>-Calibrated the flow transmitters by Pneumatic Dead Weight tester A &amp; B</p><p>-Calibrated the temperature transmitters by RTD A &amp; B</p><p>-Performed orifice plate inspection by witness of MOGE Rep.,&nbsp;</p><p>-Leak test at connection point and remove the maintenance mode</p><p>-Leak test counter checked by operator (Luis)</p>', NULL, '2023-07-20 16:43:45', '2023-07-20 16:46:14', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-M-8415-ASSY', 'ATL-MS-M-8415-ASSY', 'Export Gas Metering Run-A', NULL, NULL, 'Export Gas Metering Run-A', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10757
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace new Helium Cylinder No.3 @ AIT-84307', 'Electrical & Instrument', 'CM ', 'Completed', '2023-07-20', '<p>Perform Helium cylinder replacement on AIT-84307 (No.3)</p><p>Inform MOGE Rep. person to replace Helium cylinder by email</p><p>Check the pressure of old Helium cylinder about 300 psi</p><p>Inform CCR to replace the new Helium Cylinder No.3.</p><p>Replace the new Helium cylinder and purge the gas from vent</p><p>Set the outlet pressure about&nbsp;120 psi&nbsp;with pressure regulator at cylinder&nbsp;no.4.</p><p>Set the outlet pressure about 110 psi&nbsp;with pressure regulator at cylinder&nbsp;no.3.</p><p>Check the leak with snoop at every joint of tubing and cylinder head.</p><p>Inform CCR to change back to AIT-84307 in used manual mode.</p>', NULL, '2023-07-20 16:52:50', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-AIT-84307', 'ATL-MS-AIT-84307', 'Gas chromatograph to metering.N2and CO2', NULL, NULL, 'Gas chromatograph to metering.N2and CO2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

