  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Reinstalled TC-2 brake assembly', 'Mechanic', 'CM', 'Completed', '2023-07-25', '<p>1. Cleaned all of the brake assemblies and wheel parts.</p><p>2. Installed new brake piston, brake shoes and brake pipe.</p><p>3. Installed the wheel by using forklift.</p><p>4. Installed the gasket, washer, bearing nut and bearing to the hub.</p><p>5. Installed front axel hub cap.</p><p>6. Bleed air from the brake line and adjusted the brake shoe.</p><p>7. Cleaning the brake fluid with water and installed back brake drum cover.</p><p>8. And then removed brake drum cover of front left wheel and inspected the piston and brake shoe condition.</p><p>9. Found brake piston dust seal is partially not good but brake system is working normally.</p><p>10. Need to inspect brake system every PM.</p>', NULL, '2023-07-25 16:55:34', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-TC-02', 'ATL-OC-TC-02', 'Truck Crane-02 ISUZU FTR240 / UNIC V550', NULL, NULL, 'Truck Crane-02 ISUZU FTR240 / UNIC V550', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

