  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S diesel transfer pump lube oil ', 'Mechanic', 'CM', 'Completed', '2023-07-28', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Isolate inlet and outlet valve</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Selector switch change to off and local mode</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove the drain plug </p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Loose the vent cap bolt to release the air trap</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Drain all lube oil and tight drain plug</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Top up lube oil until sight glass 80%</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Loose the lock nut from oil cup</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Fill the oil cup ¾ and install on fitting</p><p>9.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Tight the lock nut</p><p>                  </p><p>10.&nbsp; &nbsp; &nbsp;Test run and check any oil come out or drop</p><p><br></p>', NULL, '2023-07-28 17:34:14', '2023-07-29 08:33:48', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-P-8890B-ASSY', 'ATL-OC-P-8890B-ASSY', 'ZOC Diesel Tranfer Pump B Assy', NULL, NULL, 'ZOC Diesel Tranfer Pump B Assy', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

