-- Inserting report ID 10824
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace AFR spool at G-8930 ', 'Mechanic', 'CM', 'Completed', '2023-08-07', '<p>E&amp;I team request to support AFR&nbsp; spool replacement in G-8930.&nbsp;</p><p><br></p><p>- Check the installed one AFR&nbsp;</p><p>bolt - 5/8", Flange 3" , Class 150,&nbsp;</p><p>Upper flange connection - 6 bolts&nbsp;</p><p>Down stream flange connection -4 bolts&nbsp;</p><p>Remove the flange connection and gasket (teflon) last time Mech team insert&nbsp;</p><p>Remove the installed spool from the position&nbsp;</p><p>Locate the spool and insert new gasket (3", Non CAF, flat face, inner 3-1/2" and outer 5-3/8")&nbsp;</p><p>Tighten the 4&nbsp; bolts at the down steam by 100 Nm&nbsp;</p><p>Tighten the 6 bolts at the upper connection by 65 Nm&nbsp;</p><p>check the flange alignment&nbsp;</p><p>wait for line up gas and check for leakage by snoop&nbsp;</p><p><br></p>', NULL, '2023-08-07 17:46:46', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8930-PACK', 'ATL-OC-G-8930-PACK', 'Gen, ZOC Gas Generator Package 3', NULL, NULL, 'Gen, ZOC Gas Generator Package 3', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
