-- Inserting report ID 10848
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify condensate transfer pump P8950', 'Mechanic', 'OTH', 'Completed', '2023-08-13', '<div><br></div><div><p><u>Action&nbsp;</u><br></p><p>Check the condition of the P-8950 and test run.</p><p>Test run the P-8950 for 1 drum of condensate.</p><p>P-8950 is working properly.<br></p><p><br></p><p>Before test run , the level of closed drain pump is 24.7 %.</p><p><br></p><p>After test run, the level of closed drain pump is 24.5%.</p><p><br></p><p><br></p><p>On 14-Aug-23&nbsp;</p><p>Prepare empty oil drain to pump out condensate&nbsp;</p><p><br></p><p>1. starting pump out from 24.5 to 22.4 (Pressurize)&nbsp;</p><p>2. Unable to pump out (no pressurize) on level 22.4&nbsp;</p><p>3. Drain the condensate from Knok Out drum to Closed drain vessel up upto 25.0 % level&nbsp;</p><p>4. pump out again 25.0 to 22.5 (Pressurize)&nbsp;</p><p>5.Near 22.5%, the pump sound is coming abnormal (not fully flow sound)&nbsp;</p><p><br></p><p><br></p><p><br></p><p><br></p></div>', NULL, '2023-08-13 17:07:05', '2023-08-18 07:28:29', 'PTTEP\ZOC.Se-Mech', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-MCC-8950', 'ATL-OC-MCC-8950', 'MCC for ZOC Condensate Transfer Pump', NULL, NULL, 'MCC for ZOC Condensate Transfer Pump', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10849
DO $$
