  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verified the root cause of G-8925 vent fan- 1 fail', 'Electrical & Instrument', 'OTH', 'Completed', '2023-08-15', '<div><b style="font-size: 14px;"><u>Today activity</u></b><br></div><div><p>Verified the root cause of G-8925 ventilation fan-1 failure at workshop</p><p><b><u>Action</u></b></p><p>Removed armature of the motor. Found iron dust power.&nbsp;</p><p>Cleaned the dust and inside of the motor.</p><p>Measure the winding coil resistance of the motor without installing the armature.</p><p>Bearing failure contributed to fan failure and caused motor winding short circuit to ground.</p><p>&nbsp;</p><p>U2-V2 _&nbsp; 6.9 Ohm<br></p><p>U2-W2_&nbsp; 9.6 Ohm</p><p>V2-W2_ 5.4 Ohm</p><p><u style="background-color: rgb(255, 255, 0);"><b><br></b></u></p><p><u style="background-color: rgb(255, 255, 0);"><b>History&nbsp;(14-Aug-2023)</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Check the winding of the removed G-8925 Fan 1 motor coil at workshop<br> <u><b>Action</b></u></span></p><p><span style="background-color: rgb(255, 255, 0);">Measure the winding resistance of the Fan 1 motor with micro ohm meter.</span></p><p><span style="background-color: rgb(255, 255, 0);">U2-V2 _&nbsp; 6.963 Ohm</span></p><p><span style="background-color: rgb(255, 255, 0);">U2-W2_&nbsp; 9.69 Ohm</span></p><p><span style="background-color: rgb(255, 255, 0);">V2-W2_ 5.408 Ohm</span></p><p><span style="background-color: rgb(255, 255, 0);">W2-E&nbsp; _ 1175.4 Ohm</span></p></div>', NULL, '2023-08-15 15:38:56', '2023-08-23 14:06:55', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8925-PACK', 'ATL-OC-G-8925-PACK', 'Gen, ZOC Gas Generator Package2', NULL, NULL, 'Gen, ZOC Gas Generator Package2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

