  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TS SD-81145 and SD-81166 loop device fault ', 'Electrical & Instrument', 'CM', 'Completed', '2023-08-16', '<p><b><u>Today activity</u></b></p><p>TS smoke detector loop device fault at Jr accommodation and Sr accommodation.</p><p>SD-81145 S-9 and SD-81166 J-2.</p><p><b><u>Action&nbsp;</u></b></p><p><u style="background-color: rgb(255, 255, 0);">SD-81145(S-9)</u></p><p>Cleaned the internal part of the smoke detector and reinstalled.</p><p>The fault alarm not clear.&nbsp;</p><p>Replaced with new Smoke detector. Alarm clear.</p><p>Function test with smoke detector tester. Well functionable.</p><p>SD-81145 is back to normal and working properly.</p><p>&nbsp;</p><p><u style="background-color: rgb(255, 255, 0);">SD-81166(J-2)</u></p><p>Cleaned the internal part of the smoke detector and reinstalled.</p><p>The fault alarm not clear.&nbsp;</p><p>Replaced with new Smoke detector. Alarm clear.</p><p>Function test with smoke detector tester. Well functionable.</p><p>SD-81166 is back to normal and working properly.</p>', NULL, '2023-08-16 14:38:08', '2023-08-17 07:36:24', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
