  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Fix brake oil seeping of TC-2 truck crane ', 'Mechanic', 'CM', 'In Progress', '2023-08-21', '<p>Found brake oil seeping from the rear left wheel brake cylinder&nbsp;</p><p><br></p><p>-Park the truck&nbsp;</p><p>-Remove the rear left wheel by lifting with forklift&nbsp;</p><p>-Pull out the wheel assembly and remove drive shaft assemly&nbsp;</p><p>-Drain differential gear oil&nbsp;</p><p>-block the brake fluid line&nbsp;</p><p>-release the brake spring&nbsp;</p><p>-remove the brake cylinder&nbsp;</p><p>-found brake piston stacking, piston cover damage and wearing brake shoes pad&nbsp;</p><p>-replace new brake cylinder cover seal&nbsp;</p><p>-send the brake pads to Kabauk CNC shop to replace new one&nbsp;</p><p>-Waiting replace brake pad&nbsp;</p>', NULL, '2023-08-21 18:24:13', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-TC-02', 'ATL-OC-TC-02', 'Truck Crane-02 ISUZU FTR240 / UNIC V550', NULL, NULL, 'Truck Crane-02 ISUZU FTR240 / UNIC V550', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

