-- Inserting report ID 10891
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Fix brake oil seeping of TC-2 truck crane 2nd day ', 'Mechanic', 'CM', 'Completed', '2023-08-22', '<p>· Continuous fix brake oil seeping of TC-2 truck crane, </p><p><br></p><p>Found : </p><p>wearing rear tires,</p><p> brake cylinder spring defective and</p><p> wing nut broken</p><p><br></p><p>Received new brake pad install to brake drum from kanbauk CNC shop </p><p>Install the brake assembly&nbsp;</p><p>Install drive wheel bearing&nbsp;</p><p>Fill grease EP 2&nbsp;</p><p>Install bearing holder nut and lock ring&nbsp;</p><p>Install gear oil cover plate (black)&nbsp;</p><p>install cover plate&nbsp;</p><p>install drive shaft wheel nut&nbsp;</p><p><br></p><p>Install brake spring and connection (found brake spring power loss, replace spare one)&nbsp;</p><p>Fill up brake oil Dot3.&nbsp;</p><p>Drop the lifting jack by using forklift&nbsp;</p><p>start the engine and accumulate the air in the reservoir&nbsp;</p><p>releaser the air pocket from the brake system by pressing brake lever and playing wheel&nbsp;</p><p>Fill up brake oil again&nbsp;</p><p>check the leakage&nbsp;</p><p>test drive around ZOC&nbsp;</p><p>readjust brake tension&nbsp;</p><p><br></p><p>Job completed and take the punch list&nbsp;</p><p><br></p>  ', 'Punch list:&nbsp;<span style="font-size: 14px;">wearing rear tires,</span><p>brake cylinder spring defective and</p><p>wing nut broken</p>', '2023-08-22 18:35:12', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-TC-02', 'ATL-OC-TC-02', 'Truck Crane-02 ISUZU FTR240 / UNIC V550', NULL, NULL, 'Truck Crane-02 ISUZU FTR240 / UNIC V550', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;


