  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '3MPM on forklift', 'Mechanic', 'PM', 'In Progress', '2023-08-23', '<p>Job Description : 3MPM on ZOC forklift</p><p>- Check the engine; Lube oil, coolant, fuel and air filters.</p><p>- Replaced lube oil 7.5 L.</p><p>- Replaced Fan belt with a new one.</p><p>- Check the radiator and clean with compressed air.</p><p>- Check the battery and alternator.</p><p>- Check the hydraulic system and leakage.</p><p>- Check the fork condition</p><p>- Check the chain and tension at the fork lift</p><p>- Check the tire condition.</p><p>- Check the brake system</p><p>- Test the lighting, horn and alarm system</p>', '<p>Found wear belt and replace new one from Kanbauk&nbsp;</p><p>Found poor battery condition and replace new battery&nbsp;</p><p><br></p>', '2023-08-23 15:37:00', '2023-08-23 18:00:22', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
