-- Inserting report ID 10908
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'B-8910B abnormal noise CM', 'Mechanic', 'CM', 'In Progress', '2023-08-26', '<p>Job Description; B-8910B abnormal noise CM</p><p><br></p><p>Job Steps;</p><p>- Removed the pulley from pulley side.&nbsp;</p><p>- Removed the bearing covers and inspected. Found grease were dry and old. Replaced.</p><p>- Played the bearing for a while.</p><p>- Removed the gears side cover.</p><p>- Removed the gears and inspected. Found that the gears alignment are over gapped.</p><p>- Found that the rotary lubes are stacked from long term uses and not smooth.</p><p>- Used WD-40 and adjusted the gears gap.&nbsp;</p><p>- Sight glass is dirty and not clear.&nbsp;</p><p>- Drain line plug is not good and replaced with new one.</p><p>- Removed the silencer and inspected.</p><p>- Removed and replace flange fitting</p><p><br></p><p>- Will install and test run</p>', NULL, '2023-08-26 17:17:21', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-SW-B8910B', 'ATL-OC-SW-B8910B', 'Sewage Blower Unit B', NULL, NULL, 'Sewage Blower Unit B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

