  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S G-8920 shutdown trip.', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2023-09-21', '<p>- Verify the Gas generator SD trip with "Wrm Speed Low" and "Radiator Fan fault"</p><p>- Found the power cable(Radiator fan cable) inside radiator fan room bad condition. &gt;&gt; Cut the damage cable and repair terminal.</p><p>- Found the "1CR" relay socket inside the UCP-8920 (SWG-Room) was damage(melt). &gt;&gt; replaced the new one.</p><p>- Test run with no load for 1 Hr.&gt;&gt; normal</p><p>- Test run with full load.</p><p>- Keep monitor</p><p><br></p><p>** Temporary disconnect the signal at the "MS1" and "MS2". to monitor root cause.</p>', NULL, '2023-09-21 18:13:11', '2023-10-22 07:16:27', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
