  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Overhaul sewage blower B-8910B', 'Mechanic', 'CM', 'In Progress', '2023-09-21', '<p>- Install blower at local.<br>- Install the belts.</p><p>- Adjust the alignment.</p><p>- Test run the blower.</p><p>- Found pressure can not buildup. (0.2B)</p><p>- Close the outlet valve of unit A during B running. (Pressure 0.4B)</p><p>- Check the abnormal noise.</p><p>- Remove the blower package to the workshop.</p><p>- Check the lobe condition.</p><p>- Adjust the lobe.</p><p><br></p>', NULL, '2023-09-21 18:15:44', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-SW-B8910B', 'ATL-OC-SW-B8910B', 'Sewage Blower Unit B', NULL, NULL, 'Sewage Blower Unit B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
