-- Inserting report ID 10990
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S Gas generator G-8925 GVPs failed', 'Electrical & Instrument', 'CM', 'In Progress', '2023-09-22', '<p>- Clean the timing sensor(Ignition control system).</p><p>- Check the timing ignition sensor feedback.&gt;&gt; showed firing during cranking.</p><p>- Check the AFR Controller and connect with the DC Desk software.</p><p>- Try to start and record all value found.</p><p>&nbsp; &nbsp; - sometime the GPVs failed or leak alarm.</p><p>&nbsp; &nbsp; - In case the battery voltage strong enough. the GVPs vale will pass the fuel gas to AFR Controller.</p><p>&nbsp; &nbsp; - <span style="background-color: rgb(255, 255, 0);">The Actuator indicator of the AFR control not move during engine cranking.</span></p><p>&nbsp; &nbsp; - Online the DC Desk software to check the value ( have no Act output).</p><p><span style="background-color: rgb(239, 239, 239);">- Plan to charge the battery start first and try to start again.&nbsp;</span><br><br></p>', NULL, '2023-09-22 15:41:06', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Inst-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8925-PACK', 'ATL-OC-G-8925-PACK', 'Gen, ZOC Gas Generator Package2', NULL, NULL, 'Gen, ZOC Gas Generator Package2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 10991
DO $$
