  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot blower can not buildup pressure ', 'Mechanic', 'CM', 'Completed', '2023-09-22', '<p>- Drained the gear oil.</p><p>- Remove the gear housing.</p><p>- Remove the air filter housing.</p><p>- Check the lode condition.</p><p>- Adjust the lode clearance.</p><p>- Install the gear and gear housing.</p><p>- Install the air filter housing.</p><p>- Top-up gear oil.</p><p>- Function test at workshop. (Clear abnormal noise)</p><p>- Install blower package at onsite.</p><p>- Install the check valve.</p><p>- Test un (Found pressure 0.4 bar when close the outlet valve of unitA)</p><p>- Changed the check valve of unit A.</p><p>- Test run and check the pressure.</p><p>- Not found any abnormal noise and pressure 0.4 Bar.</p><p>&nbsp;</p>', NULL, '2023-09-22 16:16:36', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-SW-B8910B', 'ATL-OC-SW-B8910B', 'Sewage Blower Unit B', NULL, NULL, 'Sewage Blower Unit B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
