-- Inserting report ID 11037
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Reset G-8320 tripped and G-8310 failed to start', 'Electrical & Instrument', 'CM', 'Completed', '2023-10-01', '<p><b><u>Today activity&nbsp;</u></b></p><p>Reset G-8320 tripped and G-8310 started from CCR failed to start</p><p><b><u><br></u></b></p><p><b><u>Action for G-8320</u></b></p><p><span style="background-color: rgb(255, 255, 0);"><b>G-8320</b></span> tripped by SD L1 over voltage<br>Rest alarm and the test run.</p><p>The voltage is still high (430 V)</p><p>Stopped G-8320.</p><p><br><span style="background-color: rgb(0, 255, 0);">Plan to check and TS the AVR of G-8320 at next visit.</span><br></p><p><br></p><p><b><u>Action for G-8310</u></b><br><span style="background-color: rgb(255, 255, 0);"><b>G-8310 </b></span>start from CCR and failed to start.<br><b>Found</b> : Under oil pressure alarm.<br>Rest the alarm and test run.<br>Fls lube oil alarm occur, reset alarm and after around 5 minutes the alarm occur again.</p><p>G-8310 can run in this alarm.</p><p><br></p><p>Reset all alarm of battery charger.<br><br></p><p><b><u>Conclusion</u></b><br><span style="background-color: rgb(255, 255, 0);">G-8310 is on duty and G-8320 is on standby.</span></p><p><br></p><p><br></p><p><br><br><br></p><p><br></p>', '<p><br></p>', '2023-10-01 14:06:28', '2023-10-01 17:37:33', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8320-PACKAGE', 'ATL-BV2-G-8320-PACKAGE', 'Gen, ZBV2 Diesel Generator package2', NULL, NULL, 'Gen, ZBV2 Diesel Generator package2', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
