  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Support the drone guard installation team', 'Electrical & Instrument', 'OTH', 'Completed', '2023-10-02', '<p><b><u>Today Activity</u></b></p><p>Support the drone guard installation team to install the circuit breaker (Continue from tomorrow)</p><p><br><u><b>Action</b></u><br>Installed a 2P 16A circuit breaker initially for the power supply to a drone guard.</p><p>Performed a function test on the power circuit, the main 4P 63A circuit breaker tripped. </p><p>Discovered that the 4P 63A breaker was damaged, and there were no spare breakers available. </p><p>Bypassed the 4P 63A breaker and used the 2P 16A breaker for the drone guard''s power supply.</p><p><br></p><p><b><u>Conclusion</u></b></p><p>4P 63 breaker was damaged and no spare available.<b><u><br></u></b>Power supply for drone guard circuit breaker is ready to use.&nbsp;<br><br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>History (01/10/2023)</u></b><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Support the drone guard installation team to start up power supply for drone guard.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Found</u></b></p><p><span style="background-color: rgb(255, 255, 0);">ESD fault alarm at the switch gear P10, P-8955.</span></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>Action</u></b><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Cleared the fault alarm at CCR by operator.<br>Fault alarm clear and reset the breaker.</span></p><p><span style="background-color: rgb(255, 255, 0);">Power supply back to normal.<br><br>Plan to install the drone guard power supply terminal tomorrow</span></p>', 'G:\Department Share\04 Maintenance\06. Daily report E&amp;I Technician report\01.Picture working\2023\10.OCT\2023-10-02_Support the drone guard installation team', '2023-10-02 16:15:16', '2023-10-02 16:56:47', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTH', 'OTH', 'Other', NULL, NULL, 'Other', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
