  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '6MPM on CAT backhoe', 'Mechanic', 'PM', 'Completed', '2023-10-03', '<p><u>Working Steps</u></p><p><br></p><p>- Checked the coolant level. ( Drained and topped up 15 Liters. )</p><p>- Checked and cleaned the radiator.</p><p>- Checked the lube oil level. ( Drained and topped up 8 Liters ) Replaced at 4150.7 Hr.</p><p>- Checked the hydraulic level.&nbsp;</p><p>- Checked and cleaned the air filter.</p><p>- Checked the radiator fan belt tension and condition.</p><p>- Lubricated the joints with a grease gun.</p><p>- Checked the battery voltage and CCA.&nbsp;</p><p>- Housekeeping.</p><p><br></p><p>Running hr. 4150.7 Hr</p>', 'Found starter key near to broken and plan to buy new one.&nbsp;', '2023-10-03 14:19:19', '2023-10-03 17:05:38', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
