  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S SD-81133 water ingress at Senior accommodation', 'Electrical & Instrument', 'CM', 'Completed', '2023-10-03', '<p><u><b>Today activity</b></u></p><p>T/S SD-81133 water ingress at Senior accommodation<br></p><p><b><u>Found</u></b></p><p>Water was observed at the SD-81133 smoke detector<br></p><p><b><u>Action&nbsp;</u></b></p><p>Cleaned carefully the internal components of the smoke detector.</p><p>After cleaning, the smoke detector was reinstalled in its designated location.</p><p>The alarm status was clear.<br></p><p>Function test with smoke detector tester. Well functionable.</p><p>SD-81133 has been restored to normal working condition and is now operational.<br></p><p>Informed&nbsp;the&nbsp;logistic team to check the source of water ingress.<br></p><p><br></p><p>  <b><u>Conclusion</u></b></p><p></p>  <p>The SD-81133 is now fully operational.<br></p><p>Further investigation by the logistic team will help identify and address the root cause to prevent similar incidents in the future.</p><p><br></p>', NULL, '2023-10-03 15:15:43', '2023-10-05 15:08:57', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
