  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Inspection mechanic items at G-8925', 'Mechanic', 'PM', 'Completed', '2023-10-04', '<p>Perform precheck for 2KPM and support T/S unable to start.</p><p><br></p><p><br></p><p>-Clean air filter by compress pneumatic air&nbsp;</p><p>-remove breather filter and cleaning inside oil</p><p>-Check ignition coil connection visually&nbsp;</p><p>-Check cylinder cover head connection and connection pipe&nbsp;</p><p>-Check the coolant level, lube oil level.</p><p>-Clean the air filters, breather filters.</p><p>-Check the lube oil cooler, coolant pumps, oil filters change date, and turbocharger.</p><p>-Check the radiator fans condition and ventilation fans.</p><p>-Perform general visual check around the generator and housekeeping.</p><p>-Replace fuel filter element at the dog house.</p><p>-Applied Benzona at the coolant leak point.</p><p><br></p><p>After that, support EI team for T/S unable to start up.</p>', '-Applied Benzona on coolant seeping of seeping of cooling pipe bank B in charge air cooler line.&nbsp;', '2023-10-04 16:23:48', '2023-12-03 09:33:34', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
