  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify and TS  fire truck unable to start.', 'Mechanic', 'CM ', 'Completed', '2023-10-05', '<p><b>Description:&nbsp; Verify and troubleshoot Intervention fire truck I-01 unable to start.</b></p><p><br></p><p><b>Working steps.</b></p><p>-Check the battery and found low voltage alarm.</p><p>-Removed the batteries (2EA) and charged for 3 hours for each.</p><p>-Installed back the batteries and try to start the truck.</p><p>-still unable to start.</p><p>-Removed and checked all relays and installed back.</p><p>-Tried to start again and able to start.</p><p>-The unit back to service.</p>', '-it seems that the relays connection are loosen and not functioning properly.', '2023-10-05 18:13:05', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-FIRE TRUCK FORD550', 'ATL-OC-FIRE TRUCK FORD550', 'OC Fire truck Ford550', NULL, NULL, 'OC Fire truck Ford550', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
