DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '1MPM G-8310 & G-8320 ZBV2 Diesel Gen Package .', 'Electrical & Instrument', 'PM', 'Completed', '2023-10-06', '<p><b><u>Today activity</u></b></p><p>1M PM G-8310 &amp; G-8320 ZBV2 Diesel Gen Package .</p><p><b><u>Action</u></b></p><p><u>G-8310 </u></p><p><span style="background-color: rgb(0, 255, 255);"><u>(</u>Running Hr-46671 Hr)</span></p><p>Open Junction boxes for cleaning and re-tighten wiring termination, corrosion, clean terminals.</p><p>Check and record generator power output.<br>Top up battery water 1 liter and clean the terminal.</p><p>      </p><p>Check battery charging system.</p><p>Test run, no alarm and working properly.</p><p><u><br></u></p><p><u>G-8320</u><br></p><p><span style="background-color: rgb(0, 255, 255);"><u>(</u>Running Hr-28096 Hr)</span></p><p>Open Junction boxes for cleaning and re-tighten wiring termination, corrosion.<br></p><p><span style="background-color: rgb(255, 255, 0);"><u>Top up battery water 2 liters</u>&nbsp;</span>and clean terminals.</p><p>Check and record generator power output.</p><p></p><p>Check battery charging system.<br>Test run, no alarm and working properly.</p><p><br></p>', 'G:\Department Share\04 Maintenance\06. Daily report E&amp;I Technician report\01.Picture working\2023\10.OCT\2023-10-06_1MPM G-8310 and G-8320', '2023-10-06 15:03:58', '2023-12-05 17:11:14', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8320-PACKAGE', 'ATL-BV2-G-8320-PACKAGE', 'Gen, ZBV2 Diesel Generator package2', NULL, NULL, 'Gen, ZBV2 Diesel Generator package2', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11063
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S G-8320 tripped by hi voltage alarm', 'Electrical & Instrument', 'CM', 'Completed', '2023-10-06', '<p><b><u>Today Activity</u></b></p><p> </p><p>TS G-8320 tripped by Hi Voltage alarm.</p><p><b><u>Found </u></b></p><p>Phase to phase voltage is 446 447 448.&nbsp;<br><span style="background-color: rgb(0, 255, 0);">SD Hi Voltage alarm set point is 440.</span></p><p><b><u>Action</u></b><br></p><p>Replaced with Hot spare good condition AVR and tuning the voltage.</p><p>Tune the phase voltage 401 401 402 V .</p><p>G-8320 is on duty and G-8310 is stand by.</p><p><br></p><p>MESC No of AVR:&nbsp;36.56.44.655.3<br></p><p><br></p><p><b><u style="background-color: rgb(255, 255, 0);">History(01-Oct-2023)</u></b></p><p><u style="background-color: rgb(255, 255, 0);"><b>Today activity&nbsp;</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Reset G-8320 tripped and G-8310 started from CCR failed to start</span></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);"><b>Action for G-8320</b></u></p><p><span style="background-color: rgb(255, 255, 0);">G-8320&nbsp;tripped by SD L1 over voltage<br>Rest alarm and the test run.</span></p><p><span style="background-color: rgb(255, 255, 0);">The voltage is still high (430 V)</span></p><p><span style="background-color: rgb(255, 255, 0);">Stopped G-8320.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br>Plan to check and TS the AVR of G-8320 at next visit.<br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><u><b>Action for G-8310</b></u><br>G-8310&nbsp;start from CCR and failed to start.<br>Found&nbsp;: Under oil pressure alarm.<br>Rest the alarm and test run.<br>Fls lube oil alarm occur, reset alarm and after around 5 minutes the alarm occur again.</span></p><p><span style="background-color: rgb(255, 255, 0);">G-8310 can run in this alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Reset all alarm of battery charger.<br><b><u><br></u></b></span></p><p><span style="background-color: rgb(255, 255, 0);"><b style=""><u>Conclusion</u></b><br>G-8310 is on duty and G-8320 is on standby.</span></p><p><br></p><p><br></p>', 'G:\Department Share\04 Maintenance\06. Daily report E&amp;I Technician report\01.Picture working\2023\10.OCT\2023-10-06_TS G-8320 Hi Voltage alarm SD, Replace AVR', '2023-10-06 15:16:01', '2023-10-12 19:45:05', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8320-PACKAGE', 'ATL-BV2-G-8320-PACKAGE', 'Gen, ZBV2 Diesel Generator package2', NULL, NULL, 'Gen, ZBV2 Diesel Generator package2', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

