-- Inserting report ID 11066
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S brake loosen in Forklift ', 'Mechanic', 'CM', 'In Progress', '2023-10-06', '<p>Logistic inform forklift couldn''t control brake system during driving.&nbsp;</p><p>Urgently inform and send to Mechanic&nbsp;<br></p><p><br></p><p>-Dissemble right side front wheel&nbsp;</p><p>-Use 1-1/8 socket and heavy duty pneumatic gun to remove the wheel&nbsp;</p><p>- Remove the wheel hub&nbsp;</p><p>- check the cylinder and brake oil&nbsp;</p><p>-found oil seeping from the cylinder cap&nbsp;</p><p>-Remove brake pad and cylinder&nbsp;</p><p>-Remove cylinder from the brake system&nbsp;</p><p>-found cap and seal damage&nbsp;</p><p>-Go to buy Kanbauk shop for the piston seal and cap for temporary fix brake oil seeping&nbsp;</p><p>-Temporary install to stop brake oil seeping&nbsp;</p><p>- In progress&nbsp;</p><p>spare part Specification&nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">No. 17518 Toyota forklift 1-1/8 wheel cylinder&nbsp;</span></p><p><br></p>', '<p><span style="font-size: 14px;">1. Buy K the piston seal and cap K</span><span style="font-size: 14px;">anbauk shop for</span><span style="font-size: 14px;">&nbsp;for temporary fix brake oil seeping&nbsp;</span></p><p><span style="font-size: 14px;">2. Prepare PR to Buy New spare part&nbsp;</span></p><p><span style="font-size: 14px;">3. Informed to PMO/I, Myat Thwe, to carry spare part at YPM&nbsp;</span></p><p><br></p><p>spare part Specification&nbsp;</p><p>No. 17518 Toyota forklift 1-1/8 wheel cylinder&nbsp;&nbsp;<br></p><p><br></p><p><br></p>', '2023-10-06 17:30:08', '2023-10-06 17:32:57', 'PTTEP\ZOC.Se-Mech', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-FORKLIFT-01', 'ATL-OC-FORKLIFT-01', 'Operation Forklift-01', NULL, NULL, 'Operation Forklift-01', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

