-- Inserting report ID 11071
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Valve clearance adjustment of G-9115.', 'Mechanic', 'PM ', 'Completed', '2023-10-07', '<p><b>Working steps:</b></p><p>-Performed electrical and process isolation.</p><p>-Removed rocker arm covers.</p><p>-Cleaned the mating surfaces of rocker arm covers and cylinder bodies.</p><p><b>-Replaced rocker arm cover gasket.</b></p><p>-Checked valve lash clearance (all cylinder inlets and outlets.)</p><p><b>-Tighten the lock nut of valves ( torque 50 Nm).</b></p><p>-Vacuum cleaning rocker arms areas.</p><p>-Lubricate the rocker arm mechanism with lube oil.</p><p>-Installed back the rocker arm cover and tighten the Allen nuts <b>(torque 50 Nm).</b></p><p>-Housekeeping around the working area.</p><p><br></p><p><br></p>', NULL, '2023-10-07 16:55:42', '2023-10-07 17:15:47', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
