-- Inserting report ID 11073
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2MPM of Instrument Air Comp IA-8980B', 'Mechanic', 'PM', 'Completed', '2023-10-07', '<p>Perform bimonthly PM&nbsp;</p><p><br></p><p>Clean air filter&nbsp;</p><p>Drain crank case oil&nbsp;</p><p>check the motor base and compressor base&nbsp;</p><p>check the pipe and tube&nbsp;</p><p>check belt (found installed since Jun-2021), wearing belt&nbsp;</p><p>Replace new belt 3 EA,&nbsp;</p><p>adjust belt tension and alignment with laser&nbsp;</p><p><br></p><p>found Milky color crank case oil (inform to senior)&nbsp;</p><p>Continuous to CM activity.</p>', '<p><span style="font-size: 14px;">found Milky color crank case oil (inform to senior)&nbsp;&nbsp;</span></p><p><span style="font-size: 14px;">Senior &gt;&gt; change to CM and remove crank case cover and clean inside part to prevent corrosion&nbsp;</span></p>', '2023-10-07 18:18:35', '2023-10-07 18:29:54', 'PTTEP\ZOC.Se-Mech', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-A-8980B', 'ATL-OC-A-8980B', 'ZOC IA Compressor B', NULL, NULL, 'ZOC IA Compressor B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11074
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'CM Milky color compressor IA-8980B', 'Mechanic', 'CM', 'Completed', '2023-10-07', '<p>found Milky color crank case oil during draining oil in bimonthly PM&nbsp;</p><p><br></p><p>- Check the outside condition&nbsp;</p><p>-Check the gasket availability (Non-cuff gasket 2mm available)</p><p><br></p><p>-Disconnect tubing lines&nbsp;</p><p>-Separate crank case cover (NDE side) ( used 5/8" Spanner and socket, flat screw driver, mallet hammer)&nbsp;</p><p>-check inside of crank case&nbsp;</p><p>-Found only few milky under in sump area, not found in side of crank wall (means good condition, not serious)&nbsp;</p><p>- cleaning scrap gasket and surface for both side&nbsp;</p><p>-Make new Non- Cuff gasket (2mm, Klinger, oil resistance)&nbsp;</p><p>Gasket size ( inside radius 92mm, outside radius 113mm )</p><p>-Install new gasket with ultra black RTV&nbsp;</p><p>-adjust the flywheel to be center of Governor hosing&nbsp;</p><p>-Insert the NDE side cover by adjusting governor housing center point. (<span style="background-color: rgb(255, 255, 0);">difficult)</span></p><p>-Check the leakage and test run&nbsp;</p><p>-No leakage&nbsp;</p><p>-No vibration and good condition&nbsp;</p><p>Witness by operator&nbsp;</p>', '<span style="font-size: 14px;">adjust the flywheel to be center of Governor hosing</span>', '2023-10-07 18:28:39', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-A-8980B', 'ATL-OC-A-8980B', 'ZOC IA Compressor B', NULL, NULL, 'ZOC IA Compressor B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

