-- Inserting report ID 11081
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S G-8320 tripped by hi voltage alarm', 'Electrical & Instrument', 'CM', 'Completed', '2023-10-08', '<p><b><u>Today Activity</u></b></p><p>TS G-8320 tripped by hi voltage alarm<br><b style="text-decoration-line: underline;">Problem</b><br>G-8320 Tripped by Hi Vol SD alarm again</p><p><b><u>Action</u></b></p><p>Replaced with new AVR R438.<br>Before replaced the AVR, backup the history file with Com App.<br>Tune the voltage&nbsp;<br>V12=401, V23=401, V13=402.<br>I1&nbsp; &nbsp;=10A, I2&nbsp; &nbsp;=10A, I3&nbsp; &nbsp; =10A.<br></p><p>Test run and working normal.</p><p><a href="G:\Department Share\04 Maintenance\06. Daily report E&amp;I Technician report\01.Picture working\2023\10.OCT\2023-10-08_TS G-8320 AVR Hi Voltage SD" target="_blank">Backup History Excel</a><br></p><p><br></p><p><span style="background-color: rgb(0, 255, 255);">G-8320 is on duty(Under monitoring) .</span><br></p><p><br></p><p><b style="text-decoration-line: underline; background-color: rgb(255, 255, 0);">History(6-Oct-2023)</b></p><p><span style="background-color: rgb(255, 255, 0);">TS G-8320 tripped by Hi Voltage alarm.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Found </u></b></p><p><span style="background-color: rgb(255, 255, 0);">Phase to phase voltage is 446 447 448.&nbsp;<br>SD Hi Voltage alarm set point is 440.</span></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>Action</u></b><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Replaced with Hot spare good condition AVR and tuning the voltage.</span></p><p><span style="background-color: rgb(255, 255, 0);">Tune the phase voltage 401 401 402 V .</span></p><p><span style="background-color: rgb(255, 255, 0);">G-8320 is on duty and G-8310 is stand by.</span></p><p><br></p><p><b><u style="background-color: rgb(255, 255, 0);">History(01-Oct-2023)</u></b><br></p><p><u style="background-color: rgb(255, 255, 0);"><b>Today activity&nbsp;</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Reset G-8320 tripped and G-8310 started from CCR failed to start</span></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);"><b>Action for G-8320</b></u></p><p><span style="background-color: rgb(255, 255, 0);">G-8320&nbsp;tripped by SD L1 over voltage<br>Rest alarm and the test run.</span></p><p><span style="background-color: rgb(255, 255, 0);">The voltage is still high (430 V)</span></p><p><span style="background-color: rgb(255, 255, 0);">Stopped G-8320.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br>Plan to check and TS the AVR of G-8320 at next visit.<br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><u><b>Action for G-8310</b></u><br>G-8310&nbsp;start from CCR and failed to start.<br>Found&nbsp;: Under oil pressure alarm.<br>Rest the alarm and test run.<br>Fls lube oil alarm occur, reset alarm and after around 5 minutes the alarm occur again.</span></p><p><span style="background-color: rgb(255, 255, 0);">G-8310 can run in this alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Reset all alarm of battery charger.<br><b><u><br></u></b></span></p><p><span style="background-color: rgb(255, 255, 0);"><b style=""><u>Conclusion</u></b><br>G-8310 is on duty and G-8320 is on standby.</span></p><p><br></p><p><br></p>', '<p>G:\Department Share\04 Maintenance\06. Daily report E&amp;I Technician report\01.Picture working\2023\10.OCT\2023-10-08_TS G-8320 AVR Hi Voltage SD</p><p><br>G:\Department Share\04 Maintenance\00.E&amp;I\2.Manual &amp; Procedure\02.User Manual\Gas Generator Manual<br></p>', '2023-10-08 16:59:57', '2023-10-10 14:39:22', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8320-PACKAGE', 'ATL-BV2-G-8320-PACKAGE', 'Gen, ZBV2 Diesel Generator package2', NULL, NULL, 'Gen, ZBV2 Diesel Generator package2', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

