  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '3MPM MOGE orifice plate inspection Tube A', 'Electrical & Instrument', 'PM', 'Completed', '2023-10-09', '<p><b><u>Today Activity</u></b></p><p>Perform orifice plate inspection and 4 condition test at metering Tube A.<br><b><u>Action</u></b></p><p>Performed orifice plate inspection.(Normal)</p><p>Performed 4-Condition test for FQIC-81902A/B&nbsp; as per procedure.<br></p><p>All result are pass.</p>', 'G:\Department Share\04 Maintenance\06. Daily report E&amp;I Technician report\01.Picture working\2023\10.OCT\2023-10-09_Inspection Orifice plate and performed 4 condition', '2023-10-09 19:11:42', '2023-10-11 14:12:30', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
