-- Inserting report ID 11086
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Reinstall equip MOGE 5yrs inspection (TubeA)', 'Electrical & Instrument', 'OTH', 'Completed', '2023-10-09', '<p><u><b>Today Activity</b></u><br>Reinstall equip MOGE 5yrs inspection (TubeA)</p><p><b><u>Action</u></b></p><p>Reinstalled the tubing of the FIT-89102A /B and PIT-81902A/B.<br></p><p>Reinstalled the TIT-81903A/B.<br>De-isolated the power supply of FIT-81902A/B, PIT-81902A/B, TIT-81903A/B at the ITR.<br>Leak test with operation team, No leak.<br>All transmitters are working properly.<br><br><b><u style="background-color: rgb(255, 255, 0);">History(5-Oct-2023)</u></b><br></p><p><span style="background-color: rgb(255, 255, 0);">Remove the tubing and Temperature transmitter for MOGE Metering Station 5 yearly inspection (Tube A) activity.</span></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>Action</u></b><br>Isolated the power supply of FIT-81902A/B, PIT-81902A/B, TIT-81903A/B at the ITR.</span></p><p><span style="background-color: rgb(255, 255, 0);">Removed the tubing of the FIT-89102A /B and cover the fitting with plug and cap.<br>Removed the TIT-81903A/B and cleaned the TIT at the E&amp;I workshop.<br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Removed the orifice plate of Tube A.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Clean the orifice plate<br><b><u>Plan</u></b><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Reinstall all removed equipment after the MOGE 5yr inspection activity finished.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>Note</u></b><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Keep the tubing of FIT-81902A/B near the Tube A</span></p><p><span style="background-color: rgb(255, 255, 0);">Keep the TIT-81903A/B at the workshop.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><u><b>Require Equipment list&nbsp;</b></u><br>Ziploc<br>Isolation tape<br>Spanner&nbsp;<br>7/8", 11/16", 9/10" Adjustable</span></p><p><span style="background-color: rgb(255, 255, 0);">Screw driver *-<br><br><u><b>To remove orifice plate</b></u><br>3/4" socket&nbsp;<br>WD-40,<br>Rug<br>Red bags<br>Valve opener.</span></p>', NULL, '2023-10-09 19:22:41', '2023-10-09 19:28:42', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-PIT-81902A', 'ATL-OC-PIT-81902A', 'PT upstream of orifice plate forFY-8190A', NULL, NULL, 'PT upstream of orifice plate forFY-8190A', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
