-- Inserting report ID 11094
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '6MPM of JCB Backhoe loader', 'Mechanic', 'PM ', 'In Progress', '2023-10-10', '<p><b><u>Working steps:</u></b></p><p>-Removed the battery terminals.</p><p>-Checked the battery performance by the analyzer. (CCA= 476, voltage= 12.77V, display= REPLACE BATTERY)</p><p>-Removed and cleaned air filter by pressurized air.</p><p><br></p><p>-Drained the engine oil (15 Liters) and<b> filled up engine lube oil (dynamic plus).</b></p><p>-<b>Replaced the engine oil sump tank drain plug O-ring</b> as found damaged.</p><p>-Topped up <b>engine coolant (0.5 liter).</b></p><p><br></p><p>-Drained water from fuel water separator.</p><p>-<b>Removed the fuel level indicator access cover and visually checked&nbsp; as found fuel gauge on the display malfunction.</b></p><p>-Checked the Diesel fuel level visually (FULL)</p><p><b><br></b></p><p>-<b>Checked fan belt condition; found a crack line across the width.</b></p><p>-Performed greasing for excavator boom arms.</p><p>-<b>Replaced grease nipples (2EA)</b> as found damaged at excavator boom.</p><p>-<b>Inflated air into RHS tire as it has seeping.</b></p><p><b><br></b></p><p><b>-</b>Test run for 15 minutes and checked for abnormal condition.&nbsp;</p>', '<p>-Fuel gauge is malfunction.</p><p>-RHS tire has air seeping, probably from liner. (need to confirm)</p><p>-Fan belt has a crack line across the width. (need to order for standby)</p>', '2023-10-10 16:43:01', '2023-10-10 16:46:32', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-JCB-01', 'ATL-OC-JCB-01', 'Backhole Loader-JCB', NULL, NULL, 'Backhole Loader-JCB', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

