  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Maintenance request clearance ', 'Electrical & Instrument', 'CM', 'Completed', '2023-10-10', '<p><u><b>Today activity</b></u><br>Maintenance request clearance</p><p><u><b>Action</b></u></p><p>MR ID No(19) "The ice machine breaker is false 4-7 times a day and re- start by manually.(Completed)</p><p><br></p><p>MR ID No(11) "Air con unit is not working at ICT office, cannot turn on, LED is blinking at AC(Under monitoring).</p><p>&nbsp; &nbsp; &nbsp; &nbsp; Replaced remote battery.</p><p>MR ID No(17) "Defective switch for power socket" (Senior 12).(Completed)<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; Replaced with new socket.</p><p>MR ID No(9) "To check socket&nbsp; at["Warehouse"].(Completed)</p><p>&nbsp; &nbsp; &nbsp; &nbsp; Replaced with new socket.</p><p>TS the dish washer (Completed)<br></p><p>&nbsp; &nbsp; &nbsp; &nbsp; Repair pipe and clean float switch.</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', NULL, '2023-10-10 17:20:51', '2023-10-12 19:51:30', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
