-- Inserting report ID 11097
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'I-01 Firetruck T/S  intercooler broken Day-2', 'Mechanic', 'CM', 'Completed', '2023-10-11', '<p>Continuous from Day-1.&nbsp;&nbsp;</p><p>Left over night for Benzona to be dried up.<br></p><p>All are cured and hardened.</p><p><br></p><p>The broken part is assembly by 4 mini part.&nbsp;</p><p>1. 8cm diameter Rubber hose (used for Gas Generator coolant pipe)&nbsp;</p><p>2. Filler non-cuff black gasket material heat resistance&nbsp;</p><p>3. Benzona epoxy for upper cover coat&nbsp;</p><p>4. original broken part&nbsp;</p><p>5. Tighten by pipe clip 10cm&nbsp;</p><p><br></p><p>Reassembled and started the engine without Driving gears.</p><p>Found that the temperature is not too much. Around 40 Degree C.</p><p><br></p><p>After that, test ran around ZOC compound and temp was risen up to <span style="background-color: rgb(255, 255, 0);">80 Degree C</span> with the speed 40KM/Hr.</p><p>And then test ran to Junction with various speed up to 80KM/Hr., temp was <span style="background-color: rgb(255, 255, 0);">120 Degree C</span>.</p><p>After that, connected with Pump functions and Discharge Test with 1250 rpm, temp was up to <span style="background-color: rgb(255, 255, 0);">146 Degree</span> C.</p><p><br></p><p><br></p>', '<div><span style="font-size: 14px;"># Not recommended to ZMS or high hill&nbsp; travel.</span><br></div>', '2023-10-11 14:06:55', '2023-10-11 16:37:55', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-ET01', 'ATL-OC-ET01', 'ZOC Fire Intervention Truck', NULL, NULL, 'ZOC Fire Intervention Truck', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

