-- Inserting report ID 11102
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 1YPM on 2 posts car lift at WS', 'Mechanic', 'PM', 'Completed', '2023-10-12', '<p>Perform 1YPM on 2 posts car lift at the workshop</p><p><br></p><p>- Check the lift body structure.</p><p>- Check the base nuts and torque with 100 Nm</p><p>- Perform visual check around the body and structure.</p><p>- Check the hydraulic oil condition and level. not replaced.</p><p>- Check the filter.</p><p>- Check the steel cable condition and any breakage.</p><p>- Check the hydraulic hose condition and found some cracks but still usable.</p><p>- Check the stopper and works normally.</p><p>- Check the motor and abnormal noises. Works normally.</p><p>- Check the control box and works properly.</p><p>- No hydraulic leakage.</p><p>- No abnormal parameters.</p><p><br></p>', NULL, '2023-10-12 15:54:37', '2023-10-12 16:36:10', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTH', 'OTH', 'Other', NULL, NULL, 'Other', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11103
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 6MPM on TC-1', 'Mechanic', 'PM', 'Completed', '2023-10-12', '<p>Perform 6MPM on TC-1</p><p><br></p><p>-Check the PTO system; leakage, noise and fasteners conditions.</p><p>-Check the propeller shaft and apply grease. Works properly.</p><p>-Check the hydraulic pump and no abnormal noise. no leakage. works properly.</p><p>-Check the hydraulic tank and no leak, no crack and no water or air inside. Filter is cleaned and normal.</p><p>-Check the control valve and no leak, no crack or no problem.</p><p>-Check the outrigger and no leak, no drop down after rigging up, no abnormal.</p><p>-Check the swivel joint and no leak, greased, fasteners are tightened. works properly.</p><p>-Check the hoist winch and works properly. No damage, applied grease and works properly.</p><p>-Slewing device is working properly. No staggering and working normal.</p><p>-Derrick cylinder is properly working, no cracks, no damage and no leak.</p><p>-Telescoping cylinder is working normal. no leak and no sinking.</p><p>-Boom extend and retract is working normal. Greased properly. no damage and no wear.</p><p>-Wire rope condition is in good condition. 10mm thickness all the way.</p><p>-Hoses and piping are good and no leak. applied denso tape.</p><p>-Hook is still in best shape. No damage and no crack.</p><p>-Limit switch is working properly and tested.</p><p>-Mounting level is same when using outrigger.</p><p>-Alarm system is working properly.</p><p>-Name plate is good and no damage.</p><p>-Engine is checked; lube oil replaced 17 Liters.</p><p>-Coolant is good and at Max Level.</p><p>-Fan belt is good. not slack and no damage.</p><p>-bolts and nuts are tightened properly.</p><p>-Clean air filters.</p><p>-No leakage around the engine. All hoses are good.</p><p>-Drained water from fuel filters.</p><p>-Tightened the wheels nuts.</p><p>-Test run and load test at warehouse.</p>', NULL, '2023-10-12 16:05:20', '2023-10-12 16:35:36', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-TC-01', 'ATL-OC-TC-01', 'Truck Crane-01 ISUZU FTR240 / UNIC V550', NULL, NULL, 'Truck Crane-01 ISUZU FTR240 / UNIC V550', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

