-- Inserting report ID 11159
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Kobelco hydraulic seeping at supply fitting ', 'Mechanic', 'CM', 'In Progress', '2023-10-22', '<p>Operator informed hydraulic seeping from the hose fitting of direction control valves.&nbsp;</p><p><br></p><p>Verify and found that seeping from the inlet hydraulic power supply fitting&nbsp;</p><p><br></p><p>Mark the fitting number&nbsp;</p><p>check the Spanner number (22mm/ 15/16"), 27mm spanner&nbsp;</p><p>Prepare the plug fitting (female / male ), BSP fitting size (1/2" plug in supply line, 3/8" plug in other lines)</p><p>Remove the fitting of hose number, (2A, 2B, 3A, 3B, 4A,4B, 5A, 5B, 6A, 6B). by 22mm spanner and plug by 3/8 BSP fitting.&nbsp;</p><p>Remove the supply line hose (1/2" BSP )&nbsp; by 27mm spanner.&nbsp;</p><p>Remove the fitting by using 24mm spanner&nbsp;</p><p>Take out the supply fitting and check the seal condition&nbsp;</p><p>O-ring Seal is deformed and type is silicon seal</p><p>Check the available spare part seal (Silicon 113 O ring)&nbsp;</p><p>Cleaning the area by oil one&nbsp;</p><p>install back the fitting and hose by step by step.&nbsp;</p><p>found difficult installation</p><p><br></p>', '<p>Spare part - Silicon O Ring -113</p><p>Required Tool - Combination spanner ( 22mm, 24mm, 27mm) , Fabricate 22mm spanner to tight lock nut&nbsp;</p><p>Required plug - 6 pcs - 3/8" BSP female and male, 1 pcs -1/2 BSP female and male plug&nbsp;</p><p><br></p>', '2023-10-22 17:42:25', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-EXCAVATOR-01', 'ATL-OC-EXCAVATOR-01', 'Mini Excavator-KOBELCO', NULL, NULL, 'Mini Excavator-KOBELCO', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

