-- Inserting report ID 11191
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify the Generator G-8925 can not start', 'Electrical & Instrument', 'CM', 'In Progress', '2023-10-30', '<p>- Verify the Gas Generator G-8925 can''t start.</p><p>- We got the new Dongle <a href="Level:6">Level:6</a>&nbsp;for the AFR Controller.</p><p>summarize</p><p>- The Dongle <a href="level:6">level:6</a>&nbsp;(software version 00:xx:xx) can''t communicated with AFR control on G-8925. (software version 14:xx:xx)</p><p>- The back up file can''t upload to the new AFR controller (G-8930) due to the software version). 80 % of the configuration are difference and the unit also.</p><p><br></p><p>Note:&nbsp; &nbsp;- New AFR Controller on G-8930 (software version: 00:xx:xx)&nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Old AFR Controller on G-8925 (Software version: 14:xx:xx)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Back up file can''t upload to new AFR Controller because the software version.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Dongle Lever 2: for software version : 14:xx:xx</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Dongle Lever 6: for software version : 00:xx:xx<br></p>', NULL, '2023-10-30 16:01:00', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Inst-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8925-PACK', 'ATL-OC-G-8925-PACK', 'Gen, ZOC Gas Generator Package2', NULL, NULL, 'Gen, ZOC Gas Generator Package2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

