  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Adjust fan belt tension on AHU 1', 'Mechanic', 'CM', 'Completed', '2023-10-30', '<p>- Performed election isolation.</p><p>- Check the belt tension and alignment.</p><p>- Loose the mounting bolts of motor.</p><p>- Adjust the lock nut for tension.</p><p>- Adjust the alignment.</p><p>- Check the tension of belt.</p><p>- Tighten the mounting bolt.</p><p>- Housekeeping the working area.</p><p>- Test run and check the belt condition.</p>', NULL, '2023-10-30 16:06:15', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
