  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify the Generator G-8925 can''t start', 'Electrical & Instrument', 'CM', 'In Progress', '2023-10-31', '<p>- Verify the Gas Generator G-8925 can''t start.</p><p>today activities.</p><p>- Install the New AFR controller on G-8925.</p><p>- Manual the AFR-Actuator and monitor indicator.</p><p>- Try to start the generator the engine speed around 200-300 rpm and found the Gas inlet pressure around 10 kpa.(quite low)&gt;&gt; suspect battery voltage low.</p><p>- Remove the battery and re-charge at the workshop.&nbsp;</p><p>- Install the battery after re-charge around 4 Hrs.</p><p>- Try to start again but the motor start not turn due to low battery voltage.</p><p><br></p><p>Note: Battery low performance need to replace.&nbsp;&nbsp;</p>', NULL, '2023-10-31 15:58:13', '2023-10-31 15:58:47', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Inst-Tec', false) RETURNING id INTO new_report_id;
