  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Fixed the diesel seeping from diesel dispenser. ', 'Mechanic', 'CM ', 'Completed', '2023-11-01', '<p><b>Description: Verified and fixed the diesel seeping from the pump body of ZMS diesel dispenser.</b></p><p><br></p><p><b><u>Working Steps</u></b></p><p><br>Depressurized the diesel dispenser pump.</p><p>Drained the residual diesel from the pump.</p><p>Cleaned the seeping point with the sand paper.</p><p>Checked the seeping point with the penetrant sprays.</p><p>Cleaned the seeping point with the cleaner sprays.</p><p>Applied Belzona on the seeping point.<br>After 24 hours later, test run and checked the oil seeping.<br><br></p><p><br></p><p><br><br></p>', NULL, '2023-11-01 17:57:25', '2023-12-08 09:58:10', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-A-9095', 'ATL-MS-A-9095', 'Diesel Dispenser unit', NULL, NULL, 'Diesel Dispenser unit', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11197
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot SD low oil pressure alarm', 'Mechanic', 'CM ', 'Completed', '2023-11-01', '<p>Working Steps</p><p><br></p><p>Checked the alarm history and the parameter.</p><p>Removed and cleaned the pressure sensors.</p><p>Checked the sensor cable connection.</p><p>Test run and the pressure reading 2.7 bars.</p><p><br></p><p>Swapped the lube oil pressure sensors from G-9110.</p><p>Test run and the pressure reading 2.7 bars.</p><p><br></p><p>Replaced the lube oil pressure filters.</p><p>Test run and the pressure reading 5 bars.</p><p>Stopped the generator and checked oil leakage and oil level.</p><p>Topped up lube oil 14 Liters.</p><p>Test run and kept the generator online.</p><p><br></p>', NULL, '2023-11-01 18:13:13', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9120-PACKAGE', 'ATL-MS-G-9120-PACKAGE', 'Gen, ZMS Gas Generator package3', NULL, NULL, 'Gen, ZMS Gas Generator package3', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

