  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify Vent Fan fault at ZBV1', 'Electrical & Instrument', 'CM', 'In Progress', '2023-11-11', '<p>- Follow up the ventilation fan malfunction as per report (Handover) on 18 Oct 2023.</p><p>- Replaced the new power cable as per mention in the report. after replaced the ventilation still can''t run and voltage output drop measurement with connect load is 147 Vac. and disconnect load&nbsp; 203 Vac.</p><p>- Performed the insulation resistance testing the cable&nbsp; "L" and "N" and "G" all are normal condition. &gt;&gt; more than 100 M-Ohm.</p><p>- Swap the ventilation fan controller(Magnetic contactor) by </p><p>&nbsp; &nbsp; - the Ventilation fan no.1 use the Magnetic contactor no.2 &gt;&gt; Ventilation fan no.1 can''t start.</p><p>&nbsp; &nbsp; - the Ventilation fan no.2 use the Magnetic contactor no.1 &gt;&gt; Ventilation fan no.2 can run as normal.</p><p>- Suspect the Magnetic contactor for ventilation no.2 abnormal condition need to deeply verify.</p><p>- Prepare the drawing and plan to T/S again soon&nbsp;</p>', NULL, '2023-11-11 17:00:01', '2023-11-11 17:07:09', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-VENTILATION-FAN-2', 'ATL-BV1-VENTILATION-FAN-2', 'FAN, ZBV1 VENTILATION FAN 2', NULL, NULL, 'FAN, ZBV1 VENTILATION FAN 2', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
