-- Inserting report ID 11231
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '12M PM Emergency Diesel Generator', 'Mechanic', 'PM ', 'In Progress', '2023-11-12', '<p>11-Nov-2023</p><p><br></p><p>- Test run and record the parameter.</p><p>- Checked the lube oil level.</p><p>- Checked the lube oil leakage.</p><p>- Checked and Cleaned the crankcase breather.</p><p>- Checked the alternator belt tension and condition.</p><p>- Replaced the diesel filter.</p><p>- Checked the fuel line leakage.</p><p>- Replaced the coolant (CAT NGE Coolant - 125 Liters)</p><p>- Test run and checked any abnormality.</p><p><br></p><p>12-Nov-2023</p><p><br></p><p>- Checked the Coolant Level.</p><p>- Checked the coolant leakage.</p><p>- Checked the radiator cap condition.</p><p>- Removed the cylinder heads.</p><p>- Checked and adjusted the valve clearance.</p><p>- Remove the exhaust cover.</p><p>- Repair the exhaust cover and reinstall.</p><p>- Checked and cleaned the air filters.</p><p>- Checked the air service indicator.</p><p>- Visually inspect the turbo chargerscondition.</p><p>- Test run and check any abnormal noise and vibration.</p><p><br></p><p>13-Nov-2023</p><p>- Checked the mounting bolts tension.</p><p>- Removed and cleaned the radiator fun belt cover.</p><p>- Removed and cleaned the radiator fun by <u><b style="background-color: rgb(255, 255, 0);">removing the 6 FUN BOLTS.</b></u></p><p>- Loosen the tension lock nut and the tension bolt.</p><p>- Removed the used radiator fun belt. (4 EA)</p><p>- Replaced the new radiator fun belt. (4 EA)</p><p>- Installed the radiator fun by applying the thread lock.</p><p>- Checked and adjusted the radiator fun nuts&nbsp; tension.&nbsp;</p><p>- Checked and adjusted the radiator fun belt tension.</p><p>- Checked and tightened the radiator pulley mounting bolts and lock nuts.</p><p>- Checked and cleaned the radiator.</p><p>- Installed the radiator fun cover.</p><p>-&nbsp; Test run and check any abnormal noise and vibration.</p><p><br></p><p>15-Nov-2023</p><p>- Checked the lube oil leakage.</p><p>- Checked the fuel leakage.</p><p>- Checked the coolant leakage.</p><p>- Visually Inspected the flame arrester condition.</p><p>- Checked the machine guard condition.</p><p>- Checked the exhaust insulation and mounting condition.</p><p>- Checked the loosening bolts and nuts.<br></p><p>- Checked any abnormality.</p><p>- Checked and Cleaned the whole generator package.</p><p>- Housekeeping and Kept the generator LOCAL AUTO Mode.</p><p><br></p>', NULL, '2023-11-12 18:36:53', '2023-11-18 10:51:57', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9125-PACKAGE', 'ATL-MS-G-9125-PACKAGE', 'Gen, ZMS Diesel Generator Package', NULL, NULL, 'Gen, ZMS Diesel Generator Package', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

