  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replaced the Degrading Firewater Pump Packings', 'Mechanic', 'CM ', 'Completed', '2023-11-15', '<p><u><b>Working Steps</b></u></p><p><br></p><p>Removed the gland and the gland followers.</p><p>Removed three degrading packings from the staffing box.</p><p>Cleaned the staffing box and the gland follower.</p><p>Cut the packings in the required size.</p><p>Inserted the packing into the staffing box in the correct position one by one.</p><p>Replaced three new packings.</p><p>Test run and adjusted by checking the packing temperature.</p><p>Recorded the parameter and kept the firewater pump stand by.</p><p><br></p><p><br></p><p><br></p>', 'Replaced the DE side packings only.', '2023-11-15 18:23:25', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
