-- Inserting report ID 11263
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Day 3 of YPM of TADANO', 'Mechanic', 'PM', 'In Progress', '2023-11-23', '<p>Day 3 of YPM of TADANO,</p><p><br></p><p>Job Steps,</p><p>-Drained wench gear oil and replaced with new oil; both sides total 8 liters.</p><p>-Drained swing gear oil and replaced with new oil 1.6 liters.</p><p>-Checking Hydraulic pressure at-</p><p>&nbsp; &nbsp; -Pilot remote pressure Idle 700 rpm - 2.9 MPa, 1900 rpm - 3.9 MPa. (Instructions)</p><p>&nbsp; &nbsp; -Actual pressure idle 700 rpm - 3.85 MPa, 1900 rpm - 3.95 MPa.</p><p><br></p><p>&nbsp; &nbsp; -Outriggers pressure Minimum pressure - 3.4 MPa, Maximim at 1900 rpm - 20.6 MPa (Instructions)</p><p>&nbsp; &nbsp; -Actual pressure Minimum pressure - 3.6 MPa, Maximum at 1900 rpm - 22 MPa</p><p><br></p><p>&nbsp; &nbsp; -Steering pressure at Maximum 2500 rpm - 15.7 MPa. (Instruction)</p><p>&nbsp; &nbsp; -Actual pressure at Maximum 2500 rpm - 15.5 MPa</p><p>-Applied Brilube all along the wire rope. and Check the breakage.&nbsp;</p><p>-Check the brake system; brake pads condition and readjust the parking brake. (Need to test during test run)</p><p>-Applied grease at points and outriggers.</p><p>-Measured and recorded main hook and secondary hook block dimensions. Found no abnormal</p><p>-Housekeeping and end of Day 3</p>', NULL, '2023-11-23 16:02:25', '2023-11-23 17:49:58', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-CRANE-01', 'ATL-OC-CRANE-01', 'Operation Crane-01 TADANO-30T-GR3000EX', NULL, NULL, 'Operation Crane-01 TADANO-30T-GR3000EX', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

