-- Inserting report ID 11266
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Day 4 of YPM on TADANO ', 'Mechanic', 'PM', 'Completed', '2023-11-24', '<p>Day 4 of YPM on TADANO</p><p><br></p><p>Job Steps;</p><p><br></p><p>-Perform tightening torque on swinging bearing bolts.</p><p>&nbsp; &nbsp; -Outer ring Torque 628Nm by 300Nm and 328Nm. (5 out of 26 bolts, random check)</p><p>&nbsp; &nbsp; -Inner ring bolts same torque as outer ring. 10 bolts random check around the swing.</p><p>-Greasing the remaining points and boom extension.</p><p>-Found that air pressure gauge is not working.</p><p>&nbsp; &nbsp; -Removed the dashboard panel and test the wiring lines. (Found normal)</p><p>&nbsp; &nbsp; -Removed the control board panel behind driver seat; test the wiring. (Found normal)</p><p>&nbsp; &nbsp; -Found all wiring and sensor is working; assume that air pressure dial gauge is worn out.</p><p>-Test the crane performance by extending the boom to the limit.</p><p>&nbsp; &nbsp; -Drop the primary hook and play, swing and wait for a few minutes. No drop or no abnormal.</p><p>&nbsp; &nbsp; - Secondary hook was tested same as primary hook.</p><p>-Test run and test the brake.</p><p>-End of Day 4.</p><p><br></p><p>&nbsp;</p>', NULL, '2023-11-24 16:35:28', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-CRANE-01', 'ATL-OC-CRANE-01', 'Operation Crane-01 TADANO-30T-GR3000EX', NULL, NULL, 'Operation Crane-01 TADANO-30T-GR3000EX', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

