-- Inserting report ID 11270
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'YPM on Forklift Day 1', 'Mechanic', 'PM', 'In Progress', '2023-11-25', '<p>Perform YPM on ZOC Forklift Day 1</p><p><br></p><p>Job Steps</p><p><br></p><p>-Tools and spare parts preparations, Conducted Toolbox Talk.</p><p>-Checked around the forklift for leakage and abnormals.</p><p>-Replaced Air Filters.</p><p>-Drained engine oil and replaced with new Dynamic + for 9 liters. Lube oil filter is not yet arrived.</p><p>-Drained hydraulic oil and replaced with Hydraulic 68 for 38 liters.</p><p>-Drained Transmission fluid and replaced with new Dexron 3 for 6 Liters.</p><p>-Replaced hydraulic filter and suction filter.</p><p>-Replaced radiator coolant Premixed for 5 Liters.</p><p>-Replaced fuel water separator and check the fuel water strainer.</p><p>-Cleaned the hydraulic tank.</p><p>-Checked the fan belt tension. No need to replaced. In Good condition.</p><p>-Checked the water line pipes condition and engine mounting bolts.</p><p>-Checked the joy sticks condition and looseness.</p><p>-Checked the battery condition and in good condition.</p><p>-Visual checked around the engine and fuel lines. No leak and in good condition.</p><p>-Checked the chain connections and apply lube oil instead of grease because dusts and sands can be stacked into the chains.</p><p>-Housekeeping and end of day 1.</p><p><br></p>', NULL, '2023-11-25 17:08:52', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-FORKLIFT-01', 'ATL-OC-FORKLIFT-01', 'Operation Forklift-01', NULL, NULL, 'Operation Forklift-01', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11272
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Monthly inspection and belt replace AHU Unit-2 ', 'Mechanic', 'PM', 'Completed', '2023-11-25', '<p>Perform Monthly inspection</p><p>-found belt need is wearing, need to replace&nbsp;</p><p>-<span style="background-color: rgb(255, 255, 0);">replace new belt 2 EA</span>&nbsp;</p><p>-perform belt tension adjustment and alignment&nbsp;</p><p>-perform basement check&nbsp;</p><p>-check motor condition, look like DE motor bearing sounding. (Inform to EI)&nbsp;</p><p>-check radiator and found cleaning&nbsp;</p><p>-check pully bearing, grease is enough for both side&nbsp;</p><p>- check blower fan rotor blades, found solidity dusty&nbsp;</p><p>-cleaning the solidity dust by scrapping&nbsp;</p><p>-collect the dust by vacuum cleaning&nbsp;</p><p>-cleaning the package&nbsp;</p><p>-perform housekeeping&nbsp;</p><p>-test run the package&nbsp;</p><p><br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Required Tools,&nbsp;</span><font color="#ffff00" style="background-color: rgb(255, 255, 0);"></font></p><p>- 1-1/16 Spanner, 17mm&nbsp; spanner,&nbsp;</p><p>-flat screw driver&nbsp;</p><p>-rags, red bag&nbsp;</p><p>-claw bar&nbsp;</p><p>-touch light and portable light (borrow CCR)&nbsp;</p><p>- scraper&nbsp;</p><p>-</p><p><br></p>', NULL, '2023-11-25 17:12:53', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-HVAC-AHU2', 'ATL-OC-HVAC-AHU2', 'Air Handling Unit 2', NULL, NULL, 'Air Handling Unit 2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

