-- Inserting report ID 11280
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'YPM on Forklift Day 2', 'Mechanic', 'PM', 'Completed', '2023-11-26', '<p>Perform YPM on ZOC Forklift Day 2</p><p><br></p><p>Job Steps;</p><p><br></p><p>-Top up Differential oil at front wheel ; about 8 L. GL-5</p><p>-Cleaned the grease points thoroughly and greased properly (Need to check per month at least)</p><p>-Removed front wheels both sides and inspected the tires. (Good condition)</p><p>-Removed the wheel drum and inspected the brake drums and brake shoes;</p><p>&nbsp; &nbsp; -Left side ; brake shoe - 7mm (As Found) ; if 2mm need to be replaced.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; brake drum - 310mm (As Found) ; if 312mm need to be replaced.</p><p>&nbsp; &nbsp; -Right side; rake shoe - 6.5mm (As Found) ; if 2mm need to be replaced.<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; brake drum - 310mm (As Found) ; if 312mm need to be replaced.</p><p>-Tested the cylinder pressure; Tip cylinders pr; 20Mpa. Lift cylinders pr; 20Mpa.</p><p>-Found no leak.</p><p>-Visual check around the cylinders and all are normal.</p><p>-Test run and brake test. All are normal.</p><p>-Housekeeping and completed the job.</p><p><br></p>', NULL, '2023-11-26 17:25:17', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-FORKLIFT-01', 'ATL-OC-FORKLIFT-01', 'Operation Forklift-01', NULL, NULL, 'Operation Forklift-01', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

