  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S oil seeping of B-8910B Day2 ', 'Mechanic', 'CM', 'Under Monitoring', '2023-11-30', '<p>Continuous from day-1&nbsp;</p><p><br></p><p>-Assemble back motor part&nbsp;</p><p>-Check the alignment of motor shaft&nbsp;</p><p>-Found unbalance eccentricity circle shaft (misalignment) - 1.4mm on 180 degree position&nbsp;</p><p>-It can cause easily bearing damage&nbsp;</p><p>-Install basement frame, blower unit to the position, motor unit&nbsp;</p><p>-Align motor and blower unit&nbsp;<br></p><p>-Deisolate the electric power (by EI tech)&nbsp;</p><p>-Test and jog motor, found bearing ball playing sound from DE side</p><p>-discuss with EI team and plan to replace new motor&nbsp;</p><p>-Install back belt and make the belt alignment&nbsp;</p><p>-test runt sewage blower unit&nbsp;</p><p><br></p><p>Test run result&nbsp;</p><p>-No oil seeping on fabricate hose oil drain line - Normal&nbsp;</p><p>-belt temperature - Normal&nbsp;</p><p>-Motor bearing sound - Abnormal&nbsp;</p><p>-Blower unit sound - lube touch sound - Abnormal&nbsp;</p><p>-Temperature in bearing blower - 68 Degree (DE)&nbsp;</p><p><br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">Future planning,</span>&nbsp;</p><p>-Keep running and monitoring&nbsp;</p><p>- Replace new set of sewage blower&nbsp;</p><p>-Replace new Motor (by EI team)&nbsp;</p><p>-during spare part waiting time, replace bearing only&nbsp;</p><p>-Buy new better quality bearing&nbsp;</p>', '<p>Test run result&nbsp;</p><p>-No oil seeping on fabricate hose oil drain line - Normal&nbsp;</p><p>-belt temperature - Normal&nbsp;</p><p>-Motor bearing sound - Abnormal&nbsp;</p><p>-Blower unit sound - lube touch sound - Abnormal&nbsp;</p>', '2023-11-30 17:22:21', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-SW-B8910B', 'ATL-OC-SW-B8910B', 'Sewage Blower Unit B', NULL, NULL, 'Sewage Blower Unit B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
