  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Weekly inspection PM and running test of G-9115.', 'Mechanic', 'OTH ', 'Completed', '2023-12-01', '<p><b>Description:</b> Performed weekly inspection PM and running test of standby gas engine generator G-9115</p><p><br></p><p><b>Working steps:</b></p><p>-Checked lube oil level and<b> topped up 30 Liters.</b></p><p>-Checked radiator coolant level and<b> topped up 10 Liters.</b></p><p>-Checked and cleaned air filters.</p><p>-Checked and cleaned breather filters.</p><p>-Housekeeping around the working area.</p><p>-Test run with shared load for 30 minutes.</p>', '-Swapped the bank A side governor actuator with G-9110''s. (excluding the control circuit) to troubleshoot G-9110 tripped issue.', '2023-12-01 17:10:56', '2023-12-01 17:27:21', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
