BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verified G-9110 tripped issue.', 'Mechanic', 'CM ', 'Under Monitoring', '2023-12-01', '<p><i><u>Description: P</u></i>erformed verification of Gas Engine Generator G-9110 tripped with "<b>Sd Eng&lt;RPM" alarm.</b></p><p><br></p><p><u><i>Working steps:</i></u></p><p>-Removed and checked<b> the resistance magnetic speed senor and it is normal.</b></p><p><b>-Swapped the bank A governor actuator with G-9115''s. (excluding the control circuit).</b></p><p>-Test run with shared load.</p><p>-While running,<b> measured the consumed current</b> of the actuator of Woodward control board: found no abnormal and the current is within the allowable limit.</p><p><b>-The unit is running in progress and under monitoring.</b></p>', NULL, '2023-12-01 17:19:18', '2023-12-01 17:24:35', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
