-- Inserting report ID 11322
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S kobelco hy return line oil seeping Day 2', 'Mechanic', 'CM', 'Completed', '2023-12-02', '<p>T/S kobelco hydraulic return line oil seeping Day 2</p><p><br></p><p>Job Steps;</p><p><br></p><p>-Removed adjacent hydraulic plugs and ports to clear the area for spanner space.</p><p>-Use proper oil drum under the leak point and during the troubleshooting.</p><p>-Removed the main hydraulic return line hose connection.</p><p>-Inspected and found that the oil seal is damaged.</p><p>-Replaced with new one and installed back the hoses.</p><p>-Test run and under monitoring.</p>', NULL, '2023-12-02 15:27:03', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-EXCAVATOR-01', 'ATL-OC-EXCAVATOR-01', 'Mini Excavator-KOBELCO', NULL, NULL, 'Mini Excavator-KOBELCO', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
