-- Inserting report ID 11324
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verified G-9110 tipped issue.', 'Mechanic', 'CM ', 'Under Monitoring', '2023-12-03', '<p><b>Description: :Performed verification of Gas Engine Generator G-9110''s tripped with Low RPM alarm.</b></p><p><br></p><p><b><u>Working steps: :</u></b></p><p>-<b><i>Re-</i></b><i><b>Swapped&nbsp; back "the governor actuator bank A and B" to the original generator sets</b></i>. (excluding the control circuit).</p><p>-Removed and inspected <i><b>the AVR control board </b></i>for any abnormal condition and cleaned the connection.</p><p>-Checked <i><b>ComAp controller</b></i> for any abnormal parameters and settings.</p><p><b style="background-color: rgb(255, 255, 0);">-Test run with no load and found bank B side exhaust temperature not getting increase and Bank A side exhaust temperature higher.</b></p><p>-Removed <i><b>the Bank A side exhaust flame arrestor and cleaned it by pressurized water/air.</b></i></p><p>-Inspected <i><b>the bank A side turbo-charger</b></i> for any abnormal condition: found normal.</p><p>-Installed the bank A side flame arrestor and Test run again with no load.</p><p>-<span style="background-color: rgb(255, 255, 0);"><b>still found exhaust temperature difference higher.</b></span></p><p>-Removed<i><b> the bank B side flame arrestor </b></i>and cleaned it by pressurized water/air.</p><p>-Inspected<i><b> the bank B side turbo-charger</b></i> for any abnormal condition: found normal.</p><p>-Test run again with no load.</p><p><b>-<span style="background-color: rgb(255, 255, 0);">still found exhaust temperature difference higher.</span></b></p><p><b><i style="background-color: rgb(0, 255, 255);">-Adjusted fuel gas flow at ZPR regulator of bank A side to decrease gas. (counterclockwise ) and bank B side fuel gas flow at ZPR regulator to increase gas. (clockwise turn to about 3deg).(during running operation).</i></b></p><p><span style="background-color: rgb(0, 255, 255);"><i><b>-Found both banks temperature is getting the same.</b></i></span></p><p>-Test run with shared load for 20 minutes and change to full load.</p><p><span style="background-color: rgb(255, 255, 0);"><b><u>-the unit is under monitoring.</u></b></span></p><p><br></p>', NULL, '2023-12-03 15:29:01', '2023-12-03 18:42:09', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9110-PACKAGE', 'ATL-MS-G-9110-PACKAGE', 'Gen, ZMS Gas Generator package1', NULL, NULL, 'Gen, ZMS Gas Generator package1', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

