  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-FM200-CCR', 'ATL-OC-FM200-CCR', 'FM200 Fire Fighting Sys OC Control bld', NULL, NULL, 'FM200 Fire Fighting Sys OC Control bld', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
