  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Inspection PM and test run spare gen G-8310', 'Mechanic', 'PM', 'Completed', '2023-12-06', '<p>G-8310 is out of service and need to be replaced.</p><p>Inspection and perform PM on spare standby generator.</p><p>- Cleaned and visual check.</p><p>- Check air filters, belt tension and condition, lube oil, coolant, fuel gauge and battery condition.</p><p>- Check engine mountings, clamps and fasteners.</p><p>- Check the coolant lines, pump, alternator and starter motor condition.</p><p>- Test run and check the parameters but without load.</p><p>- Found no abnormal.</p><p>- Serviceable.</p>', NULL, '2023-12-06 16:47:28', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310', 'ATL-BV2-G-8310', 'Gen, ZBV2 Diesel generator No1', NULL, NULL, 'Gen, ZBV2 Diesel generator No1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
