-- Inserting report ID 11360
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Lifting to swapping spare generator with G-8310', 'Mechanic', 'OTH', 'Completed', '2023-12-07', '<p>Lifting the generator by fork lift from the workshop and place at the floor&nbsp;</p><p>lift the generator by TC-1 and place the the truck&nbsp;</p><p>transfer generator by TC from ZOC Workshop to ZBV#2&nbsp;</p><p>drop the spare generator&nbsp;</p><p>remove the G-8310 and lift up to the trailer&nbsp;</p><p>Lift and install spare generator to G-8310 position&nbsp;</p><p><br></p><p>Requirement&nbsp;</p><p>- 3 Ton Webbing sling&nbsp; - 2 EA&nbsp;</p><p>- 5 Ton round sling - 2 EA&nbsp;</p><p>- 4 Leg sling - 1 EA&nbsp;</p><p>- 3/4" shekel - 4 EA&nbsp;</p><p>-tag line rope&nbsp;</p>', NULL, '2023-12-07 18:12:44', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
