-- Inserting report ID 11361
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Install G-8310 at the position and test run ', 'Mechanic', 'CM', 'In Progress', '2023-12-07', '<p>Isolate power&nbsp;</p><p>Isolate 2" BA of diesel inlet line&nbsp;</p><p>Lose the bolt and nut (27 mm)&nbsp;</p><p>drain the diesel into containment ( black cup)&nbsp;</p><p>remove gasket ( 2". 150 class, spiral wound)&nbsp;</p><p>Remove the union 1.5" line, ( 15" Adjustable,&nbsp; 36" Pipe wrench) &gt;&gt; next time should <span style="background-color: rgb(255, 255, 0);">use 24" Adjustable&nbsp;</span></p><p><br></p><p>Remove the flexible line&nbsp;</p><p>lose the pipe clip of solenoid line (8"mm socket, plus small side screw driver)&nbsp;</p><p>remove the plastic flexible line&nbsp;</p><p>remove the power line of solenoid&nbsp;</p><p>remove solenoid ( Jaw plier, adjustable)&nbsp;</p><p><br></p><p>Remove the vent line ( 16mm wrench)&nbsp;</p><p>Remove the diesel inlet pipe ( 36 inch pipe wrench)&nbsp;</p><p><br></p><p>Remove concrete floor bolt ( 21mm) (WD 40)</p><p><br></p><p>Install spare generator at the place and assembly back the removal methods&nbsp;</p><p><br></p><p>Test run and found all generator parameter are normal&nbsp;</p><p>But control RTU are not available , alarm system not available&nbsp;</p><p><br></p><p><br></p>', '<p>Tools&nbsp;</p><p>Spanner&nbsp; - 8, 14, 16, 19, 21, 27, 27,&nbsp;</p><p>Adjustable - 24, 15"</p><p>Pipe wrench - 12, 36</p><p>Screw driver - + small&nbsp;</p><p>WD 40, Rags,&nbsp;</p><p>Antiseize,&nbsp;</p><p>Teflon seal tape&nbsp;</p><p>Spiral wound 2" , 150 class,&nbsp;</p>', '2023-12-07 18:24:41', '2023-12-08 06:51:08', 'PTTEP\ZOC.Se-Mech', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

