-- Inserting report ID 11366
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replaced defective pressure/temp gauge at G-9115', 'Electrical & Instrument', 'CM ', 'Completed', '2023-12-08', '<p><b><u>Replaced Defective lube oil pressure and temperature gauges at G-9115 as per the notification "100543492"</u></b></p><p><b><u><br></u></b></p><p><b>Activity</b></p><p>- Replaced defective lube oil pressure and temperature gauges at G-9115 with the new model.</p><p><br></p><p><u>New model installation guide</u></p><p>- Procedure to apply the adapter cable:</p><p>»» Connect the brown wire of the adapter cable to the cable shoe of the plus pin wire.</p><p>»» Connect the black wire of the adapter cable to the cable shoe of the minus pin wire.</p><p>»» Connect the green wire of the adapter cable to the cable shoe of the pin S.</p><p>»» Connect the red-blue cable of the adapter cable to the cable shoe of the illumination’s power line.</p><p>»» Connect the red wire of the adapter cable to the brown wire’s cable shoe.</p><p>»» Connect the blue wire of the adapter cable to the black wire’s cable shoe.</p><p><br></p><p>For more details check the user manual.</p>', '<p>For mor easy guide, </p><p>1st model</p><p>- Red cable + Brown cable connect to = Positive (+)</p><p>- Blue cable + Black cable connect to = Negative (-)</p><p>- Green cable connect to&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; = Sensor (S)</p><p><br></p><p>2nd model,</p><p>-- Red cable + Brown cable connect to = Positive (+)</p><p>- (Blue-Black) cable + Black cable connect to = Negative (-)</p><p>- Green cable connect to&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; = Sensor (S)</p><p><br></p><p><br></p>', '2023-12-08 10:11:16', '2023-12-10 16:24:43', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
