-- Inserting report ID 11383
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'YPM on G-8010 ZBV1 Day 1', 'Mechanic', 'PM', 'In Progress', '2023-12-11', '<p>Job Description; YPM on G-8010 ZBV1 Day 1</p><p><br></p><p>Job Steps;</p><p><br></p><p>-Removed the batteries and base plate.</p><p><br></p><p>-Drained the coolant from the radiator&nbsp;</p><p>&nbsp; &nbsp; Opening the drain valve and drained into the empty 20L bottle.</p><p><br></p><p>-Removed the fan guard. 10mm spanners and ratchet.</p><p><br></p><p>-Removed the radiator and fan. 8mm and 10mm spanners.&nbsp;</p><p>&nbsp; &nbsp; Cleaned the radiator with water jet. and air blower.</p><p>&nbsp; &nbsp; Cleaned the fan with brush and oiler 1.<br></p><p><br></p><p>-Loosen the alternator and removed the fan belt.</p><p>&nbsp; &nbsp; Replaced the fan belt with new one.</p><p><br></p><p>-Checked the alternator condition and cleaned with rags.</p><p><br></p><p>-Removed the cylinder head. 12mm and 10mm spanners and ratchet.</p><p>&nbsp; &nbsp; Removed and cleaned the cylinder head and head cover with WD 40.</p><p>&nbsp; &nbsp; Installed the new gasket.</p><p><br></p><p>-Readjust the valve clearance by rotating the crankshaft with 36mm socket and ratchet.</p><p>&nbsp; &nbsp; Rotated the pulley to RDC point. 1 mark at 0 degree and 3 marks 180 degree of TDC</p><p>&nbsp; &nbsp; Fire order with 1-3-4-2 with 2 turns.</p><p>&nbsp; &nbsp; Check the gap with 0.2 mm. and record as found also.</p><p>&nbsp; &nbsp; Tightened the lock nuts with 14Nm.</p><p><br></p><p>-Checked the leakages and engine condition.</p><p><br></p><p>-Replaced the fuel filter.</p><p>&nbsp; &nbsp; Check the pump</p><p>&nbsp; &nbsp; Check the injectors and leakage.</p><p><br></p><p>-Housekeeping and End of Day 1</p><p><br></p><p>-Removed the air intake filter.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">(Generator is out of service, </span>because radiator are removed outside)</p>', '<p>Required Tools</p><p><br></p><p>-8mm,10mm, 12mm, 17mm spanners. (one set of spanners)</p><p>-One socket box with ratchet</p><p>-36mm socket with extension.</p><p>-New spare lube filter, fuel filter, air filter, fan belt (Follow up Job Card)</p><p>-WD-40</p><p>-Oiler 1</p><p>-Water jet</p><p>-Blower</p><p>-Extension cable.</p><p>-Big Umbrella&nbsp;</p><p>-Plastic hammer</p><p>-Screwdriver</p><p>-etc</p>', '2023-12-11 16:41:49', '2023-12-11 17:46:51', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010', 'ATL-BV1-G-8010', 'Gen, Diesel Engine generator No1', NULL, NULL, 'Gen, Diesel Engine generator No1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

