  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verified G-8010 radiator foot mounting defective.', 'Mechanic', 'CM', 'In Progress', '2023-12-11', '<p><b><i>Description: </i></b>: found ZBV#1 Diesel Engine Generator G-8010 radiator foot mounting defective while performing YPM.<b></b></p><p><br></p><p><b><u>Working order:</u></b></p><p>-Drained the coolant from both engine side and radiator.</p><p>-Removed the fan guard, alternator belt.</p><p>-Removed the radiator and its connection hose.</p><p><b>-Found the radiator foot mounting is deformed and defective.<i></i></b></p><p><span style="background-color: rgb(255, 255, 0);">-Put the unit out of service.</span></p>', '-Plan to replace the radiator foot mounting with the new one set of support bracket (P/N: T420596) in the next day.', '2023-12-11 17:53:54', '2023-12-11 17:55:18', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
