DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TS G-8310 Trip ZBV 2 after replacement', 'Electrical & Instrument', 'CM', 'Completed', '2023-12-11', '<p><b><u>Today Activity</u></b></p><p>TS G-8310 Tripped ZBV2 after replacement</p><p><b><u>Found</u></b>&nbsp;</p><p>The LFR relay and FUER relay were activating.<br>Fuel gauge show Empty.</p><p><b><u>Action</u></b></p><p>Check the solenoid valve stem and diaphragm.</p><p>Found the solenoid diaphragm was stuck with O-ring.&nbsp;</p><p>Realignment the diaphragm, function test the solenoid.</p><p><span style="background-color: rgb(255, 255, 0);">Test run the Generator&nbsp; with full load and it is working properly.</span></p><p><br></p><p><br></p>', NULL, '2023-12-11 18:02:18', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Elec-Tec', NULL, false) RETURNING id INTO new_report_id;
