  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'G-8010 YPM day 2', 'Mechanic', 'PM', 'Completed', '2023-12-12', '<p>Perform YPM on G-8010 ZBV1 Day 2</p><p><br></p><p>-Installed the radiator after fixing the radiator damper&nbsp;</p><p>&nbsp; &nbsp; Top up coolant premixed 8L</p><p><br></p><p>-Installed fan brackets.</p><p><br></p><p>-Removed lube oil filter and top up lube oil</p><p>&nbsp; &nbsp; Topped up lube oil 8L</p><p><br></p><p>-Removed fuel water separator and strainer.</p><p>&nbsp; &nbsp; Replaced with new strainer.</p><p><br></p><p>-Cleaned with water jet and air blower.</p><p><br></p><p>-Installed the batteries and housekeeping.</p><p><br></p><p>-Test ran and found that comm link was working properly.&nbsp;&nbsp;&nbsp;&nbsp;</p><p>&nbsp; &nbsp; T/S by adjusting the comm setting. Link with proper comm line number.&nbsp;</p><p><br></p><p>-Test ran again and data can be seen by local and CCR.</p><p><br></p><p>-Online and under monitoring</p><p><br></p>', '<p>Required tools</p><p><br></p><p>-One set of spanners.</p><p>-One socket box.</p><p>-New fuel strainer</p><p>-new lube oil filter</p><p>-Water jet and air blower.</p><p>-WD-40</p>', '2023-12-12 16:37:04', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010', 'ATL-BV1-G-8010', 'Gen, Diesel Engine generator No1', NULL, NULL, 'Gen, Diesel Engine generator No1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
