  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Trial start & testing gas generator G-8930', 'Electrical & Instrument', 'CM', 'Completed', '2023-12-15', '<p><u><b>Today Activity</b></u></p><p>Test run the G-8930<br><b><u>Action</u></b></p><p>Test run G-8930 (2 Times) cannot start.<br><u>First time&nbsp;<br></u>Voltage at GVP - 16.19V<br>Gas valve open - 9Kpa<br><u>Second time<br></u>Voltage at GVP - 16.1V<br>Gas valve open - 12Kpa<br><br></p><p><u><b style="background-color: rgb(0, 255, 255);">History(12-12-2023)</b></u><br></p><p><span style="background-color: rgb(0, 255, 255);">Trial start &amp; testing gas generator G-8930 prior on vendor supporting for readiness.&nbsp;<u><b><br></b></u></span></p><ul class="BulletListStyle1 SCXW40179356 BCX0" role="list"><li data-leveltext="-" data-font="Arial" data-listid="2" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559684&quot;:-2,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Arial&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="59" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW40179356 BCX0"><p class="Paragraph SCXW40179356 BCX0" xml:lang="EN-US" lang="EN-US" paraid="218539998" paraeid="{654ac57a-4d6e-4413-8087-028b609510c3}{168}"><b><u style="background-color: rgb(0, 255, 255);">Action</u></b></p></li><li data-leveltext="-" data-font="Arial" data-listid="2" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559684&quot;:-2,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Arial&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="60" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW40179356 BCX0"><p class="Paragraph SCXW40179356 BCX0" xml:lang="EN-US" lang="EN-US" paraid="1723906738" paraeid="{95e16e49-f833-4726-a01f-287e948e0419}{172}"><span style="background-color: rgb(0, 255, 255);">Check and tighten all cable terminations at generator control panel (GCP) and local control panel (LCP).Verified voltage drop at fuel gas shut off valve.&nbsp;<br>Generator test run cannot start.<br>GVP did not open.</span></p></li></ul><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);"><br>History (10-12-2023)</u></p><p><span style="background-color: rgb(255, 255, 0);">Swap AFR unit from G-8930 to G-8925 &amp; test run.</span></p><p><span style="background-color: rgb(255, 255, 0);"><u>Action</u><br>Removed AFR from G-8930 and G-8925.<br>Swap both AFR.<br>G-8925 AFR is at G-8925.<br>The New AFR is at G-8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">G-8930 test run.<br>Gas valve fail to open.<br>Exercise the Gas valve with power supply.(24 V)</span></p><p><span style="background-color: rgb(255, 255, 0);">Test run. Generator fail to start.</span></p>', NULL, '2023-12-15 18:03:56', '2024-01-23 09:55:30', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
