  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform yearly performance test on firewater pump ', 'Mechanic', 'PM', 'Completed', '2023-12-28', '<p>-&nbsp;&nbsp;Check engine lube oil.</p><p>-&nbsp;&nbsp;Check and clean engine air filter.</p><p>-&nbsp;Check control panel, push lamp to check indicator light bulb function.</p><p>- Check diesel day tank level.</p><p>-&nbsp;Line up process and valve as per PID mark up for before testing.</p><p>-&nbsp;Start the fire water pump and operate as per weekly running for 10 min (During this stage, the water shall be returned to the tank by PCV, min flow, of each line)</p><p>-&nbsp;Adjust flow rate as per required start from 250 GPM and record the operating data &amp; vibration data as per required in performance test record sheet.</p><p>-&nbsp;After finished testing, line up the piping system back to normal operation.</p><p>-&nbsp;Send the record data to in charge engineer for further analysis.</p>', NULL, '2023-12-28 13:29:48', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
