  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Function Test on New Ventilation Fan for G-8930', 'Electrical & Instrument', 'OTH', 'Completed', '2024-01-14', '<p>Perform insulation and resstance on new ventilation fan motor.</p><ul class="BulletListStyle1 SCXW28913022 BCX0" role="list"><li data-leveltext="?" data-font="Wingdings" data-listid="18" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559683&quot;:0,&quot;335559684&quot;:-2,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Wingdings&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;?&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="40" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW28913022 BCX0"><p class="Paragraph SCXW28913022 BCX0" xml:lang="EN-US" lang="EN-US" paraid="101138911" paraeid="{8c8356f7-14f2-4953-9fe5-c55347781b64}{205}">Install pully at DE site for fan installation. Clean fan.&nbsp;</p></li><li data-leveltext="?" data-font="Wingdings" data-listid="18" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559683&quot;:0,&quot;335559684&quot;:-2,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Wingdings&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;?&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="41" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW28913022 BCX0"><p class="Paragraph SCXW28913022 BCX0" xml:lang="EN-US" lang="EN-US" paraid="1218433502" paraeid="{5ac205a2-78bb-4f35-83b7-80f7e580b539}{24}">Check IR test (M Ohm) and winding resistance on each winding. Record the results.&nbsp;</p></li></ul><p>-L1-L2, L1-L3, L2-L3 :<span style="background-color: rgb(255, 255, 0);"> 5.43 G-ohm</span></p><p>-Internal resistance:<span style="background-color: rgb(255, 255, 0);"> 3.6 Ohm</span></p><ul class="BulletListStyle1 SCXW28913022 BCX0" role="list"><li data-leveltext="?" data-font="Wingdings" data-listid="18" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559683&quot;:0,&quot;335559684&quot;:-2,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Wingdings&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;?&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="42" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW28913022 BCX0"><p class="Paragraph SCXW28913022 BCX0" xml:lang="EN-US" lang="EN-US" paraid="1111005963" paraeid="{25149d59-c8d9-4cf9-8b0b-7dfe3d8db6b2}{66}">Perform test run.&nbsp;</p></li></ul><p><br></p>', NULL, '2024-01-14 16:37:14', '2024-01-17 19:00:25', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
