-- Inserting report ID 11520
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Weekly Test Run G-9115', 'Mechanic', 'OTH ', 'Pending', '2024-01-14', '<p><b><u>Working Steps</u></b></p><p><br></p><p>- Checked the lube oil level. (Found that lube oil level is high.)<br>- Checked the coolant level. (Found that coolant level of the jacket water is low, and the raw water is normal.)</p><p>- Drained lube oil for certain amount. <span style="background-color: rgb(255, 255, 0);">(Found that coolant was mixing in the lube oil sump.)</span><br>- Checked the inspection ports of the both jacket water pumps. <span style="background-color: rgb(255, 255, 0);">(Found that coolant and lube oil seeping from the inspection ports.)</span></p><p>- Drained coolant form the both oil cooler. (No oil was mixing.)</p><p>- Drained lube oil from one lube oil filter for each side of generator. (No coolant was mixing.)<br>- Opened the crankshaft window to check coolant seeping. (Unable to verify the seeping.)<br>- Installed the parts back to normal.</p><p><br></p>', 'POSTPONED WEEKLY TEST RUN DUE TO COOLANT MIXINIG IN THE LUBE OIL SUMP TO THE DAY AFTER&nbsp; CORRECTIVE MAINTENANCE.', '2024-01-14 18:02:02', '2024-01-14 18:10:48', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

