  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace Helium Cylinder No.1 AIT-81906 ', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2024-01-18', '<p><b><u>Today Activity</u></b><br></p><p>Replace Helium Cylinder No.1, AIT-81906 at GC Shelter</p><p><u><b>Action</b></u></p><p>Changed AIT-81906 auto to AIT-81907 at ITR. (6 Modules)</p><p>Replaced Helium Cylinder No.1.<br>Set the pressure at 110 Cylinder No.1.<br>Set the pressure at 120 Cylinder No.2.</p><p>Performed the leak test.<br>No leak.<br><br><span style="background-color: rgb(255, 255, 0);">Note: Before performed replacing, sent email as an information.</span></p><p><br></p>', NULL, '2024-01-18 15:43:47', '2024-01-18 15:49:17', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
