  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify the G-8920 cannot start', 'Electrical & Instrument', 'CM', 'Completed', '2024-01-20', '<p><b><u>Today activity</u></b></p><p>Verify the G-8920 cannot start after normal stopping. (Stopped for test run the rental generator with full load)</p><p><b style="text-decoration-line: underline;">Action</b><br>Reinstall the batteries at the G-8920 bank 2 and started the generator 3 times.</p><p>Fail to start.</p><p>Use battery charger and starter at the G-8920 battery panel and started again.</p><p>G-8930 can start and running normal.</p><p><u><b>History(19-20-2023)</b></u><br></p><p><span style="background-color: rgb(255, 255, 0);">Verify the G-8920 cannot start after normal stopping. (Stopped for test run the rental generator with full load)</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Start 3 times, the voltage drop and the AMP of the batteries cannot start the starter motor.</span></p><p><span style="background-color: rgb(255, 255, 0);">Removed the batteries from G-8930 and charging at the battery room.<br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to install the battery bank 2 of G-8920 and start again tomorrow.</span></p><p><br></p>', NULL, '2024-01-20 14:31:21', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Elec-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8920-PACK', 'ATL-OC-G-8920-PACK', 'Gen, ZOC Gas Generator package1', NULL, NULL, 'Gen, ZOC Gas Generator package1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

