-- Inserting report ID 11562
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Test run FSISA Generator 220 KVA', 'Mechanic', 'OTH', 'Completed', '2024-01-22', '<p>Test run FSISA Generator&nbsp;</p><p><br></p><p><b><u>Precheck condition -&nbsp;</u></b></p><p>Fuel - 40 % (about 150 liters) - (Full tank 350 Liters)&nbsp;</p><p>Lube oil - 100%</p><p>Coolant - Normal&nbsp;</p><p>Belt - normal (visual check)&nbsp;</p><p>Battery volt - 24.8 V&nbsp; (2 Batteries)&nbsp;</p><p><br></p><p>Test run with idle (no load)&nbsp; about 1 hour&nbsp;</p><p>All engine sound is normal., Vibration - Normal&nbsp;</p><p>All parameters are normal in during test run.&nbsp;</p><p><br></p><p>Check Emergency Stop - OK&nbsp;</p><p>Check Air Shutoff valve - OK&nbsp;</p><p><br></p><p>oil pressure- 51 psi&nbsp;</p><p>Coolant Temp- 84 C</p><p>Charger Volt- 28V</p><p>RPM- 1499</p><p>Load- 0&nbsp;</p><p>AVG- 401&nbsp;</p><p>Frequency- 50.0Hz</p><p>Exhaust- 190</p><p><br></p><p><br></p>', NULL, '2024-01-22 11:52:49', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTH', 'OTH', 'Other', NULL, NULL, 'Other', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11563
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2KPM of G-8920 Day-3', 'Mechanic', 'PM', 'In Progress', '2024-01-22', '<p>90% in progress&nbsp;</p><p><br></p><p><b><u>Working Steps (Day 3) 22-Jan-2024</u></b></p><p>.&nbsp; &nbsp; &nbsp; Top up new lube oil (260 L) Methana</p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replace new gas inlet filter.</p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Top up coolant about 10 liters </p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Check the coolant pH level with pH tester (pH – 9.2).</p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Greasing to fan motor 4 stoke </p><p>              </p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Tighten the radiator fan blade and radiator fan motor base (torque – 98 N-m).</p><p>.&nbsp; &nbsp; &nbsp; Replace new charger alternator belt</p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Test run with full load and checking parameter&nbsp;</p><p><br></p><p><br></p><p><u>Perform 2K PM of Gas generator, Day-2:</u></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Perform valve lash adjustment,<br></p><p>·&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;clean combustion chamber,</p><p>·&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;install new spark plug with torque 50 Nm.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; install rocker box cover with gasket.</p><p></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Recondition oil level sight glass.</p><p>.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Replace new breather filters 2EA.</p><p><br></p><p><u>Perform 2K PM of Gas generator, Day-1:</u><br></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Equipment isolation,<br></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; drain engine lube oil,</p><p>·&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;remove spark plug,</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; remove rocker cover</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; clean rocker cover gasket</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; and inspection combustion chamber,</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;found two spark plug tip was ashy (1B) and one spark plug is too hardy to remove on (5B)</p>', NULL, '2024-01-22 14:42:44', '2024-01-22 17:46:39', 'PTTEP\ZOC.Se-Mech', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8920-PACK', 'ATL-OC-G-8920-PACK', 'Gen, ZOC Gas Generator package1', NULL, NULL, 'Gen, ZOC Gas Generator package1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

