  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify the battery bank 1 of the G-8920', 'Electrical & Instrument', 'OTH', 'Completed', '2024-01-22', '<p><b><u>Today Activity</u></b></p><p>Verify the battery bank 1 of the G-8920<br></p><p><b><u>Action</u></b></p><p>Refill the battery water to the 4 batteries.<br>Check the battery with HIOKI battery tester.</p><p>Charge 2 batteries of the G-8920 bank-1. (Charge 8 Hr).</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>History(22-01-2024)</u></b><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Verify the battery bank 1 of the G-8920</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Check the battery with HIOKI battery tester.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found the batteries need to refill the battery water.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan: To fill battery water and charge the battery tomorrow.</span></p>', NULL, '2024-01-23 07:20:44', '2024-01-24 15:02:38', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8920-PACK', 'ATL-OC-G-8920-PACK', 'Gen, ZOC Gas Generator package1', NULL, NULL, 'Gen, ZOC Gas Generator package1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
