  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2KPM of G-8920 Day-4 and Test run ', 'Mechanic', 'PM', 'Under Monitoring', '2024-01-23', '<p><u>Working Steps (Day 4) 23-Jan-2024&nbsp;</u></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Torque tightens engine basement mounting bolt,H</p><p>.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Housekeeping area and test run generator with full load (Completed) </p><p>&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;</p><p>    </p><p>Found lube oil seeping from Raw Water Shaft Oil seal, and inform to PMO/I engineer to order spare part&nbsp;</p><p><br></p><p><br></p><p><u>Working Steps (Day 3) 22-Jan-2024</u></p><p>.&nbsp; &nbsp; &nbsp; Top up new lube oil (260 L) Methana</p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replace new gas inlet filter.</p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Top up coolant about 10 liters</p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Check the coolant pH level with pH tester (pH – 9.2).</p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Greasing to fan motor 4 stoke</p><p></p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Tighten the radiator fan blade and radiator fan motor base (torque – 98 N-m).</p><p>.&nbsp; &nbsp; &nbsp; Replace new charger alternator belt</p><p>.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Test run with full load and checking parameter&nbsp;</p><p><br></p><p><br></p><p><u>Perform 2K PM of Gas generator, Day-2:</u></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Perform valve lash adjustment,<br></p><p>·&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;clean combustion chamber,</p><p>·&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;install new spark plug with torque 50 Nm.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; install rocker box cover with gasket.</p><p></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Recondition oil level sight glass.</p><p>.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Replace new breather filters 2EA.</p><p><br></p><p><u>Perform 2K PM of Gas generator, Day-1:</u><br></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Equipment isolation,<br></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; drain engine lube oil,</p><p>·&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;remove spark plug,</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; remove rocker cover</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; clean rocker cover gasket</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; and inspection combustion chamber,</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;found two spark plug tip was ashy (1B) and one spark plug is too hardy to remove on (5B)</p>', '<p>Found lube oil seeping from Raw Water Shaft Oil seal, and inform to PMO/I engineer to order spare part&nbsp;</p><p><br></p>', '2024-01-23 17:48:06', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Se-Mech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8920-PACK', 'ATL-OC-G-8920-PACK', 'Gen, ZOC Gas Generator package1', NULL, NULL, 'Gen, ZOC Gas Generator package1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

