-- Inserting report ID 11594
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S SD-81153 fault alarm at Jr.accommodation', 'Electrical & Instrument', 'CM', 'Completed', '2024-01-29', '<p><b><u>Today activity</u></b></p><p>TS smoke detector SD-81153 device fault at Jr accommodation.</p><p><u><b>Action&nbsp;</b></u><br></p><p><u><b>SD-81153(Jr.16)</b></u></p><p>Replaced with new Smoke detector. Alarm clear.<br></p><p>Function test with smoke detector tester. Well functionable.</p><p>SD-81153 is back to normal and working properly.</p><p><u><b><br></b></u></p><p><u><b style="background-color: rgb(255, 255, 0);">History(25-01-24)</b></u></p><p><span style="background-color: rgb(255, 255, 0);">T/S SD-81153 fault alarm at Jr.accommodation.<br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Found</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Insert and dust was observed at the SD-81153.<br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action&nbsp;</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Cleaned carefully the internal components of the smoke detector.</span></p><p><span style="background-color: rgb(255, 255, 0);">After cleaning, the smoke detector was reinstalled in its designated location.</span></p><p><span style="background-color: rgb(255, 255, 0);">The alarm status was clear.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Function test with smoke detector tester. Well functionable.</span></p><p><span style="background-color: rgb(255, 255, 0);">SD-81153 has been restored to normal working condition and is now operational.</span></p><p><br></p>', NULL, '2024-01-29 15:13:15', '2024-01-29 15:17:57', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-SD-81153', 'ATL-OC-SD-81153', 'Smoke detector in staff dormitory R06', NULL, NULL, 'Smoke detector in staff dormitory R06', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

