-- Inserting report ID 11601
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Continue G8010 TS tripped by oil pressure low', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2024-01-31', '<p><b><u>Today Activity</u></b></p><p>G8010 TS tripped by oil pressure low.<br><b><u>Action</u></b></p><p>Found that the power supply voltage drop.<br>Reroute one new wire line from Battery to Comapps panel.<br></p><p>Test run.<br>G8010 is on duty and under monitoring.</p><p><br></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>History</u></b><u><b>&nbsp;(24-Jan-24)</b></u></span></p><p><span style="background-color: rgb(255, 255, 0);">Verify G-8010 trip ZBV1.</span></p><p><u><b style="background-color: rgb(255, 255, 0);">Found&nbsp;</b></u></p><p><span style="background-color: rgb(255, 255, 0);">SD oil pressure low alarm.<br>Breaker trip position.</span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action&nbsp;</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Check the voltage of the battery.</span></p><p><span style="background-color: rgb(255, 255, 0);">Check the voltage of the lube oil pressure sensor (10.8V).</span></p><p><span style="background-color: rgb(255, 255, 0);">The voltage is not working properly.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to jump dc wire to the com app board next visit.</span></p>', NULL, '2024-01-31 15:44:58', '2024-02-05 06:49:43', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010-PACKAGE', 'ATL-BV1-G-8010-PACKAGE', 'Gen, ZBV1 Diesel Generator package1', NULL, NULL, 'Gen, ZBV1 Diesel Generator package1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11602
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Coolant and lube oil mixing G-9115 Day 1', 'Mechanic', 'CM ', 'In Progress', '2024-02-01', '<p align="center">Job Steps for removal</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Perform process and electrical isolation.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Prepare blue drums and empty drums.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Drain lube oil with lube oil drain pump. (Pipe clips, seal tape and pipe gauge)</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Drain coolant with Wildam pump. (Mobile air compressor, pneumatic pipe, wire extension)</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove the whole batteries bank and unit.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Drain coolant from heat exchanger via drain valve.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove the coolant inlet line to the heat exchanger.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Removed the lube oil inlet line to the heat exchanger.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove the lube oil outlet li</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Disconnect the coolant out line.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove the heat exchanger bolts (6 Bolts)</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Use some blocks under the heat exchanger for the easy removal. Leave 2 bolts for hanging. </p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The exchanger is heavy and lift with enough manpower.</p>', NULL, '2024-02-01 17:46:14', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

