-- Inserting report ID 11607
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Coolant and lube oil mixing G-9115 Day 2', 'Mechanic', 'CM ', 'Completed', '2024-02-02', '<p align="center">Job Steps</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove the filter base plate and connected lines.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Clean the oil sump with lots of rags.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove the remaining gasket pieces at the face of plates and bodies.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Overhaul the heat exchanger by removing the both side-covers. Found that oil cooler cover oil seal was deformed and flattened.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; And rearrange the new oil cooler unit to match with bank B side attachment. (Because only Bank A oil cooler, 582/137 is available and interchange with bank B old oil cooler)</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Bank B is 582/139.</p>  Housekeeping and end of day 2.', NULL, '2024-02-02 17:16:16', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11608
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'G-9115 coolant and lube oil mixing Day 3', 'Mechanic', 'CM ', 'In Progress', '2024-02-03', '<p align="center">Job Steps for removal</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Installed back the lube oil filter base plate. (Prepare the gaskets)</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Installed back the connected lines with proper gaskets.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Installed back the oil cooler.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Cleaned the oil sump again to make sure there was no residues.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Topped up coolant 160L and drained from oil cooler to make sure there was no trapped air.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Monitored about one hour and there was no leak inside the oil cooler and found no traces inside the oil sump.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Topped up coolant up to full level.</p>  <p></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Monitored for one day and will continue tomorrow.</p>', NULL, '2024-02-03 17:07:09', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

