  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'G-9115 T/S coolant and lube oil mixing Day 4', 'Mechanic', 'CM ', 'In Progress', '2024-02-04', '<p><p></p><p align="center"><span style="background-color: rgb(255, 255, 0);">Note:&nbsp; Found unplan defective item</span>&nbsp;</p><p align="center"><span style="background-color: rgb(255, 255, 0);">item -1</span> - coolant heat 3/4" isolation valve seeping from packing&nbsp; (Completed Fix)</p><p align="center"><span style="background-color: rgb(255, 255, 0);">Item-2</span> - Oil seeping from defective hose of lube oil overpressure return line (In progress)&nbsp;</p><p align="center"><br></p><p align="center"><br></p><p align="center">Day 4 Job Steps</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Found no leak of coolant in the system. </p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b>Turn the manual crankshaft rotating and manual hand pump at the same time to make sure there is no air trapped inside.</b></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; No coolant in the oil cooler.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Topped up lube oil up to 50% of strainer inside the oil sump.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Repeat the <b>step 2. </b>Until there is lube oil filled up in the oil cooler.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Drain some oil to check the coolant is still mixed.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Installed back the oil sump covers. Make sure to clean all the remaining of gaskets.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Test run the engine for 5 mins.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Check the system for any leakages. Drained some oils to check the lube oil and coolant mixing.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Stop the engine and check for the leakages.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Top up the lube oil up to 80% of dipstick.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Test run with share load and take a log.</p>  Monitoring and will run with full load.&nbsp;&nbsp;</p><p><p><br></p><p>.&nbsp;&nbsp; &nbsp; &nbsp;Found oil cooler bank B is working well, inlet temp 70.8 and outlet temp 58.5 .</p><p><br></p><p>&nbsp; &nbsp; .&nbsp;Oil seeping from defective hose of lube oil overpressure return line</p><p>&nbsp; &nbsp; . Switching back the generator to G-9120&nbsp;</p><p>&nbsp; &nbsp; . plan to troubleshoot again on the unplan items&nbsp;</p><p>&nbsp; &nbsp; .&nbsp;<br></p></p>', '<p align="center"><span style="background-color: rgb(255, 255, 0);">Note:&nbsp; Found unplan defective item</span>&nbsp;</p><p align="center"><span style="background-color: rgb(255, 255, 0);">item -1</span>&nbsp;- coolant heat 3/4" isolation valve seeping from packing&nbsp; (Completed Fix)</p><p align="center"><span style="background-color: rgb(255, 255, 0);">Item-2</span>&nbsp;- Oil seeping from defective hose of lube oil overpressure return line (In progress)&nbsp;</p><p align="center"><br></p>', '2024-02-04 18:10:40', '2024-02-04 20:41:27', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

