BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Continue G8320 verify the generator tripped ZBV2', 'Electrical & Instrument', 'CM', 'Completed', '2024-02-05', '<p><b><u>Today Activity</u></b></p><p>Verify the G8320 ZBV2 tripped.</p><p><b><u>Action</u></b></p><p>Check the winding resistance of the generator alternator.(Normal)</p><p>Found that the AVR was damaged.</p><p><br></p><p>Plan to replace with new AVR.</p><p><br></p><p>P1-E_ 4.6M Ohm</p><p>P2-E_ &gt;550M Ohm</p><p>P3-E_ &gt;550M Ohm</p><p>N-E _ &gt; 550M Ohm</p><p>T1,T2,T3,___T12 _ &gt;550M Ohm</p><p><br></p><p>T1-T4 _ 0.064 mOhm</p><p>T2-T5 _ 0.067 mOhm</p><p>T3-T6 _ 0.066 mOhm</p><p>T7-T10 _ 0.065 mOhm</p><p>T8-T11 _ 0.066 mOhm</p><p>T9-T12 _ 0.065 mOhm</p><p><br></p><p><b style=""><u style="background-color: rgb(255, 255, 0);">History(02-Feb-2024)</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Verify the G8320 ZBV2 tripped.</span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Check the winding resistance of the generator alternator.</span></p><p><span style="background-color: rgb(255, 255, 0);">T4-E _ 2.7 M Ohm (Damaged)<br></span></p><p><span style="background-color: rgb(255, 255, 0);">T5-E_OL</span></p><p><span style="background-color: rgb(255, 255, 0);">T6-E_OL</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Test run the generator by manual mode.</span></p><p><span style="background-color: rgb(255, 255, 0);">Measure the AC Voltage</span></p><p><span style="background-color: rgb(255, 255, 0);">T4-E_ 104 V AC(Damaged)</span></p><p><span style="background-color: rgb(255, 255, 0);">T5-E_ OL</span></p><p><span style="background-color: rgb(255, 255, 0);">T6-E_ OL<br><br>Test run by remote and load share, the generator tripped again.<br>G8320 is unavailable.<br>G8310 is on duty.</span></p><p><br></p>', NULL, '2024-02-05 16:59:48', '2024-02-12 18:32:03', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
