-- Inserting report ID 11628
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'G8320 D350 new design AVR replacement ZBV2', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2024-02-11', '<p><b><u>Today Activity</u></b></p><p>G8320 New design AVR replacement.</p><p><b><u>Action</u></b></p><p>1. Removed AVR RM480 from damaged generator (previously removed from ZBV2 G8320 due to alternator coil damage).</p><p>2. Installed the previously removed AVR RM480 at generator G8320 and initiated start-up. Generator started but tripped due to high voltage alarm (450V). Adjusted voltage to 400V, restarted, and tripped again.</p><p>3. Installed new design AVR D350 and conducted a test run with full load for 3 hours.</p><p>&nbsp; &nbsp;- G8320 is currently operational and running normally under monitoring.<br><br><span style="background-color: rgb(255, 0, 0);">Note: voltage sensing line of AVR no need to install.</span></p><p><br></p><p><b style="background-color: rgb(255, 255, 0);"><u>History(11-Feb-2024)</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Verify the G8320 ZBV2 tripped.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Check the winding resistance of the generator alternator.(Normal)</span></p><p><span style="background-color: rgb(255, 255, 0);">Found that the AVR was damaged.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to replace with new AVR.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">P1-E_ 4.6M Ohm</span></p><p><span style="background-color: rgb(255, 255, 0);">P2-E_ &gt;550M Ohm</span></p><p><span style="background-color: rgb(255, 255, 0);">P3-E_ &gt;550M Ohm</span></p><p><span style="background-color: rgb(255, 255, 0);">N-E _ &gt; 550M Ohm</span></p><p><span style="background-color: rgb(255, 255, 0);">T1,T2,T3,___T12 _ &gt;550M Ohm</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">T1-T4 _ 0.064 mOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">T2-T5 _ 0.067 mOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">T3-T6 _ 0.066 mOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">T7-T10 _ 0.065 mOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">T8-T11 _ 0.066 mOhm</span></p><p><span style="background-color: rgb(255, 255, 0);">T9-T12 _ 0.065 mOhm</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">History(02-Feb-2024)</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Verify the G8320 ZBV2 tripped.</span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Check the winding resistance of the generator alternator.</span></p><p><span style="background-color: rgb(255, 255, 0);">T4-E _ 2.7 M Ohm (Damaged)<br></span></p><p><span style="background-color: rgb(255, 255, 0);">T5-E_OL</span></p><p><span style="background-color: rgb(255, 255, 0);">T6-E_OL</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Test run the generator by manual mode.</span></p><p><span style="background-color: rgb(255, 255, 0);">Measure the AC Voltage</span></p><p><span style="background-color: rgb(255, 255, 0);">T4-E_ 104 V AC(Damaged)</span></p><p><span style="background-color: rgb(255, 255, 0);">T5-E_ OL</span></p><p><span style="background-color: rgb(255, 255, 0);">T6-E_ OL<br><br>Test run by remote and load share, the generator tripped again.<br>G8320 is unavailable.<br>G8310 is on duty.</span></p><p><br></p>', NULL, '2024-02-11 19:49:43', '2024-02-13 11:39:50', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8320-PACKAGE', 'ATL-BV2-G-8320-PACKAGE', 'Gen, ZBV2 Diesel Generator package2', NULL, NULL, 'Gen, ZBV2 Diesel Generator package2', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

