  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TS the open/close status GCB error at CCR of G8310', 'Electrical & Instrument', 'CM', 'In Progress', '2024-02-11', '<p><b><u>Today Activity</u></b><br>TS the open and close status GCB error at CCR of G8310</p><p><b><u>Action</u></b></p><p>Checked relay contactors 95, 96, and 98. Found all relay contactors to be functioning properly.</p><p>Inspected the internal parts of the breaker.</p><p>Discovered that the mechanical part of the relay on/off switch (on the GCB side) was damaged.</p><p>Planned to repair or replace the damaged relay on/off mechanical part.</p><p><br></p><p></p>', NULL, '2024-02-11 19:56:12', '2024-02-11 20:07:46', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
