-- Inserting report ID 11632
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Performed 6MPM of G-8020.', 'Mechanic', 'PM', 'Completed', '2024-02-12', '<p><b>Description: Performed 6MPM of Diesel engine generator G-8020 at ZBV#1.</b></p><p><br></p><p><b><i>Working steps:</i></b></p><p>-Performed electrical isolation.</p><p>-Drained Lube Oil (Dynamic Plus) and <b>topped up 8 Liters</b>.</p><p><b>-Replaced the lube oil filter, fuel filter, Air filter, and fan belt.</b></p><p>-Drained coolant and f<b>illed up 4 Liters. (SuperCoolant)</b></p><p>-Removed Fan guard cover, fan and radiator.</p><p>-Cleaned radiator by pressurized water jet.</p><p>-Installed back radiator and adjusted fan belt tension.</p><p>-Installed back fan guard cover.</p><p>-Housekeeping around the working area.</p><p>-Performed electrical de-isolation and test run.</p><p>-Record the engine parameter and put the unit online.</p><p><br></p><p><i><b>Required spare parts:</b></i></p><p>1. Dynamic Plus (engine oil) = 8 Liters.</p><p>2. Coolant (Ptt supercoolant) = 4 Liters.</p><p>3. Fan belt = 1 EA.</p><p>4. Engine oil filter = 1EA.</p><p>5. Diesel Filter = 1EA.</p><p>6. Air Filter = 1 EA.</p>', '<p>-found the radiator (LH side) mounting base damaged. (need to replace).</p><p>-found the radiator (RH side bottom) screw went through into the radiator and make the leaking when unscrewed.&nbsp;</p><p>-found fan guard (top shock absorber) screw worn out.&nbsp;</p>', '2024-02-12 16:26:12', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8020-PACKAGE', 'ATL-BV1-G-8020-PACKAGE', 'Gen, ZBV1 Diesel Generator package2', NULL, NULL, 'Gen, ZBV1 Diesel Generator package2', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11634
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Continue G8010 TS tripped by oil pressure low', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2024-02-04', '<p><b><u>Today Activity</u></b></p><ul class="BulletListStyle1 SCXW184507945 BCX0" role="list"><li data-leveltext="-" data-font="Arial" data-listid="2" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559684&quot;:-2,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Arial&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="55" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW184507945 BCX0"><p class="Paragraph SCXW184507945 BCX0" paraid="1525300853" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{44}">Verify ZBV diesel generator G-8010 trip. (Monitoring)&nbsp;<br>Action</p><p class="Paragraph SCXW184507945 BCX0" paraid="1525300853" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{44}">SD low oil pressure alarm.</p><p class="Paragraph SCXW184507945 BCX0" paraid="1525300853" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{44}">Remove the oil pressure sensor.</p><p class="Paragraph SCXW184507945 BCX0" paraid="1525300853" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{44}">Clean the sensor adaptor port (Found Teflon tape inside the port).</p></li><li data-leveltext="-" data-font="Arial" data-listid="2" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559684&quot;:-2,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Arial&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="56" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW184507945 BCX0"><p class="Paragraph SCXW184507945 BCX0" paraid="1572943710" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{53}">Replace lube oil pressure sensor and test run with full load.&nbsp;</p><p class="Paragraph SCXW184507945 BCX0" paraid="1572943710" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{53}">Under Monitoring.</p></li></ul><p><b><u><br></u></b></p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History(31-Jan-24)</u></b></p><p><span style="background-color: rgb(255, 255, 0);">G8010 TS tripped by oil pressure low.<br><b><u>Action</u></b></span></p><p><span style="background-color: rgb(255, 255, 0);">Found that the power supply voltage drop.<br>Reroute one new wire line from Battery to Comapps panel.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Test run.<br>G8010 is on duty and under monitoring.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>History</u></b><u><b>&nbsp;(24-Jan-24)</b></u></span></p><p><span style="background-color: rgb(255, 255, 0);">Verify G-8010 trip ZBV1.</span></p><p><u><b style="background-color: rgb(255, 255, 0);">Found&nbsp;</b></u></p><p><span style="background-color: rgb(255, 255, 0);">SD oil pressure low alarm.<br>Breaker trip position.</span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action&nbsp;</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Check the voltage of the battery.</span></p><p><span style="background-color: rgb(255, 255, 0);">Check the voltage of the lube oil pressure sensor (10.8V).</span></p><p><span style="background-color: rgb(255, 255, 0);">The voltage is not working properly.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to jump dc wire to the com app board next visit.</span></p>', NULL, '2024-02-12 18:45:13', '2024-02-12 18:46:12', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
