  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'G-8010 Monthly PM Diesel Generator at ZBV#1', 'Mechanic', 'PM', 'Completed', '2024-02-16', '<p><u>Working Steps</u></p><p><br></p><p>- Checked and cleaned the air filter.</p><p>- Checked the air service indicator.</p><p>- Checked the radiator cap condition.</p><p>- Checked the coolant level and its condition.</p><p>- Checked the lube oil level and its condition.</p><p>- Checked the belt tension and its condition.</p><p>- Checked and tightened the loosening bolts and nuts.</p><p>- Housekeeping and test run.</p><p>- Recorded the parameters and checked any abnormalities.</p>', NULL, '2024-02-16 16:05:33', '2024-02-16 16:23:40', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
END $$;

-- Inserting report ID 11639
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'G-8020 CM Radiator and Exhaust Insulation', 'Mechanic', 'CM', 'Completed', '2024-02-16', '<p><b><i><u>Wokings Steps</u></i></b></p><p><br></p><p>- Stopped the generator.</p><p>- Drained the coolant and removed the radiator cap.</p><p>- Removed the radiator fan guard.</p><p>- Removed the radiator from the engine.</p><p>- Removed the radiator mounting bracket.</p><p>- Installed the new radiator mounting bracket.</p><p>- Replaced the radiator with the hot spare.</p><p>- Removed the defective exhaust insulation tape.</p><p>- Wrapped the exhaust with the new insulation tape.</p><p>- Installed the radiator fan guard.</p><p>- Topped up coolant (PTT Premixed Coolant -4L).</p><p>- Checked and Tightened loosening bolts and nuts.</p><p>- Test run and checked any abnormalities.</p><p>- Stopped&nbsp; the generator.</p><p>- Checked the coolant level and the coolant leakage.</p><p>- Tightened the radiator cap.</p><p>- Started the generator and recorded the parameters.</p><p>- Housekeeping and kept the generator online.</p><p><br></p><p><br></p><p><br></p>', NULL, '2024-02-16 16:21:22', '2024-02-16 16:25:26', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8020-PACKAGE', 'ATL-BV1-G-8020-PACKAGE', 'Gen, ZBV1 Diesel Generator package2', NULL, NULL, 'Gen, ZBV1 Diesel Generator package2', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

