  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replaced new MCCB at G-8010', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2024-02-17', '<p><u style="">Today Activity&nbsp;</u></p><p>Replaced the shut trip relay from hot spare.</p><p><u>Action</u></p><p>- Replaced the shut trip relay form hot spare and test run the MCCB, but the unit was still tripped.</p><p>- Replaced with the new MCCB.</p><p>- Installed the cable lug of the power cable.</p><p>- Test run Generator from local control and ON the MCCB. (2 Hr)</p><p>- Run the generator form CCR and monitoring the MCCB status.</p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);">History (12-Feb-2024)</u></p><p><span style="background-color: rgb(255, 255, 0);">Verify the GCB of the generator.</span></p><p><u style="background-color: rgb(255, 255, 0);">Action</u></p><p><span style="background-color: rgb(255, 255, 0);">Found at the local MCCB main panel breaker was tripped.</span></p><p><span style="background-color: rgb(255, 255, 0);">Check the internal part of the GCB of G8010.<br>The shunt trip relay was damaged.<br>Plan to replace or repair.<br><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Waiting Spare.<br></span></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><br></p><p><u style="background-color: rgb(255, 255, 0);">History(04-02-2024)</u></p><ul class="BulletListStyle1 SCXW184507945 BCX0" role="list"><li data-leveltext="-" data-font="Arial" data-listid="2" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559684&quot;:-2,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Arial&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="55" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW184507945 BCX0"><p class="Paragraph SCXW184507945 BCX0" paraid="1525300853" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{44}"><span style="background-color: rgb(255, 255, 0);">Verify ZBV diesel generator G-8010 trip.<br><u>Action</u></span></p><p class="Paragraph SCXW184507945 BCX0" paraid="1525300853" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{44}"><span style="background-color: rgb(255, 255, 0);">SD low oil pressure alarm.</span></p><p class="Paragraph SCXW184507945 BCX0" paraid="1525300853" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{44}"><span style="background-color: rgb(255, 255, 0);">Remove the oil pressure sensor.</span></p><p class="Paragraph SCXW184507945 BCX0" paraid="1525300853" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{44}"><span style="background-color: rgb(255, 255, 0);">Clean the sensor adaptor port (Found Teflon tape inside the port).</span></p></li><li data-leveltext="-" data-font="Arial" data-listid="2" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559684&quot;:-2,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Arial&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="56" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW184507945 BCX0"><p class="Paragraph SCXW184507945 BCX0" paraid="1572943710" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{53}"><span style="background-color: rgb(255, 255, 0);">Replace lube oil pressure sensor and test run with full load.&nbsp;</span></p><p class="Paragraph SCXW184507945 BCX0" paraid="1572943710" paraeid="{e9424fdc-0e5e-4d2e-ba67-9406ad6fe0b6}{53}"><span style="background-color: rgb(255, 255, 0);">Under Monitoring.</span></p></li></ul><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);">History(31-Jan-24)</u></p><p><span style="background-color: rgb(255, 255, 0);">G8010 TS tripped by oil pressure low.<br><u>Action</u></span></p><p><span style="background-color: rgb(255, 255, 0);">Found that the power supply voltage drop.<br>Reroute one new wire line from Battery to Comapps panel.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Test run.<br>G8010 is on duty and under monitoring.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><u>History</u><u>&nbsp;(24-Jan-24)</u></span></p><p><span style="background-color: rgb(255, 255, 0);">Verify G-8010 trip ZBV1.</span></p><p><u style="background-color: rgb(255, 255, 0);">Found&nbsp;</u></p><p><span style="background-color: rgb(255, 255, 0);">SD oil pressure low alarm.<br>Breaker trip position.</span></p><p><u style="background-color: rgb(255, 255, 0);">Action&nbsp;</u></p><p><span style="background-color: rgb(255, 255, 0);">Check the voltage of the battery.</span></p><p><span style="background-color: rgb(255, 255, 0);">Check the voltage of the lube oil pressure sensor (10.8V).</span></p><p><span style="background-color: rgb(255, 255, 0);">The voltage is not working properly.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Plan to jump dc wire to the com app board next visit.</span></p>', '- The existing MCCB was the old model and there was no shut relay spare parts at the warehouse for the MCCB model.', '2024-02-17 15:06:23', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Inst-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010', 'ATL-BV1-G-8010', 'Gen, Diesel Engine generator No1', NULL, NULL, 'Gen, Diesel Engine generator No1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

