  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot Valve Stack (BA-0257)', 'Mechanic', 'CM', 'Completed', '2024-02-26', '<p><i><u>Working Steps</u></i></p><p><br></p><p>Valve Stem Gearbox</p><p><br></p><p>Removed the valve status indicator.</p><p>Removed the valve stem gearbox cover.</p><p>Found water and the degraded grease.</p><p>Removed the grease and cleaned the gearbox.</p><p>Checked and cleaned the gear teeth.</p><p>Injected grease into the gearbox and exercise the valve.</p><p>Checked and cleaned the cover and indicator.</p><p>Covered the gearbox by applying the RTV Gasket Maker.</p><p>Installed the valve status indicator.</p><p><br></p><p>Valve Handwheel Gearbox</p><p><br></p><p>Removed the valve handwheel.</p><p>Removed the cover of the valve handwheel gearbox.</p><p>Removed and cleaned the gears.</p><p>Removed and cleaned the valve handwheel gearbox.</p><p>Removed and cleaned the cylindrical worm gear.</p><p>Removed and cleaned the cylindrical worm gear back cover.</p><p>Installed the cylindrical worm gear back cover.</p><p>Installed the cylindrical worm gear.</p><p>Installed the valve handwheel gearbox.<br></p><p>Checked the bearings and the gear teeth condition.</p><p>Injected the grease into the bearings and the gearbox.</p><p>Covered the gearbox and installed the hand wheel.</p>', NULL, '2024-02-26 17:56:06', '2024-05-09 16:38:15', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
