-- Inserting report ID 11703
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TS Oil Seeping in Left Stabilizer of CAT Backhoe', 'Mechanic', 'CM', 'In Progress', '2024-03-03', '<p>Working Steps</p><p><br></p><p>1. Depressurized and drained the hydraulic oil from the cylinder.<br>2. Disconnected the hydraulic hoses.</p><p>3. Removed the snap ring from the lower pin.</p><p>4. Try to remove the lower pin by hitting with hammer on the snap ring side face. (Not moving)</p><p>5. Welded the nut on the pin and try to rotate it. (Not moving)</p><p>6. Used Enerpac hydraulic jack and ram on the snap ring side face until pressure is reached to 2000 psi. (Not moving)</p><p>7. Applied the heat with brazing torch until 400 °C&nbsp;and try to remove with hammer. (Not moving)</p><p><br></p>', NULL, '2024-03-04 18:41:18', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-CAT-01', 'ATL-OC-CAT-01', 'Backhole Loader-Caterpillar', NULL, NULL, 'Backhole Loader-Caterpillar', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

