  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Performed 2KPM G-9120', 'Mechanic', 'PM ', 'Completed', '2024-03-07', '<p>Day 1,</p><p>- Performed process and electrical isolation.</p><p>- Replaced air filters.</p><p>- Top up lube oil 50 Liters.</p><p>- Check the coolant level and radiator caps.</p><p>- Replaced the fuel filters.</p><p>- Clean the fuel filter housing.</p><p>- Performed process and electrical de-isolation.</p><p><br></p><p>Day 2,</p><p>- Performed process and electrical isolation.</p><p>- Removed the cylinder head cover.</p><p>- Removed the spark plugs.</p><p>- Check the old spark plugs.</p><p>- Check the new spark plugs with spark plugs taster.</p><p>- Install the new spark plugs. (T-50N.m)</p><p>- Check and adjust the valve clearance for each cylinder.&nbsp;</p><p></p><p>- Cleaned the cylinder head cover.</p><p>- Install new gasket.</p><p>- Install the cover of cylinder head. (T-50N.m)</p><p>- Performed process and electrical de-isolation.</p><p>- Test run and check the abnormal noise.</p><p>Day 3,</p><p>- Perform process and electrical isolation.</p><p>- Removed the enclosure motor covers.</p><p>- Check the fan blade torque. (T-7N.m)</p><p>- Clean the fan blade.</p><p>- Apply the grease to enclosure motor.</p><p>- Install the fan blade cover. (T-75N.m)</p><p>- Remove the alternator cover.</p><p>- Check the alternator belt condition.</p><p>- Clean the alternator belt cover.</p><p>-&nbsp; Install the cover of alternator.</p><p>- Check the engine mounting bolts.</p><p>- Housekeeping inside the generator.</p><p>- Perform electrical and process de-isolation.</p><p>- Test run and check the abnormal noise and vibration.</p>', NULL, '2024-03-07 20:47:18', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9120-PACKAGE', 'ATL-MS-G-9120-PACKAGE', 'Gen, ZMS Gas Generator package3', NULL, NULL, 'Gen, ZMS Gas Generator package3', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

