  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '3MPM on Kenworth Fire Truck T370', 'Mechanic', 'PM', 'In Progress', '2024-03-12', '<p><u>Description</u>: Performed 3MPM of Fire Truck Kenworth I-03.</p><p><br></p><p><u>Working Orders:</u></p><p>- Check lube oil level and lube oil condition.</p><p>- Visually checked the lube oil filter and lube oil leakage along with the connection and turbocharger.</p><p>- Visually checked the fuel pump, fuel water separator, and fuel line leakage.</p><p>- Checked the radiator fan belt, cooling water hose &amp; system, heat exchanger.</p><p>- Checked air filter condition and air restriction indicator.</p><p>- Checked the air compressor system and air tank.</p><p>- Checked transmission fluid level.</p><p>- Checked the batteries condition and CCA.</p><p>- Topped up batteries water 6 L.</p><p>- Visually check the tire condition and tire pressure&nbsp;found 90psi front tires and 90 psi rear outbound tires.</p><p>- Tested the rain sweeper system and fluid level.</p><p>- Tested Air-Con system, panel lights, seat belts, gauges, and parking gear.</p><p>- Recorded the mileage meter.</p>', NULL, '2024-03-12 17:06:29', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-FIRE TRUCK KENWORTH', 'ATL-OC-FIRE TRUCK KENWORTH', 'OC Fire truck Kenworth', NULL, NULL, 'OC Fire truck Kenworth', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

