-- Inserting report ID 11757
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Monitoring lube oil seeping after hose replacement', 'Mechanic', 'CM', 'Completed', '2024-03-17', '<p><b>Description: Verified and monitored lube oil seeping while test running after the damaged hose replacement</b></p><p><br></p><p><b><u>Working steps:</u></b></p><p>-Performed electrical and process de-isolation.</p><p>-Performed test run and checked if any leakage.</p><p>-found oil leak from the joint of turbocharger oil feed line.</p><p>-Stop the engine.</p><p>-Removed the flange joint of oil feed line and<b> found the deformed gasket.</b></p><p>-Replaced the gasket and installed the line.</p><p>-Test run with shared load for one hour and<b> found no leakage.</b></p><p><br></p>', NULL, '2024-03-17 17:22:42', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8920-PACK', 'ATL-OC-G-8920-PACK', 'Gen, ZOC Gas Generator package1', NULL, NULL, 'Gen, ZOC Gas Generator package1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11758
DO $$
