  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verified lube oil seeping of G-8920', 'Mechanic', 'OTH', 'Under Monitoring', '2024-03-17', '<p><b>Description: Verified lube oil seeping of Gas engine generator G-8920 at suspected area.</b></p><p><br></p><p><b><u>Working steps</u></b><br>-Performed electrical isolation.</p><p>-Removed front flywheel guard cover.</p><p>-Cleaned the suspected area. (jacket water pump, crankshaft seal, alternator shaft seal).</p><p>-Removed the alternator belt guard cover.</p><p>-Test run and monitored lube oil seeping from those areas.</p>', '<p>Recommended by MATC&nbsp;</p><p>- thrust shaft oil seal need to replace earlier before lift span&nbsp;</p><p>- Top up lube oil to the gas generator until 95% of dipstick only because to prevent blower by pressure of high amount oil.&nbsp;</p><p>-Monitoring and cleaning each month&nbsp;</p>', '2024-03-17 17:26:34', '2024-03-17 18:18:19', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
