  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2MPM of instrument air compressor A unit.', 'Mechanic', 'PM ', 'Completed', '2024-03-19', '<p>Working steps:</p><p><br></p><p>- Checked and cleaned the air filter.</p><p>- Drained and topped up lube oil (Total Azolla ZS-46) 4 Liters.</p><p>- Checked the belt tension and pulley alignment.</p><p>- Checked the belt condition.</p><p>- Checked and tightened the motor mounting bolts.</p><p>- Checked fan guard bolts/nuts tension.</p><p>- Visually checked the dryer.</p><p>- Housekeeping the compressor assembly.</p><p>- Performed electrical and process de-isolation.</p><p>- Test run, leak checks and checked any abnormality.</p>', '<p>Found that the thread between intercooler air connection and hose is leaking.</p><p>Will Perform CM</p>', '2024-03-19 15:47:11', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
