-- Inserting report ID 11780
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '3MPM of Truck Crane TC-1', 'Mechanic', 'PM', 'Completed', '2024-03-21', '<p><b>Description: performed 3MPM of truck crane TC-1.</b></p><p><br></p><p><b>Working steps:</b></p><p>-Greasing the propeller driving shafts, shock bar joints, steering joints, PTO joints.</p><p>-Greasing the boom joints, hydraulic cylinder joints, swivel joint, telescoping joints.</p><p>-Drained out the lube oil and <i><b>replaced the drain plug O-ring.</b></i></p><p><b><i>-Replaced the lube oil filter. </i></b>(MESC: 36.81.14.001.3)</p><p><b><i>-Filled up lube oil (Dynamic Plus 18 L).</i></b></p><p><br></p><p>-Checked radiator coolant level and condition.</p><p>-Checked the tension and condition of the fan belt and air compressor belt.</p><p>-Cleaned the radiator by pressurized air.</p><p>-Drained out the water from fuel-water separator.</p><p><br></p><p>-Checked hydraulic pump,Hoses, filter and control valve for any leak and abnormal condition.</p><p>-Checked hydraulic oil level.</p><p>-Checked wire rope condition for any damage and kink.&nbsp;</p><p>-Checked and inspected the Hook condition.</p><p><br></p><p><b><i>-Checked Front wheel nuts tension by torque 200 N-m.</i></b></p><p>-Performed Functional test of boom cylinder, telescoping cylinder and slew cylinder.</p><p><b><i>-Checked all lightings. (left side signal light is not illuminating.)</i></b></p>', NULL, '2024-03-21 14:46:09', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-TRUCK-01', 'ATL-OC-TRUCK-01', 'Operation HINO Truck 500 FC9J', NULL, NULL, 'Operation HINO Truck 500 FC9J', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

