-- Inserting report ID 11795
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Blind flange gasket replacement.', 'Mechanic', 'CM', 'Completed', '2024-03-27', '<p>Description: Replaced the deformed spiral wound gasket of the flange at the diesel storage tank B overflow line as found diesel seeping and rusty bolts.</p><p><br></p><p>working steps:</p><p>-Removed the bolts,&nbsp;</p><p>-Cleaned the flanged area, gasket mating surfaces, stud bolts and nuts.</p><p>-Changed the spiral wound gasket. (2" 150#).</p><p>-Installed the blind flange and checked alignment.</p><p><br></p><p>Tools&nbsp;</p><p>- 27mm spanner and socket&nbsp;</p><p>-Mallet&nbsp;</p><p>-Wire brash, scrapper, WD40, Oiler, Rags&nbsp;</p><p>-</p>', 'Replace Spiral Wound, 2", 150 class&nbsp;', '2024-03-27 16:10:24', '2024-03-28 06:09:14', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-T-8880', 'ATL-OC-T-8880', 'ZOC Diesel Storage Tank 2', NULL, NULL, 'ZOC Diesel Storage Tank 2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 11796
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Repair defective gearbox DBA0208 in Diesel storage', 'Mechanic', 'CM', 'In Progress', '2024-03-27', '<p>Remove indicator cover&nbsp;</p><p>Remove gear box cover&nbsp;</p><p>found grease with water (too much water amount)&nbsp;</p><p>found rusty cover lip seal&nbsp;</p><p>Found no gasket in cover plate</p><p>Found worm defective in end of helix&nbsp;</p><p>Found lost in neddle bearing and cut pieces of spacer washer&nbsp;</p><p>Found shaft seal damage of handle wheel&nbsp;</p><p>Remove worm and handle&nbsp;</p><p>Clean in side par and each part&nbsp;</p><p>Clean worm and handle shaft&nbsp;</p><p>Applied EP2 grease to each part&nbsp;</p><p>Install back the unit&nbsp;</p><p>Rotate the valve to open position&nbsp;</p><p>Inform operator&nbsp;</p><p><br></p><p>Defective part</p><p><span style="font-size: 15px;">1.</span><span style="font-size: 15px;">Trust bearing and      spacer.</span></p><p><span style="font-size: 15px;">2. Handle shaft seal</span></p><p><span style="font-size: 15px;">3. Open/close indicator      hole cover lip seal</span></p><ol type="1">  <li>4.Worm Gear&nbsp;</li></ol><p><br></p><p>Tools&nbsp;</p><p>-8mm, 13mm combination spanner&nbsp;</p><p>-Mallet</p><p>-Scraper, wire brush, flat screw driver, spike,&nbsp;</p><p>-Rags, WD40, Oiler,&nbsp;</p><p>-</p><ol type="1"> </ol>', 'Temporary fix and order spare part, not available valve gear box drawing&nbsp;', '2024-03-27 16:17:14', '2024-03-27 16:30:18', 'PTTEP\ZOC.Se-Mech', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-T-8880', 'ATL-OC-T-8880', 'ZOC Diesel Storage Tank 2', NULL, NULL, 'ZOC Diesel Storage Tank 2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;



