-- Inserting report ID 11799
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Defective GVPS assembly replacement.', 'Mechanic', 'CM', 'In Progress', '2024-03-28', '<p><b>Description: Performed replacement of the defective GVPS gas valve assembly of gas engine generator G-8925.</b></p><p><br></p><p><b><i><u>Working steps</u></i></b></p><p>-Performed process isolation.</p><p>-Vent out the line pressure.</p><p>-Removed the wiring connection.</p><p>-Removed the defective gas valve assembly.</p><p>-Cleaned the gasket mating surfaces.</p><p>-<b>Replaced the gaskets. (2EA).</b></p><p>-Installed the new gas valve assembly.</p><p>-Checked the valve assembly and flange alignment.</p><p>-tightened the flange bolts/nuts with <b>torque (90 N-m).</b></p><p>-Test run and leak check is still in progress.</p><p><br></p><p><b><i><u>Required tools,</u></i></b></p><p>-24 mm or 15/16 inches</p><p>-Torque wrench</p><p>-screw diver, crawl bar,&nbsp;</p><p>-contact cleaner, brush, scotch brush, fine sand paper.</p><p>-cotton rags,&nbsp;</p>', NULL, '2024-03-28 16:26:50', '2024-03-29 06:20:45', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8925-PACK', 'ATL-OC-G-8925-PACK', 'Gen, ZOC Gas Generator Package2', NULL, NULL, 'Gen, ZOC Gas Generator Package2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

