-- Inserting report ID 11813
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'BA-0433 Valve stem playing at Tube 5.', 'Mechanic', 'CM ', 'Completed', '2024-03-29', '<p>During Metering, found that BA-0433 valve stem is loosening and playing.</p><p>Cannot turn properly and firmly.</p><p>So, issued the CM work order and perform the CM activity.</p><p><br></p><p>Steps</p><p>- Isolate the Tube line, Close position.</p><p>- Removed the Valve handle by removing the nuts. (14mm spanner)</p><p>- Removed the key from key way at valve handle stem. (Hit softly with plastic hammer)</p><p>- Removed the gear covers. (5/16 and 3/8 allen keys)</p><p>- Removed the second gear cover which is located at another side. ( 13mm spanner)</p><p>&nbsp;- Removed the driver gear and removed the bearing at driver gear.</p><p>- Removed the Driven Gear with proper Puller tools. (borrow from ZOC)</p><p>- Removed the other bearing.&nbsp;</p><p>- Cleaned the housing and apply new EP-2 grease.</p><p>- Replaced the worn out bearings with new ones. (6205)</p><p>- Reassembled the parts and test.</p>', 'Required tools - spanners set, puller from ZOC, plastic hammer, allen keys set, WD-40, screw driver, scrapers, brushes, rags, and surgical gloves.', '2024-03-29 17:29:20', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-BA0433', 'ATL-MS-BA0433', 'Valve, 12"-PG-84067-FS1N of FST-84351', NULL, NULL, 'Valve, 12"-PG-84067-FS1N of FST-84351', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

