  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '30Ton Crane wire rope sling reconditioning.', 'Mechanic', 'CM', 'Completed', '2024-04-04', '<p><b>Description: </b></p>  <p>TADANO 30 Ton Crane''s Auxiliary wire rope sling broken by incident during lifting operation. Found wire rope sling damage and cut off from the hoist assembly.</p>  <p><span style="background-color: rgb(255, 255, 0);">Failure&nbsp;</span></p><p>- Wire Rope cut, material brakeage&nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">Cause</span></p><p>-Operator didn''t familiar with this crane, Human Error&nbsp;</p><p><span style="background-color: rgb(255, 255, 0);">Tools&nbsp;</span><br></p><p>- 17mm Spanner, Hammer, Wire cable, Hydraulic Cutter, Plier, Tape&nbsp;&nbsp;</p><p><b><u>Working steps:</u></b><br></p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Parked the TADANO crane at the besides of warehouse building.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Released the auxiliary drum as to pull out the wire rope sling.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Cut off the damaged part of the wire rope sling (approximately 40 feet).</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Lined up the auxiliary wire rope sling from the winch drum to hoist.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Removed the damaged part sling from the hoist.</p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Installed and connected the sling to the hoist. </p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Load test with 1.1 Ton for 30 minutes. </p>  <p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Checked wire rope sling condition on the drum properly seated and minimum 5 wraps on.</p><p><br></p><p><br></p>', '-Auxiliary wire rope sling need to be performed lifting inspection by authorized certified inspector.', '2024-04-04 17:18:25', '2024-04-10 09:22:12', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-CRANE-01', 'ATL-OC-CRANE-01', 'Operation Crane-01 TADANO-30T-GR3000EX', NULL, NULL, 'Operation Crane-01 TADANO-30T-GR3000EX', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

