  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform MPM G-8010 at ZBV-1', 'Electrical & Instrument', 'PM', 'Completed', '2024-04-06', '<p><u>Today Activity</u></p><p>Performed monthly PM diesel generator G-8010 at ZBV-1</p><p><br></p><p><u>Action</u></p><p>- Performed electrical isolation G-8010.</p><p>- Checked battery voltage, battery terminal connection and battery water level (Top up - 0 L)</p><p>- Cleaned the battery bank surface.</p><p>- Checked and tightened wiring terminal connection inside generator control panel.</p><p>- Removed control relay and cleaning with contact cleaner.</p><p>- Performed cleaning inside generator control panel with air blower.</p><p>- Checked, cleaned and tightened sensor termination and sensor cable lug.</p><p>-<span style="background-color: rgb(255, 255, 0);"> Found Lube Oil temperature sensor cable lug was loosen ( Replaced with the new cable lug )</span></p><p>- Performed electrical de-isolation G-8010.</p><p>- Performed manual fuel top up function test. (Normal)</p><p>- Performed test run G-8010 and Recorded parameter as per PM job card.</p>', '<p># Recommended to check sensor terminal and cable lug every PM.</p><p><span style="background-color: rgb(255, 255, 0);">#Found Lube Oil temperature sensor cable lug was loosen ( Replaced with the new cable lug )</span><br></p>', '2024-04-06 16:19:10', '2024-04-11 18:23:32', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Inst-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010-PACKAGE', 'ATL-BV1-G-8010-PACKAGE', 'Gen, ZBV1 Diesel Generator package1', NULL, NULL, 'Gen, ZBV1 Diesel Generator package1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
