  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S valves hard to operate at utility water system', 'Mechanic', 'CM ', 'In Progress', '2024-04-08', '<p>Job Title :&nbsp;T/S hard to operate valves at fire water system.</p><p><br></p><ul class="BulletListStyle1 SCXW69137797 BCX0" role="list"><li data-leveltext="?" data-font="Symbol" data-listid="2" data-list-defn-props="{&quot;335551671&quot;:0,&quot;335552541&quot;:1,&quot;335559685&quot;:1440,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Symbol&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;?&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="0" data-aria-level="2" role="listitem" class="OutlineElement Ltr SCXW69137797 BCX0"><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">During performance test of fire water pumps, found that some valves are hard to operate.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}"><br></p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">Root cause : Due to long time no greasing and no covers at Valve Stems.&nbsp;</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}"><br></p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">Valve Tags numbers : ??????</p><ul class="BulletListStyle1 SCXW69137797 BCX0" role="list"><li data-leveltext="?" data-font="Symbol" data-listid="2" data-list-defn-props="{&quot;335551671&quot;:0,&quot;335552541&quot;:1,&quot;335559685&quot;:1440,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Symbol&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;?&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="0" data-aria-level="2" role="listitem" class="OutlineElement Ltr SCXW69137797 BCX0"><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="1239525853" paraeid="{fa648c54-a9fd-4ab5-9531-7cd6ffda5408}{174}"><br></p></li></ul><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}"><br></p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">Job Steps:&nbsp;</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">- Inspect the valve conditions visually.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">- Cleaned out old grease mixing with dusts and other stuffs.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">- Played the valve handles to fully close and fully open.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">- Removed the valve handle lock and inspected.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">- Checked the valve packing gland and cover. Found no over tighten or any leakages.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">- Applied New EP-2 Grease and played the valves.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">- Found that the grease nipples are worn out due to rust and no greasing for long time.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">- Need to replace the grease nipples with new ones and need PVC pipes to cover the valve stems.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}"><br></p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">Require Tools:&nbsp;</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">Big adjustable spanner.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">Plastic hammer.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">One set of spanner.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">A Scrubber and a paint brush.</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">EP-2&nbsp;</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">Rags</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">Rubber gloves</p><p class="Paragraph SCXW69137797 BCX0" xml:lang="EN-US" lang="EN-US" paraid="727450857" paraeid="{5f97df44-bd6b-4f1d-a649-1b0f4ad4d0a3}{94}">Grease gun and spare grease nipples.</p></li></ul>', NULL, '2024-04-08 15:13:45', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTH', 'OTH', 'Other', NULL, NULL, 'Other', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

