  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 2MPM on IA-8980 B', 'Mechanic', 'PM', 'Completed', '2024-04-08', '<p>Performed 2 Monthly PM for Instrument Air Compressor-B</p><p><br></p><p>Working Steps:</p><p><br></p><p>1) Changed air compressor oil: AZOLLA ZS 46 about 4 Liter.</p><p>2) Checked and adjusted pulley alignment.</p><p>3) Checked and adjusted the belts'' tension.</p><p>4) Cleaned air filter.</p><p>5) Checked air horses, fittings, and tubings.</p><p>6) Housekeeping and tested run.</p>', NULL, '2024-04-08 16:20:44', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-A-8980B', 'ATL-OC-A-8980B', 'ZOC IA Compressor B', NULL, NULL, 'ZOC IA Compressor B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
