  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TS emergency lighting at ZOC day 6', 'Electrical & Instrument', 'CM', 'In Progress', '2024-04-09', '<p><u>Today Activity</u></p><p>Troubleshooted emergency lighting at ZOC Emergency Diesel Generator G-8935 Day-6.</p><p><u><br></u></p><p><u>Action</u></p><p>- Troubleshooted (1) Emergency lightings Emergency Diesel Generator.</p><p>- Replaced new switches, ballast, battery and light bulbs.<br>- Cleaned the lighting area.<br>- Performed function test at emergency situation and normal operation.<br>- Emergency lightings were working properly at normal operation and emergency situation.</p><p><u><br></u></p><p><u><br></u></p><p><u>History(07-04-24)</u></p><p>Troubleshooted emergency lighting at ZOC fire water pump shelter Day-5.</p><p><u><br></u></p><p><u>Action</u></p><p>- Troubleshooted (1) Emergency lightings Fire water pump shelter.</p><p>- Replaced new switches, ballast, battery and light bulbs.<br>- Cleaned the lighting area.<br>- Performed function test at emergency situation and normal operation.<br>- Emergency lightings were working properly at normal operation and emergency situation.</p><p><br></p><p><u><br></u></p><p><u>History (06-04-2024)</u></p><p>Troubleshooted emergency lighting at ZOC fire water pump shelter Day-4.</p><p><u><br></u></p><p><u>Action</u></p><p>- Troubleshooted (1) Emergency lightings Fire water pump shelter.</p><p>- Replaced new switches, ballast, battery and light bulbs.<br>- Cleaned the lighting area.<br>- Performed function test at emergency situation and normal operation.<br>- Emergency lightings were working properly at normal operation and emergency situation.</p><div><br></div><p><u><br></u></p><p><u><br></u></p><p><u>History(05-04-2024)</u><br></p><p>Troubleshooted emergency lighting at ZOC fire water pump shelter Day-3.</p><p><u><br></u></p><p><u>Action</u></p><p>- Troubleshooted (2) Emergency lightings Fire water pump shelter.</p><p>- Replaced new switches, ballast, battery and light bulbs.<br>- Cleaned the lighting area.<br>- Performed function test at emergency situation and normal operation.<br>- Emergency lightings were working properly at normal operation and emergency situation.</p><p><u><br></u></p><p><u>History(04-04-2024)</u></p><p>Troubleshoot emergency lighting at ZOC water treatment package Day 2.</p><p><u>Action<br></u></p><p>TS (2) Emergency lighting at water treatment area.</p><p>Replaced new switches, ballast, battery and lightings.<br>Cleaned the lighting area.<br>Function test at emergency status and normal status.<br>These lightings are working properly at every status.</p><p><u><br></u></p><p><u>History(03-Apr-24)</u><br></p><p>Troubleshoot emergency lighting at ZOC water treatment package.<br><u>Action</u><br>TS (2) Emergency lighting at water treatment area.</p><p>Replaced new switches, ballast, battery and lightings.<br>Function test at emergency status and normal status.<br>These lightings are working properly at every status.</p>', NULL, '2024-04-09 17:21:48', '2024-04-19 17:36:00', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Inst-Tec', false) RETURNING id INTO new_report_id;
