  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform monthly inspection for AHU-01', 'Mechanic', 'PM', 'Completed', '2024-04-11', '<p><b><u>Monthly inspection for AHU-01</u></b></p><p><br></p><p><b>Required Handtools and equipment:</b><br></p><p>1) Laser Alignment</p><p>2) Portable lamp</p><p>3) Spanner 16mm, 17mm, 26mm, 27mm<br></p><p>4) Pry Bar</p><p>5) Steel Ruler (1 meter)</p><p>6) Grease Gun C/W EP-2 grease</p><p>7) WD-14</p><p>8) Cotton Rag</p><p><br></p><p><b>Work Step:</b></p><p>1) Checked pulley alignment</p><p>2) Checked the pulley''s belt condition and readjusted tension.</p><p>3) Greased drive shaft bearing on both driven and non-driven sides.</p><p>4) Performed housekeeping around the area.</p><p>5) Performed test run after deisolation.</p>', NULL, '2024-04-11 17:18:37', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
