  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S OGC AIT-81906 failure', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2024-04-14', '<p><u>Today Activity</u></p><p>Troubleshooted online gas chromatograph OGC AIT-81906 failure.</p><p><br></p><p><u>Action</u></p><p>- Checked online gas chromatograph OGC AIT-81906 active alarm. (power failure alarm)</p><p>- Replaced hot spare power supply unit sent from ZMS.</p><p>- Connected the OGC AIT-81906 with MOON 2000 software and cleared the active alarm. (no alarm)</p><p>- Monitored OGC AIT-81906 after replaced power supply.</p>', NULL, '2024-04-14 16:41:14', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Inst-Tec', NULL, false) RETURNING id INTO new_report_id;
