  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot EDG G-8935 Lockout Relay Alarm Active', 'Electrical & Instrument', 'CM', 'Completed', '2024-04-28', '<p><u>Activity</u></p><p>Troubleshoot EDG G-8935 Lockout Relay Alarm Active.</p><p><u>Action</u></p><p>Check the internal wiring of Protection Relay(REM543) for EDG G-8935 has loose connection or not.</p><p>Perform Visual inspection of all control wiring connection physical condition is good or not.</p><p>No abnormity found at the Protection Relay Control Circuit.</p><p>Finally reset the Generator Protection Relay(REM543) incoming control power about 5 sec and turn on power. And then push reset button for&nbsp; the Lock Out Relay Alarm at the LVSWG-8100 Switchgear.&nbsp;</p><p>Now, alarm clear at the EDG Generator ACB04(2000AF/2000AT) and unit back in service.</p><p>Under Monitoring for the EDG G-8935 rare alarm.</p>', NULL, '2024-04-28 12:42:59', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Inst-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8935-PACK', 'ATL-OC-G-8935-PACK', 'Gen, ZOC Diesel Generator Package', NULL, NULL, 'Gen, ZOC Diesel Generator Package', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

