  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify the OGC-81906', 'Electrical & Instrument', 'CM', 'In Progress', '2024-05-01', '<p><u><b>Today Activity</b></u><br>Verify&nbsp; the OGC AIT-81906<br><u><b>Action</b><br></u>Perform as per maintenance check list.<br>Perform the leak test at the tubing of the OGC-81906.<br></p><p>Perform calibration the AIT-81906.<br><br>In progress and plan to continue tomorrow.</p><p><br><u style="background-color: rgb(255, 255, 0);">History(14-04-2024)</u></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshooted online gas chromatograph OGC AIT-81906 failure.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">Action</u></p><p><span style="background-color: rgb(255, 255, 0);">- Checked online gas chromatograph OGC AIT-81906 active alarm. (power failure alarm)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Replaced hot spare power supply unit sent from ZMS.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Connected the OGC AIT-81906 with MOON 2000 software and cleared the active alarm. (no alarm)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Monitored OGC AIT-81906 after replaced power supply.</span></p>', NULL, '2024-05-01 18:00:48', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Elec-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-AIT-81906', 'ATL-OC-AIT-81906', 'Gas chromatograph metering N2 and CO2 1', NULL, NULL, 'Gas chromatograph metering N2 and CO2 1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
