veltext="-" data-font="Arial" data-listid="8" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559683&quot;:0,&quot;335559684&quot;:-2,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Arial&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="57" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW91811463 BCX0"><p class="Paragraph SCXW91811463 BCX0" xml:lang="EN-US" lang="EN-US" paraid="1216342704" paraeid="{cda498c5-e26f-4b8c-a630-ea152c81604b}{37}"><br></p></li></ul>', NULL, '2024-05-12 19:47:52', '2024-05-15 11:13:53', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
