-- Inserting report ID 12865
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 6MPM on G-9125 Day 1', 'Mechanic', 'PM ', 'In Progress', '2024-05-14', '<p>Job description: <b>6MPM on G-9125</b></p><p><br></p><p>Job Steps:</p><p><b>Performed electrical and process isolation.</b></p><p><b>Checked and cleaned the air filters condition.</b></p><p><b>Checked the air service indicator condition.<br>Checked the exhaust condition.<br>Checked the turbo charger and its blades condition.</b></p><p><b>Checked and cleaned the breather filter.</b></p><p><b>Checked the coolant level and the leakage.</b></p><p><b>Checked the radiator cap condition.</b></p><p><b>Checked and cleaned the radiator fins.</b></p><p><b>Checked the radiator fan blades condition.</b></p><p><b>Checked the radiator fan bolts. (75 Nm)</b></p><p><b>Checked the radiator fan belt tension.</b></p><p><b>Checked and tightened the radiator fan cover bolts. (25 Nm)</b></p><p><b>Checked and tightened the radiator mounting bolts. (300 Nm)</b></p><p><b>Checked and tightened the engine mounting bolts. (400 Nm)</b></p><p><b>Cleaned the generator package.</b></p><p><b>Checked any loosening bolts and nuts.</b></p><p><b>Checked any leakage in the engine.</b></p><p><b>Checked the flame arrester condition.</b></p><p><b>Checked the diesel day tank level.</b></p><p><b>Drained diesel from the day tank about 1 Liter.</b></p><p><b>Checked the fuel line leakage.</b></p><p><b>Drained diesel from water separator.</b></p><p><b>Checked the alternator and its belt tension.</b></p>', NULL, '2024-05-14 14:00:52', '2024-05-14 14:03:16', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9125-PACKAGE', 'ATL-MS-G-9125-PACKAGE', 'Gen, ZMS Diesel Generator Package', NULL, NULL, 'Gen, ZMS Diesel Generator Package', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

