  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Monthly Inspection PM of AHU unit 1.', 'Mechanic', 'PM', 'Completed', '2024-05-14', '<p><u>Monthly inspection for AHU-01</u></p><p><br></p><p>Required Handtools and equipment:<br></p><p>1) Laser Alignment</p><p>2) Portable lamp</p><p>3) Spanner 16mm, 17mm, 26mm, 27mm<br></p><p>4) Pry Bar</p><p>5) Steel Ruler (1 meter)</p><p>6) Grease Gun C/W EP-2 grease</p><p>7) WD-14</p><p>8) Cotton Rag</p><p><br></p><p>Work Step:</p><p>1) Checked pulley alignment</p><p>2) Checked the pulley''s belt condition and readjusted tension.</p><p><span style="background-color: rgb(255, 255, 0);">3) Replaced the belt (2EA).</span></p><p>4) Greased drive shaft bearing on both driven and non-driven sides.</p><p>5) Performed housekeeping around the area.</p><p>6) Performed test run after deisolation.</p>', NULL, '2024-05-14 16:06:34', '2024-05-14 16:47:46', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
