  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 6MPM on G-9125 Day 2', 'Mechanic', 'PM ', 'Completed', '2024-05-15', '<p>Job description:&nbsp;6MPM on G-9125 Day 2</p><p><br></p><p>Job Steps:</p><p>Performed electrical and process isolation.</p><p>Warmed up the generator for 15 mins.</p><p>Drained all lube oil.</p><p>Replaced all lube oil filters. (3 units)</p><p>Topped up with new lube oil. (140 L, 20 L flushing; Total 160L )</p><p>Performed de isolations.</p><p>Test run for 1 hour with shared load.</p><p>Found no abnormal.</p><p>Recorded the generator parameters.</p><p><br></p>', NULL, '2024-05-15 15:47:56', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9125-PACKAGE', 'ATL-MS-G-9125-PACKAGE', 'Gen, ZMS Diesel Generator Package', NULL, NULL, 'Gen, ZMS Diesel Generator Package', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
