  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '3MPM MOGE Metering calibration tube A', 'Electrical & Instrument', 'PM', 'Completed', '2024-05-17', '<p><u><b>Today Activity</b></u></p><p>3MPM MOGE metering for Tube A and four condition test.<br></p><p><b><u>Action<br></u></b></p><p>Set maintenance mode for FQIC-81902 A &amp; B.</p><p>Print constant log, current Rp 1 and 2.(After maint mode)</p><p>Performed Pressure transmitters calibration A and B.<br></p><p>Performed Temperature transmitters calibration A and B.</p><p>Performed Flow transmitters calibration A and B.<br>Removed the orifice plate and reinstalled the orifice plate after inspection by MOGE.(Good)<br><span style="background-color: rgb(255, 255, 0);">(19 bolt for Torque is 110Nm)</span><br>Tighten the cable terminal of all transmitters.<br></p><p>Performed 4-Condition test for FQIC-81902A/B&nbsp; as per procedure.<br></p><p>All result are pass.</p><p>Print report constant log, Current report 1 and 2.(Before removed maint mode)</p><p>Clear the maintenance mode.</p>', NULL, '2024-05-17 16:37:50', '2024-05-17 16:38:47', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
