-- Inserting report ID 12885
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '12MPM of G-8320 at ZBV#2.', 'Mechanic', 'PM', 'In Progress', '2024-05-17', '<p><b>Description: Performed 12M PM of diesel engine generator G-8320 at ZBV#2. (1st day)</b></p><p><br></p><p><b>Working steps:</b></p><p>-The unit was already being online with load.&nbsp;</p><p>-Taken the engine parameters and logs before PM.</p><p>-Stopped the unit from CCR.</p><p>-Performed electrical isolation.</p><p><br></p><p>-Removed the exhaust guard and fan guard.</p><p>-Drained the coolant and removed the radiator.</p><p><b><i>-Removed the rocker arm box cover and replaced seal (P/N.998-397).&nbsp;</i></b></p><p><b><i>-Adjusted valve tappet clearance. (14Nm for locknut torque).</i></b></p><table class="table table-bordered"><tbody><tr><td><i>Cylinders</i></td><td>I<i>nlet mm (before)</i></td><td><i>Exhaust mm (before)</i></td><td><p>Inlet mm (after)	<i></i></p></td><td><i>Exhaust mm (after)</i></td></tr><tr><td>No.1</td><td><b>0.3</b>&nbsp;</td><td><b>0.3</b></td><td>0.2</td><td>0.2</td></tr><tr><td>No.2</td><td><b>0.3</b></td><td><b>0.25</b></td><td>0.2</td><td>0.2</td></tr><tr><td>No.3</td><td>0.2</td><td>0.2</td><td>0.2</td><td>0.2</td></tr><tr><td>No.4</td><td>0.2</td><td>0.2</td><td>0.2</td><td>0.2</td></tr></tbody></table><p>-Cleaned rocker arm cover box, breather filter.</p><p>-Cleaned the radiator, fan guard, Fan by water jet.</p><p>-Installed back the fan, radiator,</p><p><b><i>-Replaced the belt. P/N.10000-66575.</i></b></p><p>-Adjusted fan belt tension.&nbsp;</p><p><b><i>-Filled up radiator coolant. PTT PRE-MIXED COOLANT 5L.</i></b></p><p><br></p><p>-Performed electrical de-isolation.</p><p>-Test run with no load, without radiator cap.</p><p>-Monitored the engine parameters if any abnormal condition.</p><p>-stopped the unit and checked coolant level.</p><p>-Put the unit on auto remote standby.</p><p><br></p><p><b>Required tools and equipment.</b></p><p>-Torque wrench</p><p>-Socket. (1 7/16 inches or 36mm)</p><p>-water jet</p><p>-Extension cord</p>', '-The radiator rubber mounting is defective. Need to replace.', '2024-05-17 17:10:52', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Inst-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8320-PACKAGE', 'ATL-BV2-G-8320-PACKAGE', 'Gen, ZBV2 Diesel Generator package2', NULL, NULL, 'Gen, ZBV2 Diesel Generator package2', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

