  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2K-5310C Verify unit tripped and clean air cooler', 'Mechanic', 'CM', 'In Progress', '2024-05-07', '<p align="left"><u>Symptom Reported</u>:&nbsp;Verify unit tripped and clean air cooler.</p><p align="left"><u>Remedy</u>: 7 May 2024.&nbsp;</p>  <p align="left">o&nbsp;&nbsp; Request to Process and Electrical isolation.</p>  <p align="left">o&nbsp;&nbsp; Remove enclosure door at cooler system.</p>  <p align="left">o&nbsp;&nbsp; Visual check the cooler fin tube both inter and after coolers found dirt and oily.</p>  <p align="left">o&nbsp;&nbsp; Cleaning the fin tube by using the oiler-1 then washing with potable water both inter and after coolers.</p>  <p align="left">o&nbsp;&nbsp; Dry the fin tube with clean air.</p>  <p align="left">o&nbsp;&nbsp; Request to Process and Electrical de-isolation for running test. </p>  <p align="left">o&nbsp;&nbsp; Running test at Lead result below;</p>  <table border="1" cellspacing="0" cellpadding="0">  <tbody><tr>   <td width="294" valign="top">   <p align="center"><b>Temperature   (‘C)</b></p>   </td>   <td width="168" valign="top">   <p align="center"><b>Before   cleaning (‘C’)</b></p>   </td>   <td width="156" valign="top">   <p align="center"><b>Running   test (‘C)</b></p>   </td>  </tr>  <tr>   <td width="294" valign="top">   <p align="left">2TIT-53171C Ambient Temp.</p>   </td>   <td width="168" valign="top">   <p align="center">34</p>   </td>   <td width="156" valign="top">   <p align="center">33.2</p>   </td>  </tr>  <tr>   <td width="294" valign="top">   <p align="left">2TIT-53152C LP Element   Outlet Temp.</p>   </td>   <td width="168" valign="top">   <p align="center">216</p>   </td>   <td width="156" valign="top">   <p align="center">199</p>   </td>  </tr>  <tr>   <td width="294" valign="top">   <p align="left">2TIT-53153C HP Element   inlet Temp.</p>   </td>   <td width="168" valign="top">   <p align="center">42</p>   </td>   <td width="156" valign="top">   <p align="center">39.7</p>   </td>  </tr>  <tr>   <td width="294" valign="top">   <p align="left">2TIT-53155C HP Element   Outlet Temp.</p>   </td>   <td width="168" valign="top">   <p align="center">209</p>   </td>   <td width="156" valign="top">   <p align="center">196</p>   </td>  </tr>  <tr>   <td width="294" valign="top">   <p align="left">2TIT-53157C Comp Air Discharge   Temp.</p>   </td>   <td width="168" valign="top">   <p align="center">37</p>   </td>   <td width="156" valign="top">   <p align="center">35.3</p>   </td>  </tr> </tbody></table>  <p align="left">&nbsp;</p>  <p align="left">o&nbsp;&nbsp; Monitor Electrical auto drain both the intercooler and the aftercooler during running about 30 minutes, found that its proper work but after that aftercooler malfunction. Then unit trip by condensate aftercooler high.</p>  <p align="left">o&nbsp;&nbsp; Restart unit again then monitor the intercooler and the aftercooler found intercooler proper work, but aftercooler malfunction, there is condensate aftercooler high then open ball to manual drain for maintain unit running.</p>  <p align="left">o&nbsp;&nbsp; Inform MEI to verify the Aftercooler Electrical auto drain malfunction.&nbsp;</p><p align="left"><br></p>', NULL, '2024-05-17 20:10:16', '2024-05-22 17:00:50', 'PTTEP\TasapornV', 'PTTEP\WittayaB', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-5310C.PK', 'GBS-2X-5310C.PK', 'PPS AIR COMPRESSOR C PACKAGE', NULL, NULL, 'PPS AIR COMPRESSOR C PACKAGE', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

