BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace discharge check valve 16"150#', 'Mechanic', 'CM', 'Completed', '2024-05-18', '<p>Replace discharge check valve 16"150# due to passing.</p><p>- Request to Process and Electrical isolations.</p><p>- Remove discharge check valve, as found erosion between valve seat and flapper.</p><p>- Replace discharge check valve with new one including new rubber gasket.</p><p>- Apply JIMs to tighten stud bolts, torque value 100 N.m.</p><p>- Request to Process and Electrical isolations.</p><p>- Test valve passing found no passing.</p><p>- Cleaning the working area.</p><p><br></p>', '<p><a href="G:\GBSShare\Department Share\03 Maintenance\031 DBS_MM\6. Picture\62. QPS Equipment Picture\Fire water ring main\2024\2024.05.18 2P-6201 Replace discharge check valve 16 inches class 150">2024.05.18 2P-6201 Replace discharge check valve 16 inches class 150</a></p><p>Spare part used :&nbsp;</p><p>&nbsp; &nbsp; &nbsp;- Check valve 16" 150#, Q''ty 1 Set.</p><p>&nbsp; &nbsp; &nbsp;- Rubber gasket 16" 150#, Q''ty 2 EA.<br><br></p>', '2024-05-18 16:35:20', '2024-05-19 13:23:48', 'PTTEP\WittayaB', 'PTTEP\GBS.Mechanic-WorkS', false) RETURNING id INTO new_report_id;
