-- Inserting report ID 12994
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '6MPM of EDG-8935', 'Mechanic', 'PM', 'Completed', '2024-05-20', '<p><b>Description: Performed 6M PM of Emergency Diesel Engine Generator EDG-8935.</b></p><p><br></p><p><b><u>Working steps:</u></b></p><p>-Performed electrical isolation.</p><p>-Drained water from Diesel day tank and fuel-water separator.</p><p>-Cleaned air filters (2EA) and visually checked turbo chargers condition.</p><p>-Checked lube oil level and condition.&nbsp;</p><p><br></p><p>-Checked radiator coolant level and condition.</p><p>-Removed and cleaned breather filters.</p><p>-Checked fan belt tension and pulley alignment.</p><p><br></p><p>-Checked exhaust flange bolts tightness.</p><p>-Checked fan guard bolt tightness, radiator base mounting bolt tightness with<b> <i style="">torque 100 N-m</i></b></p><p>-Checked engine mounting bolt for any corrosion and loosen tightness.&nbsp;</p><p>-Performed electrical de-isolation.</p><p>-Performed test run and recorded parameters.</p><p><br></p><p><br></p><p><b>Required tools and equipment.</b></p><p>-Wrench 30mm, 19mm (for radiator mounting bolts)</p><p>-Adjustable spanner.</p><p>-Torque wrench</p><p>-Contact cleaner, safety solvent.</p><p>-Cotton Rags.</p><p>-Laser alignment equipment.</p><p>-Spill container for diesel water drain.</p><p><br></p>', NULL, '2024-05-20 16:27:52', '2024-05-20 16:38:58', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Inst-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8935-PACK', 'ATL-OC-G-8935-PACK', 'Gen, ZOC Diesel Generator Package', NULL, NULL, 'Gen, ZOC Diesel Generator Package', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 13005
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Precheck and test run before 16KMPM and overhaul ', 'Mechanic', 'CM ', 'In Progress', '2024-05-20', '<p>&nbsp;Job title :<b>Precheck and test run before 16KPM and overhaul (Assisted PMO/I team)</b></p><p><br></p><p>Job Steps;</p><p><br></p><p>-Removed rocker arm cover at 5B and check the spark plug. (readjusted the spark plug gap 0.4")</p><p>-Inspected the spark plug housing, spark plug seal and rocker chamber.</p><p>-Installed back and test run.</p><p>-During test run, found grey smoke at exhaust.&nbsp;</p><p>-Another finding, found coolant is seeping between 2 radiator plates, found some coolant at the floor.</p><p>-Test run was stopped and tomorrow plan will be replacing the new seal at spark plug seal and test run.</p>', 'Required tools; Special tool to remove spark plug, socket set with ratchet, one set of allen keys, plastic hammer, flashlight', '2024-05-20 16:49:13', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

