  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 6M PM Lube oil cooler fan of SGC#2 Train 2', 'Mechanic', 'PM', 'Completed', '2024-05-20', '<p>Perform Lube oil cooler fan 6M PM BM-2640 / BM-2645<br>- As found pulley alignment found are in good condition.<br>- Checked belt tension old belt both unit found tension average about 800 Newton.<br>- Replaced fan belt, belt tension and anlignment,<br>- Belt tension BM-2640 = 1311 Newton , bm-2645 = 1339 Newton, Target New belt 1310 Newton.<br>- Inject grease to fan shaft bearings.<br>- Re-tighten all fan blade clamping bolt and nuts.<br>- BM-2640 Motor found abnormal noise from bearing while turn the rotor by hand with out fan belt.<br>- Test run at local station found normal operation both unit.</p><p><br></p><p>Tools:<br>- Wrench 1/2, 9/16, 3/4, 7/8, 11/16, 15/16, 1"<br>- Socket 11/16", 15/16"<br>- Hand torgue for fan blade 55 ft.lb<br>- Flat screw driver<br>- SKF belt frequently meter<br>- Grease gun<br><br>Consumer:<br>- Cotton rag<br>- WD-40<br>- Solvent<br>- Grease EP2<br><br>Belt type: 5VX (Mesc: 58.14.11.112.9 = 3ea)<br>Small pulley diameter: 180 mm.<br>Speed range: 1465 RPM/min<br>Span length (m): 0.650 m.<br>Mass single belt: 0.223 kg/m<br>Belt tension: 1,310 Newton (new belt)<br></p>', '<p>WO&nbsp;<span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;">500533956</span></p><p><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;">58.14.11.112.9 , V-Belt 5VX1120 = 6 Ea..</span><span style="color: rgb(102, 102, 102); font-family: Arial, sans-serif; font-size: 12px;"><br></span></p>', '2024-05-21 08:44:13', '2024-05-21 10:13:22', 'PTTEP\TasapornV', 'PTTEP\Art.MechTurbine', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-BM-2640', 'ART-BM-2640', 'COOLER FAN MOTOR', NULL, NULL, 'COOLER FAN MOTOR', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-BM-2645', 'ART-BM-2645', 'COOLER FAN MOTOR', NULL, NULL, 'COOLER FAN MOTOR', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
