  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replaced Kobelco defective lower rollers. ', 'Mechanic', 'CM', 'Completed', '2024-05-21', '<p><b>Description: Performed the defective lower rollers (8EA) of Mini excavator KOBELCO.</b></p><p><br></p><p><b>Working steps:</b></p><p>-Placed the vehicle in maintenance position.</p><p>-Removed the defective lower rollers (both sides) total quantities 8EA.</p><p>-Installed the new lower rollers P/N: PX64D00009F.</p><p>-Tightened the bolts by pneumatic gun.</p><p><br></p><p><b>Required Tools:&nbsp;</b></p><p>Pneumatic Gun, Scaffolding bar, Wood (stopper), Hummer, Grease Gun,&nbsp;</p><p>Socket 22 mm.</p><p><br></p><p><br></p>', '<p>Failure Cause: Operation General&nbsp;</p><p>Short Failure: Operation Error&nbsp;</p>', '2024-05-21 17:36:33', '2024-05-25 08:24:35', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
