END $$;

-- Inserting report ID 13064
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'G-9115 16KPM Day 1', 'Mechanic', 'PM ', 'In Progress', '2024-05-21', '<p><i>Job Description : </i></p><p><b>Perform 16KPM on G-9115 Day 1</b></p><p><br></p><p><i>Job Steps :</i></p><p><b>- Applied new seal at spark plug chamber, installed back the old spark plug with proper gap.</b></p><p><b>- Performed test run and record parameters. Normal but found grey smokes at exhaust.</b></p><p><b>- During test run, found coolant seeping from between of 2 radiators. (fault finding).</b></p><p><b>- Stopped the generator and performed isolations; Mechanical, Electrical and Process.</b></p><p><b>- Prepared empty drums and blue drums to drain coolant and lube oil.</b></p><p><b>- Set lube oil pump and connected hoses to drain into empty drums.</b></p><p><b>- Connected coolant hoses at coolant drain points.</b></p><p><b>- Disconnected vent line and closed the connection with PVC cap for temporary to keep from dusts.</b></p><p><b>- Removed batteries and test voltages. Need to recharged.</b></p><p><b>- Fabricated new lighting unit and installed it inside generator housing for proper light.</b></p><p><b>- Removed cover brackets around the generator.&nbsp; (both sides)</b></p><p><b>- Removed air filters, filter brackets and air inlet lines. (both sides)</b></p><p><b>- Removed fuel/gas feeding lines. (both sides)</b></p><p><b>- Removed actuators. (both sides)</b></p><p><b>- Checked the turbocharger inlet and condition. (both sides)</b></p><p><b>- Housekeeping and end of Day 1.</b></p><p><br></p><p><i>Required Tools.</i></p><p><b>- Adjustable wrench. (Big one)</b></p><p><b>- Socket and ratchet set.</b></p><p><b>- Spanner set.</b></p><p><b>- Allen keys set.</b></p><p><b>- Pipe gauge (monkey head)</b></p><p><b>- Lube oil pump, connections and hoses (kept at spare parts store room)</b></p><p><b>- Coolant pump, connections and hoses (kept at spare parts store room)</b></p><p><b>- Blind flange for mechanical isolation for gas generator (Kept at spare parts store room)</b></p><p><b>- Rags and trays.</b></p><p><b>- Pellets and racks.</b></p><p><b>- PVC cap connection for Vent line (Kept at spare parts store room)</b></p>', NULL, '2024-05-21 17:39:13', '2024-05-21 17:40:46', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

