  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform 6MPM ME Exp Comp Discharge Cooler "B" TC#1', 'Mechanic', 'PM', 'Completed', '2024-05-13', '<p align="left">o&nbsp;&nbsp; Request to Electrical isolation.</p>  <p align="left">o&nbsp;&nbsp; Select the Local switch to Off mode.</p>  <p align="left">o&nbsp;&nbsp; Remove fan guard and teeth belt.</p>  <p align="left">o&nbsp;&nbsp; Inspect bearings condition found normal.</p>  <p align="left">o&nbsp;&nbsp; Inspect cooler fan blades condition found normal.</p>  <p align="left">o&nbsp;&nbsp; Check blade angle and blade tip clearance found normal.</p>  <p align="left">o&nbsp;&nbsp; Check pulley both motor and fan pulleys. &nbsp;</p>  <p align="left">o&nbsp;&nbsp; Check alignment found align.</p>  <p align="left">o&nbsp;&nbsp; Replace belt and adjust belt tension.</p>  <p align="left">o&nbsp;&nbsp; Apply grease on upper and lower bearings.</p>  <p align="left">o&nbsp;&nbsp; Reinstall fan guard.</p>  <p align="left">o&nbsp;&nbsp; Running test found normal condition.&nbsp;</p>', NULL, '2024-05-22 14:30:03', CURRENT_TIMESTAMP, 'PTTEP\WittayaB', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2A-3930B', 'GBS-2A-3930B', 'EXPORT GAS COM DISCHARGE COOLER FAN B', NULL, NULL, 'EXPORT GAS COM DISCHARGE COOLER FAN B', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
