-- Inserting report ID 13120
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Remove isolation valve 2ZI-30206  ', 'Mechanic', 'CM', 'Completed', '2024-05-20', '<p align="left"><u>As found</u>: - Isolation valve 2ZI-30206 body stud bolts are corroded.<br></p><ul type="square"><li>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Gas seeping at 2PI-30221thread connector.</li></ul><p align="left">o&nbsp;&nbsp; Request to Process isolation.</p><p align="left">o&nbsp;&nbsp; Remove 2PI-30221thread connector to clean and apply PTFE pipe thread tape then re-install 2PI-30221thread connector back to location.</p><p align="left">o&nbsp;&nbsp; Remove 2ZI-30206 to Mech W/S.</p><p align="left">o&nbsp;&nbsp; Remove corrode body stud bolts then replace with new ones.</p><p align="left">o&nbsp;&nbsp; Preserve body stud bolts then re-install 2ZI-30206 back to the location.</p><p align="left">o&nbsp;&nbsp; Clean all flanges.</p><p align="left">o&nbsp;&nbsp; Apply JIMs for tighten stud bolts.</p><p align="left">o&nbsp;&nbsp; Request to Process de-isolation for leakage test found no leak.</p><p align="left">o&nbsp;&nbsp; Clean the working area.</p><br>', NULL, '2024-05-22 15:30:28', CURRENT_TIMESTAMP, 'PTTEP\WittayaB', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2PR-3020', 'GBS-2PR-3020', 'PIG RECEIVER', NULL, NULL, 'PIG RECEIVER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

