  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Install blind flange 4” #600 at Multiphase flow', 'Mechanic', 'OTH', 'Completed', '2024-05-21', '<p class="Default">o&nbsp;&nbsp; After Rep. of Multiphase flow meter installs the device at 2A-2601 then have to re-install blind flange back to normal.</p>  <p class="Default">o&nbsp;&nbsp; Clean blind flange and pipe flange and preserve stud bolts.</p>  <p class="Default">o&nbsp;&nbsp; Install blind flange 4” #600 and gasket then apply JIMs to tighten stud bolts.</p>  <p class="Default">o&nbsp;&nbsp; Replace corrode gasket on 2PI-26231 and 2PI-26232 then apply JIMs to tighten stud bolts.</p>  <p class="Default">o&nbsp;&nbsp; Request to Process de-isolation for leakage test.</p>  <p class="Default">o&nbsp;&nbsp; Leak test, pressure @40 bar found no leaks all flanges.</p>0&nbsp; &nbsp;Cleaning the working area.', NULL, '2024-05-22 16:11:29', '2024-05-22 16:15:13', 'PTTEP\WittayaB', 'PTTEP\WittayaB', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-WP16-PRO', 'GBS-WP16-PRO', 'PRODUCTION PROCESS WPS16', NULL, NULL, 'PRODUCTION PROCESS WPS16', 'GBS-WP16', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

