-- Inserting report ID 13166
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '16KPM on G-9115 Day 2', 'Mechanic', 'PM ', 'In Progress', '2024-05-22', '<p>Job description :</p><p><b>-Perform 16KPM on G-9115 Day 2</b></p><p><br></p><p>Job Steps :</p><p><b>- Removed intake manifolds.</b></p><p><b>- Removed exhaust manifolds.</b></p><p><b>- Removed turbochargers.</b></p><p><b>- Removed GCV unit.</b></p><p><b>- Removed cylinder head Bank B.</b></p><p><b>- Removed charge air cooler Bank B.</b></p><p><b>- Removed water rail line.</b></p><p><b>- Removed ignition coil rail.</b></p><p><b>- Removed thermostat coolant line.</b></p><p><b>- Removed breather filters.</b></p><p><br></p><p><b style="background-color: rgb(255, 255, 0);">Fault Finding :</b></p><p><b style="background-color: rgb(255, 255, 0);">- During performing 16KPM, while removing Turbochargers and charge air line.</b></p><p><b style="background-color: rgb(255, 255, 0);">- Found lube oil residues and traces of lube oils along the air line.</b></p><p><b style="background-color: rgb(255, 255, 0);">- Lube oil or other residues are not supposed to be in the air line.</b></p><p><b style="background-color: rgb(255, 255, 0);">- Found traces and residues ever after passing the charge air cooler.</b></p><p><b style="background-color: rgb(255, 255, 0);">- But no signs of oils at exhaust section.</b></p><p><b style="background-color: rgb(255, 255, 0);">- Bank B is worse than Bank A.</b></p><p><b style="background-color: rgb(255, 255, 0);"><br></b></p><p><b style="background-color: rgb(255, 255, 0);">Suspected Root Cause :</b></p><p><b style="background-color: rgb(255, 255, 0);">- Turbocharger oil seals are worn out and passing lube oil.</b></p><p><b style="background-color: rgb(255, 255, 0);">- Lube oil are sucked along with air intake.</b></p><p><br></p><p><br></p>', NULL, '2024-05-23 14:39:27', '2024-05-23 14:52:12', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 13168
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Found lube oil leaking G-9120 while online', 'Mechanic', 'CM ', 'In Progress', '2024-05-22', '<p>Job description :</p><p><b>- Found lube oil are leaking from lube oil return line from oil cooler while online.</b></p><p><br></p><p>Job Steps :</p><p><b>- Found that lube oil are leaking from lube oil return line from oil cooler during the visual inspection.</b></p><p><b>- Informed CCR and stopped the generator immediately.</b></p><p><b>- After stopping, checking the lube oil leaking location to make sure the root cause.</b></p><p><b>- Lube oil are leaked around 20L.</b></p><p><b>- Replaced worn out oil hose with a new one.</b></p><p><b>- Cleaned up the area to make the generator able to be online.</b></p><p><b>- Meanwhile diesel generator is online.</b></p><p><b><br></b></p><p>Suspected Root cause :</p><p><b>- Long time usage and exposure to heat.</b></p><p><b>- Hose became brittle and easier to be broken.</b></p>', '<p>Required Tools : Adjustable wrench (Big), rags and red bags</p><p>Short Failure Cause: Fatigue Hose&nbsp;</p><p><br></p>', '2024-05-23 14:47:52', '2024-05-25 08:17:04', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9120-PACKAGE', 'ATL-MS-G-9120-PACKAGE', 'Gen, ZMS Gas Generator package3', NULL, NULL, 'Gen, ZMS Gas Generator package3', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
