  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2MPM of IA-8980A', 'Mechanic', 'PM', 'Completed', '2024-05-24', '<p><b>Description: Performed 2M PM of instrument air compressor unit IA-8980A.</b></p><p><br></p><p><b><u>Working steps:</u></b></p><p>-Performed process and electrical isolation.</p><p>-Drained tank pressure until to zero.</p><p>-Checked pulley alignment and belt tension; found pulley misalignment a bit and one of the belts loosen.</p><p>-Removed guard cover.</p><p><b><i>-Re-alignment the pulley and adjusted belt tension.&nbsp;</i></b></p><p><b><i>-Changed lube oil AZOLA 46 (4L).</i></b></p><p><b><i>-Changed air filter.</i></b></p><p>-Checked motor and compressor mounting bolts tightness.</p><p>-Performed electrical and process de-isolation.</p><p>-Test run and checked for any abnormal condition.</p><p><br></p>', NULL, '2024-05-24 16:19:25', '2024-05-24 17:34:15', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Mech-Tec', false) RETURNING id INTO new_report_id;
