-- Inserting report ID 13331
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '16KPM on G-9115 Day 6', 'Mechanic', 'PM ', 'In Progress', '2024-05-26', '<p>Job Description :</p><p><b>-Perform 16KPM on G-9115 Day 6</b></p><p><br></p><p>Job Steps :</p><p><b>- Cleaned removed parts from Bank A.</b></p><p><b>- Inspected and measured on piston rings gaps.</b></p><p><b>- Cleaned the engine oil sump.</b></p><p><b>- Install new liners to engine block.</b></p><p><br></p><p>Steps to install Liners :</p><p><b>- Check and make sure the spare parts are correct.</b></p><p><b>- Applied petroleum gel on liners and O rings.</b></p><p><b>- Install the liner O rings on the liner.&nbsp;</b></p><p><b>- Applied Loctite 638 on the liner (TOP) place of engine block.</b></p><p><b>- Put the liner into the engine block.</b></p><p><b>- Put the special Teflon block on the liner.</b></p><p><b>- Hit softly with plastic hammer.</b></p><p><b>- Use liner pusher special tool and some bushings to push the liner inside slowly.</b></p><p><b>- the gap from liner surface to engine block surface is between 2.07mm to 2.2 mm.</b></p><p><br></p>', 'Required tools : liner pusher special tool, plastic hammer, Teflon block, bolts from cylinder blocks, petroleum gel, one socket box and rags', '2024-05-26 15:19:45', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

