  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Weekly visit all Life Boat battery chargers.', 'Electrical', 'PM', 'Completed', '2024-05-27', '<p>Weekly visit all Life Boat battery chargers.</p><p>- Checked all battery chargers are working and stilled charging to batteries.</p><p>- Perform thermoscan all battery chargers.</p><p>- Measured voltage for all batteries.</p><p>The result of thermoscan and battery voltage are;</p><p><br></p><p>Life boat No. 1;</p><p>&nbsp; &nbsp; - Charger temperature &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; = 50.2 degC.</p><p>&nbsp; &nbsp; - Main battery voltage &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;= 13.34 VDC.</p><p>&nbsp; &nbsp; - Emergency battery voltage &nbsp; &nbsp; &nbsp;= 13.42 VDC.</p><p>&nbsp; &nbsp; - VHF battery voltage &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; = 13.37 VDC.&nbsp;</p><p><br></p><p>Life boat No. 2;</p><p>&nbsp; &nbsp; - Charger temperature&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp;= 52.2 degC.</p><p>&nbsp; &nbsp; - Main battery voltage&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;= 13.52 VDC.</p><p>&nbsp; &nbsp; - Emergency battery voltage&nbsp;&nbsp; &nbsp; &nbsp;= 13.38 VDC.</p><p>&nbsp; &nbsp; - VHF battery voltage&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;= 13.39 VDC.&nbsp;</p><p><br></p><p>Life boat No. 3;</p><p>&nbsp; &nbsp; - Charger temperature&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp;= 44.2 degC.</p><p>&nbsp; &nbsp; - Main battery voltage&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;= 13.33 VDC.</p><p>&nbsp; &nbsp; - Emergency battery voltage&nbsp;&nbsp; &nbsp; &nbsp;= 14.22 VDC.</p><p>&nbsp; &nbsp; - VHF battery voltage&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;= 14.52 VDC.&nbsp;</p>', NULL, '2024-05-27 11:03:54', CURRENT_TIMESTAMP, 'PTTEP\GBS.EI-Workshop', NULL, false) RETURNING id INTO new_report_id;
END $$;

