BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'X-6900D Perform Lifeboat and Davit YPM.', 'Mechanic', 'PM', 'In Progress', '2024-05-25', '<p>Hook release gear.</p><p>-&nbsp; &nbsp; Visual inspection for any damage and corrosion.</p><p>-&nbsp; &nbsp; Clean and greasing all moving parts.</p><p>Hydraulic starting system.</p><p>-&nbsp; &nbsp; Fill up HYD reservoir.</p><p>-&nbsp; &nbsp; Check N2 HYD start&nbsp; accumulator @ 100 Barg.</p><p>25-May-2024&nbsp;</p><p>- Replace lube oil wench and gear box.</p><p>- Check and inspect drum break and governor break .</p><p>&nbsp;- Drum break thickness = 5 mm. / Governor break thickness = 8 mm.</p><p>- Check and grease all pivots, bearings and other greasing pt.</p><p>- Carry out functional test of winch manual brake both direction and remote control.</p><p>- Visual examination of wire ropes for deterioration.</p><p></p><p>- Check all safety devices and switch gear for proper working.</p><p>- Change lube oil winch gear.&nbsp;</p><p>- Inspected and cleaning the internal parts of winch brake.</p><p>- Inspected all rotating parts for ease of movement.</p><p>- Functional tested of winch manual brake both direction and remote control was normal operation.<br></p><p><u></u></p><p><u></u></p><p></p><p><br></p>', NULL, '2024-05-27 14:53:10', CURRENT_TIMESTAMP, 'PTTEP\Mech_WS', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-X-6900D', 'GBN-X-6900D', 'LIFEBOAT/DAVIT NO.4', NULL, NULL, 'LIFEBOAT/DAVIT NO.4', 'GBN-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
