  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2TG-5510 Crank soak wash', 'Mechanic', 'PM', 'Completed', '2024-05-27', '<p>Crank soak wash before perform CAV by Solar vender</p><p>Running hours: 22,031 hrs.</p><p>Self isolation: Fuel gas valve&nbsp;</p><p>Disconnect all line that connect to transmitter</p><p>Disconnect fuel gas supply line.</p><p>Supply air to seal air bearing.</p><p>Take sampling chloride 2 point: 1. Air filter housing 2. Air inlet duct</p><p>Perform water wash</p><p>1 Chemical wash&nbsp;</p><p>2 Rinse water</p><p>Reconnect all line that connect to transmitter</p><p>Replace new spark plug with gasket.</p><p>Replace new new O-ring on fuel gas supply line.</p><p>Replace metal seal gasket on drain line of air manifold.</p><p>Fire dry with gas mode for 15 minutes No load</p><p>Stop package for stand by</p><p><br></p><p>Conductivity:</p><p>Before: 1,012 US/CM</p><p>After: 26.4 US/CM</p><p><br></p><p>Additional job:</p><p>Unblock package drain line and drop valve 2"#150</p><p><br></p><p>Spare part.</p><p>1. 20.70.27.542.3, Seal metal, 1/4" SAE O-ring, P/N 967691C1 Qty 1 ea.</p><p>2. 20.70.00.378.3,&nbsp;O-RING,VITON,SAE 225,SOLAR,P/N.903732C1 Qty 1 ea.<br></p><p>3.&nbsp;20.70.00.492.3,&nbsp;PARK PLUG,P/N.903316C1 Qty 1 ea.</p><p>4.&nbsp;87.11.50.001.9,&nbsp;ZOK 27,CLEANER (25 LITERS) Qty 1 Pail.</p><p>5. 87.16.75.001.9, Deionized Water Qty 14 pails.</p>', NULL, '2024-05-27 21:16:56', '2024-05-27 23:02:47', 'PTTEP\GBS.Mechanic-WorkS', 'PTTEP\KittipongSam', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2TG-5510', 'GBS-2TG-5510', 'GAS TURBINE GENERATOR SOLAR TAURUS 70', NULL, NULL, 'GAS TURBINE GENERATOR SOLAR TAURUS 70', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

