  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-HOV-83000-ASSY', 'ATL-BV2-HOV-83000-ASSY', 'Zawtika Block Valve 2 ASSY', NULL, NULL, 'Zawtika Block Valve 2 ASSY', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
