  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'AIT-1683_OGC-1 MPM-Chg_New-STD-GAS', 'Instrument', 'PM', 'Completed', '2024-05-29', '<p>Monthly PM_AIT-1683 _(Change New Std gas from 104252AW to 106411AW, due to empty.)</p><p>&nbsp;1- As found with the Old STD-Gas (104252AW)_ Its result was complied (PASS)</p><p>&nbsp;2- Replaced the STD-Gas Cylinder to 106411AW</p><p>&nbsp;3- As found the New Cyl. with the existing component concentration. Its result was complied. (PASS)</p><p>&nbsp;4- Halt and Checklist of maintenance, also replaced Pressure indicator gauges of the 1st carrier gas cylinder.</p><p>&nbsp;5- Baseline checked and recorded the CGM graph.</p><p>&nbsp;6- Changed component concentration as referred to in the Certificate of cylinder No. 106411AW.</p><p>&nbsp;7- Performed Forced calibration and normal calibration.</p><p>&nbsp;8- After verifying the R-SQ result from the Final calibration report, and then meet the specification compliance.</p><p>&nbsp;9-&nbsp; Then performed as left according to the Work instructions.</p><p>&nbsp;</p><p>&nbsp; &nbsp; &nbsp;&nbsp;</p>', 'There were empty cylinders for STD-GAS&nbsp; No.104252AW (LPG size), and another helium cylinder 17W116006', '2024-05-29 10:30:58', '2024-05-31 06:53:34', 'PTTEP\TawatchaiP', 'PTTEP\TawatchaiP', false) RETURNING id INTO new_report_id;
