  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot FGC#2 Startup failure due to T4.5', 'Turbine E&I', 'CM', 'In Progress', '2024-05-30', '<p>Startup Troubleshooting The FGC#2 start-up failure due to the T4.5 Software over-temp cooldown stop requested.</p><p>- The 4 times started-up had been activated by CCR since 07:00 - 9:00, but all failed.</p><p>- Due to the starting failure, the Mechanic team cleaned the package engine by the engine crank soaked washed.</p><p>- Again, the engine starting had failed 2 times after the engine washing during 21:30 - 22:30.</p><p>- Before the last starting GGBV was functionally tested and proved it is working properly.</p><p>- There got a concerning, why the speed of&nbsp; "NL" was too slow even compared with "NH" speed. there was a differential about 2100 RMP.</p><p><br></p><p>Anyway, the Package Engineer (Nopparut) will request Vendor to modify the logic 5000 Programe prior to changing the Gas composition coefficiency of combustibility.</p><p>Then The package starting was pulled over and waiting for further information from Vendor and Package Engineer.&nbsp;</p><p>&nbsp;&nbsp;<br></p><p><br></p>', '<span style="font-size: 14px;">Noted, FGC#2 was start-up failure 2 time after engine-crank-soak-washed. (Normally the FGC#2 rectifies unit start-up failure from "T455 software over-temp cool stop" ( This alarm is any T455 hitting 520 C while "NL" speed is under 3250 (Idle-speed))</span>', '2024-05-30 23:05:04', '2024-06-01 16:14:46', 'PTTEP\TawatchaiP', 'PTTEP\TawatchaiP', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-10-UG-22304-JS1N', 'ART-10-UG-22304-JS1N', 'Pipe 10" for Stand Pipe 10"', NULL, NULL, 'Pipe 10" for Stand Pipe 10"', 'ART-ASSET', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
