  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2A-3560A: Replace defective Belt', 'Mechanic', 'CM', 'Completed', '2024-05-31', '<p>&nbsp;&nbsp;&nbsp;&nbsp;2A-3560A - FGRU Discharge cooler fan replace defective belt</p><p>- Inspect Fan blade condition</p><p>- Inspect Driver/ Driven Pulley and preserve</p><p>- Alignment Driver/ Driven Pulley with Laser alignment<br></p><p>- Inspect Cooler fan Shaft Upper/ Lower bearings</p><p>- Replace Timming belt and set Belt tension at 6.8 Kgf.(Spect 6.2 - 6.8 Kgf.)</p><p>- Apply Lubrication grease for Fan shaft Upper/ Lower Bearing.</p><p><br></p><p><br></p>', NULL, '2024-05-31 14:59:23', '2024-05-31 15:23:55', 'PTTEP\GBS.Mechanic-WorkS', 'PTTEP\GBS.Mechanic-WorkS', false) RETURNING id INTO new_report_id;
