DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'To perform 6MPM', 'Mechanic', 'PM', 'Completed', '2024-05-31', '<p align="left">&nbsp;<b>Anti-Scalant Pump (2P-4846) and <br> pH adjustment Pump (2P-4845)</b></p>  <p align="left"><b><u>&nbsp;</u></b></p>  <p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replace lube oil gearbox with MOBIL SHC 630, <br> 0.5 liter for:&nbsp; &nbsp;2P-4845 pH adjuster pump.</p>  <p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2P-4846 Anti- scale pump.<u></u></p>  <p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replace oil at diaphragm housing pump with TOTAL Azolla ZS 10, 0.5 liter for:</p>  <p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2P-4845 pH adjuster pump.</p>  <p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2P-4846 Anti- scale pump.<br></p><p align="left">v&nbsp; <b>Cleaning (flush) Pump (2P-4847)</b> <b><u></u></b></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; General visual check on the holding down bolt for corrosion.</p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Tightening and driving coupling check.</p><p align="left"><b><u>Abnormal&nbsp; </u></b></p><p align="left">: Found corrosion at pump unit. (2P-4847 Flush pump) and shaft stuck.</p><p align="left">: Found love joy coupling worn out and bearing defected. </p><p align="left"><b><u>Corrective Action.</u></b></p><p align="left">: &nbsp;awaiting the start of work by the plan team leader.</p><p align="left">&nbsp;</p><p align="left">v&nbsp; <b>Membrane Feed pump (2P-4844)</b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Visual check pump coupling condition.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Suction/Discharge piping connection joints.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Pump’s motor mounting bolts.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Last running performance:</p><p align="left">                            <u></u></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Discharge pressure=43 bars.<br></p><p align="left">v&nbsp; <b><u>Filters</u></b></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove and clean the filter nozzles.</p><p align="left">o&nbsp;&nbsp; 2 multi-media filters, 2F-4840A/B.</p><p>      </p><p align="left">o&nbsp;&nbsp; 2 Carbon filters, 2F-4841A/B.<br></p><p align="left">v&nbsp; <b><u>Valve</u></b></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Water seep at FV-48471.</p><p align="left">o&nbsp;&nbsp; Remove FV-48471 to inspect.</p><p align="left">o&nbsp;&nbsp; Found flow cut at body valve and downstream spoon.</p><p align="left">o&nbsp;&nbsp; Replace valve and boat gasket.</p><p align="left"><u>&nbsp;</u></p><p align="left"><b><u>Abnormal&nbsp; </u></b></p><p align="left">: Flow control valve FV-48471 flow cut.</p><p align="left">: Downstream flow control valve FV-48471 flow cut.</p><p align="left">&nbsp;</p><p align="left"><b><u>&nbsp;</u></b></p><p align="left"><b><u>Corrective Action </u></b></p><p align="left">                        </p><p align="left">: Replace flow control valve and both gaskets.<br></p><p align="left">v <u>Unit running and back in service</u></p><p align="left">  </p><p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The unit running condition and all parameters are in normal.</p>', NULL, '2024-05-31 15:16:58', CURRENT_TIMESTAMP, 'PTTEP\DirekT', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-4840.PK', 'GBS-2X-4840.PK', 'WATER MAKER TRAIN A PACKAGE', NULL, NULL, 'WATER MAKER TRAIN A PACKAGE', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
