  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S WPS-1 Lighting system not available.', 'Electrical', 'CM', 'Completed', '2024-05-30', '<p>T/S WPS-1 Lighting system not available.</p><p>- Found all platform lighting not available since 28-30 May 2024, after verified found L1 voltage loss and common alarm present at ECS and local&nbsp; then check at the transformer JB found the transformer tap voltage selector switch was selected at 420V but usually should be selected at 400V, select to 400V and alarm cleared also lighting systems back to normal.&nbsp;</p>', NULL, '2024-05-31 15:57:11', '2024-05-31 16:03:32', 'PTTEP\GBS.EI-Workshop', 'PTTEP\GBS.EI-Workshop', false) RETURNING id INTO new_report_id;
