-- Inserting report ID 13576
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verified FGC2 cannot start from T455 software CS', 'Turbine E&I', 'CM', 'In Progress', '2024-05-31', '<p>Verified FGC#2 could not start from T455 software over temp cool stop.</p><p>-Verified and check condition of Air inlet filter duct.Found poor condition and found deposit inside housing then perform cleaned.</p><p>-Track trend of Air inlet filter DP transmitter.</p><p>-Verify Fuel gas knife swicth Co2 selection found</p><p>&nbsp;both FGC knife switch on close position</p><p>Co2 selected high =29.82 %Co2</p><p>Plan next action :</p><p>Open knife switch to select low Co2 mode = 23.269 %Co2 and function start FGC.</p><p><u><b><i>The FGC#2 was started-up successfully after changing the fuel gas selection</i></b></u> from "Alternative FG" to "Normal FG" Concentration ( From 29.8% to 23.69%) _ 18:40 Pm.</p><p><br></p><p><u>The knife switch contact is located in the UCP package rear panel</u>, it was determined that the alternative fuel-gas concentration selected (<b>Co2_29.82%)</b> with "Knife <b>Contact closed</b> " and normal fuel gas concentration selected (<b>Co2_23.269%</b>) with <b>contact open</b>.</p>', NULL, '2024-05-31 16:35:36', '2024-11-10 20:47:26', 'PTTEP\Arthit.EI-Turbine', 'PTTEP\TawatchaiP', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-C-2210-INSTR', 'ART-C-2210-INSTR', 'FEED GAS COMPRESSOR INSTRUMENTATION', NULL, NULL, 'FEED GAS COMPRESSOR INSTRUMENTATION', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

