  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-QP-PCS.ASY', 'ART-QP-PCS.ASY', 'AQP PROCESS CONTROL ASSEMBLY', NULL, NULL, 'AQP PROCESS CONTROL ASSEMBLY', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
