-- Inserting report ID 13636
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Startup T/S SGC#2 due to NGP-Under-Speed trip', 'Turbine E&I', 'CM', 'Completed', '2024-06-01', '<p>SGC#2 was start-up troubleshooting after its startup failures with an alarm (FN_NPG_UNDER_SPEED).</p><p>&nbsp;- FYI, The SGC# was volunteered to stop because the&nbsp; "Lube oil TCV" needs to be replaced by the Mechanic team ( Due to the lube oil header being high temp concerned)</p><p>&nbsp;- The 1st and 2nd start-up were failures with the NGP-Under speed tipped.</p><p>&nbsp;- The 3rd startup was tripped seal gas supply diff low (PDI-2610) and came together with alarm of ZF-2120 module Ch.1 got Overloaded. Then after verification, we found that SDV-2610 did not properly open causing the Press-Diff to low and SGC#2 blowdown tripped. So, we replaced the XSV-2610 with the new solenoid valve (Bifold-Non reset able) (Found the existing solenoid coil was 14 Ohms, its impedance should&nbsp; be 108 ohms.)</p><p>&nbsp;- 4th startup failed again after addressing the insufficient delay time in reaching the drop-off speed &gt; 73% NPG. The time delay was changed from 40 to 45 sec.</p><p>&nbsp;- 5Th Startup was successful after increase adjusting the delay time from 45 to 60 Sec.</p><p>&nbsp;- Regarding adjusting the delay time informed by the CCR operator, they had experience in adjusting the timing to overcome this problem.</p><p>&nbsp;</p>', '<p>Noted the Delay time of reaching drop-off speed &gt;73 %NGP..</p><p>The alarm "FN_NGP_UNDER_SPEED" during accelerating to idle, should be re-addressed for verified the possible route cause.&nbsp;</p>', '2024-06-01 15:27:52', '2024-06-01 20:04:01', 'PTTEP\TawatchaiP', 'PTTEP\TawatchaiP', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-C-2610', 'ART-C-2610', 'SALES GAS COMPRESSOR TRAIN 2', NULL, NULL, 'SALES GAS COMPRESSOR TRAIN 2', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-UCP-PP-2610', 'ART-UCP-PP-2610', 'SALES GAS COMPRESSION TRAIN 2 CTRL PANEL', NULL, NULL, 'SALES GAS COMPRESSION TRAIN 2 CTRL PANEL', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-SDV-2610', 'ART-SDV-2610', 'SHUTDOWN VALVE', NULL, NULL, 'SHUTDOWN VALVE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

