-- Inserting report ID 13640
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verified FGC#2 Strtup failure with Mode Co2-high', 'Turbine E&I', 'CM', 'In Progress', '2024-06-01', '<p>FGC#2 was successfully started with cool starting and low Co2 concentration mode selection.</p><p>For more details, please review the below telling.&nbsp;</p><p>----------------------------------------------</p><p>Since we have successfully started the FGC#2 with the 23.26% concentration fuel gas selected.</p><p>Then we got an opportunity to reconfirm the starting could be affected by the Co2%&nbsp; concentration selected. Because FGC#2 was volunteer stopped by CCR.</p><p><br></p><p>As a plan, FGC#2 would start 2 times with a high Co2 concentration (29.82) and the last with a low concentration (23.26% mode), Which expected a successful startup in the 3rd with the low Co2.&nbsp;</p><p>Its a result, 1st and 2nd startups were failures as per the assumption (T455 high coolstop). But the 3rd was still trip by the same alarm. We assume that the engine could be too hot for restarting, it would be recommended to cool down.</p><p>According to the air intake of the package was too dirty inside, then it was rectified by the mechanic team.</p><p><br></p><p>18:45_Then FGC#2 could be started up successfully once with cooled start-up.</p><p><br></p><p><br></p><p>&nbsp; &nbsp;<br></p><p><br></p><p><br></p><p><br></p><p><br></p>', NULL, '2024-06-01 16:02:08', '2024-06-02 09:56:39', 'PTTEP\TawatchaiP', 'PTTEP\TawatchaiP', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PP-A2210.PK', 'ART-PP-A2210.PK', 'APP FEED GAS COMPRESSOR TRAIN 2 PACKAGE', NULL, NULL, 'APP FEED GAS COMPRESSOR TRAIN 2 PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-UCP-PP-2210', 'ART-UCP-PP-2210', 'FEED GAS COMPRESSION TRAIN 2 CTRL PANEL', NULL, NULL, 'FEED GAS COMPRESSION TRAIN 2 CTRL PANEL', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

