  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Monthly backup database DCS, SIS system', 'Automation', 'OTH', 'Completed', '2024-06-01', '<p>Monthly backup database DCS, SIS system.</p><p>DCS System: </p><p>Backup Project.</p><p>Backup long term trend and meassage.</p><p>Backup tuning parameters: FCS0102 CPU idle time 7-8sec, tuning parameter take resource cps about 3-4sec. So, If perform back up tuning parameter on FCS0102 the cpu idle time view reduce to 3-4 sec it may cause unexpected shutdown from cpu not response. The cpu idle time should more than 5 sec.</p><p>Note: Tuning parameter for FCS0102 will perform during FSD period.</p><p>SIS System: </p><p>-Backup Project.</p><p>-Backup SOE.</p><p>-Clear disk cache by using message cache tool.</p>', NULL, '2024-06-01 16:02:14', '2024-06-01 20:29:14', 'PTTEP\Art.Automation', 'PTTEP\Art.Automation', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-QP-PCS.ASY', 'ART-QP-PCS.ASY', 'AQP PROCESS CONTROL ASSEMBLY', NULL, NULL, 'AQP PROCESS CONTROL ASSEMBLY', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
