-- Inserting report ID 13645
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot B-8910B pulley worn out.', 'Mechanic', 'CM', 'Under Monitoring', '2024-06-01', '<p><b>Description: Sewage blower unit B-8910B found pulley and shaft worn out.</b></p><p>Root cause : high belt tension, Maintenance error&nbsp;</p><p><br></p><p><b><u>Working steps</u></b></p><p>-Performed electrical isolation.</p><p>-<i><b>Found Blower pulley inside circumference worn out, Shaft worn out, Key damaged.</b></i></p><p><br></p><p>-Fabricated <b>the new key</b> at local shop.</p><p>-Installed <b>the new pulley and key</b> into the shaft.&nbsp;</p><p>-Checked the pulley if any clearance with the shaft.</p><p>-Locked the pulley with lock screw.</p><p>-<b>Changed the motor pulley as the same size as the blower pulley.</b></p><p><b>-Installed the new belts (2EA).</b></p><p>-Adjusted the pulley alignment and belt tension.</p><p>-Performed electrical de-isolation.</p><p>-Test run and checked any abnormal condition.</p><p><b>-the unit is under monitoring.</b></p><p><br></p><p><br></p><p><b><u>Required tools and equipment.</u></b></p><p>-Wrench 27, 17, 19, mm</p><p>-Claw Bar, Straight edge, laser alignment.</p><p>-Mallet Hammer, Wooden block</p><p>-Torch light, cotton rags, Oiler.</p>', '-blower pulley shaft was worn out and under monitoring.', '2024-06-01 16:53:06', '2024-11-12 13:29:47', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-SW-B8910B', 'ATL-OC-SW-B8910B', 'Sewage Blower Unit B', NULL, NULL, 'Sewage Blower Unit B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

