  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replaced  TCV901 Lube oil Regulator Temperature.', 'Turbine Mech', 'CM', 'Completed', '2024-06-01', '<div>Replaced&nbsp; TCV901 Lube oil Regulator Temperature.</div><div>- Item 20.70.06.621.3 REGULATOR, TEMP, P/N 120337-25</div><div>- Service bulletin 6-6-106A&nbsp;</div><div>- Old TCV901 Brand :Robertshaw ,Model :1205QS118, Ser:F09B878, Drawing : 120713-19,Temp Set point 120''F/ 49''C</div><div>- New TCV 901 Brand: amot, Model: 120337-25, Ser: A9182011, Temp Set point 120''F/ 49''C</div><div>- Open drain valve 3/4" in package from lube oil pump discharge and lube oil from cooler to TCV port "C" pipe 4"150#&nbsp; to drain pipe 1" out side package.</div><div>- Open vent plug 3/4" at cooler header inlet maniold and vent pipe 3/4" at outlet manifold and apply N2 regulat pressure 2 bar.</div><div>- Drain lube oil from Lube oil cooler inlet and outlet pipe 4"150#&nbsp; approx 50 liters</div><div>- Tighten stud bolts 5/8" nut 1-1/16" torque 70 ft.lb, Flange 4# 150#</div><div>- Top up lube oil PTT TERBIN M32 = 120 Liters Tank level 62.2 cm.</div><div>- Run DC Back up lube oil pump pressure 1.1 bar for fill up lube oil system and leak test and bleed air from filters housing result no leak.</div><div>- Start up SGC#2 observed lube oil temp header stable at 49''C</div>', 'TCV901 Change brand and Model as per Solar Service Bulletin&nbsp;&nbsp;6-6-106A&nbsp;', '2024-06-01 20:09:27', '2024-06-02 22:07:13', 'PTTEP\Art.MechTurbine', 'PTTEP\Art.MechTurbine', false) RETURNING id INTO new_report_id;
