  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, ' Performed Crank soak wash', 'Turbine Mech', 'PM', 'Completed', '2024-05-30', '<p>30/05/24 Perfomed Crank soak wash. Fire hour 16,310 hrs.</p><p>16:47, 1st<sup> </sup>Crank Soak wash by ZOK27 and soaked by 15 mins.</p>  <p>17:07, 2nd Crank soak wash by ZOK27 and soaked by 15 mins.</p>  <p>Rinse by de-ionized water 4 times.</p>  <p>Crank dry 1 time.</p>  <p>Start FGC#2 for fire dry.</p>  <p>21:14, 5th start fail trip by T455 Software Overtemp Coolstop.</p>  <p>22:14, 6th start fail trip by T455 Software Overtemp Coolstop.</p><p>K. Nopharut L. EMI/M recommend E&amp;I to edit gas heat value to matching with arthit gas composition but could not, then he plan to request FSR to visit on board as soon as posible.</p><p>- FGC#2 start up postponed</p><p><br></p>', NULL, '2024-06-02 15:56:01', '2024-06-02 20:48:03', 'PTTEP\Art.MechTurbine', 'PTTEP\Art.MechTurbine', false) RETURNING id INTO new_report_id;
END $$;

