-- Inserting report ID 13703
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S Flow Transmitter B on Metering Tube 3', 'Electrical & Instrument', 'CM ', 'In Progress', '2024-06-02', '<p>Troubleshooting Flow Transmitter B (FIT-84252B) on Metering Tube 3.(New Flow Transmitter reading value is not stable,slightly change)</p><p><br></p><p>Check the leak point of the five way valves of the Flow Transmitter.<br></p><p>Check the leak point of swagelok connection of the low side and high side of the fittings at the Flow Transmitter and proper tighten the all swagelok connections.</p><p>Finally, found the vent valve of the flow transmitter has gas leak and re tighten the connection.</p><p>Under Monitoring.</p><p><br></p><p><u style="background-color: rgb(255, 255, 0);">History</u></p><p><u style="background-color: rgb(255, 255, 0);">1st June 2024</u></p><p><span style="background-color: rgb(255, 255, 0);">Replace new flow transmitter for FIT-84252B on Metering Tube 3.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Installed new flow transmitter and proper tighten all electrical connection.</span></p><p><span style="background-color: rgb(255, 255, 0);">Calibrate as found value for the flow transmitter.</span></p><p><span style="background-color: rgb(255, 255, 0);">Check leak point of the all swagelok connections at the new flow transmitter including five way valve connections.</span></p><p><span style="background-color: rgb(255, 255, 0);">Under Monitoring</span></p><div><br></div><p><br></p><div><u style="font-size: 14px; background-color: rgb(255, 255, 0);">History</u><br></div><p><u style="background-color: rgb(255, 255, 0);">31th May 2024</u></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshooting Flow Transmitter B (FIT-84252B) on Metering Tube 3.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Swapping Flow Transmitter A&amp;B outing cable from junction box.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Monitoring the flow transmitter reading values with the supply power from Flow A Circuit.<br></span></p><p><span style="background-color: rgb(255, 255, 0);">Found the new flow transmitter also malfunction because Flow Transmitter A reading is stable even though the power supply circuit from Flow B Circuit.</span></p><p><span style="background-color: rgb(255, 255, 0);">Under Monitoring.</span></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);">History</u></p><p><u style="background-color: rgb(255, 255, 0);">30th May 2024</u></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshooting Flow Transmitter B (FIT-84252B) on Metering Tube 3.</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked the internal control wiring of the flow transmitter.</span></p><p><span style="background-color: rgb(255, 255, 0);">Cleaning and servicing two equalising valves.</span></p><p><span style="background-color: rgb(255, 255, 0);">Tighten all electrical wiring concern with flow transmitter B.</span></p><p><span style="background-color: rgb(255, 255, 0);">Calibrate as found value and the calibration result pass after re calibration completed.</span></p><p><span style="background-color: rgb(255, 255, 0);">Under Monitoring.</span></p>', NULL, '2024-06-02 17:09:33', '2024-06-07 14:40:26', 'PTTEP\ZMS.MTN-Tech', 'PTTEP\ZMS.MTN-Tech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-FST-84251', 'ATL-MS-FST-84251', 'Metering Tube for metering M-8425 Run-C', NULL, NULL, 'Metering Tube for metering M-8425 Run-C', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
