-- Inserting report ID 13717
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'To perform 6MPM.', 'Mechanic', 'CM', 'Completed', '2024-06-02', '<p align="left">&nbsp; &nbsp;<b><u>Task list and Activities<br></u></b></p><p align="left"><b>Anti-Scalant Pump (2P-4856) and <br> pH adjustment Pump (2P-4855)</b></p><p align="left"><b><u>&nbsp;</u></b></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replace lube oil gearbox with MOBIL SHC 630, <br> 0.5 liter for:&nbsp; &nbsp;2P-4855 pH adjuster pump.</p><p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2P-4856 Anti- scale pump.<u></u></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replace oil at diaphragm housing pump with TOTAL Azolla ZS 10, 0.5 liter for:</p><p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2P-4855 pH adjuster pump.</p><p align="left">            </p><p align="left">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2P-4856 Anti- scale pump.<br><br></p><p align="left"><b>Cleaning (flush) Pump (2P-4847)</b> <b><u></u></b></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; General visual check on the holding down bolt for corrosion.</p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Tightening and driving coupling check.<br></p><p align="left">v&nbsp; <b>Membrane Feed pump (2P-4844)</b></p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Visual check pump coupling condition.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Suction/Discharge piping connection joints.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Pump’s motor mounting bolts.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;Last running performance:</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Discharge pressure=43 bars.<br></p><p align="left">&nbsp;<b><u>Filters</u></b></p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove and clean the filter nozzles.</p><p align="left">&nbsp;2 multi-media filters, 2F-4840A/B.</p><p>      </p><p align="left">&nbsp;2 Carbon filters, 2F-4841A/B.<br></p><p align="left"><u>Unit running and back in service</u></p><p align="left">  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; The unit running condition and all parameters are in&nbsp;<br></p><p align="left">          <br></p><p align="left">    <br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><br><u></u></p>', NULL, '2024-06-02 18:26:22', CURRENT_TIMESTAMP, 'PTTEP\GBS.Mechanic-WorkS', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-4850.PK', 'GBS-2X-4850.PK', 'WATER MAKER PACKAGE TRAIN B', NULL, NULL, 'WATER MAKER PACKAGE TRAIN B', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
