  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '6M PM Lube oil Cooler fan FGC#1', 'Turbine Mech', 'PM', 'Completed', '2024-06-02', '<div>&nbsp;6M PM Lube oil cooler fan BM-1240 BM-1245</div><div>- Found BM-1240 BM-1245 Lube oil cooler fan belts were strange noise..</div><div>- Checked belts tension found belt tension lower than specify.</div><div>- Removed fan belts both unit and cleaning pulley.&nbsp;</div><div>- Pulley alignment checked.</div><div>- Replace fan belts with new spare part 2 ea , belt tension adjusted 1959 Newton, New belt spec 1876 Newton.</div><div>- Test run cooler fan vy command start ans staop cooler fan at HMI in LER found normal both unit.</div><div><br></div><div><p><b>Feed Gas Compressor</b></p>  <p>Belt type: 3VX</p>  <p>Small pulley diameter: 180 mm.</p>  <p>Speed range: 1470 RPM/min</p>  <p>Span length (m): 0.450 m</p>  <p>Mass single belt: 0.102 kg/m X 4 belt in band = 0.408 kg/m</p>  <p>Belt tension: 1,876 Newton (new belt)</p>  <p>&nbsp;</p>  <p>Tools:&nbsp; </p>  <p>-&nbsp; &nbsp;Wrench 1-1/4” = 2ea, 9/16” = 2ea, 1/2” = 2ea</p>  <p>-&nbsp; &nbsp;Common tools</p>  <p>-&nbsp; &nbsp;Grease gun / Grease EP2</p>  <p>-&nbsp; &nbsp; SKF belt tension / SKF Laser alignment&nbsp;&nbsp;</p></div><div><br></div><div>Spare part :&nbsp;58.14.09.091.9 V-BELT,DRIVE, IMPERIAL,4RVX-900 = 2 EA.</div>', '<p>Fire hour 25,473 Hrs</p><p><br></p>', '2024-06-03 08:58:34', CURRENT_TIMESTAMP, 'PTTEP\Art.MechTurbine', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-BM-1240', 'ART-BM-1240', 'MOTOR,ELECTRICAL,LUBE OIL COOLER FAN', NULL, NULL, 'MOTOR,ELECTRICAL,LUBE OIL COOLER FAN', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-BM-1245', 'ART-BM-1245', 'MOTOR,ELECTRICAL,LUBE OIL COOLER FAN', NULL, NULL, 'MOTOR,ELECTRICAL,LUBE OIL COOLER FAN', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
