-- Inserting report ID 13741
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S T455 TC-1 High spread Alarm, then sensor Repla', 'Turbine E&I', 'CM', 'Completed', '2024-06-03', '<p>The FGC#2 was volunteer stopped because the T455 T/C-1 was swing reading while the unit running._02 June 24. During the unit standing down, its ATM''s reading of T/C-1 was normal.</p><p>- Anyway, We replaced it with the new sensor and confirmed ATM''s reading with UCP and CCR. It was reading normally.</p><p>- Also verified reading to be confirmed once the FGC#2 start up.</p><p><br></p><p>For alarm "T455 T/C 1 high spread alarm" came at 16:33 0n 02 Jun 2024)</p><p><br></p><p>T/C-1 Wiring connection ( JB "A" By R-R on RB211 24G)</p><p>&nbsp; 26GG455-01C : 1/2, = ATM reading mv = 17.1 (new sensor reading, But the removed mv almost same)</p><p>&nbsp; 26GG455-01B :&nbsp; 3/4 = ATM reading mv = 17.4.</p><p>&nbsp; 26GG455-01A :&nbsp; 5/6 = ATM reading mv = 17.3</p><p>&nbsp;&nbsp;</p><p>Sensor Detail :&nbsp;</p><p>&nbsp; - New replacement sensor: Item : MESC: 20.58.39.661.3 Thermocouple T44(K TYPE) TRIPLE LW17607_ item 753-10-33, SN: 13389.</p><p>&nbsp; - The removed sensor SN: 9952</p><p><br></p><p>Tools required&nbsp;</p><p>Combination wrench : 1/4, 8 mm, 5/8</p><p>Block wrench: 5/8, 4mm</p><p>Lubricant: liquid wrench, high-temperature grease.</p><p><br></p><p><br></p>', NULL, '2024-06-03 16:42:31', '2024-06-03 17:04:00', 'PTTEP\TawatchaiP', 'PTTEP\TawatchaiP', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PP-A2210.PK', 'ART-PP-A2210.PK', 'APP FEED GAS COMPRESSOR TRAIN 2 PACKAGE', NULL, NULL, 'APP FEED GAS COMPRESSOR TRAIN 2 PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-C-2210-INSTR', 'ART-C-2210-INSTR', 'FEED GAS COMPRESSOR INSTRUMENTATION', NULL, NULL, 'FEED GAS COMPRESSOR INSTRUMENTATION', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
