  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify clamp-on Sand Probe Monitoring', 'Instrument', 'CM', 'Completed', '2024-06-06', '<p>Verified clamp-on sand probe monitoring that removed from WPS-02</p><p>Clamp-on serial no.12925</p><p>- Open top cover to verified terminal and wiring and found it have bad smell like electronic devices short circuit came out.&nbsp;</p><p>- Measured power supply terminal resistance and found it was 4.209 Mega-Ohm reference with the good one power supply resistance was around 27.86 K-Ohm. Suspected electronics circuit was short circuit.</p><p>- Measured power RS-485 terminal resistance and found it was 2.315 K-Ohm.</p><p><br></p><p>Functional test clamp-on sand probe spare part that operation team send to verify by connect clamp-on software and brushing test as detail below,</p><p>- Clamp-on serial no.11244 and 10291 are working properly.</p><p>- Clamp-on serial no.10164, 10408 and 14325 couldn''t connect via software and suspected there''re malfunction.</p><p>- Clamp-on serial no.22500 (New clamp-on) couldn''t connect via software and it should be test by mobile logger station for function test again.</p><p><br></p>', NULL, '2024-06-06 14:33:38', CURRENT_TIMESTAMP, 'PTTEP\GBS.EI-Workshop', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-WELL-WP02', 'GBS-WELL-WP02', 'GBS WP02', NULL, NULL, 'GBS WP02', 'GBS-WP02', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

