  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S 2X-5210A Electrochlorination flow low tripped.', 'Electrical', 'CM', 'Completed', '2024-06-06', '<div class="ewa-rteLine">T/S 2X-5210A Electrochlorination flow low tripped. </div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">- Today, re-installed bookcell tubes completed.</div><div class="ewa-rteLine">- Perform leak test, the result is no leaks.</div><div class="ewa-rteLine">- Closed bookcell cover and function test found the bookcell voltage = 45 V. and current = 48 A.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">Now unit is working properly and keep monitoring.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">For pictures of cleaning activity, see in folder location as below.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">G:\GBSShare\Department Share\03 Maintenance\032 DBS_MEI\087 E&amp;I Pictures\1. PPS\Electrical\ELECTROCORONATION\Electrochlorination bookcell bank A cleaning during 4-6 June 2014<br></div>', NULL, '2024-06-06 18:14:01', '2024-06-08 10:18:50', 'PTTEP\GBS.EI-Workshop', 'PTTEP\GBS.EI-Workshop', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-5210.PK', 'GBS-2X-5210.PK', 'ELECTROCHLORINATION PACKAGE', NULL, NULL, 'ELECTROCHLORINATION PACKAGE', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
