BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'WP20 : Verify ESD signal (hardwire) to BC', 'Instrument', 'CM', 'In Progress', '2024-06-08', '<p>&nbsp;Verify ESD signal (hardwire) to Booster Compressor.</p><p>- Bypass signal of TB1-161/162 at BC package for clear ESD signal (hardwire), Relay R212 active and BC package status ready to start.</p><p>- Check voltage at TB1-161/162&nbsp; = 24 Vdc.&nbsp;</p><p>- Force signal at PLC of Rack:4, <a href="Card:8,">Card:8,</a>&nbsp;<a href="Point:1">Point:1</a>&nbsp;for clear ESD signal (hardwire) but BC package still alarm ESD signal (hardwire)</p><p>- Check wiring and voltage form DO card to STB4050-15/16.</p><p>- Not found wiring to STD011-15/16.</p><p>- Found PLC show code error "1412", Suspected DO card damage due to led status at DO card no bright.<br></p>', NULL, '2024-06-08 20:05:14', '2024-06-09 08:27:40', 'PTTEP\Bongkot.Inst-Lead', 'PTTEP\Bongkot.Inst-Lead', false) RETURNING id INTO new_report_id;
