-- Inserting report ID 13968
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S and PM in Online Sand Probe Monitoring WP03.', 'Instrument', 'PM', 'Completed', '2024-06-08', '<div class="ewa-rteLine">Troubleshooting and PM in Online Sand Probe Monitoring WP03.</div><div class="ewa-rteLine">- According to&nbsp; device couldn''t be online monitor from sand monitoring server and found EDW-100 onsite was loss of power supply.</div><div class="ewa-rteLine">- Found circuit breaker no.Q15 inside PLC cabinet 2SC-1301 was in turn-off status then turn on it and device was back to online as normal.</div><div class="ewa-rteLine">- Perform visual inspection and cleaning device.</div><div class="ewa-rteLine">- Connect laptop to EDW-100 ( Serial to ethernet converter) found signal from online Sand Probe Monitoring was reading as normal.</div><div class="ewa-rteLine">- Functional test by brushing test and monitor signal value, It s worked as normal. </div>', NULL, '2024-06-08 20:58:32', CURRENT_TIMESTAMP, 'PTTEP\GBS.EI-Workshop', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-WELL-WP03', 'GBS-WELL-WP03', 'GBS WP03', NULL, NULL, 'GBS WP03', 'GBS-WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

