  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S 2XV-13004K Valve fault alarm.', 'Instrument', 'CM', 'Completed', '2024-06-08', '<div class="ewa-rteLine">T/S 2XV-13004K Valve shown status fault alarm during route well out of test separator.</div><div class="ewa-rteLine">- Perform stroking test valve and found it can travelling smoothly.</div><div class="ewa-rteLine">- Measured voltage drop at proximity magnetic switch at close position and found it was around 1.035 VDC</div><div class="ewa-rteLine">- Measured resistance of proximity magnetic switch and found it was around 1 K-ohm</div><div class="ewa-rteLine">- Replaced by new spare and function tested.</div>', NULL, '2024-06-08 21:05:57', CURRENT_TIMESTAMP, 'PTTEP\GBS.EI-Workshop', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-WELL-WP03-K', 'GBS-WELL-WP03-K', 'GBS WP03 K', NULL, NULL, 'GBS WP03 K', 'GBS-WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
