BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'To perform 6MPM 2A-3240D ', 'Mechanic', 'PM', 'Completed', '2024-06-10', '<b><u>1. System status</u></b><br><div>1.1 Local switch is in off mode and tagging.</div><div>1.2 Main circuit breaker isolated and lockout-tag out.<br><br><b><u>2. Driving motor;<br></u></b><div>2.1 Check foundation holding down bolts and tightening.</div><div>2.2 Apply grease on electrical driving motor both end DE/NDE.&nbsp;<br><br><u><b>3. Driving belt and pulley/sprocket;<br></b></u><div>3.1 General visual inspection of belt condition.</div><div>3.2 Check driven pulley/sprocket condition.</div><div>3.3 check lock hub and re-tightening.<br></div><div>3.4 Check belt tensioning.<br></div><div>3.6 Check protection guard condition and clean.<br></div><div>3.5 Check belt alignment.<br><br><u><b>4. Cooler fan shaft &amp; bearing;<br></b></u><div>4.1 Retighten bolts and check cooler fan shaft &amp; bearing top and bottom</div><div>4.2 Re-grease cooler fan shaft bearing top and bottom.<br><br><u><b>5. Fan blades;<br></b></u><div>5.1 Cooler fan blades inspection for crack &amp; damage.</div><div>5.2 Check blades clearance between blade edge and casing (plenum<br></div><div>5.3 Measure blades angle.&nbsp;<br></div><div>5.4 Fan hub and hub tube checking.<br></div><div>5.5 Air seal plate and mounting inspection and cleaning.<br>5.6 Clean fan blades.<br><br><u><b>6. Bearing-Top and Bottom (Vibration);</b></u><br>6.1 Check bearing top and bottom vibration sensor condition.<br></div></div></div></div></div>', NULL, '2024-06-10 17:07:11', CURRENT_TIMESTAMP, 'PTTEP\GBS.Mechanic-WorkS', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2A-3240A', 'GBS-2A-3240A', 'BC DISCHARGE COOLER FAN A', NULL, NULL, 'BC DISCHARGE COOLER FAN A', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

