  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2A-3240F', 'GBS-2A-3240F', 'BC DISCHARGE COOLER FAN F', NULL, NULL, 'BC DISCHARGE COOLER FAN F', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

