-- Inserting report ID 14035
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TG1 2MOV-551232 fuel gas metering valve', 'Instrument', 'CM', 'Completed', '2024-06-10', '<div class="ewa-rteLine">''TG1 2MOV-551232 fuel gas metering valve (PECC) replacement. </div><div class="ewa-rteLine">- Performed replaced 2MOV-551232 by new spare and re-install wiring completed.</div><div class="ewa-rteLine">- Pressure tested at 30 Bar at inlet side found satisfy no passing. </div><div class="ewa-rteLine">- Apply tighten with torque 75 N.m as per manual.</div><div class="ewa-rteLine">- Stroking test found working properly.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"> </div><div class="ewa-rteLine"><p>We have replaced the PECC Valve Gen 6 SN: 112343 on TG#1 and adjusted the parameter KT_Bleed_Vlv_1s_Trigger.Val to -3 (Normal operation) to address the bleed valve issue.</p>  <p>Unfortunately, the bleed valve issue remained during on-load control. We have now reverted the KT_Bleed_Vlv_1s_Trigger.Val parameter back to -5, which has resolved the problem, and TG#1 is running normally and remains on duty.</p>  <p>We plan to use the removed PECC Valve Gen 6 (old version from TG#1) for TG#3 replacement.</p></div>', NULL, '2024-06-10 18:57:16', CURRENT_TIMESTAMP, 'PTTEP\GBS.Turbine-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2TG-5510', 'GBS-2TG-5510', 'GAS TURBINE GENERATOR SOLAR TAURUS 70', NULL, NULL, 'GAS TURBINE GENERATOR SOLAR TAURUS 70', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

