  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S 2GDU-32401 IO Fault alarm.', 'Instrument', 'CM', 'Completed', '2024-06-10', '<div class="ewa-rteLine">T/S 2GDU-32401 IO Fault alarm.</div><div class="ewa-rteLine"> - Replace new GDU (Brand :GM Observier i) instead of old GDU fault (Brand :Detronic)</div><div class="ewa-rteLine">- Installed new device support that fabricate by construction team.</div><div class="ewa-rteLine">- Online edit Triconex PLC logic to change engineering range (EUmin/max) from 58-104 dB to 40-120 dB by automation team.</div><div class="ewa-rteLine">- Reconfiguration device HART to Disable mode (HTOF).(Acoustic Error =1 mA )</div><div class="ewa-rteLine">- Reconfiguration device&nbsp;Enhance Mode to Off&nbsp; in order to setting gas detector in classic mode (ENOF).(4 - 20mA for 40 to 120dB)</div><p>-Functional step test with Gassonic observer simulation from 50 dB to 100 db found the gas detector was still accurate no need to recalibrate.</p><p>-Simulated @ 64 dB and found the alarm was activated.</p><div class="ewa-rteLine">- Function test, working properly.</div><div class="ewa-rteLine"><br></div>', NULL, '2024-06-11 07:02:03', CURRENT_TIMESTAMP, 'PTTEP\GBS.EI-Workshop', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2GDU-32401', 'GBS-2GDU-32401', 'ACOUSTIC GAS DETECTOR', NULL, NULL, 'ACOUSTIC GAS DETECTOR', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

