-- Inserting report ID 14091
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'To perform 6MPM', 'Mechanic', 'PM', 'Completed', '2024-06-12', '<p><u>1. System status</u></p><p>1.1 Local switch is in off mode and tagging.</p><p>1.2 Main circuit breaker isolated and lockout-tag out.<br><br><u>2. Driving motor;</u></p><p>2.1 Check foundation holding down bolts and tightening.</p><p>2.2 Apply grease on electrical driving motor both end DE/NDE.&nbsp;<br><br><u>3. Driving belt and pulley/sprocket;</u></p><p>3.1 General visual inspection of belt condition.</p><p>3.2 Check driven pulley/sprocket condition.</p><p>3.3 Check lock hub and re-tightening.</p><p>3.4 Check and adjust belt tensioning.</p><p>3.6 Check protection guard condition and clean.</p><p>3.5 Check belt alignment.<br><br><u>4. Cooler fan shaft &amp; bearing;</u></p><p>4.1 Retighten bolts and check cooler fan shaft &amp; bearing top and bottom</p><p>4.2 Re-grease cooler fan shaft bearing top and bottom.<br><br><u>5. Fan blades;</u></p><p>5.1 Cooler fan blades inspection for crack &amp; damage.</p><p>5.2 Check blades clearance between blade edge and casing (plenum</p><p>5.3 Measure blades angle.&nbsp;</p><p>5.4 Fan hub and hub tube checking.</p><p>5.5 Air seal plate and mounting inspection and cleaning.<br>5.6 Clean fan blades.<br><br><u>6. Bearing-Top and Bottom (Vibration);</u><br>6.1 Check bearing top and bottom vibration sensor condition.</p>', NULL, '2024-06-12 18:42:31', CURRENT_TIMESTAMP, 'PTTEP\GBS.Mechanic-WorkS', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2A-3340C', 'GBS-2A-3340C', 'BC DISCHARGE COOLER FAN C', NULL, NULL, 'BC DISCHARGE COOLER FAN C', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
