-- Inserting report ID 14109
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Performed 12MPM gas generator G-8925.', 'Electrical & Instrument', 'PM', 'In Progress', '2024-06-13', '<p><u>Today Activity</u></p><p>Performed 12MPM G-8925.</p><p><br></p><p><u>Action</u></p><p>- Checked and tightening all the wiring connection inside switch gear room.</p><p>- Checked and tightening all the wiring connection at the generator container.</p><p>- Checked battery water level.</p><p>- Measured insulation resistance and resistance value of ventilation fan motor 1&amp;2.</p><p>- Measured insulation resistance and resistance value of space heater at switch gear.</p><p><br></p><p><br></p><p><br></p><p><u>History (11.06.2024)</u></p><p>- Performed 12MPM gas generator G-8925.</p><p><br></p><p><u>Action</u></p><p>- Performed G-8925 total electrical isolation.</p><p>- Measured / recorded insulation resistance value and resistance value of radiator fan motor No.1&amp;No.2.</p><p>- Applied grease to both fan motor bearing.</p><p>- Found Radiator fan motor No.1 winding coil insulation damage. (Applied rubber splicing scotch tape)</p><p>- Disconnected power cable form stator winding.</p><p>- Measured / recorded insulation resistance value and resistance value of stator winding.</p><p>- Measured / recorded insulation resistance value and resistance value of anti-condensation heater.</p><p>- Measured / recorded insulation resistance value and resistance value of Exciter winding (PMG)</p>', NULL, '2024-06-13 14:23:12', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Inst-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8925-PACK', 'ATL-OC-G-8925-PACK', 'Gen, ZOC Gas Generator Package2', NULL, NULL, 'Gen, ZOC Gas Generator Package2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 14110
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S FGC#2 T455 software overtemp cooldown stop', 'Turbine Mech', 'CM', 'Completed', '2024-06-13', '<div>04 June 2024&nbsp;</div><div>T/S FGC#2 T455 software overtemp with Siemens Vendor support.</div><div>- Function tested 20GGBV Bleed valve solenoid and check leak of bleed valve tubing found normal condition.</div><div>- Then Vendor decided to reduce Gas Fuel Flow Rate from 160 to 120 as suspected engine rich condition (too much fuel).</div><div>- Performed 1st starting test successfully with CO2 29% mode then normal stop and re-started normally.</div><div>- To continue verify data and test other conditions.</div><div><br></div><div><div>05 June 2024</div><div>Troubleshoot FGC Train2 Trip by T455 Software overtemp cool stop by Siemen FSR.</div><div>- Changed fuel gas composition by refer OGC monthly average in May 2024.</div><div>- Knife switch select at CO2 23%</div><div>- Start testing by Change Gas start fuel flow rate from ignition to idle as step below.</div><div>- 1st start by fuel flow rate 120 kW/S @ CO2 22.43%, Start success.</div><div>- 2nd start by fuel flow rate 160 kW/S @ CO2 22.43%, Start success.</div><div>- 3rd start by fuel flow rate 170 kW/S @ CO2 22.43%, Start success.</div><div>- Final set fuel flow rate 140 kW/S @ CO2 22.43% for opearation.</div><div><br></div><div>( Margin fuel flow rate can adjust 120 - 170 kW/S Refer vendor recomendation)</div></div>', NULL, '2024-06-13 14:30:15', CURRENT_TIMESTAMP, 'PTTEP\Art.MechTurbine', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-C-2210', 'ART-C-2210', 'FEED COMPRESSOR TRAIN 2', NULL, NULL, 'FEED COMPRESSOR TRAIN 2', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

