  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshoot Gas Generator G-9115', 'Electrical & Instrument', 'CM ', 'Under Monitoring', '2024-06-14', '<p>Troubleshooting Gas Generator G-9115 trip by Hi Lube Oil Temperature Alarm during 72 hr test run.</p><ul class="BulletListStyle1 SCXW198301530 BCX0" role="list"><li data-leveltext="-" data-font="Arial" data-listid="2" data-list-defn-props="{&quot;335552541&quot;:1,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Arial&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;-&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="54" data-aria-level="1" role="listitem" class="OutlineElement Ltr SCXW198301530 BCX0"><p class="Paragraph SCXW198301530 BCX0" xml:lang="EN-US" lang="EN-US" paraid="147222495" paraeid="{08e3ce72-c72e-46df-bb5a-0f885ba1d84b}{254}">Verity S/D by high lube oil temperature on gas generator G-9115</p></li><li data-leveltext="?" data-font="Symbol" data-listid="2" data-list-defn-props="{&quot;335551671&quot;:0,&quot;335552541&quot;:1,&quot;335559685&quot;:1440,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Symbol&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;?&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="0" data-aria-level="2" role="listitem" class="OutlineElement Ltr SCXW198301530 BCX0"><p class="Paragraph SCXW198301530 BCX0" xml:lang="EN-US" lang="EN-US" paraid="1840631992" paraeid="{177a75b5-fbe6-4fd5-9c4f-3581ed80f67f}{155}">Swap lube oil temp sensor from G-9110.&nbsp;</p></li><li data-leveltext="?" data-font="Symbol" data-listid="2" data-list-defn-props="{&quot;335551671&quot;:0,&quot;335552541&quot;:1,&quot;335559685&quot;:1440,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Symbol&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;?&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}" aria-setsize="-1" data-aria-posinset="0" data-aria-level="2" role="listitem" class="OutlineElement Ltr SCXW198301530 BCX0"><p class="Paragraph SCXW198301530 BCX0" xml:lang="EN-US" lang="EN-US" paraid="1155766183" paraeid="{cc2cb9e4-1439-4d3b-900a-23c5c814a10b}{223}">Change the float switch of radiator &nbsp;</p><p class="Paragraph SCXW198301530 BCX0" xml:lang="EN-US" lang="EN-US" paraid="1155766183" paraeid="{cc2cb9e4-1439-4d3b-900a-23c5c814a10b}{223}">Test run Gas Generator G-9115 with full load about 60 min only after troubleshooting.</p><p class="Paragraph SCXW198301530 BCX0" xml:lang="EN-US" lang="EN-US" paraid="1155766183" paraeid="{cc2cb9e4-1439-4d3b-900a-23c5c814a10b}{223}">Under Monitoring.</p></li></ul>', NULL, '2024-06-14 19:01:01', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9115-PACKAGE', 'ATL-MS-G-9115-PACKAGE', 'Gen, ZMS Gas Generator package2', NULL, NULL, 'Gen, ZMS Gas Generator package2', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
