  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Performed 12MPM G-8925.', 'Electrical & Instrument', 'PM', 'Completed', '2024-06-13', '<p><u>Today Activity</u></p><p>Performed 12MPM G-8925.<u><br></u></p><p><u><br></u></p><p><u>Action</u></p><p>- Measured frame ground to earth for loop resistance.</p><p>- Measured instrument ground to earth for loop resistance.</p><p>- Measured power ground to earth for loop resistance.</p><p>- Test run generator and recorded all the parameter.</p><p><br></p><p><u>History (12.06.2024)</u></p><p>Performed 12MPM G-8925.</p><p><br></p><p><u>Action</u></p><p>- Checked and tightening all the wiring connection inside switch gear room.</p><p>- Checked and tightening all the wiring connection at the generator container.</p><p>- Checked battery water level.</p><p>- Measured insulation resistance and resistance value of ventilation fan motor 1&amp;2.</p><p>- Measured insulation resistance and resistance value of space heater at switch gear.</p><p><br></p><p><br></p><p><br></p><p><u>History (11.06.2024)</u></p><p>- Performed 12MPM gas generator G-8925.</p><p><br></p><p><u>Action</u></p><p>- Performed G-8925 total electrical isolation.</p><p>- Measured / recorded insulation resistance value and resistance value of radiator fan motor No.1&amp;No.2.</p><p>- Applied grease to both fan motor bearing.</p><p>- Found Radiator fan motor No.1 winding coil insulation damage. (Applied rubber splicing scotch tape)</p><p>- Disconnected power cable form stator winding.</p><p>- Measured / recorded insulation resistance value and resistance value of stator winding.</p><p>- Measured / recorded insulation resistance value and resistance value of anti-condensation heater.</p><p>- Measured / recorded insulation resistance value and resistance value of Exciter winding (PMG)</p>', NULL, '2024-06-15 09:13:01', '2024-06-15 09:13:31', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Inst-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8925-PACK', 'ATL-OC-G-8925-PACK', 'Gen, ZOC Gas Generator Package2', NULL, NULL, 'Gen, ZOC Gas Generator Package2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
