  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'WPS-11 1YPM ESD 1&2 FUNCTION TEST', 'Instrument', 'CM', 'Completed', '2024-06-15', '<p><b>WPS-11 1YPM ESD 1&amp;2 FUNCTION TEST</b></p><p>- Performed function test ESD 1&amp;2 follows procedure with CCR and PM PLC system</p><p>- Cleaned and put new silica gel in all RIO Cabinet</p><p>- Check and tighten terminal.</p><p>- Performed ESD Valve stroking test , 2ESDV-21211 : closing time =29 sec&nbsp; open time = 35 sec</p><p>- Performed ESD Hand switch contact resistance checking and tightening.</p><p>- Found 2ZSL-21D03 limit switch fault. replaced new limit switch.</p><p>- TEG 2G-2195D replaced new ignition board.</p><p>- TEG 2G-2195A/B Unit Minimize and isolate fuel gas supply for stand by</p><p>- TEG onload testing is not perform because the current is lower than the load of the platform</p>', NULL, '2024-06-15 19:51:02', CURRENT_TIMESTAMP, 'PTTEP\LueW', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2WHCP-2181.PK', 'GBS-2WHCP-2181.PK', 'WELLHEAD CONTROL PANEL WPS11', NULL, NULL, 'WELLHEAD CONTROL PANEL WPS11', 'GBS-WP11', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

