  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-PP-CRS-CESD-UCP-FGRU', 'GBS-PP-CRS-CESD-UCP-FGRU', 'FLASH GAS COMPRESSOR UNIT CONTROL PANEL', NULL, NULL, 'FLASH GAS COMPRESSOR UNIT CONTROL PANEL', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
