-- Inserting report ID 14495
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform water wash Turbo compressor#1', 'Mechanic', 'PM', 'Completed', '2024-06-18', '<p class="Default">- Unit must be shut down for cooling down at least 8 hours or engine case temperature must less than 200 F (93.3 C).</p><p class="Default">- Mobile tank cleaning skid with mixed Distillated water and chemical ZOK27 in ratio 4:1 (Distillated water 100 liters and 25 liters of ZOK27 chemical).</p>  <p class="Default">- Connect electric power supply.</p>  <p class="Default">- On power heater 23TW-2 for heat up wash solution between (150 F) 65 C – (180 F) 80 C.</p><p class="Default">- Connect the quick coupling hose on offline water-wash manifold</p>  <p class="Default">- Water mist system to be inhibited before open enclosure door, P2 / P3 transmitters must be disconnected to prevent liquid go inside</p>  <p class="Default">-&nbsp; Open all 5 drain valves </p>  <p class="Default">1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Open inlet plenum drain valve TP448. </p>  <p class="Default">2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Compressor 9th stage bleeds manifold drain TP453. </p>  <p class="Default">3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Power turbine casing drain 3 points TP449 A/B/C. </p>  <p class="Default">4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Exhaust plenum drain valve</p>  <p class="Default"><b>On-crank pre-cleaning </b></p>  <p class="Default">- Open the manual isolation valve on washing water trolley.</p>  <p class="Default">- Turn off power heater.</p><p class="Default">- Inform Turbine Instrument Technician to start crank engine.</p>  <p class="Default">- Turbine off line water wash sequence initiated, Start auxiliaries, Mineral lube oil pump start.</p>  <p class="Default">- Accelerating the gas turbine 1200rpm, initiated flow of wash solution to the water wash manifold.</p>  <p class="Default">- Stop crank and stop water wash pump and wait until engine slow down to 250 RPM and repeat step until wash solution tank empty.</p><p class="Default">- Apply solution the drain water must be collected sample for laboratory.</p>  <p class="Default">- Maintain solution inside engine as soaking component for 30 minutes.</p><p class="Default">- Fill the washing tank with water 400 liters (80% of tank capacity) of water.</p>  <p class="Default">- Accelerating the gas turbine 1200rpm, initiated flow of wash to the water wash manifold.</p><p class="Default">- Stop crank and stop water wash pump and wait until engine slow down to 250 RPM and repeat step until water tank empty.</p>  <p class="Default">- Check Conductivity from Compressor casing drain should be lower than 50 µs/cm2.</p><p class="Default">- Dry crank 10 minutes.</p>  <p class="Default">- Connect all tubes and close 5 drain valves.</p>  <p>- General clean and housekeeping.</p><p>- Perform unit fire dry 10 minutes and stop for 8K PM activity.</p>', 'Running HRS. 99637.3 hr.', '2024-06-18 18:52:35', CURRENT_TIMESTAMP, 'PTTEP\GBS.Mechanic-WorkS', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2UCP-2TG-3200', 'GBS-2UCP-2TG-3200', 'UCP GAS-TURBINE DRIVER', NULL, NULL, 'UCP GAS-TURBINE DRIVER', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

