-- Inserting report ID 14585
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replace sump tank pump.', 'Mechanic', 'CM', 'Completed', '2024-06-18', '<p>- Disconnect air drive, suction and discharge lines.</p><p>- Remove pump.</p><p>- Clean all parts and working area.</p><p>- Install new pump that was overhauled from Mechanical workshop.</p><p>- Request to Process de-isolation and running test.</p><p>- Running test found leakage at Distance piece (No.25 as per drawing), opposite gas drive side.</p><p>- Stop pump and request to Process isolation.</p><p>- Disconnect pump.</p><p>- Overhaul pump by dismantle Distance piece (No.25) found O-ring (No.59 as per drawing) was loosen from O-ring groove.</p><p>- Replace O-ring then reassembly pump.</p><p>- Reconnect pump and tighten union.</p><p>- Request to Process de-isolation then running test.</p><p>- Running test found normal operate, working pressure @ 29 Barg.</p><p>- Clean the working area.</p>', '<p><a href="G:\GBSShare\Department Share\03 Maintenance\031 DBS_MM\6. Picture\65. Remote Equipment Picture\WPS 4\2024\2024.06.18 2P-1445 Replace sump tank pump and fix leaks after running tested">G:\GBSShare\Department Share\03 Maintenance\031 DBS_MM\6. Picture\65. Remote Equipment Picture\WPS 4\2024\2024.06.18 2P-1445 Replace sump tank pump and fix leaks after running tested</a><br></p>', '2024-06-21 07:47:41', '2024-06-21 17:45:40', 'PTTEP\WittayaB', 'PTTEP\GBS.Mechanic-WorkS', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-1445', 'GBS-2P-1445', 'SUMP TANK PUMP', NULL, NULL, 'SUMP TANK PUMP', 'GBS-WP04', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

