  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S 2x-5310B could not be run in Lead/Lag mode.', 'Instrument', 'CM', 'Under Monitoring', '2024-06-21', '<p>T/S 2x-5310B could not be run in Lead/Lag mode.</p><p>Continued troubleshooting after relocating after cooler Auto drain in below details.</p><p>-Removed auto drain solenoid valve to check internal parts condition: found the Diaphragm is still in good condition but the Pilot spool was damage due to long service then replaced it.</p><p>-Checked the check valve along the drain tubing found there is no check valve that equipped in the casing,it was removed before.</p><p>-Simulated the power supply found it is still in good condition,no voltage drop while simlating.</p><p>-Requested Tempo deisolation,process&amp; electrical in order run the air comp and keep monitoring.</p>', NULL, '2024-06-21 17:25:28', '2024-06-21 17:37:15', 'PTTEP\GBS.EI-Workshop', 'PTTEP\GBS.EI-Workshop', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X5310B.PK', 'GBS-2X5310B.PK', 'PPS AIR COMPRESSOR B PACKAGE', NULL, NULL, 'PPS AIR COMPRESSOR B PACKAGE', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

