DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, ' Troubleshooting engine fluctuate speed', 'Mechanic', 'CM', 'In Progress', '2024-06-02', '<p align="left">1.Perform engine fine tuning rpm=1440, both of rich and lean. Found fluctuated still intact.<u></u></p>  <p align="left">2.Carry out &nbsp;valve lash check and re-adjusting.(see as left readings below)</p>  <p align="left">Remove ll fuel injectors, cleaned, inspected(found left bank no, 4 6 8 wet condition)</p>  <p align="left">3.Re-install the existing injectors to the right bank and the reused injectors (from unit B) to the left bank and carry out recession re-adjusting=87.4 mm also synchronize rack setting.</p>  <p align="left">4.Perform piston valves bore scope.(no damaged sign found)</p>  <p align="left">5.Inspect turbo charger condition, tolerance measuring (found No excessive reading found)</p>  <p align="left">6. Re-check and set&nbsp; all valve lash.</p>  <p align="left">7. Install vacuum gauge to both of air filter engine intake in order to monitor how both turbo charger react.</p>  <p align="left">8. Running test base on fuel rack originated setting and governor speed set at 1440 rpm,(previous setting) after 5 min past time or engine reach operating temperature approx.=90 ‘C. found engine speed fluctuated still intact. Then try reducing speed by governor setting to 1430 rpm and keep continuous running for 60 min. Found engine running smoothly than 1440 rpm and no fluctuated speed (As left condition)</p>', NULL, '2024-06-22 07:55:50', '2024-06-22 07:57:15', 'PTTEP\GBS.Maintenance-Supt', 'PTTEP\GBS.Maintenance-Supt', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-5201A', 'GBS-2P-5201A', 'DIESEL FIRE WATER PUMP A', NULL, NULL, 'DIESEL FIRE WATER PUMP A', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
