  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-5310B.PK', 'GBS-2X-5310B.PK', 'PPS AIR COMPRESSOR B PACKAGE', NULL, NULL, 'PPS AIR COMPRESSOR B PACKAGE', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
