-- Inserting report ID 14644
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'PP: Electrical YPM M-3755A Lean Glycol Air Cooler', 'Electrical', 'PM', 'Complete', '2024-06-22', '<p>PP: Electrical YPM M-3755A Lean Glycol Air Cooler</p><p>- Performed function test overload and earth fault.</p><p>- Function tested low volt feeder.</p><p>- Performed insulation test motor with cable, found value more than 550 MOhm.</p><p>- Measure motor resistance.</p><p>&nbsp; &nbsp; - U1/V1 = 2.15 Ohm, V1/W1 = 2.16 Ohm and U1/W1 = 2.16 Ohm.</p><p>- Performed re-tighten cable connection and cleaning motor and feeder.</p><p>- Function tested</p><p>&nbsp; &nbsp; -&nbsp;Starting current = 64.9 A, running current L1 = 7.2A / L2 = 7.2 A / L3 = 7.0 A</p>', '<p><a href="G:\Selective Access\02-PBN-M\02 MEI\19 Photos\00 Electrical Photos\PP\MOTOR\M-3755A\M-3755A YPM on 22-06-24">G:\Selective Access\02-PBN-M\02 MEI\19 Photos\00 Electrical Photos\PP\MOTOR\M-3755A\M-3755A YPM on 22-06-24</a><br></p>', '2024-06-22 16:09:48', '2024-06-22 16:45:12', 'PTTEP\Bongkot.Elec-Lead', 'PTTEP\Bongkot.Elec-Lead', false) RETURNING id INTO new_report_id;
