  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP49-CRS-WCP', 'GBN-WP49-CRS-WCP', 'SUBSYS, WELLHEAD CONTROL PANEL', NULL, NULL, 'SUBSYS, WELLHEAD CONTROL PANEL', 'GBN-WP49', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
