-- Inserting report ID 14754
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2P-5860B To perform Mechanical 6 MPM.', 'Mechanic', 'PM', 'Completed', '2024-06-23', '<p>- Request to Process and Electrical Isolation.</p><p>- Remove min flow check valve (2"150#) to inspection and leak test found normal condition.</p><p>- Remove discharge check valve (3"150#) for inspection and leak test found normal condition.</p><p>- Clean and preserve all parts, re-install check valve both min flow and main discharge check valve including to replace all gaskets and apply JIMs.</p><p>- Visual check mechanical seal for leak found no leakage.</p><p>- Check mechanical seal holding bolts and tightening.</p><p>- Replace bearing lube oil.</p><p>- Remove coupling guard.</p><p>- Visual check coupling condition found normal and re-tight coupling bolts.</p><p>- Perform alignment check found out of spec.</p><p>- Adjust alignment as per spec.</p><p>- Preserve coupling and hub.</p><p>- install coupling guard.</p><p>- Request to Process de-isolation to leak test found no leak.</p><p>- Clean working area.</p><p>- Request to Electrical Isolation and running test found normal condition, suction pressure @ 1.2 Barg and discharge pressure @ 5.4 Barg.</p><p><br></p>', '<p>G:\GBSShare\Department Share\03 Maintenance\031 DBS_MM\6. Picture\61. PPS Equipment Picture\All pumps\2P-5860 Diesel distribution pump\2P-5860B\2024.06.23 2P-5860B perform mechanical 6 MPM<br></p>', '2024-06-24 18:00:55', CURRENT_TIMESTAMP, 'PTTEP\WittayaB', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-5860B', 'GBS-2P-5860B', 'DIESEL DISTRIBUTION PUMP B', NULL, NULL, 'DIESEL DISTRIBUTION PUMP B', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

