  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'PP: T/S jockey pump M5230 cannot start.', 'Electrical', 'CM', 'Complete', '2024-06-24', '<p>T/S jockey pump M5230 cannot start.</p><p>- Found main magnetic contractor defective (Mechanical lock).</p><p>- Replaced main magnetic contractor by removed from spare feeder(9A-13) due to no spare on board.<br>- Motor parameter, </p><p>&nbsp; &nbsp; - Insulation  84.5M.ohm </p><p>&nbsp; &nbsp; - Resistance U/V = 671.1 milliohm. U/W = 671.2 milliohm. V/W = 670.8 milliohm.</p><p>- Feeder protection tested,</p><p>&nbsp; &nbsp; - O/L tested at 2IR = 2 Amp., Cold = 60.82 Sec. // Hot = 27.28 Sec.</p><p>&nbsp; &nbsp; - Earth fault device tested at 0.1A, Inst.<br>- Function test with satisfactory result</p><p>&nbsp; &nbsp; - Starting current = 157 Amp</p><p>&nbsp; &nbsp; - Running current = 46.9<br></p>', '<span style="color: rgb(69, 90, 100); font-size: 12px; text-wrap: nowrap; background-color: rgb(249, 249, 249);">CONTACTOR,Telemecanique,LP1D8011</span>', '2024-06-24 18:38:46', '2024-06-24 18:42:24', 'PTTEP\Bongkot.Elec-Lead', 'PTTEP\Bongkot.Elec-Lead', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-M-5230', 'GBN-M-5230', 'FIRE WATER JOCKEY PUMP MOTOR', NULL, NULL, 'FIRE WATER JOCKEY PUMP MOTOR', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 14764
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Metering valve preparation for replace on TC#1 ', 'Instrument', 'OTH', 'Completed', '2024-06-24', '<p>**** Valve No.6 SN:22902011&nbsp;******<br></p><p>Metering valve preparation for replace on TC#1.</p><p>- Transfer Metering valve from upper deck to Mezz deck for cleaning and function test.</p><p>- Function test for confirm all function of V no.6 (SN:22902011) are ready to use for replace on TC#1</p><p>- Function step test 0-100% and 100-0% by increase 0.1 mA /sec was OK, The command and feedback are corrected.</p><p>- The Current was not Over 2 Amp during increase the position.</p><p>- Shutdown function was OK it can activate when contact are Open or 4-20mA was loss.</p><p><br></p><p>**** Valve No.7 SN:16033575 ******</p><p>- Performed to As found test by step up and step down which increase and decrease 0.1 mA/Sec</p><p>&nbsp; - Found valve move smoothly.</p><p>&nbsp; - Found the current during valve movement was over 4 A (when increase) and Over -4A when decrease.</p><p>Tomorrow we will be cleaning valve as function test again.</p><p><br></p>', NULL, '2024-06-24 18:39:41', CURRENT_TIMESTAMP, 'PTTEP\GBS.Turbine-Tech', NULL, false) RETURNING id INTO new_report_id;
END $$;

