  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S 71QGT GG lube oil level reading spike high.', 'Turbine E&I', 'CM', 'Under Monitoring', '2024-06-24', '<div>T/S 71QGT GG lube oil level reading spike high.</div><div>- Verify the transmitter found normally.</div><div>- Verify cable connection found normally.</div><div>- Cleaned conneting point of sensor and tranmitter. Then monitor found reading normally.&nbsp;</div><div>- Decide to replaced new level transmitter to prevent alarm occurred again.</div><div>- Recalibrated and simulate loop milliamp for function test.</div>', NULL, '2024-06-24 23:42:33', CURRENT_TIMESTAMP, 'PTTEP\Art.Automation', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PP-A2210.PK', 'ART-PP-A2210.PK', 'APP FEED GAS COMPRESSOR TRAIN 2 PACKAGE', NULL, NULL, 'APP FEED GAS COMPRESSOR TRAIN 2 PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
