-- Inserting report ID 14804
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Metering Valve in Preparation for Replacement ', 'Instrument', 'OTH', 'Completed', '2024-06-25', '<p>Function Test of Metering Valve in Preparation for Replacement on FSD 2024</p><div class="ewa-rteLine">- Transfer metering valve No. 6 (SN: 22902011) to the upper deck for preparation on FSD.</div><div class="ewa-rteLine">- Clean metering valve No. 7 (SN: 16033575) and perform a function test to ensure all functions are working properly.</div><div class="ewa-rteLine">- Preserve metering valve No. 7 and keep it in a clean and dry area.</div><p><br></p><p>**** Valve No.7 SN:16033575 ******</p><p>- Performed to As found test by step up and step down which increase and decrease 0.1 mA/Sec</p><p>&nbsp; - Found valve move smoothly.</p><p>&nbsp; - Found the current during valve movement was over 4 A (when increase) and Over -4A when decrease.</p><p></p><p><br></p><p>Performed to cleaning ball valve follow procedure of&nbsp; Flushing Procedure as per below link.G:\GBSShare\Department Share\03 Maintenance\032 DBS_MEI\002 Turbine\01. TC\Fuel gas metering valve\51342_A[1](maintenance flushing procedure).pdf</p><p>During flushing use&nbsp;<b>isopropyl alcohol from Lab </b>while the valve is stroking</p><p>Valve responds during&nbsp; flushing.</p><p></p><p><br></p><p>- First stroke valve The current was high it''s Over 4.xx A ,after stroking valve few minute the current was decreased ,the maximum current are +- 3.5 A.</p><p>Performed To AL after cleaning.</p><p><b>First AL</b></p><p></p><p><br></p><p><b>Second AL</b></p><p><br></p><p></p><p><br></p><p>After function test completed perform to preserve and keep in HVAC room.</p><p><br></p><p><br></p><p><br></p>', '<p>Table Resolution of Internal Drive current 2.4 Amp</p>', '2024-06-25 17:08:58', CURRENT_TIMESTAMP, 'PTTEP\GBS.Turbine-Tech', NULL, false) RETURNING id INTO new_report_id;
END $$;

