  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2024 FSD Preparation for 2PM-6130B', 'Electrical', 'OTH', 'Completed', '2024-06-25', '<div>2024 FSD Preparation for 2PM-6130B. (Since 21-June-2024)<br></div><div><p>- Perform connected the power cable from Spare M-start BF-402 to 2PM-6130B fresh water pump done.</p><p>- Perform motor and power cable insulation test done. @&gt;550MOhm</p><p>- Perform downloaded M-control parameter at Spare M-start&nbsp;BF-402 followed 2PM-6130B done.</p><p>-&nbsp;Perform the motor test function ELR done.</p><p>-&nbsp;Perform the motor running test done, found the motor running properly no alarm.</p><p>- The motor running current @38A, @72% @411V.</p><p>- <span style="background-color: rgb(255, 255, 0);">The temporary 2PM-6130B not show status at CCR and to be only Local start-stop at QPS switchgear.</span></p><p>-&nbsp;<span style="background-color: rgb(255, 255, 0);">Informed site operator for how to motor start-stop already</span>.</p></div>', NULL, '2024-06-25 18:16:34', '2024-06-25 18:19:07', 'PTTEP\GBS.EI-Workshop', 'PTTEP\GBS.EI-Workshop', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-HS-2PM-6130B', 'GBS-HS-2PM-6130B', 'HAND SWITCH', NULL, NULL, 'HAND SWITCH', 'GBS-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-6130B', 'GBS-2P-6130B', 'FRESH WATER PUMP B', NULL, NULL, 'FRESH WATER PUMP B', 'GBS-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
