  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'MPM IN Sales Gas Chromatograph AIT-1684', 'Instrument', 'PM', 'Completed', '2024-06-25', '<p>MPM IN Sales Gas Chromatograph AIT-1684<br></p><p>- Found calibration incomplete by R^2 was 0.989 which deviated from criteria 0.999&nbsp;&nbsp;</p><p>- K.TeerapatB (PPD/S) recommended to fine-tune time event by adjust V2 off timing from 55.5s to 56s</p><p>and force calibrate then calibrate for 2 times.</p><p>- R^2 is in criteria but %RF was out of tolerance then keep warm up the column by process gas overnight.</p><p><br></p><p>Continue from last night, Calibrate for 10 times, Completed</p>', NULL, '2024-06-25 18:35:38', CURRENT_TIMESTAMP, 'PTTEP\Art-Tech-Prod-Maint', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-AT-1684', 'ART-AT-1684', 'ANALYSIS TRANSMITTER', NULL, NULL, 'ANALYSIS TRANSMITTER', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
