  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Monthly calibration & orifice inspection on tube 5', 'Electrical & Instrument', 'PM ', 'Completed', '2024-06-25', '<p>Performed monthly metering calibration and orifice inspection on metering tube 5.&nbsp;</p><p>&nbsp; &nbsp;1.Put maintenance mode for metering tube 5.</p><p>&nbsp; &nbsp;2.Perform flow, pressure and temperature transmitter calibration.</p><p>&nbsp; 3. Check leak test after calibration.</p><p>&nbsp; 4. Verify and Checked orifice inspection with MOGE rack on metering tube 5.</p><p>&nbsp; &nbsp;5.Reinstall back orifice plate properly after inspection completed.</p><p>&nbsp; 6. Check leak test for vent valve and equalising valve at Daniel orifice housing.</p><p>&nbsp; 7. Remove maintenance mode for metering tube 5 after calibration.</p>', NULL, '2024-06-25 18:42:41', CURRENT_TIMESTAMP, 'PTTEP\ZMS.MTN-Tech', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-M-8435-ASSY', 'ATL-MS-M-8435-ASSY', 'Export Gas Metering Run-E', NULL, NULL, 'Export Gas Metering Run-E', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
