  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Coolroom got high temperature (23 C)', 'Electrical', 'CM', 'Under Monitoring', '2024-06-25', '<p>T/S Coolroom was high temp. Found its compressor unit was stopped.</p><p>Asfound (The room temp was 23C )</p><p>After pressing the reset push button to start the compressor. While the unit was running, found its suction/ discharge pressure was too high ( 80&nbsp; / 300 psi). (Found Suction was 140 psi when compressor stopped).</p><p><br></p><p>Try running the cooling system by reducing the refrigerant and also keep monitoring the room temperature.</p><p>Found the room was cooling down by keeping the suction pressure with 60 Psi.&nbsp;</p>', NULL, '2024-06-25 19:00:17', CURRENT_TIMESTAMP, 'PTTEP\Art-Tech-Prod-Maint', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-QP-GALLEYMISC.ASY', 'ART-QP-GALLEYMISC.ASY', 'AQP ELECTRICAL EQUIPMENT MISC', NULL, NULL, 'AQP ELECTRICAL EQUIPMENT MISC', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
