BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'To overhaul sump pump that was removed from WPS#4.', 'Mechanic', 'CM', 'Completed', '2024-06-26', '<p>To overhaul sump pump that was removed from WPS#4.</p><p>- Disassembly and clean all parts of sump pump.</p><p>- Pressure leaks test the discharge check valve of the hydraulic end cap both sides with pressure @ 30 Barg, found leak both sides.</p><p>- Overhaul the hydraulic end cap both sides then perform pressure leak test, pressure @ 30 Barg, found no leakage both sides.</p><p>-&nbsp; Re-assembly and replace with new repair kit for Air pilot control vale, air driving pump and both of hydraulic ends. (highlight items).</p><p>- Test to operate with bench test, @ discharge pressure 30 Barg, found normal operate and no leakage.</p><p>- Prepare to pump replacement at WPS#5.</p><p><br></p><p align="left"><u>Spare Part used:</u></p><p>  </p><table border="1" cellspacing="0" cellpadding="0" width="690">  <tbody><tr>   <td width="96">   <p align="center">Item   No.</p>   </td>   <td width="366">   <p align="center">Description</p>   </td>   <td width="72">   <p align="center">QTY.</p>   </td>   <td width="156">   <p align="center">Remark</p>   </td>  </tr>  <tr>   <td width="96" valign="top">   <p align="left">29.37.40.010.3</p>   </td>   <td width="366" valign="top">   <p align="left">Fluid   section seal for positive displacement pump P/N 86574</p>   </td>   <td width="72" valign="top">   <p align="center">1</p>   </td>   <td width="156" valign="top">   <p align="left">&nbsp;</p>   </td>  </tr>  <tr>   <td width="96" valign="top">   <p align="left">29.37.40.006.3</p>   </td>   <td width="366" valign="top">   <p align="left">Seal   kit, Air Drive P/N 86299</p>   </td>   <td width="72" valign="top">   <p align="center">1</p>   </td>   <td width="156" valign="top">   <p align="left">&nbsp;</p>   </td>  </tr>  <tr>   <td width="96" valign="top">   <p align="center">29.37.40.008.3</p>   </td>   <td width="366" valign="top">   <p align="left">Seal   kit, Air valve P/N 86298</p>   </td>   <td width="72" valign="top">   <p align="center">1</p>   </td>   <td width="156" valign="top">   <p align="left">&nbsp;</p>   </td>  </tr> </tbody></table>', NULL, '2024-06-26 17:26:22', CURRENT_TIMESTAMP, 'PTTEP\WittayaB', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-1445', 'GBS-2P-1445', 'SUMP TANK PUMP', NULL, NULL, 'SUMP TANK PUMP', 'GBS-WP04', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
