BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, '2P-4320D To clean HM pump suction strainer.', 'Mechanic', 'CM', 'Completed', '2024-06-27', '<p>- As found trend of diff. pressure of HM pump suction strainer is increase (0.7 bar).</p><p>- Perform process isolation by Operator.</p><p>- Wait for Casing temperature decrease to 90''C.</p><p>- Remove top flange of strainer vessel.</p><p>- Remove pump suction strainer found clog about 30% of strainer area.</p><p>- Clean all part and preserve stud bolt.</p><p>- Replace new strainer with mess#60 with new gasket.</p><p>- Re-install top flange of strainer vessel.</p><p>- Perform process de-isolation by Operator for leakage test, found no leak.</p><p>- Change over pump from C to D for running test, found normal operate. Diff pressure @ 0.023 bag, suction pressure@ 3.8 Barg and discharge pressure @ 15 Barg.</p><p>- Clean the strainer for spare.</p><p>&nbsp;</p>', 'G:\GBSShare\Department Share\03 Maintenance\031 DBS_MM\6. Picture\61. PPS Equipment Picture\All pumps\2P-4320 Heating Medium pumps\2P-4320 D\2024\2024.06.27 2P-4320D clean pump suction strainer', '2024-06-27 14:39:54', CURRENT_TIMESTAMP, 'PTTEP\WittayaB', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-4320D', 'GBS-2P-4320D', 'HEATING MEDIUM CIRCULATION PUMP D', NULL, NULL, 'HEATING MEDIUM CIRCULATION PUMP D', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
