  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'WP-13: Replaced defective SDV-2310 (Temporary) ', 'Mechanic', 'CM', 'Complete', '2024-06-27', '<p>Replaced defective SDV-2310 (Temporary) and send defective ball valve to investigate and refurbish at SNU then swop to SDV-2311 to investigate and refurbish too.</p><p><br></p><p>Scope:</p><p>- Removed valve actuator and accessories.</p><p>- Removed old defective valve and cleaned up pipe flanges raise face prepared to install new ball valve spare.</p><p>- Installed new ball valve spare (temporary) with new gasket and old stud bolts.</p><p>- Apply torque @ 470 ft.lb.</p><p>- Installed old one valve actuator with new stem extension, new bolts and new adaptor.</p><p>- Re-installed valve actuator HYD control and function test operated properly.</p><p>- Cleaned up working area.</p><p>*** Pending for pressure leak test due to SDV-2311 waiting to be replace ***</p>', NULL, '2024-06-27 19:32:20', CURRENT_TIMESTAMP, 'PTTEP\Bongkot.Valve', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-SDV-2310', 'GBN-SDV-2310', 'SHUTDOWN VALVE', NULL, NULL, 'SHUTDOWN VALVE', 'GBN-WP13', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

