END $$;

-- Inserting report ID 14913
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verified Dew point reading of AIT-1350,2350', 'Instrument', 'OTH', 'In Progress', '2024-06-27', '<p>Due to the CCR request to verify the Dew point value reading from AIT-1350 and AIT-2350 due to deviate reading.</p><p>Verify OGC AIT-1350 reading by performing the as-found repeat repro.</p><p>&nbsp;- Found the analyzer working properly.</p><p>Then verify both sample loops of Train 1&amp;2 (AIT-1350 and AIT-2350)</p><p>&nbsp;- Found stream-3 (AIT-2350) was not fully opened of the incoming needle valve.,</p><p>&nbsp;- Then rectified both stream 2&amp;3 needle valve openings to manipulate their sampling flow as specific (about 400 cc).</p><p>After monitoring and discussing with CCR, we agreed to increase both sampling flows to reduce contaminated condensate that could be remaining inside the sampling tube.</p><p>Finally, found that the Dew point readings of both streams (AIT-1350, and AIT-2350) got dynamic readings, Under monitoring.</p><p><br></p><p>&nbsp;&nbsp;</p><p><br></p><p><br></p>', NULL, '2024-06-27 19:50:03', CURRENT_TIMESTAMP, 'PTTEP\TawatchaiP', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-AIT-1350', 'ART-AIT-1350', 'AIT (UOP C9 GC)', NULL, NULL, 'AIT (UOP C9 GC)', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

