-- Inserting report ID 14938
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'WP-11 Start up platform after ESD-2.', 'Instrument', 'CM', 'Complete', '2024-06-27', '<p><u><b>WP-11 Platform Shutdown (ESD-2):</b></u><br></p><p>&nbsp; &nbsp; -&nbsp;The shutdown occurred due to low hydraulic pressure from HP-3.</p><p>&nbsp; &nbsp; -&nbsp;PCV-2123 couldn’t control pressure above 9.5 bar, affecting SDV-2120 on-off cycles.</p><p>&nbsp; &nbsp; -&nbsp;Despite replacing the hydraulic relay at the SDV local panel, pressure loss persisted during valve operation.</p><p>&nbsp; &nbsp; -&nbsp;Adjusting the restrictor valve before the local panel helped reduce flow rate to SDV, resulting in a 1-bar hydraulic pressure loss.</p><p>&nbsp; &nbsp; -&nbsp;PCV-2123 was isolated due to its inability to adjust pressure, with plans for an overhaul during the next visit.</p><p>&nbsp; &nbsp; -&nbsp;PCV-2122 successfully controlled pressure around 8.5 bar.</p><p>&nbsp; &nbsp; -&nbsp;After resolving the issue, HP-3 can now build up stable pressure.</p><p><u><b>Hydraulic Seepage at Stem Knob Versa Valve (SDV-2120 on WHCP):</b></u></p><p>&nbsp; &nbsp; -&nbsp;The stem knob versa valve was replaced, followed by a function test.</p><p><u><b>Hydraulic Leakage at Vent Port of PCV-21004A and B:</b></u></p><p>&nbsp; &nbsp; -&nbsp;Both pressure gauges for PCV-21004A and B were unreadable.</p><p>&nbsp; &nbsp; - Adjusting the pressure regulator to 5.0 bar, as per the drawing, eliminated hydraulic leaks at the vent port.</p><p>&nbsp; &nbsp; -&nbsp;Replacing the pressure gauges for both pressure regulators ensured accurate readings.</p><p><b><u>Spare part list</u></b></p><p>60.83.29.900.3&nbsp;3WAY HYDRAULIC <a href="VLV,BIS:3B25NH3G-6K">VLV,BIS:3B25NH3G-6K</a>&nbsp;= 1 ea. for local SDV-2120</p><p>60.35.11.054.9&nbsp;PG,63,1/4",0-14BAR,BK,WIKA,233.50 = 2 ea. for regulator PCV-21004A,B</p><p>60.35.12.447.9&nbsp;PG,63,1/4"MNPT,0-100PSI,GL,BK,SG,OPT2,D1 = 2 ea. for WHCP 5 bar logic.</p><p>60.35.12.491.9&nbsp;PG,63,1/4"MNPT,6000PSI,GL,BK,SG,OPT2,D1 = 1 ea. for WHCP HP-3 monitor.</p><p>02.02.40.507.3&nbsp;PILOT/MANUAL,P/N.BIA-3309-316-301ES-S = 1 ea. for WHCP SDV-2120 signal<br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 'Photo :&nbsp;G:\Selective Access\02-PBN-M\02 MEI\19 Photos\01 Instrument Photos\13-All Picture\01.All Wellhead Remote platform\WP11\20240627 Restart After ESD-2 HYD pressure low', '2024-06-28 16:56:27', CURRENT_TIMESTAMP, 'PTTEP\Bongkot.Inst-Lead', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP11-PRO-WH', 'GBN-WP11-PRO-WH', 'WELLHEAD AND SUBSURFACE', NULL, NULL, 'WELLHEAD AND SUBSURFACE', 'GBN-WP11', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

