  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Yearly PM ZOC Sewage Treatment System', 'Mechanic', 'PM', 'Completed', '2024-06-29', '<p><u>Today Activity</u></p><p>Yearly PM ZOC Sewage Treatment System.</p><p><br><b><i>Service for the pumps of the Sewage Treatment Tanks</i></b></p><p><u>Action</u></p><p>- Disconnected the pipe fittings.</p><p>- Lifted the pump above the ground by cleaning the pump.</p><p>- Drained and flushed out the lube oil.</p><p>- Topped up Lube oil (Azolla ZS 46).</p><p>- Performed Visual Inspection.<br>- Lower down the pump into the tank.</p><p>- Placed the pump in the original position and tightened the fitting.</p><p>- Housekeeping and Test run.</p><p><br></p><p><b><i>Service for the Aeration Blowers</i></b></p><p><u>Action</u><br></p><p>- Checked and cleaned the air filter.</p><p>- Checked the lube oil level.</p><p>- Drained and flushed the lube oil.</p><p>- Topped up Lube Oil (PTT GL-5).</p><p>- Checked the belt condition.</p><p>- Replaced the belts for Unit A.</p><p>- Checked the belt alignment and tension.</p><p>- Adjusted the belt tension.</p><p>- Checked the bolt of compressor and motor.</p><p>- Checked the mounting bolt of air compressor.</p><p>- Cleaned the air compressor package.</p><p>- Housekeeping and test run.</p><p>- Check the abnormal noise and vibration.</p><p><br></p><p><u>Required Tools</u></p><p>- Water Jet</p><p>- Laser Alignment<br>- Wrap Wrench<br>- Claw Bars<br>- Steel Rules</p><p>- Lighting</p><p>- Zip Lock</p><p>- Screw Drivers</p><p>- Tray</p><p>- Rags</p><p>- Rubber Gloves</p>', 'For DNC Tank, there is no pump in the tank and is just only mixer.<br>It needs to perform visual inspection.', '2024-06-29 17:23:39', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-UTL-SW-8900', 'ATL-OC-UTL-SW-8900', 'ZOC New Sewage Treatment Package', NULL, NULL, 'ZOC New Sewage Treatment Package', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-SW-B8910A', 'ATL-OC-SW-B8910A', 'Sewage Blower Unit A', NULL, NULL, 'Sewage Blower Unit A', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-SW-B8910B', 'ATL-OC-SW-B8910B', 'Sewage Blower Unit B', NULL, NULL, 'Sewage Blower Unit B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
