  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP01-PRO-WH', 'GBN-WP01-PRO-WH', 'WELLHEAD AND SUBSURFACE', NULL, NULL, 'WELLHEAD AND SUBSURFACE', 'GBN-WP01', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
