-- Inserting report ID 15049
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'WP-01: T/S BK-1D Hydraulic passing inside WHCP', 'Instrument', 'CM', 'In Progress', '2024-07-01', '<p><b>T/S BK-1D&nbsp; Wing valve and master valve hydraulic passing in WHCP. (Continue)</b></p><p>**WO.500553354</p><p>Action : Overhaul hydraulic relay E-1(for MV) and E-2(for WV).</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Install back to normal and function test.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Monitor hydraulic passing or leak. No more passing or leak, pressure didn''t decrease while testing.&nbsp;</p><p>Result : Well "D" can be using.&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;</p><p><br></p><p>History of 30 Jun 2024</p><p>BK-1D&nbsp;Found : WV quick exhaust valve passing to return line.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Hydraulic relay E-1(for MV) and E-2(for WV)&nbsp;inside the CP-1100 control panel have been passing to return line while command close.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Action : Overhaul quick exhaust valve and install back.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Isolated and remove some tubing for E-1 and E-2 removing preparation.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; Action plan : Hydraulic relay&nbsp;E-1 and E-2 will be overhaul.&nbsp; &nbsp; &nbsp; &nbsp;</p>', 'Material Used : 59.34.33.102.3 , Repair kit HLR P/N: 7950A = 2 set.', '2024-07-01 18:45:28', '2024-07-02 17:35:10', 'PTTEP\Bongkot.Inst-Lead', 'PTTEP\Bongkot.Inst-Lead', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP01-PRO-WH', 'GBN-WP01-PRO-WH', 'WELLHEAD AND SUBSURFACE', NULL, NULL, 'WELLHEAD AND SUBSURFACE', 'GBN-WP01', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

-- Inserting report ID 15050
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'WP-37 X-3773 Crane  Replaced defective radiator ', 'Mechanic', 'CM', 'Complete', '2024-07-01', '<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Replaced defective radiator due to cooling water leaked.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Prepared hand tools and spare parts to start work.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Installed all flexible hose.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Top up coolant water mixed about 60 liters to radiator.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Bleed air in coolant system.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Temporary use normal activate radiator level switch. (New radiator don’t design)</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Re-installed radiator guard.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Started engine for checked no found leak and running test about 2 hours found normal. </p>  <p>condition. </p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Packing old radiator prepare for back load to SKL.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Cleared hand tools and clean up working area.</p>', NULL, '2024-07-01 18:46:10', CURRENT_TIMESTAMP, 'PTTEP\Mech_WS', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-1X-3773', 'GBN-1X-3773', 'PEDESTAL CRANE GBN-WP37', NULL, NULL, 'PEDESTAL CRANE GBN-WP37', 'GBN-WP37', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

