  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'RP Verify FT-9111 reading error.', 'Instrument', 'CM', 'Under Monitoring', '2024-07-02', '<p>Found FT-9111 reading error by grease between sensor and process pipe deteriorated.</p><p>&nbsp; &nbsp; - Cleaned old grease at sensor, rubber damping and damping material.</p><p>&nbsp; &nbsp; - Apply new grease and adjust transition length of sensor.</p><p>&nbsp; &nbsp; - Sensor A old length = 143 mm. new = 145 mm.</p><p>&nbsp; &nbsp; - Sensor B old length = 143 mm. new = 140 mm.</p><p>&nbsp; &nbsp; - Check configuration found no problem.</p><p>&nbsp; &nbsp; - Then sensor A and sensor B reading flow rate compare same value.<br></p><p>&nbsp; &nbsp; - After fix problem now FT-9111 reading satisfied and keep monitoring.<br></p>', NULL, '2024-07-02 18:22:33', '2024-07-02 18:36:57', 'PTTEP\Bongkot.Inst-Lead', 'PTTEP\Bongkot.Inst-Lead', false) RETURNING id INTO new_report_id;
