  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-FM200-G-8935', 'ATL-OC-FM200-G-8935', 'FM200 Fire Fighting System G-8935', NULL, NULL, 'FM200 Fire Fighting System G-8935', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
