  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'SPP, XV-8000-1: Replaced 10"150# Butterfly Valve ', 'Mechanic', 'CM', 'Complete', '2024-07-08', '<p><b><u>SPP, XV-8000-1: Replaced 10"150# Butterfly Valve due to valve G/B internal part damage.</u></b></p><p>- Waiting for erection of scaffold and install chain hoist for remove/install valve.</p><p>- Removed stud bolt and existing valve.</p><p>- Cleaned up flanges surface prepared to install new butterfly valve.</p><p>- Installed new butterfly valve 10"150# with new CNAF gasket and new stud bolts.</p><p>- Tighten stud bolts and apply torque@ 75 ft.lb.</p><p>- Cleaned up working area.</p><p>- Coordinated with production operator line up water pressure for leak test @10 bar, not found any leak.</p><p>- Function open/close valve and production operator normalize water ring main pressure@ 9 bar</p><p><br></p>', NULL, '2024-07-08 16:25:35', CURRENT_TIMESTAMP, 'PTTEP\Bongkot.Valve', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-XV-8000-1', 'GBN-XV-8000-1', 'DELUGE PACKAGE', NULL, NULL, 'DELUGE PACKAGE', 'GBN-SPP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
