BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'RP: Verify FT-9111 spike low time to time', 'Instrument', 'CM', 'Under Monitoring', '2024-07-08', '<p><b>Found FT-9111 reading spike low time to time.</b></p><p>&nbsp; &nbsp; - Check grease condition at all sensor element./ Still ok.&nbsp;</p><p>&nbsp; &nbsp; - Adjust sensor distance as per transmitter recommendation. (Automatic calculation from pipeline outside diameter)</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Sensor A : Old length = 145 mm. new = 141 mm.</p><p>&nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;- Sensor B : Old length = 140 mm. new = 141 mm.</p><p>&nbsp; &nbsp; - Check and re-tightened mA output signal loop and replaced fuse 0.1A in the loop.</p><p>&nbsp; &nbsp; - Check and re-tightened 24VDC power supply loop (DCDB-90-402 : CKT.no.8).<br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;- Both sensors are reading flow rates that have been likely the same.</p><p>- Keep monitoring.</p><p><br></p><p>Pipeline OD = 762mm = 30 Inch</p>', 'Channel "B" has been selected.', '2024-07-08 16:39:26', '2024-07-09 05:43:11', 'PTTEP\Bongkot.Inst-Lead', 'PTTEP\Bongkot.Inst-Lead', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-FT-9111', 'GBN-FT-9111', 'FLOW TRANSMITTER', NULL, NULL, 'FLOW TRANSMITTER', 'GBN-RP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

