-- Inserting report ID 15369
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TG-5630, Performed engine crank soak wash & firing', 'Mechanic', 'PM', 'Complete', '2024-07-07', '<p>TG-5630, Performed engine crank soak wash and firing the unit</p><ul type="disc"><li>- Prepared solution on mobile machine car wash.</li><li>- Connected air line for Supply&nbsp;<u>40</u>&nbsp;Psi sealing dry air to reduction gearbox and engine bearing.</li><li>- Filled up pure water 11 Gallon &amp; chemical cleaning ZOK 4 gallon total solution 15 gallons.</li><li>- Started step crank soak wash machine and follow the&nbsp;<i><u>new procedure</u></i>&nbsp;for crank soak wash.</li><li>- Distillate water cleaning for 4 times (total 200 liters).</li><li>- Crank dry 10 minutes than starting with gas mode.</li><li>- Inspected and check leak as found no any leak.</li><li>- R/H. 32,268 hrs.</li><li>- Cleaned inside and outside skid.</li><li>- Keep unit stand-by.</li></ul>', NULL, '2024-07-09 19:40:30', '2024-07-09 19:47:28', 'PTTEP\Bongkot.turbine-Mech', 'PTTEP\Bongkot.turbine-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-TG-5630', 'GBN-TG-5630', 'TURBO GENERATOR 3 PACKAGE', NULL, NULL, 'TURBO GENERATOR 3 PACKAGE', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

