  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Removed Unused UD-10 (Universal Display)', 'Turbine E&I', 'CM', 'Completed', '2024-07-10', '<p>According to the unidentified &amp; unused UD-10 for remote monitoring 3 Gas detectors in the Air inlet filter housing. They were not properly installed and requested to be addressed by E&amp;I Supv while performing the PSSR of FGC#1 (Pre-Start up Safety Review of FGC#1 starting up after the Engine Exchange.)</p><p><br></p><p>Due to all the unused UD-10, it was not beneficial to keep. So they should be removed from the Junction box which is located outside of the Airfilter housing. (For both FGC#1 &amp; FGC#2). Then properly install the 3/4 NPT Ex-plug supporting the removal of all UD-10 extension conduits.</p><p><br></p><p>Regarding the FGC#2, Which was volunteer stopped. All the UD-10 were properly removed from the junction box and it was re-tidy up and re-tightening all terminals inside the junction box.</p><p><br></p><p>UD-10: Univeral Display, Det tronics. Only the terminal box remained, for the actual display was not available anymore.</p><p><br></p><p>Pictures&nbsp;</p><p>G:\ARTShare\Selective Access\02-PAT-M\02-PAT-M_El\02 - Automation\1.DOCUMENT FOR HAND OVER\2023_2024\0.1 Turbo Machinery\Feed 1,2\Feed Gas Compressor Train 1 A-1210\20240703_GG Engine changeout\FGC#2_F&amp;G lens cleaned and Collect data<br></p>', NULL, '2024-07-10 16:13:29', CURRENT_TIMESTAMP, 'PTTEP\TawatchaiP', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PP-A2210-C2210.SPK', 'ART-PP-A2210-C2210.SPK', 'APP FEED GAS COMPRESSOR UNIT TRAIN2 PACK', NULL, NULL, 'APP FEED GAS COMPRESSOR UNIT TRAIN2 PACK', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-GT-2220', 'ART-GT-2220', 'FEED COMPRESSION TURBINE TRAIN 2', NULL, NULL, 'FEED COMPRESSION TURBINE TRAIN 2', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

