  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify and TS G8925 lighting set malfuntion', 'Electrical & Instrument', 'CM', 'Completed', '2024-07-12', '<p><strong><u>Today''s Activity</u></strong></p><p>Verification and Troubleshooting of G8925 Lighting Set Malfunction</p><p><b><u>Findings</u><br></b>During a visual inspection of the lighting box, it was discovered that the door cover close switch on the light frame was damaged and not functioning properly. <br>Consequently, the lamps were not operating correctly.</p><p><b><u>Action Taken&nbsp; (Temporary solution)</u><br></b>Secured the door cover tightly with a cable tie. <br>The lamps are now functioning properly.<br><b style="text-decoration-line: underline;">Plan&nbsp;</b><br>To purchase the spare part of the light frame door cover switch.</p>', NULL, '2024-07-12 10:36:58', '2024-07-12 10:57:34', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
