  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'TG-2,F&G Lens cleaning and Collect Running hrs', 'Turbine E&I', 'OTH', 'Completed', '2024-07-12', '<p>Due to predictive maintenance.&nbsp;</p><p>&nbsp;1. Cleaned the detecting lens of all gas detectors inside the TG package enclosure.</p><p>&nbsp;2. Cleaned the detecting lens of all Flame detectors inside the TG package enclosure.</p><p>&nbsp;3. Collect the gas detector running hrs for summarising the database to determine the aging of the turbo package gas detectors serviceable.</p><p><br></p><p>Noted. There was rainwater ingressing through the package enclosure rooftop because of deteriorated enclosure air inlet penetration.&nbsp;</p><p><br></p><p>Noted, the relevant notification was issued to the ART-CSTR (Arthit construction team) for the rectification manner.&nbsp;</p><p><br></p><p>The related Pictures&nbsp;</p><p>G:\ARTShare\Selective Access\02-PAT-M\02-PAT-M_El\02 - Automation\1.DOCUMENT FOR HAND OVER\2023_2024\0.1 Turbo Machinery\SOLAR\Power Generator 123\A6200_Gen2\20240709_TG2_Alarm Fire system trouble</p><p><br></p>', 'There was pending inside enclosure cleaning while waiting for the package roof repair.', '2024-07-12 20:28:28', '2024-07-14 22:28:05', 'PTTEP\TawatchaiP', 'PTTEP\TawatchaiP', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6200-FIG615', 'ART-A-6200-FIG615', 'FIRE EYES,DWG. BGS.46853.0,FIG. 6.15', NULL, NULL, 'FIRE EYES,DWG. BGS.46853.0,FIG. 6.15', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
