BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'WP-28 : Rig T-15 T/S Lighting fixtures tripped.', 'Electrical', 'CM', 'Under Monitoring', '2024-07-12', '<p>WP-28 : Rig T-15 T/S Lighting fixtures tripped.</p><p>- Informed from Rig T-15 about lighting fixtures (Tempo spot light) were tripped on 3 AM. (Last night)</p><p>- Checked found circuit breaker F7 for LED Tormin floodlights tripped by earth fault. (2 set)</p><p>Insulation test (Rate testing at 220 VDC)</p><p>#1 : 0.10 M-Ohm. (Receptacle 1RN-28-701)</p><p>#2 : 0.06 M-Ohm. (Receptacle 1RN-28-702)</p><p>- Found Tormin floodlight 2 fixtures low insulation caused to circuit breaker F7 tripped.</p><p>- Now, Circuit breaker F7 supplied for 3 floodlight, load current 2.7 A.</p><p>Note; 1ACDB-28-410</p>', 'G:\Selective Access\02-PBN-M\02 MEI\19 Photos\00 Electrical Photos\WPs PICTURES\WP28\OTHER\2024-07-12 To continue trouble shooting lighting system for Rig T-15', '2024-07-12 21:07:31', '2024-07-12 21:08:39', 'PTTEP\Bongkot.Elec-Lead', 'PTTEP\Bongkot.Elec-Lead', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP28-ELE-LGHT', 'GBN-WP28-ELE-LGHT', 'LIGHTING AND SMALL POWER SYSTEM', NULL, NULL, 'LIGHTING AND SMALL POWER SYSTEM', 'GBN-WP28', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
