-- Inserting report ID 15561
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshooted XV-3NK5, XV-3NM4 IG Regulator leak ', 'Instrument', 'CM', 'Completed', '2024-07-13', '<div>**Troubleshooted LT-3N502 display blackout.</div><div>-Replaced display card.</div><div>-Function tested it was working properly.</div><div><br></div><div><br></div><div><div>**Troubleshooted XV-3NK5, XV-3NM4 IG Regulator leak and&nbsp; XV-3NR4 Solenoid defective.</div><div>-XV-3NK5 Replaced solenoid pilot and regulator.</div><div>-XV-3NM4 Replaced regulator and pilot valve.</div><div>-XV-3NH4 Overhauled regulator.</div><div>-XV-3NR4 found normal condition.</div><div>-Function test it were working properly and have no gas leaking.</div><div><br></div><div><br></div><div><div>**CM T/S back up HP-1 and HP-2 pump gas leak.</div><div>T/S back up HP-1 and HP-2 pump gas leak.</div><div>-Replaced back up&nbsp; HP-1. HP-2 pump.</div><div>-Function tested it were working properly.</div><div>-Found main pump HP1 malfunction cause of O-ring spoon damaged to be overhaule.</div></div><div><br></div><div><br></div></div>', NULL, '2024-07-13 20:17:33', CURRENT_TIMESTAMP, 'PTTEP\Art-Tech-Prod-Maint', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-XV-3NH4', 'ART-XV-3NH4', 'ACTUATED VALVE', NULL, NULL, 'ACTUATED VALVE', 'ART-WP3N', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
