  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'A-3010A , Gas Cooler Fan - To perform mechanical ', 'Mechanic', 'CM', 'Complete', '2024-07-14', '<ul type="disc">  <li><div class="row"><div class="col-sm-10"><div class="displayform multilinedesc"><p>WORK SUMMARY :<br></p><p>- Checked both bearing of fan shaft and bearing of motor, found normal condition.</p><p>-&nbsp;Checked alignment fan pulley to motor pulley was normal.</p><p>-&nbsp;Retighten all bolts as per specifications.</p><p>-&nbsp;Retighten taper bush of hub motor @ 50 Nm. and&nbsp;taper bush of hub fan @ 90 Nm.</p><p>- Checked and inspected anti rotation for free operation was normal.</p><p>-&nbsp;Checked blades angle and blades tip gap.</p><p>- General cleaned and zinc touch, lubricated bolts on equipment.</p><p>- Used special tool check belt alignment.</p><p>-&nbsp;Checked all tools for missing and re-installed protection grids.</p><p><span style="font-size: 15px;">- Replaced new belt and tensioning of belt by used the tension      measurement tools. (Required frequency </span><b style="font-size: 15px;">29&nbsp;</b><span style="font-size: 15px;">Hz</span><b style="font-size: 15px;">.)</b></p><table border="1" cellspacing="0" cellpadding="0" align="right"><tbody><tr><td width="79" valign="bottom"><p>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Blade&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p></td><td width="52"><p align="center">N</p></td><td width="52"><p align="center">E</p></td><td width="52"><p align="center">S</p></td><td width="52"><p align="center">W</p></td><td width="90"><p align="center">Remark</p></td></tr><tr><td width="79" valign="top"><p>1</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="90" rowspan="6"><p align="center">STD.</p><p align="center">3-19 mm.</p><p align="center">¼” – ¾”</p></td></tr><tr><td width="79" valign="top"><p>2</p></td><td width="52" valign="top"><p align="center">31</p></td><td width="52" valign="top"><p align="center">28</p></td><td width="52" valign="top"><p align="center">12</p></td><td width="52" valign="top"><p align="center">18</p></td></tr><tr><td width="79" valign="top"><p>3</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td></tr><tr><td width="79" valign="top"><p>4</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td></tr><tr><td width="79" valign="top"><p>5</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td></tr><tr><td width="79" valign="top"><p>6</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td><td width="52" valign="top"><p align="center">-</p></td></tr></tbody></table><table border=