  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Replaced Lube oil temp gauge', 'Turbine E&I', 'CM', 'Completed', '2024-07-14', '<p>Replaced a temperature gauge for the Lube oil temp header.</p><p>(WON: TBC), Material Reservation: TBC</p><p><br></p><p>The material used: 20.70.07.303.3</p><p>Noun: Gas Turbines<br></p><p>Modifiers: SOLAR, US<br></p><p>Description: THERMOMETER<br>MFG. for Parts: ASHCROFT<br>Part number: EQ. P/N : C-600A-04-C38-B18-A1-L03-DT<br>Additional information: -40/+180F(-40/+80C)<br>C-600A = Type of Duratemp Thermometer, Remote Mounted<br>04 = Case Style : Phenolic Snap Ring<br>C38 = Case Size : 4-1/2, Flush mounting , Rear connection<br>B18 = Bulb Style : 24? Bendable extension with 1/2 NPT union connection<br>A1 = Armor Style : Stainless steel spring lock<br>L03 = Line Length : 10 ft.<br>DT = Range : 40°C/80°C and –40°F/180°F<br>Other Specifications :<br>-Accuracy : +/- 1.0 % F.S.<br>-Sensing Portion : 3/8 dia. * 3 L<br>Parts list reference: Reff Desig. TI902<br>EQ.Tag numbers: GT-1620<br>EQ.Manufacturer: SOLAR TURBINE<br>EQ.Model: MAR 100<br>EQ.Serial numbers: MM061880<br></p>', NULL, '2024-07-15 15:51:25', '2024-07-15 20:16:22', 'PTTEP\Art-Tech-Prod-Maint', 'PTTEP\Art-Tech-Prod-Maint', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-GT-1620-TI902', 'ART-GT-1620-TI902', 'TI,LUBE OIL HEADER TEMPERATURE', NULL, NULL, 'TI,LUBE OIL HEADER TEMPERATURE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-GT-1620', 'ART-GT-1620', 'SALES GAS COMPRESSION TURBINE TRAIN 1', NULL, NULL, 'SALES GAS COMPRESSION TURBINE TRAIN 1', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
