  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Perform YPM Mini Excavator Kobelco Day 2', 'Mechanic', 'PM', 'Completed', '2024-07-16', '<p>YPM on Kobelco Day 2</p><p>Job Steps;</p><p>- Engine Test run and visually checked. Listened to the sound for abnormal noises.</p><p>- Main Pumps were checked and tested.</p><p>- After the test run, refill the hydraulic about 3 liters.</p><p>- Greasing the joints and pins.</p><p>- Pressure tested at pumps; pump 1,2 and 3. Found no abnormality.</p><p>- Exercised cylinders, booms, and arms and found no abnormalities.</p><p>- Observe bucket pins were losing. Replace the New Bucket and Bucket Pin</p><p><br></p>', NULL, '2024-07-16 16:26:59', CURRENT_TIMESTAMP, 'PTTEP\ZOC.Mech-Tec', NULL, false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-EXCAVATOR-01', 'ATL-OC-EXCAVATOR-01', 'Mini Excavator-KOBELCO', NULL, NULL, 'Mini Excavator-KOBELCO', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
