  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S UV Sterilizer package A&B unit were tripped.', 'Electrical', 'CM', 'Completed', '2024-07-18', '<p>T/S UV Sterilizer package A&amp;B unit were tripped.</p><p><br></p><p>- 2X-6160A found unit alarm low dose. (intensity value reading 0 mJ/cm2)</p><p>&nbsp; &nbsp; - Cleaned quartz sleeves due to both of them were dertied. But 1 of 2 sleeve still dirtied, replaced only 1 sleeves.&nbsp;</p><p>&nbsp; &nbsp; - Replaced 2 UV lamps completed.</p><p>&nbsp; &nbsp; - Cleaned inside chamber completed.</p><p>&nbsp; &nbsp; - Cleaned len of sensor completed.</p><p>&nbsp; &nbsp; - Running test found intensity value is 44 mJ/cm2.</p><p><br></p><p>- 2X-6160B found unit alarm low dose. (intensity value reading 9 mJ/cm2)</p><p>&nbsp; &nbsp; - Cleaned quartz sleeves due to both of them were dertied. But 1 of 2 sleeve was damaged, replaced only 1 sleeves.&nbsp;</p><p>&nbsp; &nbsp; - Replaced 2 UV lamps completed.</p><p>&nbsp; &nbsp; - Cleaned inside chamber completed.</p><p>&nbsp; &nbsp; - Cleaned len of sensor completed.</p><p>&nbsp; &nbsp; - Running test found intensity value is 35 mJ/cm2.</p><p><br></p>', '<p>Used Quartz sleeves Item No.42.40.16.202.3 = 2 Ea.</p><p>Used UV lamps LP200 EXWEE/FC0081UW Item No.42.40.16.201.3 = 4 Ea.<br></p><p><br></p>', '2024-07-18 16:37:51', CURRENT_TIMESTAMP, 'PTTEP\GBS.EI-Workshop', NULL, false) RETURNING id INTO new_report_id;
