  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Modify Air assist air for BDV-39803', 'Instrument', 'MD', 'Completed', '2024-07-18', '<p>Performed to apply air assist panel for 2BDV-39803 due to valve cannot open in normal condition.</p><p>- Performed to apply air assist to spring port of actuator.</p><p>- Apply air assist pressure 1.5 Barg with condition upstream valve pressure 128 Barg and downstream pressure 0 Barg and apply air assist timer more than 25 sec.</p><p>- The result valve fully open with in 19 sec .</p><p>- The result was accept of all party.</p><p><br></p><p>Force signal.</p><p>1.Valve_CMD_6.Valve</p><p>2.L86VM_ALM</p><p>3.l33vm2_c</p><p>4.l33vm2_o</p><p>5.BPSL_39803</p><p>6.BSHA_39803</p><p>7.l20vm2</p>', '<p><br></p>', '2024-07-18 16:45:29', '2024-07-19 08:24:57', 'PTTEP\GBS.Turbine-Tech', 'PTTEP\GBS.Turbine-Tech', false) RETURNING id INTO new_report_id;
