BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'T/S problem platform shutdown and startup.', 'Electrical', 'CM', 'Under Monitoring', '2024-07-20', '<p>T/S unexpected unknown cause to shut down and startup platform WP-26.</p><p>- Found Circuit breaker F21 CB of solar array A/B (MX), F22 CB of solar array C/D (MX), F23 CB of battery bank A (MX), F24 CB of battery bank B (MX), F25 CB of charger control &amp; voltage regulator (MX), F61 CB TEG supply in coming, F71 CB of battery bank A (MN), F73 CB of battery bank B (MN) tripped, platform ESD-1.&nbsp;</p><p>- Check all control fuse, found fuse F-65A (X0-1A) blowout due to card U-65 (current measuring for power available) defective.</p><p>- Found card K-67&nbsp;lost.</p><p>- Found jump contact bypass loop for status system running between K67(cable tag.170) with K68 (cable tag.63).&nbsp;</p><p>- Override key and resumed power supply power supply found earth fault monitoring alarm then measure voltage +/- = 25.61 Vdc, +/G = 22.50 Vdc and -/G= 3.1 Vdc.&nbsp;</p><p>- Start TEG unit A, B, C and E.</p><p>- Found telemetry failure then reboot SDA but still problem not clear to be verify by IT team.&nbsp;</p><p></p><p>- Normalize platform.</p>', '<p>G:\Selective Access\02-PBN-M\02 MEI\19 Photos\00 Electrical Photos\WPs PICTURES\WP26\OTHER\Startup platform shutdown 19-7-2024</p>', '2024-07-20 04:08:15', '2024-07-20 19:03:01', 'PTTEP\Bongkot.Elec-Lead', 'PTTEP\Bongkot.Elec-Lead', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP26', 'GBN-WP26', 'BONGKOT NORTH WELLHEAD PLATFORM WP26', NULL, NULL, 'BONGKOT NORTH WELLHEAD PLATFORM WP26', 'GBN-WP26', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
