  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'MPM diesel generator G-8310', 'Electrical & Instrument', 'PM', 'Completed', '2024-07-21', '<div><u><b>Today Activity</b></u></div><div>Performed monthly PM diesel generator G-8310 at ZBV-2.</div><div><br></div><div><u><b>Action</b></u><br></div><div>- Performed electrical isolation G-8310.<br></div><div>- Checked battery voltage, battery terminal connection and battery water level&nbsp;<br></div><div>- Cleaned the battery bank surface.<br></div><div>- Checked and tightened wiring terminal connection inside generator control panel.</div><div>- Found the loose wire connection from Main Circuit breaker Natural point incoming side.</div><div>- Retightened the loose connection</div><div>- Removed control relay and cleaning with contact cleaner.<br></div><div>- Performed cleaning inside generator control panel with air blower.<br></div><div>- Checked, cleaned and tightened sensor termination and sensor cable lug.<br></div><div>- Performed electrical de-isolation G-8310.<br></div><div>- Performed manual fuel top up function test. (Normal)<br></div><div>- Performed test run G-8310 and Recorded parameter as per PM job card.</div><div>- Retrieve the history log file from G-8310</div><div><br></div>', NULL, '2024-07-21 17:44:42', '2024-07-21 18:22:21', 'PTTEP\ZOC.Elec-Tec', 'PTTEP\ZOC.Elec-Tec', false) RETURNING id INTO new_report_id;
