  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Troubleshooting G-8310 high coolant temp tripped ', 'Mechanic', 'CM', 'Completed', '2024-07-21', '<p><b>Troubleshooting G-8310 high coolant temperature tripped</b></p><p><b><br></b></p><p><b>Root Cause: High engine temp tripping by low coolant level due to improper installation of radiator cap</b></p><p><br></p><p>Action:</p><p>1) Performed investigation on engine cooling system.</p><p>2) Firstly found engine temp high trip on panel 12-July-24</p><p>3) Found losing radiator cap from radiator and low coolant level in radiator (Last AM activity on 7-July)&nbsp;</p><p>4) Drained residual coolant and cleaned the radiator.</p><p>5) Replaced the coolant about 4.5 liters.</p><p>6) Readjusted the fan belt tension.</p><p>7) Reinstalled the radiator cap properly.</p><p>8) Housekeeping and test run to ensure no abnormality leak.</p><p><br></p>', NULL, '2024-07-21 17:49:21', '2024-07-21 18:08:58', 'PTTEP\ZOC.Mech-Tec', 'PTTEP\ZOC.Se-Mech', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV2-G-8310-PACKAGE', 'ATL-BV2-G-8310-PACKAGE', 'Gen, ZBV2 Diesel Generator package1', NULL, NULL, 'Gen, ZBV2 Diesel Generator package1', 'BV2', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

