  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted) VALUES (NULL, 'Verify the cable gland connection of PDIT-88151 ', 'Electrical & Instrument', 'CM', 'Completed', '2024-07-22', '<div><u><b>Today Activity</b></u></div><div>Verify the cable gland connection of PDIT-88151.</div><div><br></div><div><u>Action</u><br></div><div>- Checked the cable gland condition of transmitter.</div><div>- Found inserts(Ant) in the cable gland.</div><div>- Checked the power voltage of transmitter. (24Vdc)</div><div>- Isolate the power cable in the marshalling cabinet (PCM-01) at instrument room.</div><div>- Disconnect the power cable of transmitter.</div><div>- Also checked the cable termination in the junction box (PAI-JB81013)</div><div>- Found that a lot of inserts (Ant) on the terminations in the junction box.</div><div>- Disconnect the cable from the terminal block.</div><div>- Replace the new terminal block for transmitter. (PDIT-88151)</div><div>- Performed the insulation task for power cable from the junction box to the field device.</div><div>- Found low insulation within Negative cable and Ground.(Failure)</div><div>- Plan to replace new cable.</div>', NULL, '2024-07-22 17:42:06', '2024-07-23 06:46:29', 'PTTEP\ZOC.Inst-Tec', 'PTTEP\ZOC.Inst-Tec', false) RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-PDIT-88151', 'ATL-OC-PDIT-88151', 'PDT on Raw Water Tank Bucket strainer', NULL, NULL, 'PDT on Raw Water Tank Bucket strainer', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
END $$;

